import{m as b}from"./lesson-en-g-m-DCkb9trv.js";const g=[{id:"identity-gollwitzer",title:"I01 · Gollwitzer ve Sheeran · 2006 · Duruma bağlı planlar ve hedefe ulaşma",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 kişinin katıldığı 94 bağımsız testte “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı: d = 0,65.",limitation:"83 deneysel ve 11 ilişkisel test farklı hedefleri ve yöntemleri kapsadı. Bu sonuç, belirli bir markanın alışkanlık paketini veya ODA’nın tam bu planını doğrulamaz."},{id:"identity-harkin",title:"I02 · Harkin ve arkadaşları · 2016 · Hedefe doğru ilerlemeyi izlemek",url:"https://doi.org/10.1037/bul0000025",type:"research",finding:"138 rastgele kontrollü çalışmada takip uygulamaları hedefe ulaşmayı ortalama olarak artırdı: d = 0,40. Yanlılığa göre düzeltilmiş tahmin daha küçüktü: d = 0,19.",limitation:"Hedefler ve kayıt yöntemleri farklıydı. Etkiyi değiştiren koşullara dair bulgular herkese açık paylaşım gerektirmez. Bu özet kayıt ve ertesi gün değerlendirmesi sınanmadı."},{id:"identity-cole",title:"I03 · Cole ve arkadaşları · 2021 · Zihinsel canlandırma ve davranış değişimi",url:"https://doi.org/10.3758/s13423-021-01880-6",type:"research",finding:"94 rastgele kontrollü çalışmada zihinsel canlandırmanın ortalama davranış etkisi g = 0,49’du. Canlandırma alt türlerinin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı.",limitation:"Örneklemlerin çoğu öğrenciydi. Bilgilerin raporlanma biçimi ve küçük alt gruplar kesinliği sınırlar. Üstün bir canlandırma türü veya kimlik meditasyonunun etkisi belirlenmedi."},{id:"identity-lally",title:"I04 · Lally ve arkadaşları · 2010 · Alışkanlıklar nasıl oluşur?",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"Verilere iyi uyan 39 modelde, otomatikleşmenin ulaşacağı sabit düzeyin %95’ine ulaşma süresi tahmininin ortancası 66 gündü. Tahminler 18-254 gün arasındaydı.",limitation:"96 gönüllü katıldı. Davranış 84 gün izlendi. Daha uzun süreler gözlemin ötesine uzanan tahminlerdi. Kimlik değişiminin son tarihi veya iki gün kaçırma kuralının testi değildi."},{id:"identity-habit-times",title:"I05 · Singh ve arkadaşları · 2024 · Alışkanlık oluşumu derlemesi",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"20 sağlık davranışı çalışmasının derlemesi, alışkanlık oluşumunda büyük farklılıklar buldu. Yalnızca dört çalışma oluşma sürelerini bildirdi.",limitation:"11 çalışmada yanlılık riski yüksekti. Öncesi ve sonrası alışkanlık puanı artışı, rastgele kontrollü bir neden-sonuç etkisi değildir. Herkese uyan bir oluşma süresi desteklenmiyor."},{id:"identity-wood-runger",title:"I06 · Wood ve Rünger · 2016 · Alışkanlık psikolojisi",url:"https://doi.org/10.1146/annurev-psych-122414-033417",type:"research",finding:"Derleme, tekrar eden ortamlarda yinelenen davranışlarla alışkanlıkların gelişmesini anlatır. Alışkanlıklar ve bilinçli süreçler birlikte işleyebilir.",limitation:"Birleştirilmiş etki vermeyen anlatı derlemesidir. Her ruh hâlini veya düşünceyi alışkanlık saymaz. Ortamı değiştirmenin her zaman çabadan üstün olduğunu kanıtlamaz."},{id:"identity-wood-everyday",title:"I07 · Wood, Quinn ve Kashy · 2002 · Günlük hayatta alışkanlıklar",url:"https://doi.org/10.1037/0022-3514.83.6.1281",type:"research",finding:"Öğrencilerin günlüklerini kullanan iki örneklemde, bildirilen davranışların %35’i ve %43’ü neredeyse her gün, aynı yerde yapılan alışkanlık tanımına uydu.",limitation:"Örneklemler 70 ve 209 öğrenci içeriyordu. Yüzdeler toplum tahmini veya zihnin dalma sıklığı değildir. Günlüklerle değerlendirme, kimlik değiştiren bir uygulamayı sınamadı."},{id:"identity-lieberman",title:"I10 · Lieberman ve arkadaşları · 2007 · Duyguları sözcüklere dökmek",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"Yüzlere bakan 30 yetişkinde, duygu sözcüğüyle adlandırma, cinsiyete uygun bir isimle adlandırmaya göre amigdalada daha düşük etkinlik yarattı.",limitation:"Küçük bir laboratuvar beyin görüntüleme çalışmasıdır. Gündelik duygusal toparlanmayı ölçmez. Kendi sıkıntını adlandırmanın onu azalttığını göstermez."},{id:"identity-breines",title:"I11 · Breines ve Chen · 2012 · Kendine şefkat ve gelişme isteği",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Dört kısa deney, şefkatli yanıtların ardından hemen ortaya çıkan gelişme isteğini destekledi. Bir deneyde ders çalışma süresi, hiçbir uygulama almayan koşula göre daha uzundu.",limitation:"Çoğunlukla öğrenci ve internet örneklemleri vardı. Etkiler karşılaştırmaya göre farklıydı. O çalışmada sınav notlarında istatistiksel olarak anlamlı fark bulunmadı. Kalıcı kimlik değişimi gösterilmedi."},{id:"identity-clear-identity",title:"I15 · James Clear · Kimliğe dayalı alışkanlıklar",url:"https://jamesclear.com/identity-based-habits",type:"technique",finding:"Clear, küçük davranışları istenen kimliğin kanıtı olarak sunar. Davranışı oy gibi anlatmak, uygulayıcının kullandığı bir benzetmedir.",limitation:"Yazarın yazısı deney değildir. Yayın yılı doğrulanmadı. Önce kimliği değiştirmenin üstünlüğü ve “asla iki kez kaçırma” kuralı doğrulanmış bilimsel yasalar değildir."},{id:"identity-task-belief",title:"I17 · Bandura · 1977 · Öz yeterlik kuramı",url:"https://doi.org/10.1037/0033-295X.84.2.191",type:"research",finding:"Çerçeve, belirli bir işi yapabileceğine dair beklentiyi anlatır. Kendi başardıkların, başkalarını gözlemek, cesaretlendirilmek ve bedenden gelen bilgiler bu beklentiyi besler.",limitation:"Kuramsal sentezdir. Birleştirilmiş uygulama etkisi tahmini değildir. Yapabileceğine dair inanç, insan olarak değerini ölçmez veya kimliğe oy verme yöntemini doğrulamaz."},{id:"identity-activity-identity",title:"I19 · Rhodes ve arkadaşları · 2025 · Fiziksel etkinliğe ilişkin kimlik uygulamaları",url:"https://doi.org/10.1080/17437199.2024.2412996",type:"research",finding:"4.939 yetişkini kapsayan 40 deneysel veya yarı deneysel etkide, fiziksel etkinliğe ilişkin kimlik ortalama olarak az değişti: g = 0,18.",limitation:"Davranış etkileri farklı bir 30 etkilik alt örneklemden geldi ve değişkenlik gösterdi. Derleme, kimliğin davranış değişimine neden olduğunu göstermez. Bütün kişiliğin dönüşümüne genellenemez."},{id:"identity-motor-rehearsal",title:"I18 · Toth ve arkadaşları · 2020 · Zihinsel prova ve görev performansı",url:"https://doi.org/10.1016/j.psychsport.2020.101672",type:"research",finding:"37 çalışmalık derleme, hareket becerileri veya görev performansında küçük, yanlılığa göre düzeltilmiş zihinsel prova etkisi bildirdi: r = 0,131.",limitation:"Açılan özet, toplam katılımcı sayısını veya güven aralığını doğrulamadı. Hareket becerisi kanıtları kimlik değişimini, iyileşmeyi veya duyguların biyolojisine ilişkin etkileri göstermez."}],s=[{schemaVersion:2,revision:2,id:"identity-1",courseId:"identity",locale:"tr",title:"Yine telefona mı daldın? Değiştirebileceğin anı bul",goal:"Tekrarlanan bir başlama anı seç. Bu hafta sana katkısı olacak başka bir davranış dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Aynı şey dikkatini dağıttı, öğleden sonran yine gitti mi? Değiştirebileceğin tek bir an bul.",reason:{id:"identity-1-reason",label:"Bu davranış şimdi neyi koruyor, sonraya neyi bırakıyor?",kind:"text",maxLength:160,optional:!0,suggestions:["İşi yine geç saate kalmadan bitirmek","Yaratıcı çalışmama hayatımda yer açmak","Karşımdaki kişiye dikkatimi vermek"]},why:{id:"identity-1-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Önceliklerin değişse bile alışık olduğun bir ortam seni yine aynı davranışa götürebilir. Alışkanlık araştırmaları, tekrarlanan o davranışı bütün kişiliğinden ayrı tutar. “Öğle yemeğinden sonra işe başlamadan telefona dalıyorum” belirli bir durumu anlatır. “Ben tembelim” dediğinde ise üzerinde çalışabileceğin bir anı göremezsin. Hangi anda ne yaptığın belirsiz kalır.","Gündelik hayatında tanıyabileceğin tek bir an seç. O anda yapabileceğin yararlı bir alternatif belirle. Eski davranışın şimdi ne sağlıyor, sonraya ne bırakıyor, ona bak. Sonra alternatifini bir kez dene. Bu kurs boyunca aynı denemeyi geliştireceğiz. Kendini reddetmeden veya bambaşka biri olacağına söz vermeden küçük bir adımla başlayabilirsin."],example:{title:"Leyla raporun ilk cümlesini yazıyor",text:"Saat 13.30. Leyla masasına dönüyor. Raporu yazmaya başlamadan elini telefona uzatıyor. İşinin akşamları daha az uzamasını istiyor. Telefonu kenara koyup başlangıç için bir taslak cümle yazıyor. Cümle pek akıcı değil. Sonra yine telefona dalıyor. Kaydına, seçtiği anda ne yaptığını yazıyor. Bütün öğleden sonrayı hayatını değiştiren bir dönüşüm gibi anlatmıyor."}},move:{invitation:"Alışık olduğun tek bir an seç. İstediğin yola somut katkısı olacak başka bir davranış dene.",instructions:["Başlayacağın anı ve o anda gerçekten deneyeceğin davranışı belirt.","Seçtiğin an geldiğinde gerçekte ne yaptığını kaydet."],prompts:[],suggestions:{action:["İşe yarayan tek bir cümle yaz","Dikkatle dinlemek için tek bir soru sor","İşe yarayan küçük bir adımı tamamla"],minimum:["Taslağıma işe yarayan bir cümle ekle","Verilen bir yanıtı sonuna kadar dinle","İşe yarayan tek bir kısmı bitir"],cue:["Öğle yemeğinden sonra masama döndüğüm anda","Çantamı yere bıraktığım anda","Akşam genellikle işe başladığım anda"],place:["Genellikle kullandığım masa veya tezgâhta","Güvenle konuşabildiğimiz her zamanki yerde"],fallback:["Cümleyi yazmak yerine sesle yazdır","Bir sonraki uygun başlama anını kullan","Yapacağım iş için somut yardım iste"],observation:["Cümleyi gerçekten yazıp yazmadığım","Seçtiğim an geldiğinde ne yaptığım","Eski davranışımın sonraya bıraktığı iş"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşe yarayan tek bir cümle yaz",minimum:"Taslağıma işe yarayan bir cümle ekle",minutes:2,cueHint:"Öğle yemeğinden sonra masama döndüğüm anda",placeHint:"Genellikle kullandığım masa veya tezgâhta",obstacleHint:"Dikkatimi her zamanki gibi dağıtan şeye ulaşmak daha kolay.",fallbackHint:"Cümleyi yazmak yerine sesle yazdır",observationHint:"Cümleyi gerçekten yazıp yazmadığım"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-1-decision",scenario:"Leyla öğle yemeğinden sonra yazmayı planladı ama telefona daldı. Şimdi beş dakikası var. Rapor dosyası açık.",question:"Hangi adımla işe yarayan bir denemeye başlar?",options:[{id:"identity-1-redesign-day",text:"Öğleden sonrası için daha sıkı bir program hazırlasın. Ancak yeni programın tamamını bitirdikten sonra rapora başlasın.",feedback:"Program yapmak ileride yardımcı olabilir. Şimdi ise yapılabilecek bir denemenin önüne daha fazla hazırlık koyuyor. Öğle yemeğinden sonraki başlama anını belirt. İşe yarayan bir cümle yaz ve önüne ne çıktığını kaydet."},{id:"identity-1-test-cue",text:"Öğle yemeğinden sonra ne olduğunu söylesin. Rapora tek bir cümle yazıp başladığı anı kayda eklesin.",feedback:"Bu seçim, gerçek ortamda başka bir davranışı deniyor. Cümle işe katkı sağlıyor. Not da başlama anını gösteriyor. Bir deneme bilgi verir. Bütün kişiliğinin değiştiğini kanıtlaması gerekmez."},{id:"identity-1-change-break",text:"Yarın yazmayı öğle yemeğinden önceye alsın. Bugün kalan beş dakikayı bu yeni planı gözden geçirmeye ayırsın.",feedback:"Sorun öğle yemeğinin saatiyse başlama anını değiştirmek işe yarayabilir. Burada ise hâlâ beş dakikalık gerçek bir deneme mümkün. Yeni programın daha uygun olduğuna karar vermeden önce tek bir cümle dene ve başladığın anı kaydet."}],bestOptionId:"identity-1-test-cue"}},carry:{takeaway:"Tek bir ortamda tek bir davranışı değiştir. Ne olduğunu açıkça yaz.",followUp:{questionId:"identity-1-return",question:"Seçtiğin an geldiğinde, alışık olduğun davranış yerine gerçekte ne yaptın?",observationPrompt:"O anda ne yaptığını söyle. Seçtiğin an hiç gelmediyse bunu kaydet.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Bir davranış, bütün kişiliğin değildir",paragraphs:["Wood ve Rünger’in derlemesi, alışkanlıkları tekrarlanan ortamlarla ilişkili, yinelenen davranışlar olarak anlatır [I06]. Bir ortam, bilinçli seçimlerin yanında alışık olduğun bir davranışı da harekete geçirebilir. Bu, her düşüncenin, ruh hâlinin veya zor günün otomatik bir program olduğunu söylemekten daha sınırlı bir iddiadır. Bu ders, ortadan kaldırman gereken bir “eski sen” aramıyor. Gözle görülebilen tek bir davranışı soruyor.","Günlük tutulan araştırmada 70 ve 209 kişilik öğrenci örneklemleri vardı [I07]. Bildirdikleri davranışların sırasıyla %35’i ve %43’ü neredeyse her gün, aynı yerde yapılan alışkanlık tanımına uyuyordu. Bu oranlar bütün yetişkinleri anlatmaz. Zihnin başka yere kaydığı zamanın yüzdesi de değildir. Davranışlardan örnek toplamak burada bir değerlendirmeydi. Kimliği değiştirdiği gösterilmiş bir tedavi değildi.","ODA’nın başlama anı ve davranış notu, eğitim için hazırlanmış bir uyarlamadır. Sıradaki seçimine yarayacak ayrıntıyı tutman yeterli. Ruh hâlinin aynı kalması veya öğleden sonranın kusurlu geçmesi, doğru anlattığın denemeyi geçersiz kılmaz."]},{heading:"Seçtiğin alternatif gerçekten bir işe yarasın",paragraphs:["Gollwitzer ve Sheeran’ın derlemesi, 8.461 kişinin katıldığı 94 bağımsız testi birleştirdi [I01]. Belirli “şu olursa bunu yaparım” planlarının hedefe ulaşmaya ortalama katkısı bulundu. Kanıtlar, farklı hedefler ve yöntemlerle yapılmış 83 deneysel ve 11 ilişkisel testi içeriyordu. Bu sonuç, ODA’nın tam bu ders sırasının kişinin kimliğini değiştirdiğini göstermiyor.","Bu denemede, tanıyabileceğin bir olayı yapabileceğin bir davranışla birleştir: öğle yemeğinden sonra döndüğünde rapora işe yarayan bir cümle yaz. Gerçekten karşılaştığın bir an belirt. Sadece uygulamayı açmak veya malzeme düzenlemek yerine istediğin yola katkısı olan bir alternatif seç. Bunlar hazırlık olabilir. Ama yaptığın uygulamanın adını doğru koy. Hazırlığı yazma işi gibi gösterme.","Alışık olduğun her davranışı kesmek zorunda değilsin. Hayatını kolaylaştıran düzenleri koru. Bulunduğun koşullarda önce güvenlik, dinlenme veya yardım gerekiyorsa bilinçli olarak onu seç. Başka bir düzen eklemeden önce bu tek denemende ne olduğunu gözden geçir."]}],sourceIds:["identity-wood-runger","identity-wood-everyday","identity-gollwitzer"]}},{schemaVersion:2,revision:2,id:"identity-2",courseId:"identity",locale:"tr",title:"Kaygın geçmedi mi? Yine de adımını seç",goal:"Gündelik bir duygu sürerken, aynı başlama anında işe yarayan davranışını dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Başlamak için kaygının geçmesini mi bekliyorsun? Seçtiğin adımı güvenli bir ortamda dene.",reason:{id:"identity-2-reason",label:"Bu duygunun geçmesini beklerken senin için önemli neyi erteliyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Gündelik kaygım sürerken işe başlamak","Benim için değerli bir akşamı korumak","İhtiyaçlarımı gizlemeden bir yanıt vermek"]},why:{id:"identity-2-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin başlama anına ve davranışa dön. Tanıdık bir duygu, fark edebileceğin bir şeydir. Kişiliğinin değişmez olduğunu kanıtlamaz. Duyguyu adlandırmaya dair araştırma sınırlı: küçük bir çalışmada yüzlerdeki duyguyu adlandırmak, beyinde ölçülen yanıtı değiştirdi. Çalışma, senin kendi kaygının geçip geçmediğini sınamadı. Ölçülen beyin yanıtıyla günlük yaşadığın duyguyu aynı şey sayma.","Adlandırmayı bir tarif olarak kullan: “Şu an kaygı var.” Bu kaygı gerçek bir ihtiyaca mı işaret ediyor, önce ona bak. Sonra ne yapacağını seç. Kaygın sürerken cümleni yazabilirsin. Kaygılandığın sorun için bir şey yapman gerekiyorsa yardım isteyebilirsin. Ardından daha sakin hissetmesen bile, yararlı adımı yine atmış olursun."],example:{title:"Leyla kaygılıyken yazmaya başlıyor",text:"Perşembe günü öğle yemeğinden sonra Leyla yine aynı rapor için kaygılanıyor. Gereken sayıların elinde olduğunu kontrol ediyor. Kaygısını adlandırıp sıradaki işe yarayan cümlesini yazıyor. Hâlâ her şeyi yeniden kontrol etmek istiyor. Yazdığı cümleyi ve kaygının sürdüğünü kaydediyor. Yazma işini denedi. Duygunun bir alışkanlık olduğunu kanıtlamadı."}},move:{invitation:"Aynı denemeyi sürdür. İşine yarayacaksa gündelik duygunu adlandır. Sonra seçtiğin davranışı yap.",instructions:["Buna gündelik kaygı demeden önce gerçek bir sorun var mı, kontrol et.","Denemeni yaparken duygunun sürmesine izin ver."],prompts:[],suggestions:{action:["Sıradaki işe yarayan cümlemi yaz","Gündelik suçluluk duygum sürerken karşımdakini dinle","İhtiyacım olan somut yardımı iste"],minimum:["Taslağıma işe yarayan bir cümle ekle","Dikkatle dinlemek için tek bir soru sor","Tek bir somut yardım isteği gönder"],cue:["Başlama anımda kaygı belirdiğinde","Acil ihtiyacı kontrol ettikten sonra","Bir sonraki güvenli fırsatımda"],place:["Genellikle kullandığım masa veya tezgâhta","Birlikte güvenle bulunabildiğimiz bir yerde"],fallback:["İşe yarayan bir cümleyi sesle yazdır","Önce gerçekten var olan sorunla ilgilen","Bunun yerine destek almayı seç"],observation:["Kaygım sürerken adım atıp atmadığım","Karşılanmamış gerçek bir ihtiyaç olup olmadığı","Gerçekte ilettiğim istek veya verdiğim yanıt"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Sıradaki işe yarayan cümlemi yaz",minimum:"Taslağıma işe yarayan bir cümle ekle",minutes:2,cueHint:"Başlama anımda kaygı belirdiğinde",placeHint:"Genellikle kullandığım masa veya tezgâhta",obstacleHint:"Bir şey yapmadan önce bu duygunun geçmesini istiyorum.",fallbackHint:"İşe yarayan bir cümleyi sesle yazdır",observationHint:"Kaygım sürerken adım atıp atmadığım"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-2-decision",scenario:"Leyla’nın beş dakikası var. Elindeki sayılar onaylı tabloyla uyuşuyor. Yazacağı cümle yeni bir hesaplama içermiyor. Yine de kaygısı sürüyor.",question:"Bu ana hangi davranış daha iyi uyar?",options:[{id:"identity-2-recheck",text:"Cümleyi yazmadan önce kendinden daha emin hissetmek için elindeki sayıları bir kez daha kontrol etsin.",feedback:"Bilgi eksikse bir kontrol daha işe yarayabilir. Burada gereken sayılar zaten kontrol edildi. Yeniden bakmak, yapılabilecek yazma denemesini erteliyor. Daha sakin hissetmenin güvenilir bir başlama işareti olacağını da göstermiyor."},{id:"identity-2-provisional-check",text:"Geçici bir taslak cümle yazsın. Cümleyi raporda tutmadan önce bir iş arkadaşından içindeki sayıyı doğrulamasını istesin.",feedback:"Sayı belirsizse geçici cümle ve ikinci kontrol yardımcı olur. Burada ise onaylı tablo cümleyi zaten destekliyor. Bir yanıt daha beklemek, bilinen bir eksiği gidermeden işe yarayan cümleyi raporda tutmayı geciktiriyor."},{id:"identity-2-act-with-feeling",text:"Kaygısını adlandırsın. İşe yarayan tek bir cümle yazsın. Endişesinin başka bir adım gerektirip gerektirmediğini kayda eklesin.",feedback:"Leyla bu seçenekte duygusunu yok saymıyor, neye işaret ettiğine bakıyor. Duyguya otomatik olarak her şeyi durdurma hakkı vermiyor. Denediği adım, cümleyi yazmak. Gerçek bir sorun ortaya çıkarsa sıradaki adım somut yardım istemek olabilir."}],bestOptionId:"identity-2-act-with-feeling"}},carry:{takeaway:"Bir duygu sürerken de işe yarayan, güvenli bir davranışı seçebilirsin.",followUp:{questionId:"identity-2-return",question:"Adımın sırasında duygu sürdü mü? Karşılanmamış gerçek bir ihtiyaca işaret etti mi?",observationPrompt:"Süren duyguyu ve varsa gösterdiği ihtiyacı söyle. Belirgin bir ihtiyaç yoksa onu belirt.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Duyguyu adlandırma araştırmasında gerçekten ne ölçüldü?",paragraphs:["Lieberman ve arkadaşları, beyin görüntüleme cihazında duygu gösteren yüzlere bakan 30 sağlıklı yetişkini inceledi [I10]. Duygu sözcüğü seçmek, yüzün cinsiyetine uygun bir isim seçmeye göre amigdalada daha düşük etkinlikle sonuçlandı. Bu, laboratuvarda ölçülen bir beyin farkıdır. Kendi sıkıntını adlandırmanın onu azalttığını veya haftalar boyunca ruh hâlini iyileştirdiğini gösteren bir bulgu değildir. Sonucun sınırı burada kalır.","ODA, kısa bir duygu adını isteğe bağlı bir tarif olarak kullanıyor. Araştırma bu başlama anını, senin seçtiğin davranışı veya kimlik üzerine bir kursu sınamadı. Bir katkısı yoksa adlandırmayı atla. Her duyguyu düzeltmek zorundaymışsın gibi davranma. Yas, haksızlığa duyduğun öfke ve tehlike anındaki korku farklı bir yanıt gerektirebilir. Bunların verdiği bilgiyi gözden kaçırma.","Gözleminde yine aynı davranışı değerlendir. Onu yaptın mı, yardım gerekti mi, gerçek bir sorun planı değiştirdi mi? Bir kayıt, zor bir duyguyu ve yararlı bir davranışı birlikte anlatabilir. Birinin diğerine neden olduğunu söylemek zorunda değildir."]},{heading:"Sorumluluğu silmeden destek alabilirsin",paragraphs:["Breines ve Chen, çoğunlukla öğrencilerle veya internetten katılan kişilerle dört kısa deneyde şefkatli yanıtları sınadı [I11]. Bazı sonuçlar, hemen ardından kendini geliştirme isteğini destekledi. Bir çalışmada katılanlar zor bir sınavdan sonra, hiçbir uygulama almayan gruptan daha uzun süre ders çalıştı. Sonraki sınav notlarında istatistiksel olarak anlamlı fark bulunmadı. Öz saygı grubuyla karşılaştırma ise yalnızca sınırda bir bulguydu.","Bu kanıt, kalıcı kimlik değişimini veya anlayışlı davranmanın her zaman üstün olduğunu göstermez. Ama yeniden denemeden önce her zaman sert davranmak gerektiği varsayımını sorgulatır. Bu derste duyguyu tarif edip seçtiğin işe devam etmek, ODA’nın uyarlamasıdır. Araştırmada sınanan şefkatli yazma alıştırmasının kendisi değildir. İkisini aynı uygulama gibi sunamayız.","Kendi sorumluluğunu gözden kaçırmadan kendine adil davran. Beceri eksikse öğrenmek gerekir. Karşılanmamış bir ihtiyaç için yardım gerekebilir. Kendine hakaret etmeden adım atabilirsin. Ara verdiğinde de bunu bütün kişiliğinin başarısızlığı saymadan o arayı kaydedebilirsin."]}],sourceIds:["identity-lieberman","identity-breines"]}},{schemaVersion:2,revision:2,id:"identity-3",courseId:"identity",locale:"tr",title:"Geç mi fark ettin? Sıradaki adımın işe yarasın",goal:"Dikkatin dağıldıysa seçtiğin işe dön. Davranışın zarar verdiyse kendi payına düşeni düzelt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Telefona daldın mı, ağzından sert bir söz çıktı mı? Sıradaki cümlen hâlâ işe yarayabilir.",reason:{id:"identity-3-reason",label:"Aynı denemede nerede işe dönmek veya kendi davranışını düzeltmek gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Öğleden sonram bitmeden işime dönmek","Verdiğim sert bir yanıtı düzeltmek","Yararlı adımımı hâlâ atabilmek"]},why:{id:"identity-3-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Dikkatinin dağıldığını fark etmek başka, işe dönmek başka. Seçtiğin başlama anını ve davranışı koru. Geç fark ettiğinde ne yapacağını da belirle: “İşten koptuğumu fark edersem işe yarayan en küçük adımımı atacağım.” Araştırmalarda belirli bir durumu belirli bir davranışa bağlayan planlar, hedefe ulaşmayı ortalama olarak artırdı. Ama sadece fark etmiş olmak, işin yapıldığını göstermez.","Verdiğin yanıt birini incittiyse bunu kendi içinde fark etmen, düzeltme değildir. Güvenli bir ortamda kendi payını kabul et. Bir cümleyi yeniden söyle. Kimse zarar görmediyse işe dön. Yalnızca fark ettiğin anları değil, ardından ne yaptığını kaydet. Bütün günü mahvolmuş saymadan sıradaki davranışını değiştirebilirsin."],example:{title:"Leyla işten koptuğunu geç fark ediyor",text:"Saat 13.42. Leyla yazmak yerine on iki dakikadır telefona baktığını fark ediyor. Akışı kapatıp raporuna işe yarayan bir cümle ekliyor. Sonra iş arkadaşına gönderdiği sert mesajı fark ediyor. Kısa bir mesajla üslubunu düzeltiyor. Bu iki adım da kaybolan zamanı geri getirmiyor. Ama ikisi de kaydına yazabileceği somut davranışlar."}},move:{invitation:"Aynı davranışı koru. Durumu geç fark ettiğinde ardından ne yapacağını seç.",instructions:["İşe yarayan en küçük adıma dön veya kendi zararlı davranışını düzelt.","Fark ettikten sonra gerçekte ne yaptığını kaydet."],prompts:[],suggestions:{action:["İşe yarayan cümleme geri dön","Bir cümleyi saygılı biçimde yeniden söyle","Gönderdiğim sert mesajı düzelt"],minimum:["Şimdi işe yarayan tek bir cümle ekle","Sert konuştuğumu kabul edip cümlemi yeniden söyle","Düzeltme için tek bir açık mesaj gönder"],cue:["Telefona daldığımı fark ettiğim anda","Sesimdeki sertliği duyduğum anda","Güvenli bir kesinti sona erince"],place:["Genellikle kullandığım masa veya tezgâhta","Güvenle kullanabildiğim mesajlaşma kanalında"],fallback:["İşe yarayan daha kısa bir cümle kullan","Düzeltme için daha güvenli bir iletişim yolu seç","İşe yeniden başlamak için yardım iste"],observation:["Fark ettikten sonra gerçekte ne yaptığım","Kendi davranışımı gerçekten düzeltip düzeltmediğim","Bu davranışı hangi anda fark ettiğim"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşe yarayan cümleme geri dön",minimum:"Şimdi işe yarayan tek bir cümle ekle",minutes:2,cueHint:"Telefona daldığımı fark ettiğim anda",placeHint:"Genellikle kullandığım masa veya tezgâhta",obstacleHint:"Dikkatim dağıldıktan sonra ancak fark ediyorum.",fallbackHint:"İşe yarayan daha kısa bir cümle kullan",observationHint:"Fark ettikten sonra gerçekte ne yaptığım"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-3-decision",scenario:"Güvenli bir konuşma sırasında Leyla bir iş arkadaşına sert çıkıyor. Konuşmaları sürerken kendi sesindeki sertliği fark ediyor.",question:"Davranışını fark etmesini hangi adım anlamlı kılar?",options:[{id:"identity-3-repair",text:"Sert söylediği cümleyi kabul etsin. Konuşma hâlâ sürerken anlatmak istediğini saygılı bir cümleyle yeniden söylesin.",feedback:"Böylece fark etmesi somut bir işe yarıyor. Leyla kendi üslubunun sorumluluğunu alıyor, farklı bir yanıt deniyor. Düzeltme denemesinin gerçekten yapılmış olması için iş arkadaşının onu affetmesi gerekmiyor."},{id:"identity-3-private-catch",text:"Kendi içinde durup fark ettiğini kaydetsin. Sonra bir dahaki konuşmada daha sabırlı davranmaya odaklanarak bu konuşmayı sürdürsün.",feedback:"Fark etmek bilgi verir. Ama sert cümle bu konuşmayı zaten etkiledi. Düzeltmek güvenli ve uygunsa kısaca kendi payını kabul edip yeniden söylemek, sadece yarının davranışına değil, şu anki etkiye yanıt verir."},{id:"identity-3-full-explanation",text:"Teslim baskısının neden sesini sertleştirdiğini açıklasın. Ardından üslubuna yeniden dönmeden işle ilgili konuşmaya kaldığı yerden devam etsin.",feedback:"Koşullar gerginliği açıklayabilir, değişmeleri de gerekebilir. Ama bu, kendi davranışını düzeltmenin yerini tutmaz. Önce üslubunun sert olduğunu kabul et. Sonra iş yükünü konuş. Karşı tarafın kabul etmesini düzeltmenin şartı yapma."}],bestOptionId:"identity-3-repair"}},carry:{takeaway:"Fark ettiğin an, işe döndüğünde, düzelttiğinde veya daha güvenli bir davranış seçtiğinde işe yarar.",followUp:{questionId:"identity-3-return",question:"Davranışı ne zaman fark ettin? Ardından işe döndün mü, davranışını düzelttin mi?",observationPrompt:"Ne zaman fark ettin? İşe döndün mü, davranışını düzelttin mi, kendini korudun mu? Fırsat olmadıysa belirt.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Geç fark ettiğin an da başlama işaretin olabilir",paragraphs:["“Şu olursa bunu yaparım” planları, belirli bir durumla seçilmiş bir davranışı birleştirir. Gollwitzer ve Sheeran’ın derlemesi, 94 bağımsız testte hedefe ulaşmada ortalama yarar buldu [I01]. Hedefler, uygulama biçimleri ve araştırma yöntemleri farklıydı. Bu sonuç, belirli bir duraklama sözcüğünü, nefes sırasını veya gün içinde kaç kez fark etmen gerektiğini doğrulamıyor.","Bu ders, geç fark etmeyi bir başka olası başlama anı olarak ekliyor: telefona daldığını fark edersen seçtiğin işe yarayan cümleyi yaz. Davranışın hâlâ kurstaki aynı denemenin parçası. İçinden söylediğin bir işaret sözcüğü isteğe bağlı bir hatırlatmadır. Geliştirmek istediğin asıl davranışın kendisi değildir. İşe dönmeden önce nefes alıştırması yapman veya sakin hissetmen gerekmiyor.","Wood ve Rünger, alışkanlıkların bilinçli süreçlerle birlikte işlediğini anlatır [I06]. Bu, kusurlu bir düzenin içinde bilinçli bir davranışa da yer bırakır. Her dikkat dağılması alışkanlıktı demek değildir. Gördüğün şeyi anlat. Bu işareti gerçekten bulunduğun ortamda tanıyıp tanıyamadığını dene. Başlama anın, kâğıt üzerindeki hâliyle değil, yaşadığın durumla uyuşmalı."]},{heading:"Fark et, sonra ortaya çıkan sonuçla ilgilen",paragraphs:["Kaydın fark etmeyi, işe dönmeyi ve düzeltmeyi ayrı tutmalı. Harkin ve arkadaşları, ilerleme takibi üzerine 138 rastgele kontrollü çalışmayı inceledi [I02]. Takip uygulamaları hedefe ulaşmayı ortalama olarak artırdı. Yanlılığa göre düzeltilmiş tahmin ise daha küçüktü. Derleme, yalnızca fark ettiğin anları saymanın ilişkilerini değiştirdiğini göstermiyor. Kendin için yazdığın her notu paylaşman gerektiğini de söylemiyor.","Bu ODA uyarlamasında, fark ettikten sonra yaptığın davranışı kaydet. “Sesimdeki sertliği yakaladım” ile “Sertliğimi kabul edip isteğimi yeniden söyledim” farklı gerçeklerdir. Asıl işin bölündüyse geri dönüp yaptığın yararlı kısmı kaydet. Sen zarar vermediysen özür dilemen gerekmez. Kaydın seni her durumda sorumlu ilan etmesin.","Güvenli olmayan bir ilişkide önce korunmak gerekir. Seni tehdit eden birine ulaşmak, onu affetmek veya açıklama yapmak zorunda değilsin. Uygunsa sınır koymayı veya destek istemeyi seç. Bu davranışların adını doğru koy. Her arayı başarılı bir düzeltme sayma. Ara vermiş olman ile bir şeyi düzeltmiş olman ayrı kalabilir."]}],sourceIds:["identity-gollwitzer","identity-wood-runger","identity-harkin"]}},{schemaVersion:2,revision:2,id:"identity-4",courseId:"identity",locale:"tr",title:"Hep hazırlık mı yapıyorsun? Yaptığın iş kanıt olsun",goal:"En küçük adımın, seçtiğin davranışı gerçekten denemeni sağlıyor mu? Kontrol et, sonra bir kez dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yine kusursuz bir plan var, taslak hâlâ yok mu? İşe yarayan tek bir adımı kanıt olarak göster.",reason:{id:"identity-4-reason",label:"Bu en küçük adım becerini geliştiriyor mu, yoksa onu sonraya mı bırakıyor?",kind:"text",maxLength:160,optional:!0,suggestions:["İşin kendisini gerçekten denemek","En küçük adımımı anlamlı tutmak","Sadece gerçekte ne yaptığımı anlatmak"]},why:{id:"identity-4-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Son denemene bak. James Clear, davranışları bir kimliğe verilen “oylar” diye anlatır. Bu bir benzetme, bilimsel yasa değil. Önce kimliğinin değişmesi gerektiğini söylemeden de bu benzetmeyi kullanabilirsin. Şunu sor: Bu davranış, seçtiğin yol için gereken bir şeyi gerçekten yapmanı sağlıyor mu? Sadece hazırlanıyor olabilir misin?","Taslağı açman, açtığını gösterir. İşe yarayan bir cümle yazman, yazdığını gösterir. İkisinin de amacı olabilir. Ama hazırlığa hazırlık de. En küçük adımın haftana sığsın, aynı zamanda bir katkısı olsun. Gerçek bir denemeden sonra sadece o denemenin kanıtını anlat. “Bir cümle yazdım” demek için özgüveninin kalıcı olarak değiştiğini iddia etmen gerekmez."],example:{title:"Leyla işe yarayan en küçük adımı seçiyor",text:"Cuma günü Leyla beş dakika başlıkları düzenliyor. Rapora hâlâ metin yazmadı. Denemesine bakıp en küçük adımı bir başlığın altına işe yarayan tek bir cümle yazmak olarak değiştiriyor. Bırakmadan önce onu yazıyor. Cümlenin düzeltilmesi gerekiyor. İsteğe bağlı notuna “Artık disiplinli bir insanım” yerine “Bugün bir cümle yazdım” diyor."}},move:{invitation:"Kaydettiğin en küçük adıma bak. Sadece hazırlıksa adını dürüstçe koy veya asıl davranışı denemeyi seç.",instructions:["Seçtiğin yolun gerektirdiği davranışın işe yarayan küçük bir kısmını yap.","Ardından yalnızca gerçekten tamamladığın davranışı anlat."],prompts:[],suggestions:{action:["Rapora işe yarayan tek bir cümle yaz","Seçtiğim beceriyi gerçekten bir kez dene","Düzeltmek için saygılı bir cümle kullan"],minimum:["İşe yarayan tek bir cümle ekle","Bir beceri denemesini tamamla","Kendi davranışımı gerçekten bir kez düzelt"],cue:["Üzerinde çalıştığım taslağı açtığım anda","Bir sonraki uygulama anım geldiğinde","Kendi davranışımı güvenle düzeltebildiğim anda"],place:["Üzerinde çalıştığım asıl taslağın içinde","Genellikle pratik yaptığım yerde"],fallback:["İşe yarayan bir cümleyi sesle yazdır","Asıl denemeyi daha küçük bir adımla yap","Hazırlık yaptıysam bunu hazırlık olarak kaydet"],observation:["Gerçekten tamamladığım davranış","En küçük adımımın istediğim yola katkısı","Hangi hazırlıkların hâlâ beklediği"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Rapora işe yarayan tek bir cümle yaz",minimum:"İşe yarayan tek bir cümle ekle",minutes:2,cueHint:"Üzerinde çalıştığım taslağı açtığım anda",placeHint:"Üzerinde çalıştığım asıl taslağın içinde",obstacleHint:"Asıl davranışı yapmak yerine hazırlanmak daha kolay geliyor.",fallbackHint:"İşe yarayan bir cümleyi sesle yazdır",observationHint:"Gerçekten tamamladığım davranış"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-4-decision",scenario:"Leyla yorgun. Beş dakikası var ve rapora metin yazmak istiyor. Başlıkları hazır. Sıradaki cümlede kullanacağı sayı da kaynağıyla zaten uyuşuyor.",question:"Hangi en küçük adım şimdi yararlı bir iş çıkarır?",options:[{id:"identity-4-organize",text:"Yarın yazmaya başlaması daha kolay olsun diye elindeki notları daha açık bir klasör düzenine göre yeniden yerleştirsin.",feedback:"Düzenlemek sonraki yazma işini destekleyebilir. Burada ise notlar ve başlıklar zaten hazır. Daha fazla hazırlık, Leyla’nın çalışmak istediği beceriyi erteliyor. Yine de bunu seçerse adını hazırlık olarak koysun."},{id:"identity-4-write-unit",text:"Asıl rapora bir taslak cümle yazsın. Sonra o anki gücüne göre durmanın uygun olup olmadığına karar versin.",feedback:"Bu küçük adımda istediği davranışı uyguluyor, elindeki zamanı kullanıyor. Tek bir cümle yazıldığını kanıtlıyor. Kimliğinin değiştiğini değil. Cümleyi etkileyici hâle getirmek zorunda olmadan çalışmayı bırakabilir."},{id:"identity-4-verify-support",text:"Kaynak gösterdiği sayıyı yeniden kaynağından kontrol etsin. Yarın yazacağı cümle için doğrulanmış bir not bırakıp bugün çalışmayı bitirsin.",feedback:"Bilginin dayanağı belirsizse doğrulamak yararlıdır. Bu sayı zaten kontrol edildi. Aynı hazırlığı tekrarlamak bu akşamki yazma zamanını tüketir. Dayanağı olan tek bir taslak cümle, raporu şimdi ilerletebilir."}],bestOptionId:"identity-4-write-unit"}},carry:{takeaway:"Kanıtın, yaptığın davranışı anlatsın. Hazırlık ile uygulamayı birbirinden ayrı tut.",followUp:{questionId:"identity-4-return",question:"En küçük adımın gerçekte neyi gösterdi? Seçtiğin yola bir katkısı oldu mu?",observationPrompt:"En küçük adımının gösterdiği davranışı ve istediğin yola katkısını anlat.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Kimlik benzetmesinin sınırları var",paragraphs:["Clear’ın kendi yazısı, istenen bir kimliği ve onu destekleyen küçük davranışları uygulamaya dönük bir çerçeve olarak sunar [I15]. Önce kimliği değiştirmenin gerekli veya üstün olduğunu kanıtlayan kontrollü bir deney değildir. Davranışı oy gibi anlatmak akılda kalabilir. Ama akılda kalması, onu bilimsel bir açıklamaya dönüştürmez. Bu benzetmeyi kullanmak senin seçimin olarak kalır.","Bandura’nın öz yeterlik çerçevesi, belirli bir işi yapabileceğine dair beklentiyi anlatır [I17]. Kendi başardıkların bu inancın kaynaklarından biridir. Başkalarını gözlemek, cesaretlendirilmek ve bedenden gelen bilgiler de buna katkı sağlar. Bu çerçeve tek bir davranışı insan olarak değerinin ölçüsüne dönüştürmez. Bütün kişiliğin hakkında verilmiş bir hüküm de saymaz.","ODA’nın isteğe bağlı kanıt cümlesi sınırlı kalır: “İşe yarayan bir cümle ekledim” veya “İsteğimi ilettim.” Denenmemiş bir plan ve karar sorusuna verilen doğru yanıt bu davranışların yapıldığını göstermez. Kimliğinle ilgili hiçbir cümle kurmadan da aynı somut denemeye devam edebilirsin. Kaydın, yaptığını anlatmaya yeter."]},{heading:"Davranış ve kimlik farklı sonuçlardır",paragraphs:["Rhodes ve arkadaşları, 4.939 yetişkini kapsayan 40 deneysel veya yarı deneysel etkiyi inceledi [I19]. Fiziksel etkinliğe ilişkin kimlik, ortalama olarak az değişti: etki g = 0,18’di. Davranışın incelendiği 30 etkilik alt örneklemde fiziksel etkinlik için daha büyük bir ortalama etki bulundu. Ama örneklemler ve sonuçlar farklı. Bu sayılar, davranışın değişmesine kimliğin neden olduğunu kanıtlamaz.","Çalışmalar fiziksel etkinlikle ilgili. Sonuçlar farklılık gösteriyor ve yayın yanlılığı olası. Bütün kişiliğin dönüşmesini, Clear’ın oy yöntemini veya bu rapor yazma denemesini doğrulamıyorlar. Zorlanman da hedefin mutlaka peşinden gitmeye değer olduğunu göstermez. Bir beceri eksiğini, yetersiz kaynakları veya planı değiştirmen gerektiğini gösterebilir. Güçlüğün kendisi devam etme zorunluluğu yaratmaz.","En küçük adımının neye katkı sağladığını kaydına bakarak seç. Gücüne uyuyorsa küçük kısmı koru. Ancak kendi isteğinle büyüt veya uymayan hedefi değiştir. Amaç hayatında işe yarayan bir uygulama yapmak. Sembolik oylar biriktirmek değil."]}],sourceIds:["identity-clear-identity","identity-task-belief","identity-activity-identity"]}},{schemaVersion:2,revision:2,id:"identity-5",courseId:"identity",locale:"tr",title:"Yeterince prova yaptın mı? Şimdi gerçekte dene",goal:"İşine yarayacaksa kısa bir hazırlıkla tek bir engeli ele al. Ardından seçtiğin aynı davranışı dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kusursuz başlangıcı hayal etmek, başlamanın yerini mi alıyor? Hazırlığın sonunda gerçekten bir deneme yap.",reason:{id:"identity-5-reason",label:"Kısa bir prova, hangi engelle karşılaştığında sana yardımcı olabilir?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek başlama anıma hazırlanmak","Kusursuz yapmadan önce bir kez denemek","Prova ile gerçek davranışı ayrı tutmak"]},why:{id:"identity-5-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Prova hazırlıktır. Asıl davranışın kendisi değildir. Davranışı hayal etmeye dair araştırmalarda ortalama bir davranış yararı bulundu. Ama hangi hayal etme biçiminin daha iyi olduğu netleşmedi. Sonucu hayal etmek yerine adımları hayal etmenin üstün olduğunu kanıtlamıyor. Belirli süre yapılan bir kimlik meditasyonunun kişiliğini değiştirdiğini de göstermiyor. Hazırlık ile gerçekte yaptığını ayrı değerlendirmek gerekir.","Kaydında bir hazırlık eksiği varsa provayı kullan. İlk adımı ve çıkabilecek bir engeli anlat veya hayal et. Sonra davranışını gerçek başlama anında dene. Gözünde canlandırmak rahatsız ediyorsa veya bunu yapamıyorsan sözcükleri kullan ya da bu kısmı atla. Hazırlığı ayrı kaydet. Denemen pek akıcı olmayabilir. Sonucu da hâlâ belirsizdir."],example:{title:"Leyla’nın ilk cümlesi kusursuz değil",text:"Pazartesi rapor çalışmasından önce Leyla nasıl başlayacağını anlatıyor: son cümlesini okuyup kulağa acemi işi gelse de bir cümle ekleyecek. Gözleri açıkken kısaca bu geçişin provasını yapıyor. Öğle yemeği sonrası başlama anında cümleyi ekliyor. Hayal ettiğinden daha az akıcı. Kısa hazırlığını ve gerçekte yazdığı cümleyi ayrı ayrı kaydediyor."}},move:{invitation:"Hazırlık yardımcı olacaksa kısa tut. Denemenin kaydına, gerçekte yaptığın işi yaz.",instructions:["İlk yararlı adımın provasını yalnızca gerekiyorsa yap.","Gerçek başlama anında dene. Yaptığın hazırlığı ayrı kaydet."],prompts:[],suggestions:{action:["Asıl taslağıma sıradaki cümleyi ekle","Hazırladığım adımı bir kez dene","Seçtiğim küçük uygulamayı tamamla"],minimum:["Taslağın içine tek bir cümle yaz","Seçtiğim anda belirlediğim adımı at","Gerçek uygulamanın küçük bir kısmını bitir"],cue:["Öğle yemeğinden sonra yazmaya başladığım anda","Provasını yaptığım başlama anı geldiğinde","Her zamanki başlama işaretim ortaya çıktığında"],place:["Üzerinde çalıştığım asıl taslağın içinde","Genellikle güvenle adım attığım yerde"],fallback:["Provayı atla, işe yarayan bir cümle yaz","Sözcüklerle hazırlan, öğle yemeği sonrasında dene","Eksik olan becerim için yardım iste"],observation:["Gerçek denemede ne olduğu","Beklediğim engelin ortaya çıkıp çıkmadığı","Yalnızca hazırlık olan kısım"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Asıl taslağıma sıradaki cümleyi ekle",minimum:"Taslağın içine tek bir cümle yaz",minutes:2,cueHint:"Öğle yemeğinden sonra yazmaya başladığım anda",placeHint:"Üzerinde çalıştığım asıl taslağın içinde",obstacleHint:"Asıl davranışa başlamak yerine tekrar tekrar prova yapıyorum.",fallbackHint:"Provayı atla, işe yarayan bir cümle yaz",observationHint:"Gerçek denemede ne olduğu"},stopRule:"Travma içeren sahneleri atla. Sıkıntı veren canlandırmayı durdur. Sözcükleri, desteği veya doğrudan güvenli bir denemeyi seç.",accessibleAlternative:"Gözlerini açık tut veya canlandırmayı atla. Sözcüklerle hazırlanmak için “Bunu uyarla” seçeneğini kullan. Gerçekte ne zaman deneyeceğini belirt."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-5-decision",scenario:"Leyla raporun ilk noktasını ve nasıl yazacağını biliyor. On dakikası var. Kendinden emin bir çalışma hayal etmesi, son iki kez başlamasını geciktirdi.",question:"Hazırlık ile uygulamayı hangi seçim daha iyi bağlar?",options:[{id:"identity-5-direct-attempt",text:"Daha fazla prova yapmadan rapora başlama anında tek bir cümle eklesin. Başlarken gerçekten nerede zorlandığını kaydetsin.",feedback:"Kaydı, sorunun ilk adımı bilmemesi değil, provayı uzatması olduğunu gösteriyor. Bildiği cümleyi denemek bu engeli ele alır. Belirli bir hazırlığın yararlı olup olmayacağına karar vermeden önce gerçek denemenin gösterdiği zorluğu kaydet."},{id:"identity-5-timed-process",text:"İki dakika boyunca sorunsuz bir başlangıcın provasını yapsın. Ardından çalışma zamanı bitmeden raporuna tek bir cümle yazsın.",feedback:"Süreli prova hazırlığı bitirir ve tanımadığın bir adımı netleştirebilir. Leyla bu adımı zaten biliyor. Prova iki başlangıcını geciktirdi. Doğrudan uygulama, kaydın gerçekten gösterdiği sorunu sınar."},{id:"identity-5-timed-outcome",text:"Bir dakika raporu bitirdiğini hayal etsin. Sonra tek bir cümle yazıp başlamasına neyin yardımcı olduğunu kaydetsin.",feedback:"Bu seçim, gerçek bir deneme yapmayı içeriyor. Araştırmalar da üstün bir canlandırma biçimi belirlemiyor. Ama burada isteksizlikten kaynaklanan bir eksik görülmedi. Daha fazla canlandırmayı atlamak, Leyla’nın tekrar eden hazırlık gecikmesine daha doğrudan yanıt verir."}],bestOptionId:"identity-5-direct-attempt"}},carry:{takeaway:"Yararlı provanın bir bitişi, ardından da gerçekten deneyebileceğin bir fırsatı vardır.",followUp:{questionId:"identity-5-return",question:"Hazırlığınla seçtiğin başlama anında yaptığın deneme arasında ne farklıydı?",observationPrompt:"Hazırladığınla o anda olanı karşılaştır. Hazırlığı atlaman da geçerli bir seçim.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Üstün olduğu gösterilmiş bir canlandırma biçimi yok",paragraphs:["Cole ve arkadaşları 94 rastgele kontrollü çalışmayı, 123 etkiyi ve 5.685 katılımcıyı birleştirdi [I03]. Zihinsel canlandırmanın genel davranış etkisi g = 0,49’du. Bazı alt türlerin tahminleri sayısal olarak daha büyüktü. Ama alt türlerin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı. Yalnızca süreci hayal eden alt grup sadece beş etki içeriyordu. Bu grubun sonucu belirsizdi.","Örneklemlerin çoğu öğrencilerdi. Birçok çalışma yanlılık hakkında sınırlı bilgi verdi. Derleme, üstün bir canlandırma türü, daha uzun uygulamanın yararı veya on dakikalık meditasyonla kimlik değişimi belirlemiyor. Bu dersin kısa hazırlığı, seçilmiş bir tasarımdır. İncelenen araştırma uygulamasının kendisi değildir. Araştırmanın genel sonucunu bu kısa hazırlığın garantisi gibi kullanamayız.","Gerçek hazırlık eksiğine göre sözcükleri, canlandırmayı veya hiç prova yapmamayı seç. İşe yarayan ilk adımı tarif etmek, kusursuz bir gelecek sahnesinden daha kolay değerlendirilebilir. Kursun kaydı yine de şunu sormalı: o adımı gerçek ortamda denediğinde ne oldu? Hazırlanmış olman tek başına bu soruyu yanıtlamaz."]},{heading:"Gerçekte yapacağın işe hazırlan",paragraphs:["Toth ve arkadaşlarının 37 çalışmalık derlemesi, hareket becerileri ve görev performansıyla ilgiliydi [I18]. Yanlılığa göre düzeltilmiş küçük bir zihinsel prova etkisi bildirdi: r = 0,131. Bu kanıt, duyguların biyolojisinin değiştiğini, hastalıkların iyileştiğini veya bütün kimliğinin dönüştüğünü göstermez. Prova bir işi destekleyebilir. Yönergenin, malzemelerin veya gerçekten uygulama yapmanın yerini tutmaz.","Belirli “şu olursa bunu yaparım” planları için farklı testlerden, hedefe ulaşmaya dair daha geniş destek var [I01]. Bu ODA denemesinde gerçek bir başlama anını zaten seçtiğin davranışla birleştir. Provayı yalnızca ne yapacağını netleştirmek için kullan. İlk rapor cümlene hazırlanmak ve onu yazmak farklı davranışlardır. Birinden diğerinin de yapıldığını çıkarma.","Travma veya sıkıntı veren anılar içeren sahneleri atla. Gözlerini açık tutabilir, adımları görüntüsüz anlatabilir, yardım kullanabilir veya doğrudan güvenli bir denemeye geçebilirsin. Hazırlık uzayıp duruyorsa onu küçült. Bunun için bir sabah ritüeli daha eklemen gerekmiyor. Hazırlığın ne zaman biteceği belli kalsın."]}],sourceIds:["identity-cole","identity-motor-rehearsal","identity-gollwitzer"]}},{schemaVersion:2,revision:2,id:"identity-6",courseId:"identity",locale:"tr",title:"Başlama anı hep kayıyor mu? Bir koşulu değiştir",goal:"Kayıtlarına bak. Tek bir başlama anını veya malzemeyi değiştir, sonra aynı yararlı davranışı dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kurduğun güzel düzende başlama anı hiç gelmiyorsa ne işe yarar? Bugün tek bir koşulu dene.",reason:{id:"identity-6-reason",label:"Bu davranışa yer açmak için şu an işini kolaylaştıran hangi düzeni değiştireceksin?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçekten gelen bir başlama anını kullanmak","Gereken malzemeyi yakınımda hazır tutmak","Dikkat dağılmasını azaltırken acil iletişimi korumak"]},why:{id:"identity-6-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Yaptığın denemelerin kaydına dön. Seçtiğin an geldi mi? Malzemeler elinin altında mıydı? Belirli bir plan, varsaydığı durum hiç gerçekleşmediğinde aksayabilir. “Şu olursa bunu yaparım” planları ortalama olarak yardımcı olur. Ama başlama anının haftana uyması gerekir. Kâğıt üzerinde açık olması, gerçek hayatında da oluşacağını göstermez.","Alışkanlık araştırmaları, tekrar eden davranışları tekrar eden ortamlarla ilişkilendirir. Çevrenin seçimlerinden güçlü olduğunu ilan etmeden tek bir koşulu değiştir. Davranışını koru. Malzemeyi kullanacağın yere taşı veya güvenilir bir olay seç. Bir kez dene. Hangi adımda ilerledin, nerede takıldın, kaydet. Gerekli araçlara erişimini, acil iletişimi ve ihtiyacın olan düzenleri koru."],example:{title:"Leyla’nın çay molası bir türlü gelmiyor",text:"Leyla öğleden sonraki çaydan sonra yazmayı planladı. Ama toplantılar yüzünden molayı tekrar tekrar veremedi. Yalnızca başlama anını değiştiriyor: öğle yemeğinden dönünce masasında hazır bekleyen raporu açıp bir cümle yazacak. Ailesi ulaşabilsin diye telefonu erişilebilir tutuyor. Salı günü seçtiği an geliyor, cümlesini yazıyor. Cümlenin sonunu hâlâ düzeltmesi gerekiyor."}},move:{invitation:"Tek bir kayda bakarak aksayan bir koşulu değiştir. Mevcut davranışını yeni başlama anında dene.",instructions:["Gerçekten karşılaştığın olaylardan birini başlama anı, birini yedek olarak seç.","Bir başlama anını veya malzemeyi değiştir. Sonra yararlı en küçük adımı dene."],prompts:[],suggestions:{action:["Yeni seçtiğim başlama anında yaz","Hazır malzememin yanında uygulama yap","Güvenilir başlama anında seçtiğim davranışı dene"],minimum:["Bu anda işe yarayan bir cümle ekle","Gerçek uygulamanın tek bir kısmını tamamla","İşe yarayan tek bir adım at"],cue:["Öğle yemeğinden döndüğüm anda","Gerekli bir günlük işimi bitirdiğim anda","Bir sonraki güvenilir görüşme anımda"],place:["Hazır bekleyen kendi taslağımın yanında","Erişebildiğim, adımı atabileceğim yerde"],fallback:["Sonraki toplantıdan sonra masamda bir cümle yaz","Elimdeki araçla cümleyi sesle yazdır","Acil arama ve mesajlara erişimi açık tut"],observation:["Yeni seçtiğim başlama anının gelip gelmediği","Gereken malzemenin hazır olup olmadığı","Neyin işe yaradığı, neyin engel çıkardığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Yeni seçtiğim başlama anında yaz",minimum:"Bu anda işe yarayan bir cümle ekle",minutes:2,cueHint:"Öğle yemeğinden döndüğüm anda",placeHint:"Hazır bekleyen kendi taslağımın yanında",obstacleHint:"İlk seçtiğim başlama anı çoğu zaman gelmiyor.",fallbackHint:"Sonraki toplantıdan sonra masamda bir cümle yaz",observationHint:"Yeni seçtiğim başlama anının gelip gelmediği"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-6-decision",scenario:"Leyla’nın çay molası sık sık iptal oluyor. Öğle yemeğinden dönme anı ise hâlâ var. Raporu masasında hazır tutabilir.",question:"Önce hangi değişikliği denemeye değer bulursun?",options:[{id:"identity-6-earlier-clock",text:"Çaydan sonra başlama planını korusun. Molaya zaman ayırabilmek için saatli hatırlatma kursun. Ardından rapora tek bir cümle yazsın.",feedback:"Hatırlatma fark etmeye yardımcı olabilir. Ama gerçekleşmeyen çay molasını ortaya çıkarmaz. Kayıt, sorunun o anın oluşmaması olduğunu gösteriyor. Başka bir hatırlatma eklemeden önce güvenilir dönüş anını dene."},{id:"identity-6-ready-tea-draft",text:"Çaydan sonra başlama planını korusun. Taslağı fincanının yanına koysun. Sonra çayını bitirdiğinde rapora tek bir cümle yazsın.",feedback:"Taslağa ulaşmak zorsa yerini değiştirmek yardımcı olur. Burada mola sürekli iptal oluyor. Taslak zaten hazır bekleyebilir. Onu başka yere koymak, eksik başlama anını ortaya çıkarmıyor. Asıl aksayan koşul aynı kalıyor."},{id:"identity-6-reliable-event",text:"Öğle yemeğinden dönmeyi başlama anı seçsin. Taslağı hazır tutsun. O anda işe yarayan tek bir cümle yazmayı denesin.",feedback:"Bu seçim, planın hangi noktada aksadığını dikkate alıyor. Davranış aynı kalıyor, başlama anı zaten gerçekleşiyor. Malzeme hazır mıydı, cümle gerçekten yazıldı mı, kaydet. Yeni plan bunları kendiliğinden olmuş saymaz."}],bestOptionId:"identity-6-reliable-event"}},carry:{takeaway:"Kaydının gösterdiği koşulu düzelt. Daha fazla kural eklemeden önce bir kez dene.",followUp:{questionId:"identity-6-availability-return",question:"Yeni seçtiğin başlama anı gerçekten geldi mi?",observationPrompt:"Malzeme hazır mıydı? Ne işe yaradı, önüne ne çıktı?",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Belirli bir plan, her zaman yapılabilir değildir",paragraphs:["Gollwitzer ve Sheeran’ın meta-analizi, belirli durum ve davranış planlarını ortalama olarak destekliyor [I01]. Tek bir ideal günlük düzeni değil, farklı hedefleri, örneklemleri ve yöntemleri kapsıyor. “Çaydan sonra yaz” belirli bir plan. Ama belirli olması, çayı senin haftanda güvenilir bir olay yapmaz. Planın mümkün olup olmadığına bakmak ve gerçekten bir kez denemek hâlâ gerekir.","ODA’nın yeni başlama anı denemesi, kendi kaydının gösterdiği koşulu değiştirir. Seçtiğin an hiç gelmediyse tanıyabileceğin başka bir olay dene. An geldiyse ama malzemeler eksikse onları hazır et. Yapacağın iş fazla geliyorsa miktarını değiştir. Ortada yokken isteksizlik sorunu uydurma. Her aksaklığa aynı yanıtı vermek yerine gerçekte hangi noktada aksadığını bul.","Bu, eğitim için bir uyarlamadır. Üç engel planının veya adı olan bir alışkanlık birleştirme yönteminin gerekli olduğuna dair kanıt değildir. İlk öneriler, düzenlenebilir örnek bir plan oluşturur. Ancak koşullarına uyanı seçip kaydettiğinde senin yapmaya karar verdiğin plan olur. Hazır öneri tek başına söz verdiğin anlamına gelmez."]},{heading:"Ortam uygulamayı destekler, her şeye karar vermez",paragraphs:["Wood ve Rünger, benzer ortamlarda tekrar eden davranışların gelişmesini anlatır [I06]. Alışkanlıklar ve bilinçli süreçler birlikte işleyebilir. Bu anlatı derlemesi, ortam değişikliklerinin her zaman çabadan üstün olduğu evrensel bir sıralama kurmaz. Her nesnenin sessizce sıradaki seçimini belirlediğini de kanıtlamaz. Çevreyi bir destek olarak görmek, bütün seçimlerini ona bağlamak değildir.","Bu denemede malzemenin yeri, kontrol edebileceğin somut bir koşul. Raporu çalışma masanın yakınında tut veya iletişim için kullandığın aracı konuşacağın yerde hazır tut. Bedelini de belirt: telefonu uzağa koymak ona kolayca ulaşmanı zorlaştırabilir. Ama acil iletişim veya engellilik nedeniyle gereken destekler başka bir düzen gerektirebilir. Bu ihtiyaçları hazırlık uğruna ortadan kaldırma.","Tek bir koşulu değiştirmek, sonraki kaydını yorumlamayı kolaylaştırır. Yeni anın da uymadığını görmek işe yarayan bir sonuç olabilir. Hazırlığı tamamlanmış uygulama saymak yerine bu gerçeği koru. Yaptığın hazırlığı dürüstçe kaydedebilirsin. Asıl davranış için başka zaman seçebilir veya onu uyarlayabilirsin. Bir koşulun değişmesi, davranışın yapıldığı anlamına gelmez."]}],sourceIds:["identity-gollwitzer","identity-wood-runger"]}},{schemaVersion:2,revision:2,id:"identity-7",courseId:"identity",locale:"tr",title:"Birkaç gün yapamadın mı? Gücüne göre yeniden başla",goal:"Aynı denemeye dönüp bak. Gelecek hafta için yapabileceğin uygulama, destek veya toparlanma adımlarını seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Her gün yapamadın. Sıradaki planın hayatına mı yarıyor, yoksa sadece sayıyı mı düzeltiyor?",reason:{id:"identity-7-reason",label:"Bu denemeye haftanda hâlâ yer ayırmak istiyor musun?",kind:"text",maxLength:160,optional:!0,suggestions:["İşe yarayan kısmı aynı şekilde korumak","Yapacağım işi gücüme göre küçültmek","Telafi işi eklemeden dinlenip toparlanmak"]},why:{id:"identity-7-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sık duyduğun 66 gün, bir davranışın ne kadar otomatikleştiğini tahmin ediyordu. İnsanların değişmeyi bitirdiği bir tarih değildi. Tahminler çok farklıydı. Bazıları araştırmanın gözlem süresinin ötesine uzanıyordu. Kendi davranışının ne zaman kolay gelmesi gerektiğini bu sayılardan çıkaramazsın. Onları kişisel bir bitiş tarihi olarak kullanma.","Aynı denemeye bak: yararlı davranışın, başlama anın, gerçek denemelerin ve ilgilenmen gereken koşul. Gücüne uyan bir fırsat seç. Tekrarla, küçült, yardım iste, dinlen veya artık sana katkısı olmayan hedefi bırak. Kursu bitirdiğini kanıtlamak için yeni bir ritüel ekleme. Yapamadığın günleri telafi etmek üzere kendine borç da yükleme."],example:{title:"Leyla daha küçük bir adımla dönecek",text:"Hastalık sonrası Leyla’nın rapor denemesinde üç gün uygulama yok. Yazdığı cümlelere ve işe yarayan öğle yemeği sonrası başlama anına bakıyor. Hâlâ bitkin. Bugün toparlanmayı, yarın durumuna tekrar bakmayı seçiyor. Tek bir cümlenin uygun olup olmadığına o zaman karar verecek. Boş günleri yeniden yazmak veya telafi seansı sözü vermek yerine verdiği arayı dürüstçe kaydediyor."}},move:{invitation:"Aynı denemeni gözden geçir. Sıradaki uygun fırsatı seç veya ara verip dönüş tarihini kaydet.",instructions:["Yararlı davranışı koru. Yalnızca kayıtlarının gerektirdiği değişikliği yap.","Gelecek hafta ne kadarını yapacağını ve başlama anını seç. Yapamadığın günler için telafi işi ekleme."],prompts:[],suggestions:{action:["İşe yarayan en küçük adımımı tekrar at","Anlamlı, daha küçük bir kısmı dene","Bu denemem için somut destek iste"],minimum:["İşe yarayan tek bir cümle yaz","Yapabildiğim küçük bir uygulamayı tamamla","Somut bir ihtiyaç için destek iste"],cue:["Öğle yemeğinden döndüğüm bir sonraki uygun anda","Gücüm güvenli bir denemeye yettiğinde","Destek için seçtiğim görüşme başladığında"],place:["Genellikle kullandığım, erişebildiğim yerde","Güvenle destek isteyebildiğim bir konuşmada"],fallback:["Ara ver, yeniden bakmak için tarih seç","Asıl denemeyi daha küçük bir adımla yap","Önümdeki kısıt için somut yardım iste"],observation:["Davranışımın istediğim hayata katkısı","Şu anki gücüme neyin uyduğu","Yeniden başlamama hangi koşulun yardımcı olduğu"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşe yarayan en küçük adımımı tekrar at",minimum:"İşe yarayan tek bir cümle yaz",minutes:2,cueHint:"Öğle yemeğinden döndüğüm bir sonraki uygun anda",placeHint:"Genellikle kullandığım, erişebildiğim yerde",obstacleHint:"Denemediğim günleri telafi etmek istiyorum.",fallbackHint:"Ara ver, yeniden bakmak için tarih seç",observationHint:"Davranışımın istediğim hayata katkısı"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-7-decision",scenario:"Leyla hastayken uygulama yapmadı. Hâlâ bitkin. Kaydı, öğle yemeği sonrası başlama anının daha önce işe yaradığını gösteriyor.",question:"Hangi yeni plan gördüklerine ve bugünkü gücüne uyar?",options:[{id:"identity-7-preserve-volume",text:"Düzeni bozmamak için bugün aynı başlama anını kullansın. Her zamanki miktarda yazıyı daha yavaş yazarak tamamlasın.",feedback:"Gücü geri geldiğinde tanıdık bir an yardımcı olabilir. Ama bitkinliği geçersiz kılmaz. Kayıt, başlama anını destekliyor. Bugün her zamanki miktarı yazmasını değil. Toparlanmak ve tarih seçip yeniden değerlendirmek uygun olabilir."},{id:"identity-7-reassess-capacity",text:"Bugün dinlensin. Gücüne yeniden bakacağı bir tarih seçsin. Uygun olduğunda daha küçük, yararlı bir adımla geri dönsün.",feedback:"Bu seçim toparlanmayı başarısızlık saymadan yararlı denemeyi koruyor. Yazmış gibi davranmak yerine, yeniden karar vereceği bir tarih seçiyor. Sıradaki deneme, Leyla’nın o anda gerçekten sahip olduğu güce uymalı. Eski plan bu kararı onun yerine vermez."},{id:"identity-7-catch-up",text:"Bu haftaki ilk toplam hedefi yine tutturmak için yapamadığı işleri hafta sonundaki daha uzun bir çalışma zamanına taşısın.",feedback:"Gerçek bir ihtiyaç için daha sonraki çalışma seçilebilir. Ama kaçırılan uygulama bilimsel bir telafi zorunluluğu yaratmaz. Daha büyük iş toparlanmaya uymayabilir. Sıradaki adımı büyütmeden önce o andaki gücünü yeniden değerlendir."}],bestOptionId:"identity-7-reassess-capacity"}},carry:{takeaway:"Yararlı denemeni koru, koşullarına uymayan kısmını değiştir. Bambaşka biri olmak için kendine son tarih koymadan geri dön.",followUp:{questionId:"identity-7-return",question:"Seçtiğin dönüş, gücüne ve istediğin yola uydu mu? Sıradaki plan değişmeli mi?",observationPrompt:"Gücüne ve istediğin yola ne uydu? Neyi değiştirmek gerekiyor?",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"O ünlü sayı, otomatikleşmenin model tahminiydi",paragraphs:["Lally ve arkadaşları yeme, içme veya fiziksel etkinlik davranışı seçen 96 gönüllüyü 84 gün izledi [I04]. 82 kişi yeterli veri verdi. 62 model kuruldu, 39’u verilere iyi uydu. Bu modellerde, otomatikleşmenin ulaşacağı sabit düzeyin %95’ine ulaşma süresinin ortancası 66 gündü. Aralık 18-254 gündü. Bu sayılar modelin verdiği tahminlerdi.","Daha uzun süreler gözlemin ötesine uzanan tahminlerdi. Araştırma herkesin “alışkanlığı bitirmesini” izlemedi, yeni kişilik ölçmedi veya üst üste iki gün kaçırma kuralını sınamadı. Analizde tek kaçırılan fırsat, oluşumu belirgin biçimde değiştirmedi. Bu sonuç daha uzun aralar için evrensel bir yeniden başlama kuralı kuramaz. Tek fırsatla uzun arayı aynı bulgu sayamayız.","Daha sonraki 20 sağlık davranışı çalışmasını kapsayan derleme de büyük farklılıklar buldu [I05]. Yalnızca dört çalışma oluşma sürelerini bildirdi. On bir çalışmada yanlılık riski yüksekti. İki kaynak da yazmanın, dinlemenin veya ODA’da seçtiğin başka bir davranışın ne zaman otomatikleşmesi gerektiğini söylemez."]},{heading:"Yeni ritüel eklemek yerine elindeki kayıtları toparla",paragraphs:["Harkin ve arkadaşları, ilerleme takibini artıran uygulamaları 138 rastgele kontrollü çalışmada inceledi [I02]. Hedefe ulaşma ortalama olarak arttı. Yanlılığa göre düzeltilmiş tahmin daha küçüktü. Yöntemler ve hedefler farklıydı. Derleme, on beş dakikalık haftalık değerlendirmenin, kesintisiz gün sayısının veya gelecekteki kendine mektup yazmanın en iyi biçim olduğunu göstermiyor. Buradan tek bir zorunlu düzen çıkmaz.","Bu kursun sonunda kayıtları topluca değerlendirmek, ODA’nın tasarım seçimi. Aynı denemenin kayıtlarını oku. Gerçek denemeleri planlardan ve aralardan ayır. Korumaya değer koşulu belirle. Gelecek için plan yapmak, davranışı tamamlamış olmak değildir. Ne olduğunu söyleyene kadar eksik kayıtlar bilinmeyen olarak kalır. Onları kendiliğinden başarı veya başarısızlık sayma.","Gelecek hafta ne kadarını yapacağını ve hangi olayda başlayacağını ancak deneme hâlâ istediğin hayata katkı sağlıyorsa seç. Destek, toparlanma, sınır koyma veya durma bilinçli yanıtlar olabilir. Adlarını doğru koy. Düşünerek geri dönmek için yeni bir kimlik cümlesi, daha uzun çalışma veya yapamadığın günlerin telafisi gerekmiyor. Yeni planın bugünkü koşullarına uyabilir."]}],sourceIds:["identity-lally","identity-habit-times","identity-harkin"]}}],c=[{id:"identity-1",schemaVersion:2,practice:["Alışık olduğun tek bir an seç. İstediğin yola somut katkısı olacak başka bir davranış dene.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:1,photo:{id:"1519087630026-63fb0dab69bb",alt:"Duvardaki aynada kendi yansımasına bakan kadın"}},{id:"identity-2",schemaVersion:2,practice:["Aynı denemeyi sürdür. İşine yarayacaksa gündelik duygunu adlandır. Sonra seçtiğin davranışı yap.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:2,photo:{id:"1762126242240-cafa01fb1351",alt:"Koltuğa oturup yağmurlu bir pencereden dışarı bakan kişi"}},{id:"identity-3",schemaVersion:2,practice:["Aynı davranışı koru. Durumu geç fark ettiğinde ardından ne yapacağını seç.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:0,photo:{id:"1626257690705-8d62125575b0",alt:"Gündüz şehirdeki yaya yolunda koyu renk ceketle yürüyen adam"}},{id:"identity-4",schemaVersion:2,practice:["Kaydettiğin en küçük adıma bak. Sadece hazırlıksa adını dürüstçe koy veya asıl davranışı denemeyi seç.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:1,photo:{id:"1787154604447-4a62ed6654e3",alt:"Koyu renk başörtüsü ve spor kıyafetleriyle şehirde bir sokakta koşan kadın"}},{id:"identity-5",schemaVersion:2,practice:["Hazırlık yardımcı olacaksa kısa tut. Denemenin kaydına, gerçekte yaptığın işi yaz.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:0,photo:{id:"1600618528240-fb9fc964b853",alt:"Gün batımında ahşap terasta meditasyon yapan kadın"}},{id:"identity-6",schemaVersion:2,practice:["Tek bir kayda bakarak aksayan bir koşulu değiştir. Mevcut davranışını yeni başlama anında dene.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:2,photo:{id:"1675762647949-1b25f669a687",alt:"Ahşap zemin üzerinde duran bir çift beyaz ayakkabı"}},{id:"identity-7",schemaVersion:2,practice:["Aynı denemeni gözden geçir. Sıradaki uygun fırsatı seç veya ara verip dönüş tarihini kaydet.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:1,photo:{id:"1760715160644-7f5939675b68",alt:"Altın rengi çayırlıktaki patikada yürüyen doğa yürüyüşçüleri"}}],p={id:"identity",title:"Yine eski alışkanlığın mı? Bu hafta bir davranışını değiştir",subtitle:"Yedi derste seni aynı davranışa götüren anı bul. İşe yarayan başka bir adım dene, yaptıklarına bakarak onu geliştir.",description:"İstediğin bir şeye yer bırakmayan tek bir davranış seç. Senin için anlamlı başka bir adım dene. Gerçekte ne olduğunu kaydet. Başlama anını, hazırlığı veya aldığın desteği hayatına daha iyi uyacak şekilde değiştir.",outcome:"Anlamlı bir adım, denenmiş bir başlama anı ve haftana uyan dürüst bir yeniden başlama planı.",scope:"Alışık olduğun düşünme, hissetme veya tepki verme biçimini gündelik hayatta değiştirmek isteyen bir yetişkinsen bu kurs sana yol gösterir. Dr. Joe Dispenza ve James Clear’ın fikirlerinden yararlanır. Araştırmanın hangi fikirleri desteklediğini, hangilerini desteklemediğini açıkça belirtir. Terapi değildir. Depresyon, kaygı, travma veya herhangi bir hastalığın tedavisi değildir. Zorlanıyorsan bir sağlık uzmanıyla konuş. Kriz durumunda bulunduğun yerdeki acil yardım numarasını ara.",photo:{id:"1611569518992-0927098278b7",alt:"Yeşil ağaçların arasındaki toprak yolda tek başına yürüyen kadın"},lang:"tr",lessons:s.map((a,e)=>{const l=c[e],i=a.judgment.primary,r=i.options.find(n=>n.id===i.bestOptionId),t=i.options.filter(n=>n.id!==r.id).map(n=>n.text);return t.splice(l.correct,0,r.text),{...l,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${i.scenario} ${i.question}`,options:t,feedback:r.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}})},j=Object.freeze(Object.defineProperty({__proto__:null,COURSE:p,LESSONS_V2:s,SOURCES:g},Symbol.toStringTag,{value:"Module"})),v=[{id:"meaning-frankl",title:"M17 · Viktor Frankl Institute of America · Logoterapi açısından anlam",url:"https://viktorfranklamerica.com/meaning-from-a-logotherapy-perspective/",type:"guidance",finding:"Frankl, anlam bulmanın yollarını bir şey üretmek veya yapmak, bir deneyim yaşamak veya sevmek ve kaçınılmaz acı karşısında isteğe bağlı bir tutum seçmek olarak anlattı.",limitation:"Felsefi ve klinik bir açıklama, deney değil. Acı çekmek şart değil. Bu düşünme çalışması tedavi etkisini göstermez."},{id:"meaning-frankl-history",title:"M18 · Viktor Frankl Institute Vienna · Biyografi",url:"https://www.viktorfrankl.org/biography.html",type:"guidance",finding:"Frankl logoterapiyi Naziler tarafından hapsedilmeden önce geliştirdi. Enstitünün biyografisi hayatını ve çalışmalarını anlatır.",limitation:"Tarihsel yaşantı, psikolojik uygulamanın etkisini göstermez. Acıda anlam bulmanı zorunlu kılmaz."},{id:"meaning-act-values",title:"M19 · Bethay, Weinstein ve Stubbs · ACT stratejileri rehberi (VA MIRECC)",url:"https://www.mirecc.va.gov/MIRECC/VISN16/docs/act-strategies-guide.pdf",type:"guidance",finding:"ACT’de değerler, sürdürdüğün davranışların özellikleridir. Kararlı eylem bunları somut hedeflerle birleştirir.",limitation:"Uzmanlara yönelik model rehberi, deney değil. ODA pusulası ve kısa işleri birer uyarlamadır. Doğrulanmış puan veya bağımsız etki yok."},{id:"meaning-act-trials",title:"M04 · A-Tjak ve arkadaşları · 2015 · ACT meta-analizi",url:"https://doi.org/10.1159/000365764",type:"research",finding:"Klinik açıdan önemli ruhsal veya fiziksel sorunları olan 1.821 kişiyle 39 randomize araştırma, tam ACT programlarını sınadı.",limitation:"Klinik programın bütününe ait kanıt, değerler formunu tek başına sınamaz, kursu doğrulamaz veya yerleşik BDT’ye üstünlük göstermez."},{id:"meaning-sdt",title:"M05 · Ryan ve Deci · 2000 · Öz belirleme kuramı",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Kuram, kişinin benimsediği nedenle davranmasını baskıdan ayırır. Dışarıdan gelen bazı sorumluluklar kişinin benimsediği sorumluluklara dönüşebilir.",limitation:"Kuram makalesi, nedenleri ölçen test değil. Suçluluk, keyif, bedensel enerji ve başkalarının fark etmesi, bir değerin sana ait olup olmadığını belirlemez."},{id:"meaning-sdt-interventions",title:"M06 · Ntoumanis ve arkadaşları · 2021 · Sağlıkta motivasyon çalışmaları",url:"https://eprints.whiterose.ac.uk/id/eprint/155741/",type:"research",finding:"30.088 kişiyi kapsayan 73 sağlık çalışması, benimsediği nedenlerle davranmada ve sağlık davranışında ortalama iyileşmeler buldu. Etkiler farklıydı.",limitation:"58 randomize ve 15 yarı deneysel araştırma, farklı destek programları kullandı. Kısa değerler formu, araştırmada sınanan uygulama değildir."},{id:"meaning-support",title:"M20 · NIMH · Depresyon",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"Süren çökkünlük, umutsuzluk, ilgi kaybı veya günlük işleri yapmakta güçlük, uzman değerlendirmesi ve destek gerektirir. ABD’de 988 üzerinden kriz desteği alınabilir.",limitation:"Tek başına anlam kaybı depresyon tanısı koydurmaz. ODA eğitim desteğidir. Depresyonu tedavi edemez veya akut krizi yönetemez."},{id:"meaning-carrillo",title:"M09 · Carrillo ve arkadaşları · 2019 · Best Possible Self meta-analizi",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"2.909 kişiyi kapsayan 29 araştırma, iyi oluşta, olumlu duygularda ve iyimserlikte ortalama iyileşmeleri destekledi. Olumsuz duygu ve depresyondaki azalmalar gösterilmedi.",limitation:"Olumsuz duygular ve depresyon için hesaplanan iki güven aralığı da sıfırı içeriyordu. Depresyonu yalnızca üç araştırma ölçtü. Yöntemler farklı, sonuçlar çoğunlukla kısa vadeli. Anlam veya gelecekte gerçek başarı gösterilmedi."},{id:"meaning-best-possible-self",title:"M10 · King · 2001 · Hayat hedefleri hakkında yazmak",url:"https://doi.org/10.1177/0146167201277003",type:"research",finding:"81 üniversite öğrencisi dört yazma koşuluna rastgele atandı. Geleceği yazma görevi, art arda dört gün, her gün 20 dakika sürdü.",limitation:"İlk görev, ODA’nın kısa ve değerlerine bağlı uyarlamasını sınamadı. Daha çok anlam, hastalığı önleme veya geleceğin gerçekten gerçekleşmesi gösterilmedi."},{id:"meaning-planning",title:"M11 · Gollwitzer ve Sheeran · 2006 · Belirli durumda yapılacak işi planlamak",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 kişiyi kapsayan 94 bağımsız test, belirli durumu istenen yanıtla birleştiren planların hedefe ulaşmaya ortalama faydasını destekledi.",limitation:"Deneysel ve ilişkisel testler birlikteydi. Koşullar farklıydı. Plan yapmak iş yapmak değildir. Derleme, anlam artışını veya ODA’nın bu birleşik akışını doğrulamadı."},{id:"meaning-mental-contrasting",title:"M13 · Wang, Wang ve Gai · 2021 · Zihinsel karşılaştırma ve planlama",url:"https://www.frontiersin.org/articles/10.3389/fpsyg.2021.565202/pdf",type:"research",finding:"21 makaleden, 15.907 kişiyi kapsayan 24 bağımsız araştırma, hedefe ulaşmada küçük ortalama etki buldu: g = 0,336 [0,229; 0,443].",limitation:"Yayın yanlılığı ve uygulama farkları kesinliği sınırlar. Değerler, gelecek sahnesi ve işten oluşan birleşik uyarlama sınanmadı. Yapısal engeller kişisel başarısızlık değildir."},{id:"meaning-monitoring",title:"M14 · Harkin ve arkadaşları · 2016 · İlerlemeyi takip etmek",url:"https://eprints.whiterose.ac.uk/id/eprint/87431/1/bul%20harkin%20raw%20final.pdf",type:"research",finding:"138 randomize araştırmada takibi artırmak, hedefe ulaşmaya ortalama fayda sağladı: d = 0,40 [0,32; 0,48].",limitation:"Küçük araştırmalarda asimetri bulundu. Duyarlılık analizi d = 0,19 tahmin etti. Hedef ve yöntem farkları, ODA’nın ertesi gün zamanlamasını, anlam etkisini veya zorunlu açık takibi doğrulamaz."},{id:"meaning-habits",title:"M15 · Lally ve arkadaşları · 2010 · Alışkanlık oluşumu",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"84 günlük gözlem araştırması 96 kişiyi takip etti. Modellenen otomatikleşme farklı hızlarda arttı. Tek fırsatı kaçırmanın ölçülen etkisi azdı.",limitation:"Sık anılan 66 gün ortancası ve 18–254 gün aralığı model tahminleridir. Uzun değerler gözlemden ileriye uzatılır. Son tarih, tekrarlayan aralar veya değerlerin otomatikleşmesi hakkında kanıt değildir."}],y=[{schemaVersion:2,revision:2,id:"meaning-1",courseId:"meaning",locale:"tr",title:"Hafta doldu. Önemsediğin şeye sıra geldi mi?",goal:"Seçtiğin bir ilişki veya katkı için bugün işe yarayan küçük bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"İş, ev işleri, telefonda gezinmek... Bir hafta daha mı geçti? Önemsediğin tek bir şeye bugün zaman ayır.",reason:{id:"meaning-1-reason-attention-cost",label:"Bu amaca iki dakika ayırmak için isteğe bağlı hangi işi sonraya bırakabilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Telefonda gezinmeyi sonraya bırakmak","Acil olmayan ev işini ertelemek","Kısa bir konuşmaya zaman ayırmak"]},why:{id:"meaning-1-why",label:"Bu hafta hangi şeye dikkatini ayıracak kadar önem veriyorsun?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Önemsediğin bir şeyi yapmak için önce hayatının büyük amacını bulman gerekmiyor. Frankl’ın felsefesi birkaç olası yol anlatır: üretmek veya yapmak, deneyimlemek veya sevmek, kaçınılmaz zorluk karşısında bir tutum seçmek. Bunlar düşünmek için sorular. Bir sınav veya kanıtlanmış tedavi değil. Zorluk konusunu tamamen dışarıda bırakabilirsin.","Kurs boyunca denemek için katkı sağlayacağın bir işi veya bir ilişkiyi seç. Küçük bir adım atabileceğin gerçek bir fırsat bul, sonra olanı kaydet. Soruyu sorup yanıtı dinlemek bir iş yapmaktır. Kimlerin önemli olduğunu listelemek hazırlıktır. Ruh hâlin aynı kalabilir. Burada gerçekten ne yaptığına bakıyoruz."],example:{title:"Murat akşam yemeğinde soruyor",text:"Salı akşamı yemekte Murat, kızını bütün hafta neredeyse hiç dinlemediğini fark ediyor. Telefonunu kaldırıp fen projesini soruyor. Yanıtı dinliyor. Kızı çıkmadan önce yalnızca iki kısa cümle söylüyor. Murat soruyu sorduğunu ve dikkatini verdiğini kaydediyor. Konuşma kısa sürdü, ama oldu. Kızının uzun uzun anlatması, Murat’ın seçtiği dinleme adımını atmış olması için şart değil."}},move:{invitation:"Seçtiğin ilişki veya katkı için işe yarayan tek bir adım at.",instructions:["Kurs boyunca sürdüreceğin tek bir amaç seç.","Küçük bir işi yap, sonra gerçekte ne olduğunu kaydet."],prompts:[],suggestions:{action:["Telefona bakmadan bir soru sor ve dinle","Proje için işe yarayan tek cümleyi tamamla","Belirli bir konuda yardım etmeyi teklif et"],minimum:["Tek bir soru sorup yanıtını dinle","Kullanılabilecek tek bir cümle yaz","Belirli tek bir yardım teklifinde bulun"],cue:["Akşam yemeğinden sonra birlikte oturduğumuzda","Projemi açıp başına geçtiğimde","Sıradaki güvenli görüşmemiz başladığında"],place:["Mutfaktaki masamızda","Her zamanki çalışma yerimde","Güvenle konuşabildiğim mesaj grubumuzda"],minutes:[2,5],fallback:["Güvenli bir sesli veya yazılı mesaj kullan","Başka bir uygun konuşma fırsatını seç","Birinden pratik destek iste"],observation:["Ne sorduğum ve ne duyduğum","Yazdığım işe yarayan cümle","Yardım teklifini gerçekten iletip iletmediğim"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Telefona bakmadan bir soru sor ve dinle",minimum:"Tek bir soru sorup yanıtını dinle",minutes:2,cueHint:"Akşam yemeğinden sonra birlikte oturduğumuzda",placeHint:"Mutfaktaki masamızda",obstacleHint:"Karşı taraf uygun değil veya benim dikkatim dağılıyor.",fallbackHint:"Güvenli bir sesli veya yazılı mesaj kullan",observationHint:"Ne sorduğum ve ne duyduğum"},stopRule:"Güvenli ve karşı tarafın da istediği bir görüşme seç. Yardım, imkânlarına ve sınırlarına uysun.",accessibleAlternative:"Her zamanki iletişim yöntemini kullanabilir, yardım alarak katkıda bulunabilir veya kimseyle paylaşmadan yaratıcı bir iş yapabilirsin."},result:{question:"Seçtiğin işi gerçekten yaptın mı?",observationPrompt:"Neye katkı sağladın, ne sordun veya ne duydun?"},judgment:{primary:{id:"meaning-1-dinner-opening-decision",scenario:"Murat bu akşam kızının projesini dinlemeyi seçmiş. Kızının çıkmadan önce beş dakikası var. Bulaşıklar bekleyebilir. Murat bir de işe yarayan soru hazırlamak istiyor.",question:"Bu fırsatı hangi seçim kendi amacına uygun kullanır?",options:[{id:"listen-now",text:"Projesini şimdi sorup yanıtını dinlemek, ardından gerçekten neler olduğunu kısa bir notla kaydetmek.",feedback:"Seçtiği dikkatli konuşma için fırsatı kullanır. Yanıt kısa veya dalgın olabilir. Bulaşıklar ve ek hazırlık bekleyebilir. Bu örnek herkes için ilişkinin ilk sırada gelmesi gerektiğini söylemez; Murat’ın seçimine dayanır."},{id:"meaning-1-share-chore",text:"Beş dakika boyunca birlikte bulaşık yıkarken masayı toplamak ve aynı anda projenin nasıl gittiğini sormak.",feedback:"Ortak ev işi yakınlığa katkı sağlayabilir. Burada Murat dikkatini vererek dinlemeyi seçti ve bulaşıklar bekleyebilir. İkisi de ortak işi tercih etmiyorsa dikkatini bölmek yerine kısa konuşmayı korusun."},{id:"meaning-1-prepare-question",text:"Beş dakikayı proje hakkında iyi bir soru hazırlamaya ayırıp kızı evden çıktıktan sonra mesaj göndermek.",feedback:"Soru hazırlamak sonraki konuşmayı kolaylaştırabilir. Burada kızı uygun ve konu zaten belli. Şimdi sor. Kızı konuşmak istemezse bunu “Fırsat olmadı” olarak kaydet. Hazırlığı görüşmenin yerine koymak gerekmiyor."}],bestOptionId:"listen-now"}},carry:{takeaway:"Önemsediğin şeye zaman ayır. Sonra ne yaptığını ve ne olduğunu kaydet.",followUp:{questionId:"meaning-1-return",question:"Seçtiğin fırsat geldiğinde gerçekte ne oldu, ne yaptın?",observationPrompt:"Hangi işi yaptın? O fırsat gerçekten var mıydı, yoksa oluşmadı mı?",adjustmentPrompt:"Sonraki fırsat için neyi ertelemen veya değiştirmen gerekiyor?"}},goDeeper:{sections:[{heading:"Birden fazla yol gösteren bir felsefe",paragraphs:["Frankl’ın üç yolu, herkesin tamamlaması gereken bir listeden gelmiyor. Felsefi ve klinik bir açıklamanın parçaları. Üretmek, yararlı bir iş veya bir davranış olabilir. Deneyimlemek, güzelliği fark etmek veya bir ilişkiye dikkat vermek olabilir. Kaçınılmaz acı karşısındaki tutum ise başka bir ihtimal. Zorunluluk değil. Acını anlatmadan katkıyı veya ilişkiyi seçebilirsin. Frankl’ın Amerika’daki enstitüsünün açıklaması bu yolları anlatır. [M17]","Viyana’daki enstitünün biyografisi, Frankl’ın logoterapiyi Naziler tarafından hapsedilmeden önce geliştirmeye başladığını gösterir. [M18] Sonradan yaşadıkları hayatının tarihine aittir. Kısa dersin sıkıntıyı tedavi ettiğinin kanıtı değildir. Bu kurs felsefeden sorular alır, cevabı sana bırakır. Büyük bir yanıt bulamasan da küçük bir iş seçebilirsin. Dikkatli bir soru, yararlı bir paragraf veya sınırları belirli yardım teklifi, amacını gözleyebileceğin bir işe dönüştürür."]},{heading:"Fark etmekten gerçek bir fırsata",paragraphs:["Anlamlı görünen bir planla yaptığın işi ayrı ayrı kaydet. Planlama araştırmaları, ne zaman başlayacağını ve ne yapacağını belirlemeyi destekler: fark edebileceğin durum oluştuğunda, seçtiğin işi yap. Gollwitzer ve Sheeran, 8.461 kişiyi kapsayan 94 bağımsız testi birleştirdi. [M11] Hedefe ulaşmak ortalama olarak iyileşti. Ama katılımcılar, hedefler ve araştırma biçimleri farklıydı. Bu sonuç, planın anlam duygusunu artırdığını veya kursun felsefe ile işi birleştiren akışının etkili olduğunu göstermez. İki iddiayı ayrı tut.","ODA uyarlamasında tek bir amaç, iş ve yapılabilir küçük adım seçersin. İlk iş amacınla ilgili olsun. Tek yanıtı dinlemek ilişkiye katkı verir. Yalnızca kişi listesini açmak hazırlıktır. Fırsat yoksa “Fırsat olmadı”, gelecekteki görüşme içinse “Planlandı” olarak kaydet. Konuşmanın hayatını değiştirdiğini kanıtlamak gerekmiyor. Pratik değeri sonraki seçimin için bilgi vermesi. Başka ortam, destek veya başka amaç sana daha iyi uyabilir. Duygunun değişmemesi, görüşmenin yapılmadığı anlamına gelmez."]}],sourceIds:["meaning-frankl","meaning-frankl-history","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-2",courseId:"meaning",locale:"tr",title:"Önemli dediğin şeye hep kalan zaman mı?",goal:"Seçtiğin amaç için küçük bir işe zaman ayır. Bunun için neyin beklemesi gerektiğini açıkça söyle.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Önemli diyorsun. Ona zaman ayırıyor musun, yoksa bütün işlerden artan dakikaları mı bırakıyorsun?",reason:{id:"meaning-2-reason",label:"Bu amaca zaman ayırmak için hangi işi başka zamana taşıyacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Telefonda gezinmeyi başka zamana taşımak","Daha küçük bir sözü tutmak","Özenli çalışmaya yer açmak"]},why:{id:"meaning-2-why",label:"Bu amaca zaman ayırmak için hangi işi başka zamana taşıyacaksın?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Hedef, pazar günü birini ziyaret etmek gibi bitirebileceğin bir şey. Değer ise dikkatini vermek gibi sürdürmek istediğin bir davranma biçimi. Bu ayrım bir terapi modelinden gelir. Hedeflerin daha önemsiz olduğunu söylemez. Bir yere varamamış olman, hangi yönde ilerlemek istediğini tek başına belirlemez. İkisi birlikte sana yol gösterebilir.","Aynı amacı ve aynı işi denemeyi sürdür. Önündeki uygun zamana bak. Değer verdiğin iki şey aynı zamanı isteyebilir. İşe yarayan küçük adımı seç, neyin bekleyeceğini söyle. Burada bir seçim yapıyorsun. Diğer değer ortadan kalkmıyor. Seçimin işe yarayıp yaramadığını değerlendirmeden önce o işi gerçekten yap ve sonra gözle."],example:{title:"Murat konuşmaya yer açıyor",text:"Çarşamba Murat’ın evdeki bir işten önce on dakikası var. Hem yeniden konuşmak hem okumak istiyor. Kızının projesine iki dakika ayırıp ev işine başlıyor. Okuma perşembeye kalıyor. Kızı dalgın görünüyor. Murat bunu da kaydediyor. Her şeyi aynı zamana sıkıştırmak yerine sınırları belli bir iş seçti. Konuşmanın istediği gibi geçmesi, seçtiği adımı atmasının şartı değildi."}},move:{invitation:"Amacını koru. Sonraki küçük işe ayırabileceğin bir zaman seç.",instructions:["Aynı zamana denk gelen başka bir işi belirt.","İşe yarayan en küçük adımı seçip gerçekten at."],prompts:[],suggestions:{action:["Ayırdığım zamanda soru sorup yanıtını dinle","Proje için işe yarayan tek cümle yaz","Kapsamı belli bir bakım işini tamamla"],minimum:["Tek bir yanıtı dikkatimi vererek dinle","Kullanılabilecek tek bir cümle yaz","Anlaştığımız küçük işlerden tek birini tamamla"],cue:["Akşam yemeğinden sonra birlikte oturduğumuzda","Projeme ayırdığım zaman geldiğinde","Mevcut bakım işini tamamladıktan sonra"],place:["Mutfaktaki masamızda","Her zamanki çalışma yerimde","İşin gerçekten yapılması gereken yerde"],minutes:[2,5],fallback:["Daha kısa bir konuşma fırsatını kullan","İşi küçült, işe yarayan kısmını yap","Sorumluluğu paylaşmak için yardım iste"],observation:["Yaptığım iş ve beklettiğim diğer iş","Gerçekte ne kadar zaman ayırdığım","Küçük adımın amacıma katkı sağlayıp sağlamadığı"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Ayırdığım zamanda soru sorup yanıtını dinle",minimum:"Tek bir yanıtı dikkatimi vererek dinle",minutes:2,cueHint:"Akşam yemeğinden sonra birlikte oturduğumuzda",placeHint:"Mutfaktaki masamızda",obstacleHint:"Değer verdiğim iki sorumluluk aynı zamanı istiyor.",fallbackHint:"Daha kısa bir konuşma fırsatını kullan",observationHint:"Yaptığım iş ve beklettiğim diğer iş"},stopRule:"Acil bakımın veya gereken dinlenmenin zamanından alma. İşin zamanını ya da boyutunu değiştir.",accessibleAlternative:"Aynı amacı korumak için iletişim desteği, oturarak yapılacak bir iş veya birinden yardım seçebilirsin."},result:{question:"Zaman ayırdığın en küçük adımı gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın? Hangi işi daha sonraya bıraktın?"},judgment:{primary:{id:"meaning-2-chosen-commitment-decision",scenario:"Murat, kızı yolculuğa çıkmadan dikkatli bir konuşma sözü vermiş. Bu akşamki on dakika son fırsat. Acil olmayan kitabının bölümünü bitirmeye de önem veriyor. Uzun bir telefon görüşmesi gelecek haftaya kalabilir.",question:"Hangi seçim verdiği sözü bu zamana sığdırır?",options:[{id:"reading-later",text:"Zamanın sınırlı olduğunu kabul edip şimdi kısaca dinlemek, okumak için başka bir zaman seçmek.",feedback:"Bu akşam fırsat varken seçtiği konuşmayı korur. Okumak hâlâ önemli ve başka bir zamana bırakılabilir. Kararı belirleyen, verdiği söz ve zamanlama. Bir değerin diğerinden daha üstün olması değil."},{id:"full-both",text:"Önemli iki sözden hiçbiri beklemesin diye kızını dinlerken bir yandan kitabının bölümünü bitirmeye çalışmak.",feedback:"İşleri birleştirmek okuma zamanını koruyabilir. Ama söz verdiği dikkati böler. İki tam işi sığmış saymak yerine şimdi kısa dinleme adımını at, okumayı başka zamana taşı. Seçimin bedelini açık tut."},{id:"meaning-2-next-week-call",text:"Her işe ayrı zaman ayırmak için bu akşam okuyup gelecek haftaya daha uzun bir konuşma planlamak.",feedback:"Ayrı zamanlar mantıklı olabilir; uzun görüşme de değerli olabilir. Ama yolculuk öncesi seçtiği konuşma kaçmış olur. Küçük sözü şimdi tut. Daha uzun bir görüşmeyi ayrıca planlayabilirsin."}],bestOptionId:"reading-later"}},carry:{takeaway:"Hedefini kaçırınca istediğin yön kaybolmaz. Bugün ona katkı sağlayan yapılabilir tek bir iş seç.",followUp:{questionId:"meaning-2-return",question:"Ayırdığın zaman seçtiğin amaca katkı sağladı mı? Gerçekte nasıl kullandın?",observationPrompt:"Küçük adım amacına katkı sağladı mı? Hangi başka iş bunun için bekledi?",adjustmentPrompt:"Bu seçimi koruyacak mısın, yoksa zamanını veya işin boyutunu mu değiştireceksin?"}},goDeeper:{sections:[{heading:"Yön ve varış noktasının işlevi farklıdır",paragraphs:["Bethay ve arkadaşlarının uzmanlara yönelik ACT stratejileri rehberi, değerleri süren davranışların seçilmiş özellikleri olarak anlatır. Kararlı eylem bunları somut hedeflerle birleştirir. [M19] Dikkat vermek bir yön. Bu akşam tek yanıtı dinlemek bitebilen bir iş. Birlikte çalışırlar. İşi bitirirsin, dikkat vermeyi bitirmiş olmazsın. Hedefini değiştirirken yönünü koruyabilirsin. Bu ayrımlar Kabul ve Kararlılık Terapisi, yani ACT modeli içindedir. Deneylerle bulunmuş, herkese zorunlu evrensel kategoriler değildir.","ODA’nın pusulası bir eğitim uyarlaması: hayatının bir alanını seç, nasıl davranmak istediğini söyle, koşullarına bak ve yapabileceğin işi belirle. Doğrulanmış puan eşiği yok. Her alanı puanlamak veya en büyük sayısal farkı kapatmak gerekmiyor. Bakım sorumluluğu, azalan güç veya değişmeyen vardiyası olan biri önce sürdürebileceği bir düzeni seçebilir. Pusulayı hayatına hüküm vermek için kullanma. Bu haftanın gerçek koşullarına göre neye sıra vereceğini belirle."]},{heading:"Kısa adım, tedavi programının bütünü değil",paragraphs:["A-Tjak ve arkadaşları, klinik açıdan önemli ruhsal veya fiziksel sorunları olan 1.821 kişiyle 39 randomize araştırmayı inceledi. [M04] Araştırmalar, farklı durumlarda ve farklı karşılaştırmalarla tam Kabul ve Kararlılık Terapisi programlarını sınadı. Değerler pusulasını tek başına sınamadı. Bu formun etkisini göstermedi veya ODA’nın terapi sunduğunu doğrulamadı. Bir yöntem, bütün programın klinik kanıtını üstlenmeden de seçim yapmana yol gösterebilir. Yardım edici fikirle kanıtlanmış tedavi ayrı şeyler.","Zaman ayırma kısmı, belirli durumda belirli yanıtı planlama araştırmalarından ayrıca destek alır. [M11] Akşam yemeğinden sonra oturmak, “Bu hafta bir ara”dan daha tanınabilir bir an. Kanıt, hedefe ulaşmayla ilgili; hayatından memnun hissetmekle değil. Küçük adım anlamlı, seçimin bedeli açık kalsın. Acil olmayan işi ertelersen başka zamanını söyle. Gerekli bakım veya toparlanma tehlikeye giriyorsa adımı küçült, yardım al ya da başka uygun bir fırsat seç."]}],sourceIds:["meaning-act-values","meaning-act-trials","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-3",courseId:"meaning",locale:"tr",title:"Kendi seçimin de zor gelebilir",goal:"Benimsediğin bir nedenle küçük bir iş yap. Sorumluluklarını ve uyman gereken koşulları koru.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Önemsediğin bir seçim yüzünden hâlâ suçluluk mu duyuyorsun? Bu duygu, seçimin sana ait olup olmadığına karar vermez.",reason:{id:"meaning-3-reason",label:"Hangi nedeni benimsiyorsun? Hangi sorumluluğunu koruman gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Sevdiğim insanlara özen göstermek","Maddi sorumluluklarımı korumak","İsteğe bağlı tek bir işi seçmek"]},why:{id:"meaning-3-why",label:"Hangi nedeni benimsiyorsun? Hangi sorumluluğunu koruman gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ailenden öğrendiğin sorumluluğu sen de benimseyebilirsin. Motivasyon araştırmaları, benimsediğin nedenlerle davranmayı baskı altında davranmaktan ayırır. Ama bir seçimin sana ait olduğunu hemen gösteren test sunmaz. Suçluluk, yorgunluk veya memnuniyet yaşantın hakkında bir şey söyler. Bir değerin sana ait olup olmadığını tek başına belirlemez. Nereden geldiğine bakmak, kararın tamamı değildir.","Denediğin aynı amaca bak. Hâlâ benimsediğin bir nedeni ve uyman gereken bir koşulu söyle. Temel sorumluluklarını koru. Bedeli düşük, isteğe bağlı tek seçimi değiştir; sonra yararlı işi yap. Birden fazla nedenin olabilir. Önce hepsinden kesin emin olman gerekmiyor. Rahatsızlık sürerken de sorumluluklarına uyan bilinçli bir seçim yapabilirsin."],example:{title:"Murat benimsediği nedene göre davranıyor",text:"Perşembe mutfak masasında Murat, isteğe bağlı iş sohbetine katılmadığı için suçlu hissediyor. Kızıyla ilgilenmeyi hâlâ istiyor; zorunlu vardiyasını da koruyor. İki dakikalık konuşmalarında kızının maketini sorup yanıtını dinliyor. Konuşmayı ve huzursuzluğunu kaydediyor. Suçluluk sürerken de kendi nedenini benimsedi. Sırf rahat hissetmediği için bu seçimin ona ait olmadığını söylemesi gerekmiyor."}},move:{invitation:"Benimsediğin nedenle, daha önce denediğin aynı küçük adımı at.",instructions:["Gerekli sorumlulukları koru. İsteğe bağlı hangi işi erteleyeceğini söyle.","Duygunun kesinleşmesini beklemeden seçtiğin işi gerçekten yap."],prompts:[],suggestions:{action:["Benimsediğim nedenle bir soru sorup dinle","İsteğe bağlı projeye tek bir katkı yap","Başka işle çakışan isteğe bağlı daveti reddet"],minimum:["Tek bir yanıtı dikkatimi vererek dinle","İşe yarayan tek bir cümle yaz","Ne zaman uygun olduğumla ilgili sınırı söyle"],cue:["Akşam yemeğinden sonra birlikte oturduğumuzda","İsteğe bağlı projeme ayırdığım zaman geldiğinde","İsteğe bağlı davet bana ulaştığında"],place:["Mutfaktaki masamızda","Her zamanki çalışma yerimde","Güvenle konuşabildiğim mesaj grubumuzda"],minutes:[2,5],fallback:["Gerekli sorumlulukları koru, bu işi küçült","İsteğe bağlı seçeneklerden bedeli daha düşük olanı seç","Uymam gereken koşul için destek iste"],observation:["Karışık duygularıma rağmen hangi seçimi yaptığım","Hangi nedeni hâlâ benimsediğim","Hangi gerekli sorumluluğu koruduğum"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Benimsediğim nedenle bir soru sorup dinle",minimum:"Tek bir yanıtı dikkatimi vererek dinle",minutes:2,cueHint:"Akşam yemeğinden sonra birlikte oturduğumuzda",placeHint:"Mutfaktaki masamızda",obstacleHint:"Baskı hissediyorum. Bazı sorumluluklarımı bırakamam.",fallbackHint:"Gerekli sorumlulukları koru, bu işi küçült",observationHint:"Karışık duygularıma rağmen hangi seçimi yaptığım"},stopRule:"Geri dönüşü olmayan değişikliklerden kaçın. Gerekli geliri, bakımı, güvenliği ve ihtiyaç duyduğun desteği koru.",accessibleAlternative:"Seçimini kendin için yapabilir, yardım alabilir, güvenli bir yazılı sınır veya pratik destek seçebilirsin."},result:{question:"Seçtiğin işi gerçekten yaptın mı?",observationPrompt:"Hangi seçimi yaptın? Hangi sorumluluğu korudun veya hangi koşula uydun?"},judgment:{primary:{id:"meaning-3-elective-cost-decision",scenario:"Murat hem gelirine hem bu akşamki aile konuşmasına önem veriyor. İş çevresiyle sohbet yarın aynı kişilerle tekrarlanacak. Bu akşam katılmamak ücretli vardiyayı etkilemiyor. Suçluluk her etkinliğe gitmesini zorluyor.",question:"Hangi seçim benimsediği nedeni, karşılayabileceği bir bedelle dener?",options:[{id:"meaning-3-attend-and-reschedule",text:"Bu akşam iş sohbetine katılıp sonraki vardiyadan sonraya aile konuşması planlayarak iki sözü de korumak.",feedback:"Zamanı değiştirmek iki değerli sözü koruyabilir. Burada aynı kişiler yarın da uygun ve gelir kaybı yok. Bu akşam seçtiği konuşmayı taşımak, bedeli daha düşük alternatif varken baskıya göre davranır."},{id:"endorsed-choice",text:"Zorunlu vardiyasını koruyup bu akşamki isteğe bağlı etkinliği reddetmek ve önem verdiği konuşma zamanını kullanmak.",feedback:"Gelirini korurken ve yarınki iş çevresiyle görüşme fırsatını korurken benimsediği nedeni dener. Suçluluk kalabilir. Mesleki bedel farklı olsaydı başka seçim yerinde olabilirdi. Buradaki zaman ve koşullar bu kararı destekliyor."},{id:"meaning-3-split-evening",text:"İki yerde de görünür olmak için iş sohbetine kısaca katılıp ardından aile konuşmasını kısaltmak.",feedback:"Her iki fırsat da azsa bölmek işe yarayabilir. Burada iş sohbeti yarın tekrarlanıyor. Akşamı bölmek, her iki yerde de görünmesini sağlar ama seçtiği konuşmaya ayıracağı dikkati azaltır. Bunun yerine iki ayrı uygun fırsatı kullanabilir."}],bestOptionId:"endorsed-choice"}},carry:{takeaway:"Bir nedeni benimse. Bedelini kabul et ve sana uyan küçük bir seçimle onu dene.",followUp:{questionId:"meaning-3-return",question:"Bu seçimi yaptıktan sonra nedenini hâlâ benimsiyor musun? Hangi kısmı değişti?",observationPrompt:"Şimdi hangi nedeni benimsiyorsun? Emin olmadığın veya değiştirdiğin kısmı da söyle.",adjustmentPrompt:"Nedeni korumak, değiştirmek veya bedeli için destek almak arasından hangisi uygun?"}},goDeeper:{sections:[{heading:"Ailenden gelmesi, sana ait olmadığı anlamına gelmez",paragraphs:["Ryan ve Deci’nin öz belirleme kuramı, dışarıdan gelen nedenlerin kişinin kendi benimsediği nedenlere nasıl dönüşebileceğini anlatır. [M05] Aile sorumluluğu zor, ilişkilerle ilgili ve yine de senin olabilir. Keyif almak bir neden; birinin güvende olmasını önemsemek başka neden. Bu, baskı altındaki her sorumluluğu sağlıklı kılmaz. Yalnızca nereden geldiği, rahatsızlık veya takdir görme, seçimin sana ait olup olmadığını belirleyemez. Hangi nedenleri benimsediğine ve hangi baskıların seçimi sınırladığına bak.","“Kimse görmese ne yapardım?” isteğe bağlı düşünme sorusudur, doğrulanmış test değil. Suçluluk başkasının değerini taşıdığını, bedensel enerji de gerçek değerini bulduğunu kanıtlamaz. Neden diye sormak düşünmeye yardım edebilir. Tek doğru nedeni bulduğunu belgeleyemez. Karışık nedenlerinle bilinçli seçim yapabilirsin. Gerekli gelir ve bakımı koru. Kültürünle ve çevrenle ilgili sorumluluklarını da hesaba kat. Geri alınabilir, isteğe bağlı bir adım dene. Dersi bitirmek için kariyer, ilişki veya aile sorumluluğunu değiştirmek gerekmez."]},{heading:"Destek motivasyona yardım edebilir, kısa formun sınırı var",paragraphs:["Ntoumanis ve arkadaşları, 30.088 kişiyi içeren 73 sağlık çalışmasını birleştirdi. [M06] Programlar, kişinin benimsediği nedenlerle hareket etmesini ve sağlık davranışını ortalama olarak iyileştirdi. Sonuçlar oldukça farklıydı. 58 randomize, 15 yarı deneysel araştırma vardı. Kanıt, destek sunulan sağlık programlarına ait. Üç sorunun gizli doğru nedeni ortaya çıkardığını, dış nedenlerin her zaman zararlı olduğunu veya kısa ODA çalışmasının programları tekrarladığını göstermez.","ACT modeli de sürdürmek istediğin davranış özelliklerini somut işe bağlar. [M19] Burada bu bağlantı bir ODA uyarlaması. Birlikte sınanmış tedavi değil. Sonraki denemede belirli bir şey öğren: seçim sorumluluklarına uydu mu, nedenini hâlâ benimsiyor musun? Huzursuzluk kayıtta kalabilir. Baskı zorlamaya veya tehlikeye dönüşüyorsa uyum sağlamayı denemek yerine korunma ve destek önce gelir. Amacını değiştirebilir, kendine saklayabilir veya kimseye açıklama yapmak zorunda kalmadan ara verebilirsin."]}],sourceIds:["meaning-sdt","meaning-sdt-interventions","meaning-act-values"]}},{schemaVersion:2,revision:2,id:"meaning-4",courseId:"meaning",locale:"tr",title:"Acından ders çıkarmak zorunda değilsin",goal:"Seçtiğin amacı korumak için pratik bir istek, güvenli sınır veya kendine alan tanıyan tek iş seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bu acıya anlam vermeye mi uğraşıyorsun? Önce yardım edilebilecek şeye bak. Anlam sorusu bekleyebilir.",reason:{id:"meaning-4-reason",label:"Bu amacı sürdürebilmek için hangi pratik düzenlemenin değişmesi gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Tek bir bakım işini paylaşmak","İhtiyacım olan dinlenmeyi korumak","Yetkin birinden destek istemek"]},why:{id:"meaning-4-why",label:"Bu amacı sürdürebilmek için hangi pratik düzenlemenin değişmesi gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Geçmişteki olay değişmese de bugünkü düzen değişebilir. Hastalıkta kendiliğinden “Yapılacak hiçbir şey yok” sonucuna varma. Bakım ve değerlendirme gerekir. Frankl’ın kaçınılmaz acı karşısında tutum seçme fikri felsefi bir ihtimaldir. Acının iyi bir yanı olduğunu düşünmek zorunda değilsin. Başına gelenin acı ve haksız olduğunu söyleyerek de yardım istemeyi seçebilirsin.","Aynı denemene dön. Yük, bu işi sürdürmeyi güçleştiriyorsa çevresindeki desteği değiştir. Belirli tek iş için yardım iste, güvenli sınır koy veya gereken dinlenmeyi koru. Bunlar aynı amaca katkı sağlayabilir. Gerçekte ilettiğin isteği veya yaptığın değişikliği kaydet. Anlamlı hissetmen şart değil. Yanıt bekliyor olman da isteği yapmadığın anlamına gelmez."],example:{title:"Murat bakım yükünü paylaştırmak istiyor",text:"Cuma Murat, babasının ziyaretlerini düzenledikten sonra bitkin hissediyor. Bakmayı sürdürmek istiyor, ama her akşamını kaybetmek istemiyor. Mutfak masasında kardeşine cumartesi ulaşımını üstlenmesini isteyen bir mesaj gönderiyor. Yatma saatine kadar yanıt yok. Murat isteğini kaydediyor. Üzüntüsü sürüyor. Bundan bir hayat dersi çıkarmaya çalışmıyor. Yardım istemekle yardımın kabul edilmesini ayrı tutuyor."}},move:{invitation:"Amacını koru. Yardımla hafifletilebilecek tek bir yükü değiştirmek için adım at.",instructions:["Tutum çalışmasından önce hangi pratik değişikliğin mümkün olduğuna bak.","Belirli bir yardım iste veya kendini koruyan güvenli bir iş yap."],prompts:[],suggestions:{action:["Tek bir bakım işi için yardım iste","Güvenli sınır koy; uygun olduğun saatleri açıkça belirt","Yetkin birinden gereken desteği iste"],minimum:["Belirli yardım isteyen tek mesaj gönder","Tek bir sınırı açıkça söyle","Destek için bir kişiyle iletişim kur"],cue:["Akşam yemeğinden sonra ziyaretleri planlamadan önce","Sıradaki istek bana ulaştığında","Destek istemek için seçtiğim an geldiğinde"],place:["Mutfaktaki masamızda otururken","Güvenle konuşabildiğim mesaj grubumuzda","Ulaşabildiğim, mahremiyetimi koruyabildiğim yerde"],minutes:[2,5],fallback:["Destek verebilecek başka uygun birine sor","Sınırını açıklamadan koru ve yardım al","Erişebileceğim başka destek yolunu seç"],observation:["Gönderdiğim istek ve gelen herhangi bir yanıt","Gerçekte hangi pratik düzeni değiştirdiğim","Destek için gerçekten iletişim kurup kurmadığım"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Tek bir bakım işi için yardım iste",minimum:"Belirli yardım isteyen tek mesaj gönder",minutes:2,cueHint:"Akşam yemeğinden sonra ziyaretleri planlamadan önce",placeHint:"Mutfaktaki masamızda otururken",obstacleHint:"İlk kişi yardım edemiyor veya onunla görüşmek güvenli değil.",fallbackHint:"Destek verebilecek başka uygun birine sor",observationHint:"Gönderdiğim istek ve gelen herhangi bir yanıt"},stopRule:"Krizde yerel kriz desteğine ulaş. ABD’de 988’i ara veya mesaj gönder. Acil tehlikede yerel acil yardım hizmetlerini kullan.",accessibleAlternative:"Yardım alarak isteğini iletebilir veya dinlenebilirsin. Umutsuzluk sürüyorsa veya günlük işler zorlaşıyorsa daha erken uzman desteği iste."},result:{question:"Seçtiğin pratik adımı gerçekten attın mı?",observationPrompt:"Ne istedin veya ne değiştirdin? Yanıt gelmediyse onu da söyle."},judgment:{primary:{id:"meaning-4-transport-constraint-decision",scenario:"Cumartesi hastaneye ulaşımı sağlamak Murat’ı bitkin bırakıyor. Kardeşi, bu akşam haber verilirse götürmeyi teklif etti. Ziyaretler kısalabilir ama ulaşım zorunlu. Ücretsiz yerel ulaşım hizmetinin cumartesi yeri yok.",question:"Hangi düzenleme şu anki yükü gerçekten ele alır?",options:[{id:"meaning-4-shorten-visits",text:"Başkasının zamanını ayarlamakla uğraşmadan yükünü azaltmak için cumartesi ziyaretini kısaltıp arabayla götürmeye devam etmek.",feedback:"Kısa ziyaret gücü koruyabilir ve işe yarayabilir. Ama onu bitkin bırakan zorunlu ulaşım işini değiştirmez. Önce var olan ulaşım teklifini kesinleştir, sonra sürdürebileceğin ziyaret süresini seç. İki yükü ayır."},{id:"meaning-4-community-route",text:"Kardeşinin teklifini kesinleştirmeden önce yerel ulaşım hizmetine iptalden açılabilecek yeri sorup gelecek yanıtı beklemek.",feedback:"Yerel ulaşım ileride yararlı olabilir. Cumartesi için kesin yer yok. Kardeşinin teklifiyse bu akşam yanıt bekliyor. Var olan yardımı, başka yerde iptal çıkmasına bağlamak yerine güvenceye al."},{id:"share-task",text:"Kardeşinden ulaşımı üstlenmesini isteyip ardından kendi gücüne ve koşullarına uyan bir ziyaret süresi seçmek.",feedback:"Zorunlu sağlık ulaşımını korurken değiştirilebilecek yük için var olan teklifi kullanır. Kabul edilmesini beklemeden isteği iletmiş olabilir. Yanıt gelmediyse kaydına bunu yaz. İstek ve anlaşma farklı olaylar."}],bestOptionId:"share-task"}},carry:{takeaway:"Tutumunun değişmesini bekleme. Destek alarak bugünkü düzeni değiştirmek için bir adım at.",followUp:{questionId:"meaning-4-return",question:"İsteğinden sonra hangi yardım veya pratik değişiklik oldu?",observationPrompt:"Hangi yanıt veya değişiklik oldu? Yanıt yoksa onu yaz.",adjustmentPrompt:"Kalan yük için hangi yardım, güvenli sınır veya dinlenme sana uygun?"}},goDeeper:{sections:[{heading:"Geçmişteki olay ve bugünkü imkânlar",paragraphs:["Frankl’ın açıklaması, gerçekten kaçınılamayan acı karşısında seçilebilecek bir tutumu içerir. [M17] Bu felsefi rehberliktir. Tutumun hastalığı iyileştirdiğinin veya travmayı yararlı kıldığının kanıtı değil. Ölüm veya geçmiş olay geri alınamaz. Bugünkü belirtiler, tedavi seçenekleri, sosyal destek ve gündelik düzen yine de değişebilir. Yardım seçeneklerine bakmadan bir tanının, başkasından gördüğün zararın veya destek eksikliğinin değiştirilemez olduğuna karar verme.","ACT modeli zor duygular sürerken seçtiğin biçimde davranmayı anlatır. [M19] Duyguyu yok etmek veya önlenebilir tehlikede kalmak zorunlu değil. Bakım vermeyi amaçlamaya devam edebilirsin. Yeni bir ziyaret yerine, ulaşımı paylaşmak için yardım isteyebilirsin. Dinlenmek, sınır koymak veya bilgi almak yerinde olabilir. Bunları koşullarında değerlendir. Yüce bir tutumun kanıtı sayma. Anlam sorusunu yanıtsız bırakabilirsin. ODA’ya acını anlatmak zorunda değilsin. İşin yararlı olup olmadığına bakmak için ayrıntı paylaşman gerekmez. Sadece bir yükü paylaşmayı istemen bile yeterince somut olabilir. Bunun için acının nedenini çözmen veya yaşadığını haklı göstermen gerekmiyor."]},{heading:"Destek almak için amaç bulman gerekmiyor",paragraphs:["NIMH rehberi depresyon belirtilerini, uzman değerlendirmesini ve tedavi seçeneklerini anlatır. [M20] Süren umutsuzluk, çökkünlük, ilgi kaybı veya günlük işleri yapmakta güçlük destek gerektirir. Tek başına anlam kaybı tanı değildir. Kurs bu değerlendirmeyi yapamaz. Belirtiler herhangi bir süre eşiğine ulaşmadan yardım isteyebilirsin. Doktora veya ruh sağlığı uzmanına ulaşmak için kursu bitirmeyi ya da değerler sorusuna cevap bulmayı bekleme. Yardım daha erken de istenebilir.","İntihar düşüncelerinde veya duygusal krizde bulunduğun yerdeki kriz desteğine ulaş. ABD’de 988’i arayabilir veya mesaj gönderebilirsin. Acil tehlikede yerel acil yardım hizmetlerini kullan. Krizde gereken adım yeni bir düşünme alıştırması değil, insandan yardım almaktır. Kriz dışında isteğin küçük ve belirli kalabilir: bakım işi, toparlanma zamanı veya randevu. Yanıt yoksa bunu kaydet. İlk yol kullanılamıyorsa başka uygun yola bak. Engeli, hayatında anlam bulamadığının kanıtı sayma."]}],sourceIds:["meaning-frankl","meaning-act-values","meaning-support"]}},{schemaVersion:2,revision:2,id:"meaning-5",courseId:"meaning",locale:"tr",title:"Düşlediğin geleceğin küçük bir parçasını bugün yap",goal:"Sade bir gelecek sahnesinden, seçtiğin amaca katkı sağlayan somut bir iş çıkar.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Geleceğin zihninde çok net. Onun hangi küçük parçasını bu hafta gerçekten yapacaksın?",reason:{id:"meaning-5-reason",label:"Bu geleceğin haftana sığması için şimdi hangi koşulun değişmesi gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["İlişkime gerçekten zaman ayırmak","İşe yarayan tek bir şey üretmek","Bütçeme ve gücüme göre davranmak"]},why:{id:"meaning-5-why",label:"Bu geleceğin haftana sığması için şimdi hangi koşulun değişmesi gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Geleceği yazma çalışmalarında iyimserlik ve olumlu duygular için kanıt, depresyon ve olumsuz duyguların azalmasına ilişkin kanıttan daha açık. Hayal ettiğin hayatın gerçekleşeceği gösterilmiş değil. Kısa bir sahne, denemen için hazırlık olabilir. Bir iş yaptığının kanıtı değildir. Geleceği düşünmekle o geleceğe katkı veren davranışı yapmak ayrı olaylardır.","İşine yarıyorsa yakın gelecekte sıradan bir gün düşün. Aynı amacını koru. Sonraki görünür parçasını seç: gerçek konuşma, işe yarayan cümle veya belirli istek. Engeline ve imkânlarına bak. Sonra o parçayı yap. Geleceği hayal etmek yardım etmiyorsa atla. Bunun yerine işi doğrudan seçebilirsin. Hayal çalışması, işe başlamak için zorunlu şart değil."],example:{title:"Murat sıradan bir salı hayal ediyor",text:"Cumartesi kahvaltısında Murat, bakım işlerinin paylaşıldığı ve evde yardım ettiği bir salıyı düşünüyor. Bu sahne hazırlık. Tek bir parçasını işe dönüştürüyor: kızının okul maketi için anlaşılır bir etiket yazmak. Mutfak masasında etiketi bitiriyor. Maketin kalanı hâlâ çalışma istiyor. Murat hayal ettiği günle yaptığı etiketi ayrı tutuyor. Bugün gerçekten ortaya çıkan parça bu."}},move:{invitation:"Düşündüğün geleceğin bir parçasını, bugünkü küçük adımında hayata geçir.",instructions:["İşe yarıyorsa kısa bir sahne düşün. Bu hazırlıktır.","Gerçek bir engeli belirt, sonra ilgili tek parçayı yap."],prompts:[],suggestions:{action:["Proje için işe yarayan tek cümle yaz","Proje için kullanılabilecek tek taslağı çiz","İlgili bir konuda geri bildirim isteyen mesaj gönder"],minimum:["Kullanılabilecek tek bir cümle yaz","İşe yarayan tek taslağın ana hatlarını çiz","Belirli bir konuda tek geri bildirim sorusu gönder"],cue:["Projemi açıp başına geçtiğimde","Projemde ana hatları çizmem gerektiğinde","Çalışmaya ayırdığım zaman geldiğinde"],place:["Her zamanki çalışma yerimde","Mutfaktaki masamızda çalışırken","Güvenle konuşabildiğim mesaj grubumuzda"],minutes:[2,5],fallback:["Amacıma katkı sağlayan daha küçük bir parça seç","Çizmek yerine sözcüklerle tarif et","İhtiyaç duyduklarıma ulaşmak için yardım iste"],observation:["Gerçekte hangi parçayla katkıda bulunduğum","Engelin neyi değiştirdiği","Gönderdiğim istek ve gelen herhangi bir yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Proje için işe yarayan tek cümle yaz",minimum:"Kullanılabilecek tek bir cümle yaz",minutes:2,cueHint:"Projemi açıp başına geçtiğimde",placeHint:"Her zamanki çalışma yerimde",obstacleHint:"Hayal ettiğim hâli, elimdeki imkânları aşıyor.",fallbackHint:"Amacıma katkı sağlayan daha küçük bir parça seç",observationHint:"Gerçekte hangi parçayla katkıda bulunduğum"},stopRule:"Gelecek sade ve güvenli kalsın. Sıkıntı artarsa hayali bırak. Bedeli ağır sözler verme.",accessibleAlternative:"İşi doğrudan seçebilir, hayal etmek yerine sözcükleri kullanabilir veya yardım alarak katkıda bulunabilirsin."},result:{question:"Seçtiğin parçayı gerçekten ürettin mi?",observationPrompt:"Denemenden sonra gerçekte ne ortaya çıktı veya ne oldu?"},judgment:{primary:{id:"meaning-5-feedback-opening-decision",scenario:"Bir tasarımcının bitmiş bir örneği var. İş arkadaşı bu akşam geri bildirim verebilir. İstediği gelecek birlikte çalışmak. Daha güçlü ekipmanı gelecek hafta ödünç alabilir, ama bu örnek için gerekmiyor.",question:"Hangi adım, elindeki imkânlarla seçtiği amacı dener?",options:[{id:"meaning-5-prepare-presentation",text:"Örneğin sunumunu bu akşam iyileştirip ardından iş arkadaşının sonraki uygun fırsatında geri bildirim istemek.",feedback:"Daha iyi sunum örneği anlaşılır kılabilir. Bu örnek bitmiş ve geri bildirim fırsatı bu akşam. Şimdi belirli bir soru gönder. Sunumu düzeltmen gerekip gerekmediğine yanıta göre karar verebilirsin."},{id:"share-sample",text:"Bütçesini koruyup elindeki bitmiş örneği göndermek ve onun hakkında belirli tek bir geri bildirim sorusu sormak.",feedback:"Elindeki imkânlarla amacına uygun davranışı dener. Geleceği yazmakla hedefe ulaşmak farklı sonuçlar. Kusursuz olmayan yanıt da sonraki denemeye bilgi sağlar. Gönderdiği soru ve aldığı yanıt ayrı kayıtlardır."},{id:"meaning-5-borrow-equipment",text:"Geri bildirim istemeden önce daha güçlü bir örnek hazırlamak için gelecek hafta ödünç alacağı ekipmanı beklemek.",feedback:"Ekipman gerekiyorsa ödünç almak bütçeyi koruyabilir. Bu örnek için gerekmiyor ve iş arkadaşı şimdi uygun. Gerekleri büyütmeden önce elindeki örnekle birlikte çalışmayı dene. Ulaşılabilir fırsatı kullanabilirsin."}],bestOptionId:"share-sample"}},carry:{takeaway:"Gelecek sahnesi hazırlıktır. Bugün o amaca katkı sağlayan gerçek bir parçayı yap.",followUp:{questionId:"meaning-5-return",question:"Yaptığın iş, düşündüğün gelecekle bu haftan arasında somut bir bağlantı kurdu mu?",observationPrompt:"Hangi parça ortaya çıktı? Amacına nasıl katkı sağladı veya nerede yetmedi?",adjustmentPrompt:"Sonraki parça hangi eksik kaynağı veya gerçek engeli ele almalı?"}},goDeeper:{sections:[{heading:"Geleceği yazmak hakkında gerçekte ne bulundu?",paragraphs:["Carrillo ve arkadaşları, 2.909 kişiyi kapsayan 29 araştırmayı birleştirdi. [M09] Sonuçlar iyi oluş, iyimserlik ve olumlu duygularda ortalama iyileşmeleri destekledi. Olumsuz duygu ve depresyon belirtilerindeki azalmalar gösterilmedi. Güven aralıkları sıfırı içeriyordu. Depresyonu yalnızca üç araştırma değerlendirdi. Olumlu görünen ortalama, belirsiz tahmini kesinleştiremez. Çalışmalar çoğunlukla kısa vadeli sonuçları ölçtü, farklı yazma yöntemleri kullandı. Daha çok anlam veya gelecekte gerçek başarı gösterilmedi.","King’in ilk gelecek yazma görevinde, 81 üniversite öğrencisi dört yazma koşuluna rastgele atandı. Çalışma art arda dört gün, her gün 20 dakikaydı. [M10] Buradaki kısa, yakın geleceğe ve değerlerine bağlı sahne, süreyi ve amacı değiştirir. Bir ODA uyarlaması; ilk yöntem değil. İsteğe bağlı uzun yazıya ayrıca zaman ayır. İdeal beş yıllık hayat yazmak veya kendini onunla karşılaştırmak zorunda değilsin. Sıradan bir ihtimal, sonraki pratik işi seçmeye yetebilir."]},{heading:"Geleceği bugünün engeliyle birlikte düşün",paragraphs:["Zihinsel karşılaştırmayı “Şu olursa bunu yaparım” planıyla birleştirmek, yapılabilir isteği, istediğin sonucu, bugünkü engeli ve yanıtı birlikte ele alır. Wang ve arkadaşları 21 makaleden, 15.907 kişiyi kapsayan 24 bağımsız araştırmayı inceledi. [M13] Hedefe ulaşmada küçük ortalama etki bulundu: g = 0,336, yüzde 95 güven aralığı 0,229 ile 0,443. Yayın yanlılığına göre düzeltme daha küçük tahmin verdi. Uygulama ve kalite farkları kesinliği sınırlar. Herkes için kanıtlanmış tek süre yok.","Bu kurs, gelecek sahnesini aynı amacın ve somut işinle birleştirir. Bu birleşik uygulama araştırmalarda sınanmadı. Eksik kaynak, bakım sorumluluğu veya güvensiz ortam, içsel zayıflık değil gerçek koşuldur. Pratik yanıt daha küçük bir ürün, yardım isteği veya başka fırsat olabilir. Ortaya çıkan işi veya görüşmeyi sahneden ayrı kaydet. Geleceği hayal etmek baskı veya sıkıntı ekliyorsa çıkar. Doğrudan seçtiğin işle devam edebilirsin. Hayalin hoş görünmesi, gereken kaynakları kendiliğinden sağlamaz."]}],sourceIds:["meaning-carrillo","meaning-best-possible-self","meaning-mental-contrasting"]}},{schemaVersion:2,revision:2,id:"meaning-6",courseId:"meaning",locale:"tr",title:"Plan yine aksadı mı? İşe yarayanı tut",goal:"Kayıtlarından yararlan. Aynı değerine bağlı denemeyi gelecek hafta tekrarlamayı, değiştirmeyi veya bırakmayı seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Plan yine mi aksadı? Sırada ne olacağını gerçekten yaptığın denemelere göre seç.",reason:{id:"meaning-6-reason",label:"Hangi işi bu haftanda yeniden denemeye değer buluyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Yararlı küçük bir işi sürdürmek","İşe yaramayan başlama anını değiştirmek","Sürdürebileceğim bir amacı korumak"]},why:{id:"meaning-6-why",label:"Hangi işi bu haftanda yeniden denemeye değer buluyorsun?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İşi planlamakla yapmak farklı şeyler. Araştırmalar belirli bir başlama anına bağlanan planları ve ilerlemeyi takip etmeyi, hedefe ulaşmak için ortalama olarak destekler. Hiçbiri günlük bir işin anlam duygusunu artırdığını göstermez. Denemende olanları, sana hissettirdiklerinden ayrı tut. Neyi planladığınla neyi gerçekten yaptığını da ayrı ayrı gör.","Aynı amacını ve denemelerinin kayıtlarını gözden geçir. Hangi fırsat oluştu? Hangi küçük adım amacına katkı sağladı? Gelecek hafta tekrarlayacağın veya değiştireceğin tek şeyi seç. Yararlı işi tut, fazladan rutinleri bırak. Kaçan fırsat bilgi verir. Alışkanlığın son tarihi veya değerlerin hakkında hüküm değildir. Destek, dinlenme ve zarar veren planı bırakmak seçeneklerin arasında kalsın."],example:{title:"Murat kayıtlarına göre planlıyor",text:"Pazar mutfak masasında Murat kayıtlarını okuyor: iki konuşma, oluşmayan bir fırsat, yanıtsız bir yardım isteği. Akşam yemeği sonrası iki dakika, geç akşamdan daha iyi uymuş. Kızına maketi yeniden sorup yanıtını dinliyor. Gelecek hafta aynı başlama anını koruyor. Ziyaretler bu zamanı kaplarsa yeniden destek isteyecek. Kaydın gösterdiği koşulu kullanıyor. Konuşmanın yine olacağını garantilemiyor."}},move:{invitation:"Kayıtlarını kullan. Gelecek hafta işe yarayan tek bir işi sürdür.",instructions:["Gerçekte oluşan fırsatları ve denediğin küçük adımları karşılaştır.","Tek bir koşulu değiştir, sonra sıradaki denemeyi yap."],prompts:[],suggestions:{action:["İşe yarayan dinleme adımımı yeniden dene","İşe yarayan proje katkımı yeniden yap","Kayıtlarımın gösterdiği destek isteğini gerçekten ilet"],minimum:["Tek bir yanıtı dikkatimi vererek dinle","Kullanılabilecek tek bir cümle yaz","Belirli bir destek isteyen tek mesaj gönder"],cue:["Akşam yemeğinden sonra birlikte oturduğumuzda","Projede denediğim başlama anı geldiğinde","Sıradaki bakım düzenlemesini yapmadan önce"],place:["Mutfaktaki masamızda","Her zamanki çalışma yerimde","Güvenle konuşabildiğim mesaj grubumuzda"],minutes:[2,5],fallback:["Denediğim daha küçük adımı kullan","Başka bir gerçekçi fırsatı seç","Destek al veya bu plana ara ver"],observation:["Yaptığım iş ve başlama anının oluşup oluşmadığı","Değiştirdiğim koşulun neye imkân verdiği","Küçük adımın hâlâ amacıma katkı sağlayıp sağlamadığı"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşe yarayan dinleme adımımı yeniden dene",minimum:"Tek bir yanıtı dikkatimi vererek dinle",minutes:2,cueHint:"Akşam yemeğinden sonra birlikte oturduğumuzda",placeHint:"Mutfaktaki masamızda",obstacleHint:"Eski zaman aralığı artık sorumluluklarıma uymuyor.",fallbackHint:"Denediğim daha küçük adımı kullan",observationHint:"Yaptığım iş ve başlama anının oluşup oluşmadığı"},stopRule:"Güvenlik, bakım veya gereken toparlanmayla çelişen planları değiştir ya da bırak.",accessibleAlternative:"Yeni rutin eklemeden, yapabileceğin tek işi koruyabilir, yardım isteyebilir veya dinlenmeyi seçebilirsin."},result:{question:"Sıradaki en küçük adımı gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin başlama anı oluştu mu?"},judgment:{primary:{id:"meaning-6-tested-opening-decision",scenario:"Murat’ın geç akşam planı, ziyaretler uzadığı için iki kez olmadı. Akşam yemeği zamanı iki kısa konuşmaya elverdi. Hafta sonu uygunluk belirsiz. Gelecek hafta görüşmek istiyor ve akşam yemeği sonrası fırsatı yine kullanabilir.",question:"Gelecek hafta için hangi plan bu kayıtları daha iyi kullanır?",options:[{id:"meaning-6-earlier-night",text:"Daha uzun, bölünmeyen konuşmayı korumak için akşam görüşmesini otuz dakika daha erkene taşımayı denemek.",feedback:"Erken saat uzun konuşmayı koruyabilir. Ama kayıtlar ziyaretlerin uzadığını gösteriyor. Bu değişikliğin onları önleyeceği bilinmiyor. Önce gerçekten konuşmayı mümkün kılan akşam yemeği sonrası fırsatı yeniden dene. Gözlenmiş koşulu kullan."},{id:"meaning-6-weekend-conversation",text:"Hafta içi ziyaretleriyle çakışmayı önlemek için daha uzun bir konuşmayı hafta sonuna ayırıp planlamak.",feedback:"Saat üzerinde anlaşırlarsa hafta sonu konuşması değerli olabilir. Burada uygunluk belirsiz. Gelecek hafta denenmiş akşam yemeği sonrası küçük adımı koru. Gerçek fırsat çıktığında daha uzun konuşmayı ayrıca ayarla."},{id:"tested-cue",text:"İlişki amacını koruyup akşam yemeği sonrası küçük adımı kullanmak ve başka değişiklik yapmadan sonraki denemeyi kaydetmek.",feedback:"Seçtiği işi mümkün kılan fırsatı tekrarlar. Yeni konuşmayı garantilemez. Başlama anının oluşup oluşmadığını ve ne olduğunu kaydet. Sonra daha fazla destek veya değişiklik gerekip gerekmediğine karar ver."}],bestOptionId:"tested-cue"}},carry:{takeaway:"Tek amacı ve işe yarayan işi koru. Gerçekte olanı kaydederek sonraki denemeyi iyileştir.",followUp:{questionId:"meaning-6-return",question:"Kayıtlarından seçtiğin koşul sonraki işi yapmana yardım etti mi? Hangi kısmı etkiledi?",observationPrompt:"Başlama anı oluştu mu? Bu koşul neyi mümkün kıldı, ne olmadı?",adjustmentPrompt:"Aynı koşulu tekrarlamak, değiştirmek, destek almak veya bırakmak arasından hangisi uygun?"}},goDeeper:{sections:[{heading:"Planlama ve takip, davranış hakkında bilgi verir",paragraphs:["Gollwitzer ve Sheeran, 8.461 kişinin katıldığı 94 bağımsız testi birleştirdi. [M11] Belirli durumda belirli işi yapma planları, farklı ortam ve araştırmalarda hedefe ulaşmayı ortalama olarak destekledi. Harkin ve arkadaşları 138 randomize takip araştırmasını inceledi. [M14] Birleştirilmiş hedefe ulaşma tahmini d = 0,40, yüzde 95 güven aralığı 0,32 ile 0,48 idi. Küçük araştırmalarda asimetri bulundu. Duyarlılık analizi d = 0,19 tahmin etti. Bunlar hedefe ulaşma sonuçları; tatmin garantisi değil.","Bu derlemeler ODA’nın kaydını ve ertesi gün yeniden bakma zamanını doğrulamadı. Bu adımların amacı, verdiğin sözü gerçek denemeyle karşılaştırıp daha uygun adımı seçmek. Herkese açık takip gerekmiyor. İstersen özel ayrıntıları ODA dışında tut. Geleceğe dair planı gerçekleşmiş sayma. Sonucu bildirilmemiş bir denemede ne olduğu henüz bilinmiyor. İşe yarayan küçük adımı büyütmeden tekrarlayabilirsin. Pratik destek isteği veya dinlenme planı aynı amaca başka bir zorlayıcı işten daha uygun katkı sağlayabilir."]},{heading:"Alışkanlık tahmini bir son tarih değil",paragraphs:["Lally ve arkadaşları, 84 günlük gözlem araştırmasında 96 kişiyi takip etti. [M15] Katılımcılar günlük başlama anları olan yeme, içme veya hareket davranışları seçti. Modellenen otomatikleşme çok farklı hızlarda arttı. Bilinen 66 gün ortancası ve 18–254 gün aralığı, verilere uyan eğrilerle hesaplanan tahminleri anlatır. Uzun tahminler gözlem süresini aşar. İşinin son tarihi veya değerlerin otomatikleştiğinin kanıtı değildir. Birkaç kaçan günün etkisizliğini göstermez. Tek fırsatı kaçırmanın ölçülen etkisi azdı.","Bu denemede yiyecekle ilgili olmayan, değerine bağlı bir iş yapıyor ve ertesi gün olanları gözden geçiriyorsun. Bu araştırma yöntemi değil, uyarlama. Kayıtlarında işe yaradığını gördüğün şeyleri sürdür: uygun bir başlama anı, yararlı küçük adım ve engelle karşılaşınca yapacağın iş. Yardım etmeyen alıştırmayı çıkar. Bölünen haftayı her beklentiyi ikiye katlayarak düzeltme. Sonraki yapılabilir fırsatı seç, gerekirse yardım iste. Plan değiştiğinde geçmiş kaydı olduğu gibi koru. Yeni plan, eski denemede olanı değiştirmesin."]}],sourceIds:["meaning-planning","meaning-monitoring","meaning-habits"]}}],z=[{id:"meaning-1",practice:["Tek katkı veya ilişki seç. Zorlukları düşünmek isteğe bağlı.","İşe yarayan bir iş ve güvenli bir fırsat belirle.","Seçtiğin işi yap, sonra ne olduğunu kaydet."],correct:1,photo:{id:"1469474968028-56623f02e42e",alt:"Sisli vadi üzerindeki kayada tek başına duran bir kişi"}},{id:"meaning-2",practice:["Seçtiğin aynı amacı ve işi kullan.","Acil olmayan tek işi erteleyerek uygun zamana yer aç.","İşe yarayan küçük adımı at. Hangi işin beklediğini kaydet."],correct:2,photo:{id:"1470071459604-3b5ec3a7fe05",alt:"Yeşil kayalıklar ve vadinin üzerinde süzülen bulutlar"}},{id:"meaning-3",practice:["Karışık nedenlere yer bırakırken benimsediğin bir nedeni söyle.","Gerekli sorumlulukları koru. Geri alınabilir, isteğe bağlı tek işi ertele.","İşi yapıp seçimini kaydet. Suçluluğuna puan vermek gerekmiyor."],correct:0,photo:{id:"1447752875215-b2761acb3c5d",alt:"Yeşil ormanın içinden geçen ahşap yaya köprüsü"}},{id:"meaning-4",practice:["Hangi pratik yardımın veya korunmanın mümkün olduğuna bak.","Belirli bir istek, güvenli sınır veya gereken dinlenmeyi seç.","Anlam veya iyi taraf bulmayı şart koşmadan seçtiğin adımı at."],correct:2,photo:{id:"1519681393784-d120267933ba",alt:"Gece karlı dağların üzerinde parlayan yıldızlar"}},{id:"meaning-5",practice:["İstersen yakın gelecekte sade bir sahne düşün. Bu hazırlıktır; ilk araştırmadaki yazma yöntemi değil.","Gerçek bir engel seç ve karşılaştığında ne yapacağını belirle.","Amacına katkı sağlayan tek parçayı yap. Sahneyi ve işi ayrı kaydet."],correct:1,photo:{id:"1501785888041-af3ef285b470",alt:"Dağlarla çevrili sakin bir göl"}},{id:"meaning-6",practice:["Aynı amacın için gerçekten yaptığın denemeleri karşılaştır.","Gelecek hafta tekrarlayacağın veya değiştireceğin tek koşulu seç.","Yararlı küçük adımı dene. Başlama anını ve yaptığın işi kaydet."],correct:1,photo:{id:"1472214103451-9374bd1c798e",alt:"Yumuşak ışıkta ağaçların olduğu yeşil çayır"}}],h={id:"meaning",title:"Günün dolu, önemsediğin şeye sıra yok mu?",subtitle:"6 ders. Seçtiğin amaç için küçük adımlar at, olanları kaydet ve haftana uyan bir plan yap.",description:"Dikkatini vermeye değer bir ilişki veya katkı seç. Küçük bir iş dene, seçimlerinin bedeline bak ve gerçekte olana göre değiştir.",scope:"Günleri dolu ama yönünü kaybetmiş hisseden, yol ayrımında olan veya günlerini önem verdiği şeylere göre yaşamak isteyen yetişkinler için. Hayatın ve seçimlerin üzerine düşünmeni sağlayan bir eğitimdir. Terapi veya tedavi değildir. Boşluk veya umutsuzluk sürüyorsa ya da günlük işleri yapmak zorlaşıyorsa bir doktora veya ruh sağlığı uzmanına başvur. Daha erken destek de isteyebilirsin. İntihar düşüncelerinde veya duygusal krizde bulunduğun yerdeki kriz desteğine ulaş. ABD’de 988’i arayabilir veya mesaj gönderebilirsin. Acil tehlikede yerel acil yardım hizmetlerini kullan.",outcome:"Sorumluluklarını koruyan bir deneme, yaptıklarının kaydı ve gelecek hafta için bir plan.",photo:{id:"1500530855697-b586d89ba3ee",alt:"Açık tepeler arasından ufka doğru kıvrılan bir yol"},lang:"tr",lessons:y.map((a,e)=>{const l=z[e],i=a.judgment.primary,r=i.options.find(n=>n.id===i.bestOptionId),t=i.options.filter(n=>n.id!==i.bestOptionId).map(n=>n.text);return t.splice(l.correct,0,r.text),{...l,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${i.scenario} ${i.question}`,options:t,feedback:r.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}})},q=Object.freeze(Object.defineProperty({__proto__:null,COURSE:h,LESSONS_V2:y,SOURCES:v},Symbol.toStringTag,{value:"Module"})),f=[{id:"motivation-lally",title:"Surrey Üniversitesi · “Bir alışkanlık edinmek gerçekten 66 gün mü sürer?” Dr. Pippa Lally ile söyleşi",url:"https://www.surrey.ac.uk/news/does-it-really-take-66-days-form-habit-we-asked-expert-dr-pippa-lally",type:"guidance",finding:"Lally, 2010 tarihli çalışmasında günlük bir alışkanlığın ortalama 66 günde oluştuğunu anlatıyor. Ancak süre 18 ile 254 gün arasında değişiyordu. Alışkanlık edinme süresinin çok değişken olduğunu vurguluyor. Bilmenin tek başına davranışı değiştirmediğini belirtiyor ve neyi, ne zaman, nerede yapacağını belirleyen net bir plan öneriyor.",limitation:"Çalışmayı özetleyen bir üniversite haber söyleşisidir, makalenin kendisi değildir. Rakamlar tek bir örneklemi ve günlük davranışları anlatır; senin süren farklı olabilir."},{id:"motivation-fogg",title:"BJ Fogg · Tiny Habits (2020), Forbes söyleşisi, “Stanford’lı davranış bilimci değişimin anahtarının bu olduğunu söylüyor”",url:"https://www.forbes.com/sites/alisacohn/2020/02/25/stanford-behavior-scientist-says-this-one-thing-is-the-key-to-change/",type:"technique",finding:"Fogg’un yöntemi üç parçadan oluşuyor. İlki bir çıpa: diş fırçalamak gibi her gün yaptığın ve yeni davranışı hatırlatan bir şey. İkincisi küçük bir davranış: örneğin yirmi dakika yerine bir dakika meditasyon yapmak ya da yalnızca bir dişin arasını diş ipiyle temizlemek. Üçüncüsü, hemen ardından kutlamak. Fogg’a göre alışkanlığı oluşturan, davranışla birlikte yaşanan olumlu duygu.",limitation:"Kitabı anlatan bir söyleşi. Kitap Fogg’un kendi çalışmalarına ve koçluk deneyimine dayanıyor. Bulabildiğimiz kadarıyla yöntemin tamamını ve özellikle kutlama adımını destekleyen bağımsız kontrollü araştırmalar az."},{id:"motivation-fogg-model",title:"BJ Fogg · Fogg davranış modeli (behaviormodel.org)",url:"https://behaviormodel.org/",type:"guidance",finding:"Modelin formülü B = MAP. Buna göre motivasyon, yapabilme ve bir hatırlatıcı aynı anda bulunduğunda davranış gerçekleşir. Davranış gerçekleşmiyorsa bu üçünden en az biri eksiktir.",limitation:"Yazarın kendi sitesinde sunduğu açıklayıcı bir model; bir deney sonucu değil. Aksayan bir alışkanlıkta neyin eksik olduğunu anlamaya yardımcı olabilir. Ölçümlere dayanan bir öngörü sunmaz."},{id:"motivation-woop",title:"Gabriele Oettingen · WOOP: Dilek, Sonuç, Engel, Plan (woopmylife.org)",url:"https://woopmylife.org/",type:"technique",finding:"Psikolog Gabriele Oettingen’in geliştirdiği WOOP’un dört adımı var: bir isteğini belirle, en iyi sonucu hayal et, seni engelleyen duygu, düşünce ya da alışkanlığı fark et. Sonra bu engelle karşılaşınca ne yapacağını belirleyen bir eğer-öyleyse planı yaz. Site, yöntemi istekleri gerçekleştirmek ve alışkanlıkları değiştirmek için bilime dayalı bir zihinsel strateji olarak tanımlıyor.",limitation:"Yöntemin resmî sitesidir. Zihinsel karşılaştırmayı eğer-öyleyse planlarıyla birleştiren araştırmalar küçük ile orta arası ortalama etkiler gösterir (bkz. Wang ve ark. meta-analizi); sitenin kendisi okundu, her çalışma okunmadı."},{id:"motivation-milkman",title:"Katy Milkman · Keyifli bir şeyle eşleştirme (Character Lab önerisi; bkz. ayrıca How to Change, 2021)",url:"https://characterlab.org/tips-of-the-week/temptation-bundling/",type:"technique",finding:"Wharton profesörü Milkman, zevk aldığın bir şeyi yararlı ama angarya gibi gelen bir işle eşleştirmeyi öneriyor. Örneğin sürükleyici bir romanı yalnızca egzersiz yaparken okumak ya da sevdiğin diziyi yalnızca ev işi yaparken izlemek. Böylece hedefin için çalışmak daha keyifli hâle geliyor.",limitation:"Araştırmacının kısa bir pratik önerisi. Saha çalışmalarında egzersiz için sınırlı bir ortalama yarar görüldü. Diğer yaşam alanlarındaki etkisi daha az incelendi."},{id:"motivation-bundling-gym",title:"Milkman, Minson & Volpp · 2014 · Spor salonunda keyifli bir şeyle eşleştirme (Knowledge at Wharton özeti)",url:"https://knowledge.wharton.upenn.edu/article/researchers-used-hunger-games-encourage-healthier-choices/",type:"research",finding:"Üniversitenin spor salonuna üye 226 kişiyle dokuz haftalık bir deney yapıldı. Sürükleyici sesli kitapları yalnızca salonda dinleyebilenler, başlangıçta kontrol grubuna göre salona %51 daha sık gitti. Etki Şükran Günü tatilinden sonra zayıfladı. Deneyin sonunda katılımcıların %61’i, sesli kitapları yalnızca salonda dinlemeye devam etmek için ödeme yapmayı seçti.",limitation:"Tek bir üniversite örneklemi ve kısa bir çalışma; etki de zamanla geçti. Makalenin bir üniversite haber özeti okundu, makalenin tamamı değil."},{id:"motivation-bundling-teaching",title:"Kirgios ve ark. · 2020 · Egzersizi artırmak için keyifli bir şeyle eşleştirmeyi öğretmek: bir saha deneyi",url:"https://www.sciencedirect.com/science/article/pii/S074959782030385X",type:"research",finding:"6.792 spor salonu üyesiyle yapılan geniş bir saha deneyinde, bir gruba sesli kitap verildi ve kitabı egzersizle eşleştirmeleri önerildi. Bu grubun herhangi bir haftada antrenman yapma olasılığı kontrol grubuna göre %10–14 daha yüksekti. Haftalık antrenman sayısı da %10–12 daha fazlaydı. Yararlar 17 hafta sonrasına kadar görüldü.",limitation:"Spor salonu üyelerinde egzersiz için mütevazı bir ortalama etki; başka hedefler için sınanmadı. Yalnızca özet okundu."}],B={"motivation-1":{deeper:[{heading:"Kalıcı motivasyonun ardındaki üç ihtiyaç",paragraphs:["Psikologlar Edward Deci ve Richard Ryan’ın geliştirdiği öz belirleme kuramına göre, üç temel ihtiyaç karşılandığında motivasyon daha uzun sürer. Özerklik, başkasının zoruyla değil, kendi seçiminle hareket ettiğini hissetmektir. Yeterlik, bunu yapabileceğine inanmaktır. İlişki kurma ise bu süreçte başkalarıyla bağının olmasıdır.","Kuram iki tür motivasyonu ayırır. Özerk motivasyon, ilginden ya da değerlerinden doğar. Kontrollü motivasyonun kaynağı baskı, ödül ya da başkalarının beklentileridir. İkisi de seni harekete geçirebilir. Ama ilki genellikle daha kalıcıdır."],visual:{kind:"table",title:"Üç ihtiyaç, üç soru",columns:["İhtiyaç","Ne demek","Kendine sor"],rows:[["Özerklik","Kendi seçiminle hareket etmek","Bunu ben mi seçiyorum, yoksa yapmam gerektiğini mi düşünüyorum?"],["Yeterlik","Bunu yapabileceğini hissetmek","İlk adım başarabileceğim kadar küçük mü?"],["İlişki kurma","Başkalarıyla bağ hissetmek","Bunu kiminle paylaşabilirim? Kim bana destek olabilir?"]],note:"Öz belirleme kuramına (Deci ve Ryan) dayanır. Sorular ODA’nın uyarlamasıdır."}},{heading:"Araştırma ne diyor?",paragraphs:["2021 tarihli bir meta-analiz, öz belirleme kuramına dayanan 73 sağlık uygulaması çalışmasını bir araya getirdi. Bu uygulamalar, özerk motivasyonda ve ilgili ölçümlerde ortalama küçük ile orta düzeyde artış sağladı. Fiziksel ve psikolojik sağlıkta küçük iyileşmeler görüldü. Özerk motivasyon arttığında sağlıkla ilgili davranışlar da genellikle iyileşiyordu.","Etkiler sınırlıydı ve çalışmadan çalışmaya değişiyordu. Üstelik araştırmalar yalnızca sağlık alışkanlıklarıyla ilgiliydi. Yine de şu fikir işe yarayabilir: gerçekten benimsediğin bir hedefle başlamak, sırf bir hedefin olmalı diye düşündüğün bir şeyi seçmekten daha iyi olabilir."]}],example:{title:"Serkan, 31, müşteri hizmetleri temsilcisi",text:"Serkan’ın hedef listesinde üç yıldır “maraton koşmak” vardı; çoğunlukla iki iş arkadaşı kendi hedeflerinden bahsettiği için. Gününde neyi değiştirmek istediğini kendine sorduğunda dürüst cevap farklıydı: işten sonra bedenindeki tutulmayı azaltmak ve hava kararmadan biraz dışarıda zaman geçirmek istiyordu. İkisi için de maraton gerekmiyordu. Hedefi “mesaimden sonra parkta 20 dakikalık yürüyüş, haftada üç gün” diye yeniden yazdı. Aynı saatte köpeğini gezdiren komşusuna da salı günleri ona katılıp katılamayacağını sordu. İlk hafta iki kez yürüdü. Maratondan küçük bir hedefti ama kendi isteğiydi. Üstelik yürüyüş saatini iple çekiyordu."},sources:["motivation-sdt","motivation-sdt-meta"]},"motivation-2":{deeper:[{heading:"Davranış için istek, yapabilme ve hatırlatıcı gerekir",paragraphs:["Stanford’da çalışan davranış bilimci BJ Fogg, modelini B = MAP formülüyle anlatır. Buna göre motivasyon, yapabilme ve bir hatırlatıcı aynı anda bulunduğunda davranış gerçekleşir. Davranış gerçekleşmiyorsa bu üçünden en az biri eksiktir.","Motivasyonun artıp azalır; ona her zaman güvenemezsin. Yapabilme ise davranışın senin için ne kadar kolay olduğuyla ilgilidir. Bunu kolaylaştırabilirsin. Başlangıcı küçültmek bu yüzden işe yarar: ilk adım kolay olunca, motivasyonunun düşük olduğu bir anda da başlayabilirsin."],visual:{kind:"table",title:"B = MAP: eksik parçayı bul",columns:["Öğe","Soru","Örnek çözüm"],rows:[["Motivasyon","Bunu gerçekten istiyor muyum?","Senin için neden önemli olduğunu hatırla (1. ders)"],["Yapabilme","Şu an yeterince kolay mı?","Bir bölüm yerine bir sayfa"],["Hatırlatıcı","Doğru anda bunu bana ne hatırlatır?","Yastığın üstünde kitap (3. ders)"]],note:"Fogg’un davranış modeline dayanır. Bir davranış aksadığında hangi parçanın eksik olduğuna bak."}},{heading:"Fogg neden küçük bir kutlama ekliyor?",paragraphs:["Fogg, Tiny Habits yöntemine birçok kişinin atladığı bir adım ekler: küçük davranışı yapar yapmaz kutlamak. Sessizce “Evet!” diyebilir ya da gülümseyebilirsin. Ona göre davranışla birlikte yaşanan olumlu duygu, alışkanlığın yerleşmesine yardımcı olur.","Yöntemin bu kısmı, kontrollü çalışmalardan çok Fogg’un deneyimine ve koçluk çalışmalarına dayanıyor. Bu yüzden deneyip sana uyup uymadığına bak. Küçük bir sevinç anı yarın yeniden yapmanı kolaylaştırıyorsa devam et. Zorlama geliyorsa, yaptığını bir tik işaretiyle kaydetmek de aynı işe yarayabilir."]}],example:{title:"Nurten, 52, eczacı",text:"Nurten akşamları esneme hareketleri yapmak istiyordu. Ama sofrayı topladığında 20 dakikalık bir rutin imkânsız geliyordu. Tek bir hareketle başlamaya karar verdi: üç nefes boyunca ayak parmaklarına dokunacak kadar öne eğilmek. Yoga minderini koltuğun yanına serip bıraktı. Pazartesi günü bu hareketi yaptı. Sonra kendisi de şaşırarak iki hareket daha ekledi. Salı günü bitkindi ve yalnızca ilkini yaptı. Ardından yüksek sesle “Tamam” deyince güldü. Hafta sonuna doğru minder salonun bir parçası olmuştu. Tek hareket, çoğu akşam beş altı harekete dönüşmüştü. Bazı akşamlar yine yalnızca birini yapıyordu. Bunun da sayılmasına karar verdi."},sources:["motivation-fogg","motivation-fogg-model"]},"motivation-3":{deeper:[{heading:"Çıpayı davranışa bağla",paragraphs:["BJ Fogg, hatırlatıcı olarak kullandığın günlük davranışa çıpa der. Bağlantıyı şöyle kurar: “[Çıpa davranışını] yaptıktan sonra [küçük davranışı] yapacağım.” Çıpa, her gün düşünmeden yaptığın bir şey olmalı. Yeni davranış da aynı yerde kolayca yapılabilmeli. Örneğin diş ipi kullanmak, işe giderken yaptığın yolculuktan çok diş fırçalamaya bağlanır.","Aynı koşullarda tekrar ettikçe, hatırlatıcı davranışı daha kolay aklına getirir. Zamanla daha az düşünerek yaparsın. Araştırmacıların alışkanlık dediği şey bu giderek artan otomatikleşmedir."],visual:{kind:"cycle",title:"Bir hatırlatıcı nasıl alışkanlığa dönüşür?",center:"Aynı koşullar, tekrar tekrar",nodes:[{label:"Hatırlatıcı",text:"Zaten yaptığın bir çıpa: “Çayımı doldurduktan sonra…”"},{label:"Küçük davranış",text:"“…kitabımı açacağım.”"},{label:"Küçük bir memnuniyet",text:"Küçük bir memnuniyet anı."},{label:"Tekrar",text:"Her gün aynı hatırlatıcı, aynı yer."}],note:"Alışkanlık araştırmalarına ve Fogg’un yöntemine dayanan basit bir şema. Sürecin nasıl işlediğini anlatır; ne kadar süreceğini söylemez."}},{heading:"Ne kadar sürer?",paragraphs:["Bir alışkanlığın 21 ya da 66 günde oluştuğunu duymuş olabilirsin. Pippa Lally’nin 2010 tarihli çalışmasında günlük bir alışkanlığın oluşması ortalama 66 gün sürmüştü. Ama süre 18 ile 254 gün arasında değişiyordu. Lally, asıl bulgunun bu büyük farklar olduğunu vurguluyor.","Yetişmen gereken bir tarih yok. Bir ay sonra alışkanlığını sürdürmek için hâlâ çabalıyorsan bu normal. Yanlış yaptığını göstermez."],visual:{kind:"bars",title:"Günlük bir alışkanlığın otomatikleşmesi için geçen gün sayısı",bars:[{label:"En hızlı",value:18,display:"18 gün"},{label:"Ortalama",value:66,display:"66 gün"},{label:"En yavaş",value:254,display:"254 gün"}],note:"Lally 2010, Lally’nin Surrey Üniversitesi söyleşisindeki anlatımıyla: tek bir örneklem ve yalnızca günlük davranışlar; senin süren farklı olabilir.",sourceId:"motivation-lally"}},{heading:"Sık yapılan hatalar",paragraphs:["En yaygın hatırlatıcı aynı zamanda en belirsizi: “Vaktim olduğunda.” Bunun belli bir zamanı yok. Her gün farklı saatte ya da yerde gerçekleşen bir çıpa seçmek de işi zorlaştırır. Düzenli yaptığın bir şey seç. Birkaç denemeden sonra işe yaramazsa, kendini suçlamadan önce hatırlatıcıyı değiştir."]}],example:{title:"Berk, 24, kurye",text:"Berk İspanyolca çalışmak istiyordu ama hep “sonra vakit bulurum” diyordu ve o vakit hiç gelmiyordu. Her gün aşağı yukarı aynı saatte olan bir şey aradı. Cevap öğle yemeğiydi: hep öğlen civarı minibüste yerdi. Tarifi şöyle oldu: “Yemeğimi açtıktan sonra dil uygulamamda bir ders yapacağım.” İlk iki gün unuttu, çünkü telefonu torpido gözündeydi. Onu bardaklığa taşıdı. Çarşamba günü işe yaradı, perşembe günü de. Cuma günü öğle yemeğini tamamen atladı, yani hatırlatıcı da olmadı. Dersi evde yaptı ve bunu dert etmedi. Üç hafta sonra, canı istemeyen günlerde bile yemeğini açmak ona dersi hatırlatıyordu."},sources:["motivation-fogg","motivation-lally"]},"motivation-4":{deeper:[{heading:"Yalnızca hayal etmek neden yetmez?",paragraphs:["Psikolog Gabriele Oettingen, zihinsel karşılaştırma denen bir yaklaşım geliştirdi. Önemsediğin isteği hayal eder, sonra seni neyin engellediğine açıkça bakarsın. Buna bir eğer-öyleyse planı eklenince dört adımlı WOOP yöntemi ortaya çıktı: Dilek, Sonuç, Engel, Plan (Wish, Outcome, Obstacle, Plan).","21 çalışmanın meta-analizinde, zihinsel karşılaştırmayı eğer-öyleyse planlarıyla birleştirmek hedeflere ulaşmayı ortalama küçük ile orta düzeyde artırdı. Etki var ama sınırlı. Yararlı bir araç olabilir; sonucu garanti etmez."],visual:{kind:"compare",title:"Olumlu hayal ya da zihinsel karşılaştırma",left:{label:"Yalnızca mutlu son",items:["Hedefe çoktan ulaşmış gibi hayal et","Şimdi iyi hisset","Engelle hazırlıksız karşılaş"]},right:{label:"Zihinsel karşılaştırma (WOOP)",items:["En iyi sonucu hayal et","İçindeki engeli adlandır","Onu bir eğer-öyleyse planına bağla"]},note:"Gabriele Oettingen’in WOOP yöntemine dayanır. Hayal kurmak yararlı olabilir. Önündeki engeli de açıkça görürsen daha çok işe yarar."}},{heading:"İçindeki engeller ve dış koşullar",paragraphs:["WOOP, seni engelleyen bir alışkanlığa, duyguya ya da düşünceye odaklanır. Çünkü bunlarla karşılaşınca ne yapacağını planlayabilirsin. Çocuğunun hasta olması, gece vardiyasında çalışmak ya da bütçenin dar olması da gerçek engellerdir. Ama bunlar için başka çözümler gerekir: hedefi küçültmek, zamanını ya da biçimini değiştirmek veya yardım istemek.","Bunları ayırt etmek seni iki tuzaktan korur: kontrol edemediğin şeyler için kendini suçlamak ve kontrol edebildiklerini görmezden gelmek."]}],example:{title:"Gamze, 36, banka gişe görevlisi",text:"Gamze haftada üç akşam gitar çalışmak istiyordu. Eve dönerken otobüste WOOP’u denedi. Dilek: yaza kadar üç şarkıyı iyi çalmak. En iyi sonuç: yeğeninin doğum gününde çalmak. Engel, açıkça bakınca: eve gelince “bir dakikalığına” kanepeye oturuyor ve akşam bitiyordu. Plan: “Kanepeye oturmak istersem, oturmadan önce gitarı kılıfından çıkaracağım.” İlk akşam planı unuttu. İkinci akşam hatırladı, gitarı çıkardı ve kanepenin üstünde on dakika çaldı. Perşembe günü mesaisi uzadı. Bu dışarıdan gelen bir engeldi. O yüzden suçluluk duymadan bıraktı ve cumartesi çaldı."},sources:["motivation-woop"]},"motivation-5":{deeper:[{heading:"Kaçırılan bir gün alışkanlığı silmez",paragraphs:["Lally’nin alışkanlık çalışmasında, davranışı bir kez yapmamak otomatikleşme sürecini belirgin biçimde aksatmadı. Daha önemli olan, yeniden yapmak gibi görünüyor. Bir günün aksamasından çok, ardından kendine söylediğin cümle sorun çıkarabilir: “Düzenimi bozdum, artık neden uğraşayım?”","Bir sonraki hatırlatıcıyı yeni bir fırsat saymak daha nazik ve yararlı bir yaklaşım. Büyük bir çabayla telafi etmek yerine davranışın küçük hâliyle yeniden başla."]},{heading:"Yeniden başlamayı daha keyifli yap",paragraphs:["Wharton profesörü Katy Milkman, yapmaktan kaçındığın bir işi keyifli bir şeyle eşleştirmenin etkisini inceliyor. İlk çalışmasında, sürükleyici sesli kitapları yalnızca spor salonunda dinleyebilenler başlangıçta salona kontrol grubundan %51 daha sık gitti. Ancak tatil arasından sonra etki zayıfladı.","6.792 spor salonu üyesiyle yapılan sonraki saha deneyinde daha küçük ama uzun süren bir etki görüldü. İnsanlara sesli kitabı egzersizle eşleştirmeyi öğretmek, herhangi bir haftada antrenman yapma olasılığını %10–14 artırdı. Yararlar 17 hafta sonrasına kadar görüldü. Etkisi sınırlı ama denemesi kolay."],visual:{kind:"table",title:"İki çalışmada keyifli bir şeyle eşleştirme",columns:["Çalışma","Kim","Ne oldu"],rows:[["Milkman ve ark. 2014","226 üniversite spor salonu üyesi","Yalnızca salonda dinlenebilen sesli kitaplarla başlangıçta %51 daha fazla ziyaret; etki bir aradan sonra zayıfladı"],["Kirgios ve ark. 2020","6.792 spor salonu üyesi","Eşleştirmeyi öğrenenlerde belirli bir haftada antrenman yapma olasılığı %10–14 daha yüksek, 17 haftaya kadar"]],note:"İki çalışma da egzersizle ilgilidir. Etki ortalama olarak mütevazıdır ve başka hedefler için farklı olabilir."}}],example:{title:"Kemal, 47, otobüs tamircisi",text:"Kemal, on bir gün boyunca akşam yürüyüşünü aksatmadı. Sonra bir aile ziyareti yüzünden beş gün yürüyemedi. İlk düşüncesi düzenini “mahvettiği” oldu. Telafi için iki kat mesafe yürümesi gerektiğini sandı. Sonra kısa haftalık notuna baktı. Ne işe yaramıştı? Yemekten hemen sonra yürümek ve podcast dinlemek. Ne ters gitmişti? Planında bir sorun yoktu; sadece yoğun bir haftaydı. Pazartesi günü küçük adımla yeniden başladı: yemekten sonra mahallede bir tur. Yürüyüşü daha keyifli yapmak için sevdiği futbol podcast’ini yalnızca yürürken dinlemeye karar verdi. O hafta dört kez yürüdü. Aksayan beş gün artık her şeyin bittiği anlamına gelmiyordu."},sources:["motivation-milkman","motivation-bundling-gym","motivation-bundling-teaching"]}},I=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:B,SOURCES:f},Symbol.toStringTag,{value:"Module"})),A=[{id:"manifest-positive-fantasies",title:"Kappes & Oettingen · 2011 · İdealleştirilmiş gelecek hayalleri enerjiyi tüketir",url:"https://www.sciencedirect.com/science/article/abs/pii/S002210311100031X",type:"research",finding:"Dört deneyde katılımcılardan kusursuzlaştırılmış bir gelecek hakkında olumlu hayaller kurmaları istendi. Bu grubun bedensel ve davranışsal göstergelerle ölçülen enerjisi daha düşüktü. Karşılaştırılan gruplar, istenen geleceği sorgulayan, olumsuz ya da nötr hayaller kurmuştu. Hayal daha acil bir ihtiyaçla ilgili olduğunda enerji daha çok düştü. Yazarlar, kendiliğinden kurulan olumlu hayallerin daha az başarıyla ilişkili olmasını kısmen bu enerji düşüşüne bağlar.",limitation:"Küçük katılımcı gruplarıyla yapılmış laboratuvar deneyleridir. Hayal kurmanın her zaman zararlı olduğunu göstermez. Engel ve plan içermeyen kusursuzlaştırılmış bir hayalin, harekete geçme enerjisini azaltabileceğini gösterir. Yalnızca özet okundu."},{id:"manifest-belief-study",title:"Dixon, Hornsey & Hartley · Personality and Social Psychology Bulletin · Manifestasyon inancının psikolojisi (Queensland Üniversitesi özeti, 2023)",url:"https://news.uq.edu.au/2023-09-20-manifesting-your-way-bankruptcy",type:"research",finding:"1.023 katılımcıyla üç çalışma yapıldı. Katılımcıların yaklaşık üçte biri manifestasyon inançlarını benimsiyordu. İnananlar kendilerini daha başarılı görüyor ve daha yüksek hedefler koyuyordu. Ama riskli yatırımlara da daha çok ilgi duyuyorlardı. İflas yaşamış olma ihtimalleri ve hızla zengin olmaya dair gerçekçi olmayan beklentileri daha yüksekti. Araştırmacılar manifestasyonun işe yaradığına dair nesnel kanıt bulamadı.",limitation:"Anket araştırmasıdır; ilişkileri gösterir, nedenleri değil. Makalenin tam metni değil, üniversitenin haber özeti okundu. Bu yüzden ölçümlerin ayrıntıları kontrol edilmedi."},{id:"manifest-murphy",title:"Joseph Murphy · The Power of Your Subconscious Mind (1963; Tarcher baskısı 2008)",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Murphy’ye göre uykuya dalmadan önceki mahmur hâl, telkine en açık zamandır. Dileği kısa bir cümleye indirmeyi ve ninni gibi sakince tekrarlamayı önerir. Ardından sonuç gerçekleşmiş gibi kısa bir sahne hayal edilir. Örneğin bir arkadaşın seni tebrik eder. Sahne bir teşekkür duygusuyla biter. Yayıncı, kitabın temel fikrini çekincesiz inanmak ve içindeki engelleri aşacak biçimde sonucu canlandırmak olarak tanımlar.",limitation:"Yayıncının sayfası okundu. Uykudan önce zihinsel prova yapmak ve net bir niyet belirlemek hazırlanmana yardımcı olabilir. Ancak kitabın, bilinçaltının zenginlik, başarı ya da bedensel iyileşme getirdiği iddiaları araştırmayla desteklenmiyor. Bu iddialar nedeniyle tıbbi tedavini değiştirme."}],S={"manifest-1":{deeper:[{heading:"Hangi uygulamalar araştırmayla destekleniyor?",paragraphs:["Manifestasyon kitapları ve videoları çoğu zaman iki farklı şeyi birbirine karıştırır. İlki günlük hayatta yararlı olabilecek alışkanlıklardır: Ne istediğini belirlemek, gözünde canlandırmak, aklında tutmak ve harekete geçmek. İkincisi ise dünyanın nasıl işlediğine dair bir iddiadır. Buna çoğunlukla çekim yasası denir. Benzerin benzeri çektiği, düşüncelerinin sinyal yaydığı ve evrenin olayları buna göre düzenlediği söylenir. Bazen kuantum fiziğinin de bunu kanıtladığı iddia edilir.","İlk kısmı kullanıp ikinci kısmı bir kenara bırakabilirsin. Yararlı bir şey kaybetmezsin. Fizikçiler dünyayı böyle açıklamaz. Para, bir partner ya da iş hakkında düşünmenin, bunları kendiliğinden getirdiğini gösteren bir çalışma yok. Alışkanlıklar ise sınanmış yöntemlerle örtüşür: Net hedef koymak, zihinsel prova yapmak, engeller için plan hazırlamak ve ilerlemeyi takip etmek. Kurs bunlara dayanır."],visual:{kind:"compare",title:"Yararlı uygulamalar ve kanıtsız iddialar",left:{label:"Kullan: yararlı uygulamalar",items:["Net ve belirli bir niyet","Adımları zihninde prova etmek","Engeli fark edip ona karşı plan hazırlamak","Harekete geçmek, sonra dürüstçe gözden geçirmek"]},right:{label:"Kenara koy: kanıtı yok",items:["Düşünceleri olayları çeken bir mıknatıs saymak","Evrenin odaklandığın şeyi sana getirmesi","Kuantum fiziğinin senin gerçekliğini yeniden şekillendirmesi","Bir aksiliği olumsuz düşünmenin kanıtı saymak"]},note:"Sağ sütundaki iddiaları bırakırken umudunu koruyabilirsin. Umudunu bir planla destekle."}},{heading:"Manifestasyon inancı üzerine araştırma",paragraphs:["Queensland Üniversitesi’nden araştırmacılar manifestasyona inanan insanları inceledi. 1.023 kişinin katıldığı üç çalışmada, yaklaşık üçte biri bu inançları benimsiyordu. İnananlar kendilerini daha başarılı görüyor ve daha yüksek hedefler koyuyordu. Ancak riskli yatırımlara daha çok ilgi duyuyorlardı. İflas yaşamış olma ve hızla zengin olmayı bekleme ihtimalleri de daha yüksekti. Araştırmacılar manifestasyonun işe yaradığına dair nesnel kanıt bulamadı.","Bunlar anketlerdi. Bir ilişki gösterirler ama nedenini açıklamazlar. Yine de bulgular bu kursun yaklaşımıyla uyumlu. Bir şeyi istemekte sorun yok. Risk, kesinlik duygusu gerçekleri kontrol etmenin, tavsiye almanın ve küçük, sınanabilir adımlar atmanın yerini aldığında başlar. Yapacağın davranışı belirlemek, planını gerçekle karşılaştırmanı sağlar."]}],example:{title:"Daniel, 31, depo vardiya amiri",text:"Daniel, lojistik planlama işine geçmek istiyordu. Aylardır telefonunun duvar kâğıdında bir ofis masası vardı. Doğru işin kendisini bulacağını söylüyordu. Pazar günü alıştırmayı denedi. Dileği bir planlama işiydi. Yapacağı davranışı şöyle belirledi: Perşembeye kadar özgeçmişimin ilk üç satırını, hazırladığım vardiya çizelgelerinden söz edecek şekilde yeniden yazacağım. Çarşamba akşamı yemekten sonra bunu yaklaşık yirmi dakikada yaptı. Bir satır hâlâ tuhaf görünüyordu, o hafta kimse aramadı. Ama artık gönderebileceği bir sayfası vardı. Sonraki adım da açıktı: Karşılaştırmak için iki iş ilanı bulmak. Duvar kâğıdını değiştirmedi. Ama artık hayaline bağlı bir işi vardı."},sources:["manifest-belief-study"]},"manifest-2":{deeper:[{heading:"Zihinsel prova hakkında araştırmalar",paragraphs:["2021 tarihli bir meta-analiz, zihinsel canlandırmaya ilişkin 94 randomize çalışmayı birleştirdi. Bu, gelecekteki bir davranışı ya da olayı bilerek hayal etmektir. Sonraki davranış üzerinde genel olarak orta düzeyde etki görüldü. Canlandırmanın türü önemliydi. Kendini işi yaparken, özellikle iyi yaparken görmek en güçlü etkiyi gösterdi. Yalnızca istenen sonucu hayal etmenin etkisi küçüktü. Yalnızca süreç adımlarını hayal etmenin etkisi güvenilir değildi. Ancak bu tahmin sadece beş etkiye dayanıyordu. Sonuç ile süreci birleştiren sekiz çalışmada daha büyük etki bulundu.","Beceri ve spor alanındaki zihinsel provayı inceleyen ayrı bir derleme, küçük ama gerçek bir fayda buldu. Fiziksel uygulama ise yalnızca zihinsel provadan daha etkiliydi. Kendini işi yaparken görmek küçük ile orta düzey arasında bir fayda sağlayabilir. İşi gerçekten yapmak daha fazla yardımcı olur."],visual:{kind:"bars",title:"Zihinsel canlandırma ve sonraki davranış (ortalama etki, Hedges g)",bars:[{label:"Kendini işi iyi yaparken canlandırmak",value:.67,display:"g = 0,67"},{label:"Standart performans provası",value:.48,display:"g = 0,48"},{label:"İstenen sonucu canlandırmak",value:.23,display:"g = 0,23"},{label:"Yalnızca süreç adımlarını canlandırmak (5 etki)",value:.17,display:"g = 0,17"}],note:"Cole ve ark. (2021), 94 randomize çalışma. Yaklaşık 0,2 küçük, 0,5 orta etki sayılır. Katılımcıların çoğu öğrenciydi. Bazı canlandırma türleri az sayıda çalışmaya dayanıyor. Yalnızca süreç adımlarına ait tahmin istatistiksel olarak güvenilir değildi.",sourceId:"identity-cole"}},{heading:"Joseph Murphy ve Dr. Joe Dispenza’nın yöntemleri",paragraphs:["İki tanınmış öğretmen, yöntemlerinde zihinsel provaya yer verir. Joseph Murphy, The Power of Your Subconscious Mind kitabında uykuya dalmadan önceki mahmur dakikaları önerir. Dileğini kısa bir cümleye indirir, sakince tekrarlarsın. Sonuç gerçekleşmiş gibi kısa bir sahne hayal eder, teşekkür duygusuyla bitirirsin. Dr. Joe Dispenza ise Breaking the Habit of Being Yourself kitabında sabah meditasyonu önerir. Bu çalışmada, olmak istediğin kişinin nasıl düşündüğünü, davrandığını ve hissettiğini ayrıntılı biçimde prova edersin.","İki yöntemde de yararlı olabilecek uygulamalar var. Ama ikisi de araştırmaların desteklediğinden çok fazlasını iddia eder. Murphy, bilinçaltının zenginlik ve iyileşme getirebileceğini yazar. Dispenza, uygulamasını kuantum alanıyla ve genlerini değiştirmekle ilişkilendirir. Zihinsel provayı kullanıp diğer iddiaları bir kenara bırakabilirsin."],visual:{kind:"table",title:"İki yöntemde ne var, ne desteklenmiyor?",columns:["Öğretmen","Ne yapıyorsun","Tut","Kenara koy"],rows:[["Joseph Murphy","Uykudan önce kısa bir cümle ve sonuç gerçekleşmiş gibi bir sahne","Sakin, net bir niyet; bir sahneyi prova etmek","Bilinçaltının para ya da iyileşme getirmesi"],["Dr. Joe Dispenza","Olmak istediğin kişiyi prova ettiğin sabah meditasyonu","Nasıl davranıp yanıt vereceğini prova etmek","Kuantum alanı ve gen değiştirme iddiaları"],["Bu kurs","Önce sonuç, sonra ilk somut hareket","Adımı yaparken kendini görmek","Hayali, eylemin yerine koymak"]],note:"Yöntemlerin tamamını değil, ana noktalarını özetledik. İkisi de bütün hâliyle kontrollü araştırmalarda sınanmadı."}}],example:{title:"Priya, 27, çocuk hemşiresi",text:"Priya bir uzmanlık eğitimine başvurmak istiyordu. Yeni rozetini takacağı günü sık sık hayal ediyordu. Bu ona iyi geliyordu ama hiçbir şeyi değiştirmiyordu. Bir gece yatakta başka bir sahne düşündü. Rozetin ardından ertesi sabahı canlandırdı: Kahvaltıdan sonra mutfak masasında, bilgisayarı açık. Ekranda başvuru sitesi ve kendisini anlatması gereken metin alanı var. Giriş bilgilerini bilmediğini, metne de ilk cümleyle başlaması gerektiğini fark etti. Sabah şifresini yeniledi. Çocuk hemşireliğini neden seçtiğini anlatan ilk cümleyi yazdı. On dakika sonra bilgisayarı kapattı. Rozeti almasına hâlâ aylar vardı. Ama başvuru sonunda başlamıştı."},sources:["manifest-murphy","identity-cole","identity-toth","identity-dispenza-habit"]},"manifest-3":{deeper:[{heading:"Hoş bir hayal neden enerjini azaltabilir?",paragraphs:["Oettingen’in ekibinin önceki araştırmasında, gelecek hakkında kendiliğinden pembe hayaller kuran kişiler daha az başarı gösterme eğilimindeydi. Nedenini araştırmak için Heather Barry Kappes ve Gabriele Oettingen dört deney yaptı. Katılımcılardan kusursuzlaştırılmış bir geleceği hayal etmelerini istediler. Bu grubun hem bedensel hem davranışsal göstergelerle ölçülen enerjisi daha düşük çıktı. Karşılaştırma grupları geleceği sorgulayan, olumsuz ya da nötr hayaller kurmuştu. İhtiyaç daha acil hissedildiğinde enerji daha çok düştü.","Bunu şöyle düşünebilirsin: Kusursuz bir hayal, çabalamadan sonuca ulaşmanın tadını verir. Beden, iş bitmiş gibi gevşeyebilir. Bu, hayal kurmanın kötü olduğu anlamına gelmez. Hayali, son durak yerine başlangıç olarak kullanmak daha yararlı olabilir."],visual:{kind:"cycle",title:"Hayal döngüsü",center:"Yalnızca hayal",nodes:[{label:"Kusursuz hayal",text:"Sonuca ulaşmışsın gibi hayal edersin. Hiç engel yoktur."},{label:"Varmış gibi hissettirir",text:"Zihnin, sanki gerçekleşmiş gibi bu sonucu yaşar."},{label:"Enerji düşer",text:"Harekete geçmek için eskisi kadar acele etmen gerekmediğini hissedersin. Beden gevşer."},{label:"Az adım",text:"Gün somut bir adım atılmadan geçer."},{label:"Dilek hâlâ uzakta",text:"Gerçekle hayal arasındaki fark canını yakar. Yeniden hayale dönersin."}],note:"Kappes & Oettingen (2011) çalışmasına dayanan basitleştirilmiş bir anlatım. Döngüden çıkmak için hayali, gerçek bir engel ve planla birleştir."}},{heading:"WOOP: hayali gerçekle karşılaştırmak",paragraphs:["Oettingen, zihinsel karşılaştırmayı WOOP adlı dört adımlı bir yönteme dönüştürdü: Wish (Dilek), Outcome (Sonuç), Obstacle (Engel), Plan. Önce hoş kısma bakarsın. Dileğini belirler, en iyi sonucu hayal edersin. Sonra içindeki asıl engeli ele alırsın. Bu bir alışkanlık, duygu ya da inanç olabilir. Son adım olan planı bir sonraki derste işleyeceğiz.","15.907 kişinin katıldığı 21 çalışmayı birleştiren 2021 tarihli meta-analizde, zihinsel karşılaştırma ve eğer-öyleyse planları hedeflere ulaşmada küçük ile orta düzey arasında ortalama etki gösterdi. Bu gerçek bir etkiydi ama garanti değildi. WOOP, dileğin sana uymadığında da bilgi verir. Engele dürüstçe bakınca dilek gerçekçi gelmiyorsa, onu yeniden şekillendirebilirsin. Bu bir başarısızlık değildir."]}],example:{title:"Lena, 38, ortaokul öğretmeni",text:"Lena, veri becerileriyle ilgili çevrim içi kursunu bitirmek istiyordu. Genellikle sertifikasını ve ilçe müdürlüğünde yeni bir görevi hayal ediyordu. Bu kez WOOP kullandı. Dilek: Bu ay üçüncü modülü bitirmek. Sonuç: İşte elektronik tabloları rahatça kullanabilmek. Sonra engele baktı. Asıl sorun tembellik değildi. Sınav kâğıtlarını okuyup iki çocuğunu yatırınca saat 21.30 oluyordu. Bitkin düşüyor, telefonuna uzanıyordu. Bunun bir kısmı değiştiremediği dış koşullardı. Bu yüzden planı değiştirdi. Eşi çocukları parka götürürken cumartesi sabahı kırk beş dakika çalışacaktı. İlk cumartesi bir ders bitirdi. Umduğundan azdı ama önceki üç haftada yaptığından fazlaydı."},sources:["oettingen-woop-method","manifest-positive-fantasies"]},"manifest-4":{deeper:[{heading:"Eğer-öyleyse planları neden işe yarar?",paragraphs:["Psikologlar bunlara uygulama niyetleri der. Peter Gollwitzer ve Paschal Sheeran 94 bağımsız testi birleştirdi. Ne zaman, nerede ve nasıl davranacağını önceden belirleyen planların hedefe ulaşmada orta ile büyük düzey arasında ortalama etkisi vardı. Yayın yanlılığını hesaba katan daha yeni analizlerde gerçek etki daha düşük çıkabilir. Ama genel yön aynı kalır.","Muhtemel neden basittir. Bir durumu önceden bir davranışa bağladığında, durumun kendisi hatırlatıcı olur. Yorgun ya da huzursuz olduğun anda yeniden karar vermen gerekmez. Telefonda gezinmek kolay gelse de, ne yapacağını önceden belirlemişsindir."],visual:{kind:"compare",title:"Belirsiz niyetler ve kullanılabilir planlar",left:{label:"Belirsiz",items:["Bu hafta üzerinde çalışırım.","Daha disiplinli olmaya çalışırım.","Ne olursa olsun pozitif kalırım."]},right:{label:"Eğer-öyleyse",items:["Salı akşamı saat 8 olduğunda mutfak masasında dosyayı açacağım.","Telefonuma uzanırsam onu 15 dakikalığına diğer odaya bırakacağım.","Cesaretim kırılırsa işe yarayan bir şeyi yazacağım."]},note:"Eğer kısmı kolayca fark edeceğin bir durumu anlatır. Öyleyse kısmı, kötü bir günde bile yapabileceğin kadar küçük bir davranıştır."}},{heading:"Sık yapılan hatalar",paragraphs:["En yaygın hata, zamanı belirsiz bırakmaktır. Vaktim olursa çoğu zaman işe yaramaz. Planı bir saate, yere ya da öğle yemeğinin bitmesi gibi tanıdık bir ana bağla. İkinci hata, çok büyük bir iş seçmektir. Bütün bölümü yazacağım demek, yine başlamaktan kaçınmana yol açabilir. Üçüncü hata, aynı anda çok fazla plan yapmaktır. Gerçekten kullandığın bir ya da iki plan, bir sayfa kuraldan daha yararlıdır.","Planı uygulayamadığında bunu kendin hakkında bir yargı değil, bilgi olarak gör. Belki işareti fark etmedin ya da seçtiğin davranış hâlâ çok büyüktü. Bir parçayı değiştirip yeniden dene."]}],example:{title:"Tomás, 35, serbest grafik tasarımcı",text:"Tomás bir yıldır hayal ederek portfolyo sitesini gerçeğe dönüştürmeye çalışıyordu. Siteyi açıkça hayal edebiliyordu. Ama site oluşturma aracını her açtığında boş sayfayı görüyor, e-postalarına geçiyordu. Ekranının yanındaki bir nota iki plan yazdı. Aracı açıp tıkanırsam yalnızca sayfa başlığını ve iki projenin adını yazacağım. Salı sabahı saat 9’da başlamamışsam on dakikalık bir zamanlayıcı kuracağım. Salı günü ikinci planı 9.05’te uyguladı. Başlığı ve üç projenin adını yazdı, on iki dakika sonra durdu. Henüz bir sitesi yoktu. Ama ilk kez zihnindeki resimden daha fazlası vardı."},sources:["if-then-plans"]},"manifest-5":{deeper:[{heading:"Neyi takip etmeli, neden yazmalı?",paragraphs:["Yaklaşık 20.000 kişiyle yapılan 138 deneyin meta-analizinde, ilerlemeyi takip etmeyi artıran uygulamalar hedefe ulaşmaya yardımcı oldu. Ortalama etki küçük ile orta düzey arasındaydı. İlerleme kâğıda ya da uygulamaya kaydedildiğinde ve bir başkasına bildirildiğinde fayda daha büyüktü. Notlarını paylaşmak zorunda değilsin. Ama kısa bir satır yazmak, işlerin nasıl gittiğini belirsizce hatırlamaktan daha yararlı görünüyor.","Daha çok elinde olanı takip et: Adımı attın mı? Ne zaman? Hangi koşullarda? Sonuç da önemlidir ama çoğu zaman çabadan daha geç görünür. Başkalarına da bağlıdır. Yalnızca sonucu takip edersen, düzenli çalıştığın hâlde yavaş geçen bir ayı başarısızlık sanabilirsin."],visual:{kind:"cycle",title:"Gözden geçirme döngüsü",center:"Gözden geçirme günü",nodes:[{label:"Dene",text:"Planladığın küçük adımı at."},{label:"Kaydet",text:"Bir satır yaz: ne yaptın, ne zaman, hangi koşullarda."},{label:"Bak",text:"Gözden geçirme gününde notları birlikte oku."},{label:"Öğren",text:"Ne yardımcı oldu? Ne engel oldu?"},{label:"Yeniden seç",text:"Sürdür, küçült, destek al ya da hedefi değiştir."}],note:"Bu döngü, işe yaramayanlar dâhil her denemeden sonraki deneme için bilgi çıkarmanı sağlar."}},{heading:"Sonuç gelmediğinde",paragraphs:["Popüler manifestasyon anlayışı burada bir yük getirebilir. Düşüncelerin gerçekliği yarattığını kabul edersen, sonuç gelmediğinde düşüncelerinin yanlış olduğuna inanabilirsin. Tek çözümün daha çok inanmak olduğunu sanabilirsin. Bu, aynı yerde kalmana ya da riskli adımlar atmana yol açabilir. Manifestasyona güçlü biçimde inananları inceleyen anket araştırmasında da riskli yatırımlar ve iflasla ilişki bulundu. Ancak bu araştırma nedenini gösteremez.","Kendine daha nazik ve yararlı bir soru sorabilirsin: Denemelerim bana ne söylüyor? Bazen sürdürmek gerekir; çaba ile sonuç henüz aynı hızda ilerlemiyordur. Bazen planı değiştirmek, yardım istemek ya da hedefi bırakmak gerekir. Bunların her biri geçerli bir seçimdir."],visual:{kind:"table",title:"Notlarından sonraki adımı seçmek",columns:["Ne görüyorsun?","Makul bir sonraki seçim"],rows:[["Adımları attın; sonuç yavaş","Sürdür ve bir sonraki değerlendirme tarihini belirle"],["Adımı nadiren attın","Adımı küçült ya da eğer kısmındaki işareti değiştir"],["Bir dış koşul seni sürekli engelledi","Zamanlamayı değiştir ya da destek iste"],["Hedef artık senin için önemli değil","Bırak ya da yeni bir dilek seç"]],note:"Bu seçimlerin hiçbiri başarısızlık değildir. Her biri yaşananlara bakarak verilmiş bir karardır."}}],example:{title:"Aisha, 45, küçük bir ev pastanesi işletiyor",text:"Aisha, çeyrek sonuna kadar haftada on düzenli sipariş almak istiyordu. Altı hafta boyunca her pazartesi fotoğraf paylaştı ve iki yerel kafede numune dağıttı. Her denemeden sonra defterine bir satır yazdı. Değerlendirme günü notlarına baktı. Dokuz paylaşım, altı numune günü ve on yerine dört düzenli sipariş vardı. Yeterince inanmadığını düşünmek yerine olanları inceledi. Dört düzenli müşterinin üçü aynı kafeden gelmişti. Orada müşterilerle yüz yüze konuşmuştu. Ayda iki paylaşımı bırakıp o zamanı ikinci bir kafeye ayırmayı seçti. Hedef tarihini bir ay erteledi. Bu ona yenilgi değil, verilmiş bir karar gibi geldi."},sources:["manifest-belief-study"]}},R=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:S,SOURCES:A},Symbol.toStringTag,{value:"Module"})),D=[{id:"meditation-mind-wandering-cycle",title:"Hasenkamp ve ark. · 2012 · Odaklı meditasyonda zihin dağılması ve dikkat (NeuroImage)",url:"https://www.sciencedirect.com/science/article/abs/pii/S1053811911007695",type:"research",finding:"Deneyimli on dört kişi, fMRI cihazında nefese odaklanarak meditasyon yaptı. Zihinlerinin dağıldığını her fark ettiklerinde bir düğmeye basıp dikkatlerini nefese geri verdiler. Araştırmacılar tekrarlanan dört aşamalı bir döngü tanımladı: zihnin dağılması, bunu fark etme, dikkati geri verme ve odağı sürdürme. Her aşamada farklı beyin ağları daha etkindi. Zihin dağılırken varsayılan mod ağı, fark etme sırasında belirginlik ağı, geri dönme ve odaklanma sırasında yürütücü bölgeler öne çıktı. Bazı etkinlik örüntüleri, kişilerin yaşamları boyunca edindikleri meditasyon deneyimiyle ilişkiliydi.",limitation:"Deneyimli 14 kişiyle yapılan küçük bir beyin görüntüleme çalışmasıdır. Meditasyon sırasında olanları anlatır; sağlık yararı göstermez. Beyindeki farklara meditasyonun yol açtığını da kanıtlamaz. Yayıncı sayfasındaki özet okundu."},{id:"meditation-trauma-sensitive",title:"David Treleaven · Travmaya duyarlı farkındalık (davidtreleaven.com)",url:"https://davidtreleaven.com/",type:"guidance",finding:"Farkındalık eğitmenleri yetiştiren David Treleaven, uygulamanın istemeden travmatik stres belirtilerini tetikleyebileceğini belirtir. Travma yaşamış kişiler, dikkatlerini içe çevirdiklerinde geçmişteki olayı yeniden yaşıyormuş gibi hissedebilir (flashback), duygularını düzenlemekte zorlanabilir ya da kendilerinden veya çevrelerinden kopmuş hissedebilir. Sitesinde eğitmenlere ve uygulayan kişilere bu durumları önlemek için eğitim ve kaynaklar sunar.",limitation:"Bir eğitmenin web sitesidir, araştırma değildir. Yalnızca ana sayfa okundu; burada belirli uyarlamalar sıralanmıyor. Bu kurstaki gözleri açık tutma, süreyi kısaltma, dışarıdaki bir şeye odaklanma ve eğitimli bir eğitmenle çalışma önerileri yaygın güvenlik uygulamalarıdır. Bu sayfadan elde edilmiş araştırma bulguları değildir."}],H={"meditation-1":{deeper:[{heading:"Dikkatin dağılması neden uygulamanın parçası?",paragraphs:["Küçük bir beyin görüntüleme çalışması, meditasyon sırasında olanları gösteriyor. Deneyimli on dört kişi nefeslerine odaklandı. Zihinlerinin dağıldığını her fark ettiklerinde bir düğmeye bastılar. Araştırmacılar sürekli tekrarlanan bir döngü tanımladı: zihnin dağılır, fark edersin, dikkatini yeniden nefesine verirsin. Bir süre nefesini izlersin, sonra zihnin yeniden dağılır.","Deneyimli kişiler bile bu döngüyü tekrar tekrar yaşadı. Huzursuz bir günde bunu hatırla. Dikkatinin çok dağılması meditasyonun başarısız olduğu anlamına gelmez. Her fark edip geri döndüğünde uygulamanın en önemli iki adımını tekrarlamış olursun. Çalışma küçüktü ve sağlık üzerindeki etkileri göstermiyor. Ama anlatılan döngü, çoğu insanın deneyimiyle örtüşüyor."],visual:{kind:"cycle",title:"Meditasyon sırasında tekrarlanan döngü",center:"Odak noktası: nefes",nodes:[{label:"Dikkatin dağılır",text:"Dikkat bir plana, bir anıya ya da bir endişeye kayar."},{label:"Fark et",text:"Artık nefesini izlemediğini fark edersin."},{label:"Geri dön",text:"Kendini azarlamadan dikkatini yeniden nefesine verirsin."},{label:"Kal",text:"Dikkatin yeniden dağılana kadar bir süre nefesini izlersin."}],note:"Hasenkamp ve ark. (2012), deneyimli 14 kişide bu dört aşamayı tanımladı. Döngü olağandır. Fark etmek ve geri dönmek uygulamanın kendisidir."}},{heading:"Sık yapılan hatalar",paragraphs:["En sık yapılan hata, nefesi kontrol etmeye çalışmak. Daha derin, daha yavaş ya da daha “doğru” nefes almaya uğraşabilirsin. Bu alıştırmada yalnızca izlemen yeterli. İzlemek nefes alışını yapaylaştırıyorsa dikkatini daha rahat hissettiğin bir yere ver. Burnundaki hava akışı ya da karnının yükselmesi olabilir.","İkinci hata, dikkatin her dağıldığında kendini azarlamak. İçinden sessizce “düşünce” deyip sakin biçimde geri dönmeyi dene. Kendine kızmaktan daha yararlıdır. Beş dakikayla başlamak yeterli. Düzenli yaptığın kısa bir uygulama, gözünü korkutan uzun bir uygulamadan daha iyidir."]}],example:{title:"Leyla, 31, eczacı",text:"Leyla sabah vardiyasından önce beş dakikalık sayaç kurdu. Mutfak sandalyesine oturup ayaklarını yere bastı. Karnının yükselip alçalmasını izlemeyi seçti. Daha ilk dakikada aklında sevkiyat programını düzenlemeye başlamıştı. Bunu fark etti, içinden “düşünce” deyip dikkatini karnına verdi. Sonra yanıtlaması gereken bir mesajı düşündü. Ardından aklına bir şarkı geldi. Sonunda kaç kez geri döndüğünü sayamaz olmuştu. Zihninin bu kadar meşgul olmasına biraz kızdı. Otobüste dersteki döngüyü hatırladı: dağıl, fark et, geri dön, kal. Az önce alıştırmayı onlarca kez yapmıştı. Ertesi sabah yeniden denedi. Bu kez biraz daha az kızıyordu. Kızgınlığını da fark edebileceği bir duygu olarak gördü."},sources:["meditation-mind-wandering-cycle"]},"meditation-2":{deeper:[{heading:"Beden taraması nasıl ilerler?",paragraphs:["Basit bir sıra belirlemek, nereden devam edeceğini düşünme ihtiyacını azaltır. Genellikle kolayca bir şey hissettiğin bir yerden, örneğin ayak tabanlarından başla. Dikkatini yavaşça yukarı taşı. Her bölgede birkaç nefes boyunca kalıp ne hissettiğine bak. Sonra nefes verirken o bölgeyi bırakıp bir sonrakine geç.","Bedeninin her santimini taraman gerekmez. Beş altı bölgeye dikkatle bakmak, bütün bedeni aceleyle taramaktan daha yararlıdır."],visual:{kind:"steps",title:"Kısa bir beden taramasında izlenecek sıra",steps:[{label:"Ayaklar",text:"Parmaklar, tabanlar, topuklar: basınç, sıcaklık, zeminle ya da yatakla temas."},{label:"Bacaklar",text:"Baldırlar, dizler, uyluklar: ağırlık, gerginlik ya da belirgin bir duyum olmaması."},{label:"Gövde",text:"Karın ve sırt: nefesin hareketi, yüzeyle temas."},{label:"Kollar ve eller",text:"Parmaklar, avuç içleri, ön kollar: karıncalanma, sıcaklık, durgunluk."},{label:"Omuzlar ve yüz",text:"Boyun, çene, gözler, alın. Sonra bedeninin tamamını bir bütün olarak hisset."}],note:"MBSR beden taramasına dayanan basitleştirilmiş bir sıra. Ağrı ya da sıkıntı hissettiğin bir bölgeyi atlayabilir veya üzerinde kısa süre durup geçebilirsin."}},{heading:"Bedenine odaklanmak zor geliyorsa",paragraphs:["Bedenine uzun süre dikkat vermek bazı insanları sakinleştirmek yerine sıkıntıya sokabilir. Özellikle travma geçmişin ya da kronik ağrın varsa bu yaşanabilir. Travma alanında çalışan eğitmenler, içe odaklanmanın bazen geçmişteki olayı yeniden yaşıyormuş gibi hissettirebileceğini ya da kopukluk hissini tetikleyebileceğini belirtir.","Nasıl uygulayacağına sen karar verirsin. Gözlerini açık tutabilir, uzanmak yerine oturabilirsin. Taramayı birkaç dakikaya indirebilir ya da yalnızca ellerine ve ayaklarına bakabilirsin. Hâlâ zor geliyorsa odadaki sesler gibi dışarıdaki bir şeye odaklan. Bu alanda eğitimli bir eğitmenle çalışmayı da düşünebilirsin."]}],example:{title:"Tolga, 46, kurye",text:"Tolga uzun bir vardiyadan sonra yatağa uzanıp beden taramasını denedi. Dizlerine gelmeden uyuyakaldı. Ertesi akşam koltuğa oturdu. Gözlerini yarı açık tutup sekiz dakikalık sayaç kurdu. Ayaklarında sıcaklık ve ağırlık hissediyordu. Baldırlarında belirgin bir şey yoktu. Bunun doğru mu yanlış mı olduğunu düşünmeye başladığını fark etti. Yalnızca adını koydu: “Burada belirgin bir duyum yok.” Belinin alt kısmına gelince tanıdık ağrıyı hissetti. Onu gidermeye çalışmadı. İki nefes boyunca orada kalıp devam etti. Sonunda telefonuna üç kelime yazdı: ağır, ağrı, sıcak. Derin bir gevşeme yaşamadı. Ama haftalardır ilk kez bedeni ağrıyla dikkatini çekmeden önce onu fark etmişti."},sources:["meditation-trauma-sensitive"]},"meditation-3":{deeper:[{heading:"Zorlamamak neden önemli?",paragraphs:["Meditasyonu da iyi yapman gereken bir işe çevirebilirsin. Düşüncelerle savaşır, nasıl gittiğini kontrol eder, gevşeyemediğin için gerilirsin. Benson’ın yöntemi bu baskıyı azaltmayı amaçlar. Tekrarladığın kelime, dikkatini verebileceğin basit bir şeydir. Düşüncelere karşı pasif tutum ise onları çözmen gereken sorunlar olarak görmemektir. Geldiklerinde yalnızca kelimeye dönersin.","Nefes alıştırmasında da aynı şeyi yapmıştın. Yalnızca odaklandığın şey değişiyor. Bazı insanlar kelime tekrarlamayı daha kolay bulur. Çünkü nefes gibi bir şeyi izlemek yerine bir şey yaparlar. Bazılarına da fazla mekanik gelir. Sana uygun olanı ararken her iki tepkiyle de karşılaşman olağandır."],visual:{kind:"compare",title:"Çaba mı, rahatlık mı?",left:{label:"Zorlamak",items:["Düşünceleri uzaklaştırmaya çalışmak","Artık gevşedim mi diye yoklamak","Dikkatim dağılınca kelimeyi daha hızlı tekrarlamak"]},right:{label:"Zorlamamak",items:["Düşüncelerin gelip geçmesine izin vermek","Uygulamayı iyi ya da kötü diye puanlamamak","Kelimeye aynı rahat hızla dönmek"]},note:"Harvard Health açıklamasında anlatılan Benson yöntemindeki pasif tutumun özeti."}},{heading:"Kelimeni seç",paragraphs:["Kısa, nefes verirken içinden kolayca söyleyebildiğin bir kelime seç. Sana hoş ya da nötr gelsin. İnancından bir dua ya da zikir sözü olabilir. “Sakin”, “burada” ya da “bir” gibi gündelik bir kelime de seçebilirsin. Benson yöntemi ikisiyle de aynı şekilde uygulanır.","En az bir hafta aynı kelimeyi kullanmayı dene. Her gün değiştirmek, uygulamayı kusursuz kelimeyi aramaya çevirebilir. Bu da kendini zorlamanın başka bir yoludur."]}],example:{title:"Mehmet, 58, emekli öğretmen",text:"Mehmet nefesini izlemenin kendisini huzursuz ettiğini fark etti. Öğleden sonra çayının ardından Benson yöntemini denedi. Çocukluğundan beri bildiği kısa bir zikir sözü seçti. Koltuğuna oturup kaslarını ayaklarından yüzüne doğru gevşetti. Her nefes verişinde sözü içinden tekrarladı. Torununun sınavıyla ilgili düşünceler aklına geliyordu. Her seferinde “Sorun değil” deyip aynı yavaş tempoyla söze döndü. On dakika sonra kalkmadan önce bir dakika daha sessizce oturdu. Büyük bir değişiklik hissetmedi. Ama on bir dakikadır telefonuna bakmamıştı; bu onun için yeniydi. Haftanın kalanında aynı sözü kullanıp aynı koltukta oturmaya karar verdi."},sources:[]},"meditation-4":{deeper:[{heading:"Gündelik hayatta",paragraphs:["Özel bir yola ihtiyacın yok. Yürüyüş meditasyonunu zaten yaptığın yürüyüşlerden birine ekleyebilirsin. Durağa giderken yolun son kısmı, iş yerindeki bir koridor ya da arabadan kapıya yürüyüş olabilir. Bir dakika boyunca adımlarını fark ederek yürümek bile bir uygulamadır.","Yavaş yürümeyi sakin ve güvenli bir yerde dene. Kalabalık sokakta normal hızında yürü. Ayaklarını ve yüzüne değen havayı hissederken çevreni dikkatle izle."],visual:{kind:"table",title:"Nerede, nasıl yürüyebilirsin?",columns:["Yer","Hız","Odak noktası"],rows:[["Evde koridor ya da oda","Çok yavaş","Her ayağın kalkışı, ilerleyişi, yere basışı"],["Park ya da sakin bir yol","Yavaş","Nefese uydurulmuş adımlar"],["İşe ya da durağa yürüyüş","Normal","Ayaklar ve çevrendeki sesler, gözler açık"]],note:"Plum Village rehberine dayanarak hazırladığımız öneriler. Trafikte, merdivenlerde ve kalabalıkta önce güvenlik gelir."}},{heading:"Hareket sırasında odaklanmak neden kolay gelebilir?",paragraphs:["Gözlerin kapalı otururken huzursuz, uykulu ya da tedirgin olabilirsin. Yürümek, dikkatini düşüncelerinin dışında somut bir şeye vermeni sağlar: ayak tabanının yere değdiği ana. Gözlerin açık kalır, bedenin de hareket eder.","Oturmak zor geldiğinde yürüyüş meditasyonunu deneyebilirsin. Dikkatini içe çevirmek seni rahatsız ediyorsa bu uygulama daha rahat bir başlangıç olabilir."]}],example:{title:"Ada, 27, hemşire",text:"Ada gece vardiyalarından sonra hareketsiz oturamayacak kadar gergindi. Hastanenin yanındaki küçük parkta yürüyüş meditasyonunu denedi. Yaklaşık on beş adımlık sakin bir patika seçti. Önce nefes alırken iki, verirken üç adım saydı. Rahat gelmeyince nefes verirken de iki adıma geçti. Aklı, zor geçen bir hasta devir teslimindeydi. Bunu her fark ettiğinde topuğunun çakıla değdiği ana dikkatini verdi. Son iki dakika saymayı bırakıp çevresini dinledi: fren yapan bir otobüs, serçeler, ağaçlardaki rüzgâr. Toplam yedi dakika sürdü. Eve yine yorgun döndü, ama tramvayda devir teslimi artık tekrar tekrar düşünmüyordu."},sources:[]},"meditation-5":{deeper:[{heading:"Araştırma ne diyor?",paragraphs:["Meta-analiz iki tür olumlu duyguyu inceledi. Coşku ve neşe gibi canlı duygularla hoşnutluk ve huzur gibi sakin duygulara baktı. Sevgi-şefkat meditasyonu yapanlarda, bekleme listesindeki gruplara göre her iki tür de benzer ve sınırlı miktarda arttı.","Sonuçlar umut verici, ama sınırlı. Çoğu çalışma meditasyonu hiçbir uygulama yapmamayla karşılaştırdı. Birçoğunda yanlılık riski yüksekti. Üstelik şefkat meditasyonu araştırmasına katılanlar zaten daha iyi hissedeceklerini bekliyor olabilir. Bulgular olumlu duygularda küçük ile orta düzey arasında bir artış gösteriyor. Kişiliğin değiştiği sonucunu vermiyor."],visual:{kind:"bars",title:"Sevgi-şefkat meditasyonu ve günlük olumlu duygular",bars:[{label:"Canlı olumlu duygular (coşku, neşe)",value:.395,display:"g = 0,395"},{label:"Sakin olumlu duygular (hoşnutluk, huzur)",value:.392,display:"g = 0,392"}],note:"Zeng ve ark. (2015): 1.759 kişinin katıldığı 24 çalışmanın meta-analizi. Değerler, rastgele gruplara ayrılan katılımcılarla yapılan çalışmalarda bekleme listesiyle karşılaştırmanın standartlaştırılmış etki büyüklükleridir. Çalışmaların %38,9’unda yanlılık riski yüksekti.",sourceId:"meditation-lovingkindness"}},{heading:"Sık yapılan hatalar",paragraphs:["İlk hata, sıcak bir duygu hissetmeye çalışmak. Cümleleri iyi niyetle tekrarlaman uygulama için yeterli. Duygu sonra ya da başka bir gün gelebilir. İkinci hata, en zorlandığın kişiyle başlamak. Önce haftalarca kendine, sevdiğin birine ve hakkında güçlü bir duygu beslemediğin birine iyi dileklerde bulunabilirsin.","Üçüncü hata, iyi dilekte bulunmayı boyun eğmekle karıştırmak. Birinin acısının sona ermesini dilemek, yaptıklarını mazur görmek, onunla barışmak ya da sınırlarından vazgeçmek değildir. Kendine iyi dilekte bulunmak canını acıtıyorsa sevdiğin biriyle başla. Kendine daha sonra dönebilirsin."]}],example:{title:"Zeynep, 38, grafik tasarımcı",text:"Zeynep sevgi-şefkat meditasyonunu fazla duygusal buluyordu. Yine de bir müşteriyle gergin geçen haftanın ardından denedi. E-postasını açmadan önce masasında içinden şöyle dedi: “Güvende olayım, huzurlu olayım, kendime nazik davranayım.” Tebrik kartı okuyormuş gibi geldi. Buna rağmen devam etti. Aynı dilekleri önce kız kardeşi, sonra adını bilmediği köşedeki bakkal için tekrarladı. Neredeyse hiçbir şey hissetmedi. Derse göre bu da olağandı. Zorlandığı müşteriyi atladı; hazır değildi. O gün müşteri yine sert bir mesaj gönderdi. Zeynep’in cevabı hâlâ netti, ama her zamankinden biraz daha az sertti. Bu küçük değişikliği fark edip ertesi sabah yeniden denemeye karar verdi."},sources:[]},"meditation-6":{deeper:[{heading:"Uygulanabilir adımlar ve desteklenmeyen iddialar",paragraphs:["Dispenza’nın meditasyonunda uygulanabilir adımlarla büyük iddialar bir arada. Bunları ayırmak yararlı olabilir. Uygulanabilir kısmın üç parçası var. Dikkat: alıştığın tepkiyi olup bittikten sonra değil, o sırada fark etmek. Prova: belirli bir sahnede yeni tepkini zihninde canlandırmak. Duygu: prova sırasında sakinlik ya da özgüven gibi bir duyguyu da hissetmek. Bu, provayı daha canlı ve akılda kalıcı kılar.","Bu adımlar, alışkanlıkları fark etme, zihinsel pratik ve planlama araştırmalarıyla uyumlu. Meditasyonun kuantum alanıyla gerçekliği değiştirdiği, genleri açıp kapattığı ya da hastalıkları düşünceyle iyileştirdiği iddialarının ise bilimsel desteği yok. İddiaları kabul etmeden uygulanabilir adımları deneyebilirsin. Bu iddialar yüzünden tedavini asla değiştirme."],visual:{kind:"compare",title:"Dispenza’nın meditasyonunda hangi adımları deneyebilirsin?",left:{label:"Uygulanabilir adımlar",items:["Alıştığın tepkiyi ve onu tetikleyen durumları fark etmek","Yeni bir tepkiyi belirli bir sahnede prova etmek","Prova sırasında yeni tepkiye eşlik eden duyguyu hissetmek","Sonrasında gerçek hayatta küçük bir adım atmak"]},right:{label:"Kanıtla desteklenmeyenler",items:["Kuantum alanı aracılığıyla gerçekliği değiştirmek","Düşünerek genleri açıp kapatmak","Tedavi yerine düşünceyle hastalığı iyileştirmek"]},note:"Kitaptaki anlatımla zihinsel pratik ve eğer-öyleyse planları araştırmalarına dayanan özetimiz."}},{heading:"Dispenza’nın yöntemini günlük hayata uyarlamak",paragraphs:["Kitapta meditasyon dört hafta boyunca aşama aşama ilerler. Önce dikkatini bedenine verirsin. Sonra eski hâlini tanıyıp kabul eder, bırakmayı denersin. Ne zaman devreye girdiğini fark eder ve olmak istediğin kişiyi zihninde prova edersin. Bu ders, yöntemi dokuz dakikalık tek bir uygulamaya indiriyor. Bu nedenle burada basitleştirilmiş biçimini deniyorsun.","Zihinsel pratik araştırmaları, provayı daha yararlı kılmanın bir yolunu gösteriyor: somut ve gerçekçi bir sahneyi canlandır, sonra uygula. “Yöneticim işimi eleştirirse durup nefes vereceğim ve bir soru soracağım” diye planlayabilirsin. Böyle bir eğer-öyleyse planı, provanı aynı gün deneyebileceğin bir davranışa bağlar."]}],example:{title:"Kerem, 42, satış müdürü",text:"Kerem raporlar geciktiğinde ekibine çıkışmayı bırakmak istiyordu. Dokuz dakikalık meditasyonda önce alıştığı tepkiyi ayrıntılı olarak canlandırdı: raporun gelişi, göğsündeki sıcaklık, kimsenin işi ciddiye almadığı düşüncesi, gönderdiği sert mesaj. Bu tepkisini açıkça kabul etti. Onu bırakmayı hayal etti. Sonra pazartesi toplantısını, olmak istediği yönetici gibi üç kez prova etti. Duruyor, nefes veriyor, raporun neden geciktiğini soruyordu. Canlandırırken sakinliği hissetmeyi denedi. Gözlerini açmadan önce bir plan yaptı: “Rapor gecikirse başka bir şey söylemeden bir soru soracağım.” Pazartesi bir rapor gecikti. Göğsündeki sıcaklığı hissetti, planını hatırladı ve soruyu sordu. Toplantı biraz daha iyi geçti."},sources:[]},"meditation-7":{deeper:[{heading:"Düzenini kur",paragraphs:["Düzenli uygulama için üç şey belirle: her gün zaten yaptığın bir şey, zor bir günde bile ayırabileceğin süre ve plan işlemezse kullanacağın yedek. Bir eğer-öyleyse planı bunları birbirine bağlayabilir: “Sabah çayımı koyduktan sonra on dakika meditasyon yapacağım.” Bu biçimdeki planlar, birçok araştırmada insanların niyetlerini uygulamasına yardımcı oldu.","İlk haftayı sade tut: tek teknik, tek zaman, tek yer. Haftanın sonunda neyin işe yaradığına bak. Her şeyi baştan kurmak yerine süreyi ya da tekniği değiştir."],visual:{kind:"steps",title:"Bir haftalık başlangıç düzeni",steps:[{label:"Bir hatırlatıcı seç",text:"Çay koymak ya da arabayı park etmek gibi her gün zaten yaptığın bir şey."},{label:"Bir teknik seç",text:"Nefes, beden taraması, kelime, yürüyüş, metta ya da prova."},{label:"Bir süre belirle",text:"Normal günlerde on dakika, en az üç dakika."},{label:"Bir yedek yaz",text:"“Oturamazsam üç dakika adımlarımı fark ederek yürüyeceğim.”"},{label:"Gözden geçir",text:"Yedi gün sonra neyin yardımcı olduğunu not et ve bir şeyi ayarla."}],note:"Aynı koşullarda tekrarlanan alışkanlıklarla eğer-öyleyse planları araştırmalarına dayanan şablonumuz."}},{heading:"Meditasyon zor duygular ortaya çıkardığında",paragraphs:["Sessizce meditasyon yaparken bazen zor duygular, anılar ya da bedensel hisler ortaya çıkar. Bu, yanlış yaptığın anlamına gelmez. Kendini zorlayıp sürdürmen de gerekmez. Travma alanında çalışan eğitmenler, içe odaklanmanın bazı kişilerde geçmişteki olayı yeniden yaşama hissini, duyguları düzenlemekte belirgin güçlüğü ya da kopukluk hissini tetikleyebileceğini belirtir. Özellikle travma geçmişi olanlarda bu yaşanabilir.","Uygulamayı değiştirmek yardımcı olabilir. Gözlerini açık tut, süreyi kısa tut. Sesler ya da ayaklarının yere teması gibi bir şeye odaklan. İhtiyaç duyduğunda dur. Travma geçmişin varsa eğitimli bir eğitmenle ya da bir terapistin desteğiyle çalışmak uygun olabilir. Bazı kişiler uygulamadan önce veya sonra birkaç kez yavaşça nefes alıp uzun süre vermenin sakinleşmelerine yardımcı olduğunu fark eder."]}],example:{title:"Elif, 35, öğretmen",text:"Elif beden taramasını seçti. İşten sonra arabasını park edince uygulamaya başladı. Dört gün iyi gitti. Beşinci gün taramanın ortasında göğsünde bir sıkışma hissetti. Bu his yıllar önceki acı bir anıyı aklına getirdi; kendini sarsılmış hissetti. Dersteki öneriyi hatırladı. Gözlerini açtı, ayaklarını arabanın zeminine bastırdı. Dışarıdaki ağaçlara bakıp birkaç kez uzun nefes verdi. O gün uygulamayı bıraktı. Ertesi gün yazdığı yedek planı denedi: gözleri açık, üç dakikalık yürüyüş meditasyonu. Anı o hafta yeniden gelince terapistine anlattı. Terapisti şimdilik süreyi kısa tutmasını ve gözlerini açık bırakmasını önerdi. Elif, durmanın da uygulamanın parçası olduğunu fark etti."},sources:["meditation-trauma-sensitive"]}},L=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:H,SOURCES:D},Symbol.toStringTag,{value:"Module"}));function K(a){const e=`manifest-${a.number}`;return{schemaVersion:2,revision:1,id:e,courseId:"manifest",locale:"tr",title:a.title,goal:a.goal,minutes:{learning:5,suggestedAction:5,review:2},direction:{hook:a.hook,reason:{id:`${e}-reason`,label:a.reason,kind:"text",maxLength:160,optional:!0,suggestions:["Hedefim için daha az tekrar","Daha fazla hazırlanmadan işe başlamak","Yeniden denemeden önce destek almak"]},why:{id:`${e}-purpose`,label:"Bu adım bu hafta senin için neden değerli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:a.paragraphs,example:a.example},move:{invitation:"Hedefin aynı kalsın. Bugün ona yarayan tek bir iş seç.",instructions:a.instructions,prompts:[],suggestions:{action:a.action,minimum:a.minimum,cue:a.cue,place:a.place,fallback:a.fallback,observation:a.observation,minutes:[5,2,10],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:a.action[0],minimum:a.minimum[0],minutes:5,cueHint:a.cue[0],placeHint:a.place[0],obstacleHint:a.obstacle,fallbackHint:a.fallback[0],observationHint:a.observation[0]},accessibleAlternative:"İstersen yaz, sesle yazdır ya da uygulamayı sözle anlat; malzeme bulman veya zihninde canlı görüntüler oluşturman gerekmiyor.",stopRule:a.stopRule},result:{question:"Bugün seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Uygulamanın kendisinden ayrı olarak, hedefin için hangi somut işi yaptın?"},judgment:{primary:{id:`${e}-decision`,scenario:a.scenario,question:a.question,options:a.options.map(l=>({id:`${e}-${l.key}`,text:l.text,feedback:l.feedback})),bestOptionId:`${e}-${a.best}`}},carry:{takeaway:a.takeaway,followUp:{questionId:`${e}-return`,question:a.review,observationPrompt:"Planladığın fırsatta ne oldu? Bir yanıt geldiyse onu ayrı anlat.",adjustmentPrompt:"Bir sonraki fırsata uyması için planında hangi tek şeyi değiştireceksin?"}},goDeeper:{sections:a.deeper,sourceIds:a.sources}}}const u=[{id:"manifest-T01",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 makalede yer alan 24 bağımsız etki ve 15.907 katılımcı incelendi. Zihinsel karşılaştırmayı ‘şu olursa bunu yaparım’ planlarıyla birleştirmek, hedefe ulaşmayı ortalama olarak destekledi: g = 0,336 [0,229; 0,443]. Yanlılık düzeltmesi sonrası tahmin 0,242 [0,143; 0,342] oldu.",limitation:"Etkiler değişkenlik gösterdi ve yayın yanlılığına işaret eden bulgular vardı. Başarı garantisi sunmaz, sıkıntı yaşamanın gerekli olduğunu kanıtlamaz. Bu kütüphane veya ritüellerin ODA uyarlamaları sınanmadı."},{id:"manifest-T02",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Bu alandaki temel meta-analizlerden biri, 94 bağımsız test ve 8.461 katılımcıyı kapsadı. Belirli bir durumu yapılacak işe bağlayan ‘şu olursa bunu yaparım’ planları, hedefe ulaşmada ortalama fayda gösterdi: d = 0,65 [0,60; 0,70].",limitation:"Eski ve farklı yöntemleri bir araya getiren araştırmalar. Araştırma planlarının tamamı önceden kayda geçirilmiş değildi. Bir plan dış engelleri ortadan kaldıramaz, çaba gereğini silemez veya başkasının kararını garanti edemez."},{id:"manifest-T03",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Rastgele atamalı 138 deneyde toplam 19.951 katılımcı vardı. İlerlemeyi takip etmeye teşvik etmek, hedefe ulaşmayı ortalama olarak artırdı: d = 0,40 [0,32; 0,48]. Çalışmalar karşılaştırıldığında, ilerlemeyi yazılı kaydetmek daha büyük etkilerle ilişkiliydi.",limitation:"Uygulamalar ve hedefler farklıydı. Çalışmalar arasındaki bu ilişkiler, her kayıt özelliğinin işe yaradığını kanıtlamaz. Ertesi gün gözden geçirmek bir ODA uyarlamasıdır; en uygun sıklık olduğu gösterilmiş değildir."},{id:"manifest-T04",title:"Cole et al. · 2021 · Mental simulation and behavior change",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 çalışma, 123 etki ve 5.685 katılımcı incelendi. Zihinde canlandırma, daha sonraki davranışı ortalama olarak destekledi: g = 0,49 [0,37; 0,62]. Tüm canlandırma türlerini birlikte karşılaştıran analiz, türler arasında fark olduğunu ortaya koymadı.",limitation:"Örneklemlerin çoğu öğrenciydi; işler ve canlandırmalar farklıydı. Bazı alt gruplarda az sayıda etki vardı. Türler arasında güvenilir bir sıralama, dış olayları çekme veya yatmadan önce yapmanın özel bir üstünlüğü gösterilmedi."},{id:"manifest-T05",title:"Kappes & Oettingen · 2011 · Idealized positive fantasies",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Dört deneyde, kusursuz bir olumlu gelecek hayal etmenin bazı durumlarda o andaki enerjiyi azalttığı bulundu. Daha sonraki bazı başarı ölçümlerinde de farklar vardı. Bu bulgu, keyifli hayaller kurmakla çaba göstermeye hazırlanmayı ayırır.",limitation:"Kısa deneyler; katılımcılar çoğunlukla öğrenciydi. Her iyimserlik veya hayal kurma zararlı değildir. Beynin hedefi zaten tamamlanmış saydığı yönündeki açıklama, bu araştırmada ölçülmedi."},{id:"manifest-T06",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/abs/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"İki deneyde, kişinin kendisi hakkında çok olumlu bir cümleyi tekrarlamasının, özsaygısı düşük katılımcıların ruh hâlini kötüleştirebildiği bulundu. Özsaygısı yüksek katılımcılardaki fayda sınırlıydı.",limitation:"Belirli cümleler, örneklemler ve kısa vadeli sonuçlar incelendi. Her destekleyici sözün zarar verdiğini göstermez; tüm olumlama uygulamaları sınanmadı. İnanabileceğin bir eylem cümlesi kullanmak ODA'nın uyarlamasıdır."},{id:"manifest-T07",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://pubmed.ncbi.nlm.nih.gov/25133846/",type:"research",finding:"144 deneysel testte, sağlık bilgisiyle birlikte kişinin önemli bulduğu değerleri, özellikleri veya ilişkileri düşünerek kendini olumlaması incelendi. Bilgiyi kabul etme ve niyetler üzerindeki etkiler küçüktü. Davranışı ölçen 46 test ve 2.715 katılımcıda d = 0,32 [0,19; 0,44] bulundu.",limitation:"Değerlere dayalı kendini olumlamak, istenen sonucu olmuş gibi tekrarlamaktan farklıdır. Sağlık mesajlarıyla ilgili bulgular, tekrar edilen sloganların iş, para veya ilişki çektiğini göstermez."},{id:"manifest-T08",title:"Carrillo et al. · 2019 · Best possible self meta-analysis",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 çalışma ve 2.909 katılımcı incelendi. Emek verdikten sonra ulaşılabilecek en iyi gelecek hakkında yazmak, kontrol gruplarına kıyasla iyi oluşu, iyimserliği ve olumlu duyguları ortalama olarak artırdı.",limitation:"Katılımcılar çoğunlukla genç öğrencilerdi. Hiçbir çalışma tüm kalite ölçütlerini karşılamadı. Ruh hâli ve iyimserlik bulguları, dış hedeflere ulaşıldığını veya geleceği şimdiki zamanda yazmanın işe yaradığını kanıtlamaz."},{id:"manifest-T09",title:"Davis et al. · 2016 · Gratitude interventions meta-analysis",url:"https://scottbarrykaufman.com/wp-content/uploads/2021/05/davis2016.pdf",type:"research",finding:"Rastgele atamalı şükran çalışmalarında, bazı kontrol koşullarına karşı iyi oluşta küçük ortalama faydalar bulundu. Şükran uygulamaları, psikolojik açıdan etkin başka uygulamalardan iyi oluşta daha iyi sonuç vermedi. Kaygı bulguları kesin bir sonuca varmak için yeterli değildi.",limitation:"Etkiler, karşılaştırılan uygulamalara ve çalışmaların kalitesine bağlı. Herkes için geçerli bir günlük yazma sıklığı, dış olayları çekme veya henüz yaşanmamış bir olaya olmuş gibi şükretmenin ek faydası gösterilmedi."},{id:"manifest-T10",title:"Cregg & Cheavens · 2021, online 2020 · Gratitude and symptom change",url:"https://link.springer.com/article/10.1007/s10902-020-00236-6",type:"research",finding:"27 çalışma ve 3.675 katılımcı incelendi. Şükran uygulamalarının, birlikte değerlendirilen depresyon ve kaygı belirtilerindeki ortalama etkileri küçüktü. Bekleme listesine karşı etkiler, etkin kontrol koşullarına karşı olanlardan daha büyüktü. Kaygıyı ayrı inceleyen analiz yalnızca beş çalışmayı kapsadı ve kesin bir sonuca varamadı.",limitation:"Belirtilerdeki sınırlı bulgular, şükranın tek başına yeterli tedavi olduğunu göstermez. Yazarlar, depresyon veya kaygısını hafifletmek isteyenlere daha güçlü kanıta sahip uygulamaları öneriyor."},{id:"manifest-T11",title:"Locke & Latham · 2002 · Goal setting and task motivation",url:"https://med.stanford.edu/content/dam/sm/s-spire/documents/PD.locke-and-latham-retrospective_Paper.pdf",type:"research",finding:"On yıllara yayılan hedef belirleme araştırmalarını inceleyen bu derleme, belirli ve zorlayıcı hedeflerin performansı nasıl destekleyebildiğini anlatır. Hedefe bağlılık, geri bildirim, beceri ve işin karmaşıklığı sonuçları etkiler.",limitation:"Kuramı anlatan bir derleme; manifest ritüellerini sınayan bir çalışma değil. Hedefler uygulanabilir yöntemler ve kaynaklar gerektirir. Yeni veya karmaşık işlerde, hemen sonuç alma baskısı yerine öğrenmeye yönelik hedefler gerekebilir."},{id:"manifest-T12",title:"Frattaroli · 2006 · Expressive disclosure meta-analysis",url:"https://bpb-us-e2.wpmucdn.com/faculty.sites.uci.edu/dist/c/602/files/2019/08/Frattaroli-psych-bulletin-2006.pdf",type:"research",finding:"Yaşantı veya duyguları anlatmayı inceleyen rastgele atamalı 146 çalışma, ölçülen sonuçlar genelinde küçük bir ortalama fayda buldu: ortalama r = 0,075 [0,052; 0,098]. Etkiler, ölçülen sonuca ve uygulama biçimine göre değişti.",limitation:"Yaşanan olayları yazmak, istenen bir olayı olmuş gibi yazmaktan farklıdır. Bu derleme her günlük türünü doğrulamaz, travmadan iyileşme sözü vermez veya yazılan hikâyelerin dış sonuçlara neden olduğunu göstermez."},{id:"manifest-T13",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Manifestation beliefs",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"ABD'deki üç çevrimiçi anket örnekleminde toplam 1.023 katılımcı vardı. Manifest inancı, özgüven ve kişinin bildirdiği bazı finansal riskler ile iflasla ilişkiliydi. Bildirilen gelir veya eğitim düzeyiyle ilişkili değildi.",limitation:"İlişkiler ve kişilerin kendi bildirdiği sonuçlar, neden-sonuç ilişkisini, bu inancın toplumdaki yaygınlığını veya her tekniğin etkili olduğunu göstermez. Özgüven, başarının nesnel kanıtı değildir."},{id:"manifest-T14",title:"Denrell · 2003 · Undersampling failure and success stories",url:"https://pubsonline.informs.org/doi/10.1287/orsc.14.2.227.15164",type:"research",finding:"Faaliyetini sürdüren kuruluşlardan nasıl ders çıkarıldığını inceleyen analiz, başarısız örneklerin yeterince görülmemesinin, başarıyla ilgisiz bir uygulamayı başarıyla ilişkili gösterebildiğini anlatır.",limitation:"Kuruluşlara ilişkin modeller kullanıldı; ürün sahibinin viral paylaşımı incelenmedi. Aynı örnekleme ilkesini manifest başarı hikâyelerine uygulamak bir çıkarımdır. Belirli bir hikâyeyi anlatanın dürüst olmadığını göstermez."},{id:"manifest-T15",title:"Awh, Belopolsky & Theeuwes · 2012 · Attentional control",url:"https://research.vu.nl/en/publications/top-down-versus-bottom-up-attentional-control-a-failed-theoretica/",type:"research",finding:"Bu dikkat derlemesine göre, neye dikkat ettiğimizi mevcut hedeflerimiz, bir şeyin fiziksel olarak ne kadar göze çarptığı ve geçmişte nelere dikkat ettiğimiz şekillendirir. Hedefler, başka etkenlerle birlikte dikkatimizi yönlendirebilir.",limitation:"Görsel dikkat kuramı; hayal panolarını, olumlamaları, RAS'ın tek bir dilek filtresi gibi çalıştığı iddiasını veya dış fırsatların yaratılmasını sınamaz. Bir fırsatı fark etmekle o fırsatı var etmek farklı iddialardır."},{id:"manifest-T16",title:"Dai et al. · 2023 · Behavioral priming meta-analysis",url:"https://socialactionlab.org/wp-content/uploads/2024/01/Dai_Priming-Behavior-A-Meta-Analysis-of-the-Effects-of-Behavioral-and-Nonbehavioral-Primes-on-Overt-Behavioral-Outcomes_2023.pdf",type:"research",finding:"351 çalışma ve 862 etkiyi kapsayan derleme, hazırlayıcı uyaranların davranış üzerinde ortalama bir etkisini buldu. Planı önceden kayda geçirilmiş daha küçük çalışma grubunda etkiler daha küçüktü ve istatistiksel olarak kesin bir sonuca varılamadı. Bu durum, etkinin güvenilirliği ve hangi koşullarda görüldüğü konusundaki belirsizliği gösterir.",limitation:"Deneylerde hazırlayıcı uyaranlarla karşılaşmak, isteyerek yapılan manifest ritüellerinden farklıdır. Önceden kayda geçirilmiş küçük grup, hazırlayıcı uyaranların tüm etkilerini çürütmez. Genel sonuç da tekrarlanan cümleleri, kesin süre eşiklerini veya kozmik çekimi doğrulamaz."},{id:"manifest-T17",title:"Pham & Taylor · 1999 · Process versus outcome simulation",url:"https://journals.sagepub.com/doi/abs/10.1177/0146167299025002010",type:"research",finding:"Sınavlarla ilgili erken bir çalışma, yalnızca iyi bir notu hayal etmeye kıyasla ders çalışma sürecini canlandırmayı destekledi. Planlama ve kaygı, not farklarını açıklamaya katkı sağladı. Süreç canlandırmanın notlar üzerindeki ana etkisi istatistiksel anlamlılık sınırındaydı. Sonradan yapılan, yalnız süreç ile yalnız sonuç canlandırmayı karşılaştıran analizde fark anlamlıydı.",limitation:"Daha sonraki Cole sentezinde, sınavda süreç canlandırma ile kontrol grubu arasındaki sonuç istatistiksel olarak anlamlı değildi. Bu sentez, her koşulda üstün bir canlandırma türü belirlemedi. Dar kapsamlı erken çalışma, kontrole karşı güvenilir not artışı veya dış olayları çekme göstermez."},{id:"manifest-T18",title:"Taylor et al. · 1998 · Mental simulation and self-regulation",url:"https://pubmed.ncbi.nlm.nih.gov/9572006/",type:"research",finding:"Bir araştırma programını anlatan bu kaynak, süreci ve zorluklarla başa çıkmayı canlandırmakla yalnızca başarıyla bitirmiş olmayı hayal etmeyi ayırır. Planlama ve sorun çözmeyi öne çıkarır.",limitation:"Bir araştırma programının derlemesi; kapsamlı bir meta-analiz veya süreç canlandırmanın her zaman üstün olduğunun kanıtı değil. Daha sonraki Cole senteziyle birlikte değerlendir ve ardından işi gerçekten dene."},{id:"manifest-T19",title:"Larson-Prior, Ju & Galvin · 2014 · Sleep, wakefulness and arousal circuits",url:"https://www.frontiersin.org/journals/neurology/articles/10.3389/fneur.2014.00165/full",type:"research",finding:"Bu sinirbilim derlemesi, retiküler aktive edici sistemin uyanıklık ve beyin kabuğunun uyarılmasında rol alan, birbiriyle etkileşen devreler içindeki yerini anlatır.",limitation:"Uyarılma sinirbilimi, dilek yazmanın bir beyin filtresini fırsat getirecek şekilde programladığını veya uykuya yakın hâlde düşüncelerin dış olayları değiştirdiğini göstermez. Hiçbir manifest ritüeli sınanmadı."},{id:"manifest-P01",title:"Taylor McGrath · 369 manifestation method",url:"https://www.theselfcollective.com.au/blogs/news/369-manifestation-method",type:"technique",finding:"Uygulayıcının tarifi: bir niyet cümlesini şimdiki zamanda yaz; sabah üç, öğleden sonra altı, gece dokuz kez tekrarla.",limitation:"Uygulamayı anlatan bir rehber; etkinliği gösteren kontrollü araştırma değil. Tekrar sayıları, gün döngüleri, dikkatle ilgili iddialar ve Tesla bağlantıları bilimsel bulgu değildir."},{id:"manifest-P02",title:"Victoria Jackson · Scripting an ideal day",url:"https://themanifestationcollective.co/scripting-to-manifest/",type:"technique",finding:"Uygulayıcının tarifi: hayalindeki ideal günü kendi ağzından, şimdiki zamanda günlüğe yaz. Duyulara ilişkin ayrıntıları ve hislerini ekle, sonra yeniden oku.",limitation:"Bir ritüeli anlatır. Bilinçaltını programlama, titreşim, anlamlı tesadüfler ve kişinin kendi sonuçları, kontrollü araştırma kanıtı değildir."},{id:"manifest-P03",title:"Jack Canfield · Creating a vision board",url:"https://jackcanfield.com/blog/vision-board/",type:"technique",finding:"Uygulayıcının tarifi: hedeflerini ve bunları temsil eden görsel veya sözcükleri seç. Kâğıt üzerinde ya da dijital bir kolaj hazırla, görünür yere koy ve düzenli olarak gözden geçir.",limitation:"Uygulamayı anlatan bir rehber; panoların etkili olduğuna kanıt değil. Bu sayfa, Çekim Yasası'nı, başarı hikâyelerini veya RAS açıklamalarını doğrulamaz."},{id:"manifest-P04",title:"Jack Canfield · Daily affirmations",url:"https://jackcanfield.com/blog/daily-affirmations/",type:"technique",finding:"Uygulayıcının tarifi: kendi ağzından, şimdiki zamanda kısa ve belirli cümleler kur. Bunları oku veya tekrarla; çoğu tarif sabah ve akşam yapmayı önerir.",limitation:"Olumlu cümleler, değerlere dayalı kendini olumlama araştırmalarından farklıdır. Bu rehber, herkesin fayda göreceğini veya dış sonuçların değişeceğini göstermez."},{id:"manifest-P05",title:"Jack Canfield · Visualization techniques",url:"https://jackcanfield.com/blog/visualization-techniques-manifest-your-dreams/",type:"technique",finding:"Uygulayıcı rehberi, istenen sonucu duyulara ilişkin ayrıntılarla canlandırmayı, sahnede kendin varmış gibi prova yapmayı ve hedefe ulaşma sürecini zihinde canlandırmayı anlatır.",limitation:"Uygulamayı tarif eder; garantilere veya çekim iddialarına kanıt sunmaz. Zihinde canlandırmayla ilgili deneysel bulgular araştırma kaynaklarından kontrol edilmelidir."},{id:"manifest-P06",title:"Zanna Keithley · 55x5 method description",url:"https://zannakeithley.com/55x5-manifestation-method-worksheet/",type:"technique",finding:"Uygulayıcının tarifi: bir olumlama cümlesini, beş gün üst üste her gün art arda 55 kez yaz. Yazarken cümlenin zaten doğru olduğunu hayal et.",limitation:"Yalnızca herkese açık tarif kullanıldı; çalışma sayfası satın almak gerekmez. Tekrar sayıları ve yüksek titreşim açıklamaları, etkinliği gösteren yerleşik kanıt değildir."},{id:"manifest-P07",title:"Practitioner account · Two-cup method",url:"https://www.reddit.com/r/Manifestation/comments/1poqa0q/insanely_powerful_technique/",type:"technique",finding:"Uygulamayı yapan kişinin tarifi: bardaklara mevcut ve istenen durumu yazan etiketler yapıştır. Değişimi hayal et, suyu ilk bardaktan ikinciye dök ve iç.",limitation:"Adı bilinmeyen bir uygulayıcının anlatısı; doğrulanmış neden-sonuç kanıtı değil. Gerçeklik değiştirme ve sonucu zorla elde etme iddiaları desteklenmiyor. Sade içme suyu ve temiz bardaklar kullan."},{id:"manifest-P08",title:"Sandy · Pillow method guide",url:"https://theprettythoughts.com/the-pillow-method-an-easy-way-to-manifest/",type:"technique",finding:"Uygulayıcının tarifi: bir dileği şimdiki zamanda yaz, kâğıdı katlayıp yastığın altına koy. Uykuya hazırlanırken cümleyi tekrarla veya dileğini canlandır.",limitation:"Tekrar ve katlama sayıları değişir. Kâğıt, bilinçaltı, kristal, yağ ve çekimle ilgili iddialar, etkinliği gösteren kontrollü araştırma kanıtı değildir."},{id:"manifest-P09",title:"Sandy · Whisper method guide",url:"https://theprettythoughts.com/the-viral-whisper-method-manifestation-technique/",type:"technique",finding:"Uygulayıcının tarifi: rahatla, başka birinin yanına gittiğini hayal et. İstediğin şeyi kulağına üç kez fısılda, sonra hayalindeki sahneden ayrıl.",limitation:"Kişisel deneyim anlatısı; telepati kanıtı değil. Hayalinde birinden bir şey istemek, o kişiyi kontrol ettiğini göstermez; rızasını ve sınırlarını geçersiz kılamaz."},{id:"manifest-P10",title:"Simi · The Gratitude Game",url:"https://www.thesecret.tv/stories/the-gratitude-game/",type:"technique",finding:"Uygulamayı yapan kişi, şükran günlüğüne takdir ettiği şeyleri nedenleriyle birlikte yazmayı, ardından yazdıklarını yeniden okumayı anlatır.",limitation:"Kişisel anlatı; bir müdahale araştırması değil. Bu hikâye, şükranın olayları çektiğini veya sorunları ortadan kaldırdığını göstermez."},{id:"manifest-P11",title:"Alexandra · Act as if it is already done",url:"https://www.thesecret.tv/stories/act-as-if-its-already-done/",type:"technique",finding:"Kişinin kendi anlatısı, istediği işe kabulü kesinleşmiş gibi kıyafet ve bavul hazırlamayı, bu sırada istenen sonucu hayal etmeyi tarif eder.",limitation:"Yazar, zaten tanıdığı birinden teklif aldığını anlatıyor. Tek bir hikâye, sonuca neyin neden olduğunu ayıramaz veya genel bir çekim yasasını doğrulayamaz."},{id:"manifest-P12",title:"Victoria Jackson · Letter from your future self",url:"https://themanifestationcollective.co/wp-content/uploads/2021/04/Scripting-To-Success-Masterclass.pdf",type:"technique",finding:"Uygulayıcı kaynağı, hayalindeki gelecekteki hâlinin bugünkü sana hayatındaki değişimleri anlatan, anlayışla yaklaşan bir mektup yazmasını tarif eder.",limitation:"6-7. sayfalar uygulamayı belgeliyor; gelecekle iletişimi veya dış sonuçlarda etkinliği kanıtlamıyor. Tarih ve selamlama, mektup biçiminde isteğe bağlı tercihlerdir."},{id:"manifest-P13",title:"Abraham / Esther and Jerry Hicks · 17-second focus",url:"https://spiritlibrary.com/abraham-hicks/only-17-seconds-away-from-your-true-desires",type:"technique",finding:"Öğretmenin konuşma dökümü, karşıt bir düşünce olmadan istenen düşünceye 17 saniye odaklanmayı tarif eder. Dört kez yapıldığında toplam süre 68 saniyedir.",limitation:"Manevi bir öğreti; kontrollü kanıt değil. Kesin eşikler, düşüncelerin ‘tutuşması’, düşüncenin fiziksel dünyada gerçekleşmesi ve belirli çalışma saatlerine eşdeğer olduğu iddiaları desteklenmiyor."},{id:"manifest-P14",title:"Amy Parker · Creating a manifestation box",url:"https://envibelife.com/creating-a-manifestation-box/",type:"technique",finding:"Uygulayıcının kendi tarifi: niyet kartlarını veya görselleri bir kutuya koy, yaşamak istediğin duyguları ekle ve kutudakileri yeniden gözden geçir.",limitation:"Simgesel bir uygulamayı belgeler. Enerji alanı ve dileklerin gerçekleşmesine ilişkin açıklamalar inançtır; bilimsel bulgu değil. Elindeki bir kap yeterlidir."},{id:"manifest-P15",title:"Neville Goddard · Five Lessons, 1948",url:"https://readnevillegoddard.com/five-lessons/",type:"technique",finding:"Öğretmenin özgün metni, uykulu hâlde gevşemeyi, dileğin gerçekleştiği kısa bir sahneyi, sahneye kendin katılmayı ve hayalindeki eylem gerçekmiş gibi hissedene kadar tekrarlamayı anlatır.",limitation:"Ücretsiz döküm, SATS öğretisini belgeler; etkinliğini değil. Dış sonuçlara ilişkin metafizik iddialar ve eylem gerekmediği iddiası bilimsel kanıt değildir. Uykunu koru."}],T=[{number:6,technique:"3-6-9 yöntemi",title:"3-6-9: defterdeki şirkete bugün bir başvuru gönder",goal:"Defterini kullanmaya devam et; seçtiğin somut hedef için bir işi tamamla.",hook:"Yine “İşe girdim” mi yazıyorsun? Diğer sayfada adı duran şirkete bugün bir başvuru gönder.",reason:"Bu defter istediğin iş için adım atmanı mı sağlıyor, başvuru zamanını mı alıyor?",paragraphs:["3-6-9 yönteminde, istediğin şey olmuş gibi kurduğun olumlama cümlesini sabah üç, öğlen altı, gece dokuz kez yazarsın. İki sayfalı biçiminde, istediğin şirketler solda, “İşe girdim” sağda durur. Bu özel sayıların iş teklifi getirdiği iddiası araştırmayla desteklenmiyor. Tek bir başarı hikâyesi, tekrarın etkisini başvuruların etkisinden ayıramaz. Deneyip teklif alamayanları da göstermez.","ODA uyarlaması: sayfalar kalsın, tekrar düzeni isteğe bağlı olsun. Sola somut hedeflerini ve bugünkü başvuru, takip ya da hazırlık işini yaz. Sağa kendin hakkında inanabildiğin bir cümle ve “Şu engel çıkarsa bunu yaparım” planı ekle. Belirli bir işareti yapılabilir bir işle eşleştiren planları araştırma destekliyor. Bugün hedefin için bir iş yap. Yarın yaptığınla gelen yanıtı ayrı değerlendir."],example:{title:"Derya iki sayfayı da kullanıyor",text:"Derya sol sayfaya iki lojistik şirketi, sağa “Özenli başvurular hazırlıyorum” yazıyor. Öğle yemeğinden sonra bir ilanı inceleyip ona göre düzenlediği öz geçmişini gönderiyor. Planı şöyle: “Başvuru sitesi açılmazsa taslağı saklayıp insan kaynaklarına ulaşacağım.” Sitelerden biri açılmıyor. Derya ilettiği iletişim talebini kaydediyor. Henüz iki şirketten de bir iş teklifi gelmiş değil."},instructions:["Sol sayfaya bir hedef ve bugünkü başvuru, takip ya da hazırlık işini yaz.","Sağ sayfaya kendinle ilgili bir cümle ekle. Engel çıkarsa ne yapacağını yaz.","Hedefin için seçtiğin işi yap; yarın denemeni ve varsa gelen yanıtı ayrı değerlendir."],action:["İlana göre düzenlenmiş başvuruyu gönder","Şirkete başvurunun durumunu sor"],minimum:["Uygun bir ilana başvur","Başvuru hakkında bir soru gönder"],cue:["Öğle yemeği bittikten sonra","Sabah yazımı bitirdiğimde"],place:["Başvuru hazırladığım masada","Şirketin başvuru sitesinde"],obstacle:"Başvuru sitesi açılmıyor",fallback:["Taslağı sakla, insan kaynaklarına ulaş","Başka bir uygun başvuru fırsatını kullan"],observation:["Gönderdiğim başvuru veya talep, varsa yanıt","Başvuru için tamamladığım iş"],stopRule:"İş yapacağın zamanı alan tekrarları atla. Masrafını karşılayamadığın ya da uygun olmayan başvurulara ara ver.",scenario:"Derya cümlesini 18 kez yazdı ve üç şirketi listeledi. Ona uygun bir ilanın süresi bu gece doluyor. Başvuruda deneyimini anlatan kısa bir paragraf eksik.",question:"Defteri yeniden açınca hangi işi tamamlamalı?",options:[{key:"repeat",text:"Olumlama düzenini sürdürsün. Başvuruya dönmeden önce kendini anlatan daha uzun bir cümle hazırlasın.",feedback:"Bu cümle uygulamasının bir parçası olarak kalabilir. Ama onu uzatmak, başvurudaki eksik paragrafı tamamlamaz. Son tarih yaklaşıyor. Defterini açtığında bu paragrafı yazmayı hatırlasın ve kalan zamanı o iş için kullansın."},{key:"submit",text:"Eksik paragrafı yazıp başvursun. Gönderdiği başvuruyu ve işverenden gelebilecek yanıtı ayrı ayrı kaydetsin.",feedback:"Bu seçim, belirlediği hedefe ve son tarihe uyuyor. Başvuruyu göndermek onun yaptığı iş; yanıt gelmesi kendi kontrolünde değil. İsterse uygulamasını da sürdürebilir. Sonra ne olduğunu, olmayan bir yanıtı var saymadan değerlendirebilir."},{key:"expand",text:"Önce şirket listesini genişletsin; böylece yarın iş ararken daha fazla şirket arasından seçim yapabilsin.",feedback:"Daha çok yerde iş aramak ileride işe yarayabilir. Ama bu gece süresi dolan, ona uygun bir ilan zaten var. Listeyi genişletmek bu başvuruyu geciktirir. Önce başvurunun eksik deneyim paragrafını yazıp elindeki fırsatı kullansın."}],best:"submit",takeaway:"Defterini açınca başvurunu yap. Yaptığın işleri ve gelen yanıtları ayrı ayrı say.",review:"Hedefin için hangi işi yapmayı denedin? Listendeki bir şirketten yanıt geldi mi?",deeper:[{heading:"Yaygın tarif ve iki sayfalı defter",paragraphs:["1. İstediğin bir sonucu seç ve olmuş gibi bir cümle kur. 2. Bu olumlamayı sabah üç kez yaz. 3. Öğlen civarında altı kez tekrarla. 4. Gece dokuz kez yaz. Bu sayılar yöntemin yaygın tarifini anlatıyor; araştırmayla belirlenmiş bir uygulama dozu değiller. Bu yöntemi anlatan kişiler, aynı düzeni ne kadar süre sürdürdükleri konusunda da farklı şeyler söylüyor. [manifest-P01]","5. Kurs sahibinin aktardığı iki sayfalı örnekte, sağda “İşe girdim” yazıyor. Solda kişinin başvurduğu ve çalışmak istediği şirketler var. Bu kişi, listedeki bir şirketten teklif aldığını söylüyor. Bu, kurs sahibinin aktardığı bir hikâye; bağımsız olarak doğrulanmış deney verisi değil. Burada hayatta kalma yanlılığı olabileceğini söylemek bir çıkarım: görünen başarı, aynı uygulamayı deneyip teklif alamayanları göstermiyor. Kişi yaşadığını içtenlikle anlatıyor olabilir; bu yine de teklifin neden geldiğini açıklamaz. [manifest-T14]"]},{heading:"Tekrar düzeni kalsın, ardından bir iş gelsin",paragraphs:["Planlama araştırması, tanıyabileceğin belirli bir durumla yapabileceğin bir işi eşleştirmeyi inceliyor. Üç, altı veya dokuz tekrarın işvereni etkilediğini göstermiyor. Yazmak hoşuna gidiyorsa sayı kalsın. Yanına ne yapacağını ekle: hangi şirket, hangi uygun ilan ve bugün hangi iş? Sol sayfadaki şirket listesi ve gönderilen başvurular, teklif almaya giden somut bir yol sunar. Ama bu hikâye, kişinin teklifini hangi etkenin sağladığını ayırt edemez. Teklifi tek başına tekrarın sonucu sayma. [manifest-T02, manifest-T14]","Sağa “Özenli başvurular hazırlıyorum” yazmayı deneyebilirsin. Altına şunu ekle: “Site açılmazsa taslağı saklayıp insan kaynaklarına ulaşacağım.” Son tarihi, siteye erişimini ve ayırabileceğin zamanı kontrol et. Bugün başvur ya da sorunu ilet; yaptığın işi açıkça kaydet. Yarın işverenden yanıt gelip gelmediğine bak. Sessizliği yeterince inanmadığının işareti sayma. Tekrar, hazırlık, başvuru ve teklif ayrı ayrı kalsın. Böylece defterde ne yaptığın görülebilir. Bu iki sayfalı düzen ODA uyarlamasıdır; bütün olarak sınanmış bir uygulama değildir. [manifest-T02]"]}],sources:["manifest-P01","manifest-T02","manifest-T14"]},{number:7,technique:"Geleceği olmuş gibi yazma",title:"Hayalindeki gün güzel. Oraya götüren işi de yaz",goal:"Gelecekteki bir sahneden yola çık; hedefin için bugün deneyeceğin bir iş seç.",hook:"Günlüğünde her şey yolunda, bugünkü iş hâlâ bekliyor mu? O güzel güne gelmeden önce ne yaptığını da yaz.",reason:"Yeni bir sayfa yazmadan önce, bu sayfa hangi işi yapmana yardım edecek?",paragraphs:["Scripting, istediğin gelecek şu an yaşanıyormuş gibi günlük yazmaktır. Bir sahne seçer, ayrıntılarını ve hissettiklerini yazıp yeniden okursun. Bulgular karışık: gelecekteki en iyi hâlini hayal edip yazmaya dayalı benzer çalışmalarda, iyi oluş ve iyimserlik ortalama olarak arttı. Ama olmuş gibi yazmanın olayları gerçekleştirdiği gösterilmedi. Duyguları yazarak anlatma araştırmaları da gerçek yaşantılarla ilgili; dileklerin gerçeğe dönüşmesiyle değil.","ODA uyarlaması: sahne kalsın, ama oraya götüren işleri de ekle. Somut hedefini, bugünkü engeli ve engel çıkarsa ne yapacağını yaz. Bugün deneyeceğin tek işin altını çiz. Yarın bütün sahnenin gerçekleşip gerçekleşmediğini sorgulamak yerine, denediğin işle planını karşılaştır. Bu öğeleri bir araya getiren alıştırma bir uyarlamadır; aynı biçimde sınanmış değildir."],example:{title:"Elif aradaki işi de yazıyor",text:"Elif yeni işindeki sakin bir sabahı yazıyor. O sabaha gelmeden önce yapacağı mülakat hazırlığını da ekliyor. Akşam yemeğinden sonra, zor bir müşteriyle nasıl ilgilendiğini anlatan tek bir yanıtı ses kaydına alıyor. Dinlerken acele ettiğini fark edip kısaltacağı bir cümleyi işaretliyor. İş hâlâ hayal, ama yarın geliştirebileceği gerçek bir kaydı var."},instructions:["Gelecekteki sahneyi yaz; gereken işleri ve kaynakları da sahneye ekle.","Bugünkü işin altını çiz. “Şu engel çıkarsa bunu yapacağım” diye ekle.","Seçtiğin en küçük adımı dene; yarın gerçekte ne olduğunu değerlendir."],action:["Bir mülakat yanıtını ses kaydına al","Bir portfolyo açıklaması taslağı yaz"],minimum:["Tek bir yanıt kaydını sakla","Kullanılabilir bir açıklamayı kaydet"],cue:["Akşam sofrası toplandıktan sonra","Günlüğümü kapattığımda"],place:["Mutfak masamda","Portfolyo dosyamda"],obstacle:"Kusursuz bir giriş cümlesi bulamıyorum",fallback:["İlk cümleyi taslak olarak yaz","Somut bir örnek iste"],observation:["Sakladığım ses kaydı","Taslağım ve hâlâ eksik kalan kısmı"],stopRule:"Seni sıkıntıya sokan sahneleri atla. Geleceği yazmak iyi gelmiyorsa sıradan iş notları kullan.",scenario:"Elif yazdığı sahnede mülakatta kendinden emin konuşuyor. Mülakatı yarın. Müşteri hizmetleriyle ilgili sık sorulan bir soru için henüz hazır bir örneği yok.",question:"Bu sayfayı bu akşam işe yarar hâle getiren değişiklik hangisi?",options:[{key:"draft",text:"Gerçek bir müşteri örneği eklesin, bir yanıtı prova etsin ve yarın dinlemek için taslak kaydını saklasın.",feedback:"Böylece yazdığı sahne yarınki işe bağlanır. İlk yanıtın taslak olması, hangi kısmın geliştirilmesi gerektiğini görmesini sağlar. İşe alınmayı garanti etmez; ama Elif yarın dinleyip üzerinde çalışabileceği bir hazırlık yapmış olur."},{key:"feelings",text:"Hangi müşteri örneğini kullanacağına karar vermeden önce, kendinden emin olmanın nasıl hissettirdiğini ayrıntılı yazsın.",feedback:"Duyguları anlatmak sahneyi kendisi için anlamlı kılabilir. Ama burada eksik olan, yaşadığı gerçek bir olaya dayanan yanıt. Hislerini daha ayrıntılı yazsa da bu eksik kalacak. Bir müşteri örneği seçip yanıtını prova etsin."},{key:"edit",text:"Hayal ettiği mülakatı baştan sona açık ve tutarlı anlatmak için günlüğündeki bütün metni yeniden düzenlesin.",feedback:"Tutarlı bir hikâye yazmak başlı başına bir hedef olabilir. Elif’in şu an ihtiyacı bir mülakat yanıtı hazırlamak. Akşamki sınırlı zamanını hikâyeyi düzeltmeye ayırırsa, yarın sorulduğunda kullanacağı müşteri örneğini hâlâ hazırlamamış olur."}],best:"draft",takeaway:"İstediğin geleceği yazarken, oraya götüren işlerden birini de bugün gerçekten denemek için seç.",review:"Yazdığın hangi adımı atmayı denedin? O işin hangi kısmı hâlâ yarım kaldı?",deeper:[{heading:"Bu günlük uygulaması nasıl yapılıyor?",paragraphs:["1. İstediğin bir durum seç; örneğin çalışmak istediğin işte geçen bir gün. 2. O günü şimdi yaşıyormuş gibi günlük yaz. 3. Sıradan ayrıntıları anlat: neredesin, ne yapıyorsun, nasıl hissediyorsun? 4. Yazdığını yeniden oku; istersen sonra tekrar dön. Bazı biçimlerinde şükür ifadeleri veya sonucun olacağına dair kesinlik duygusu da eklenir. Bunlar uygulayıcıların tarifidir; iş teklifi almaya götürdüğü doğrulanmış bir yol değildir. [manifest-P02]","Hayal ettiğin olayların hayal olduğu açık kalsın. Başka birinin vermediği sözü vermiş gibi yazmadan da sıradan bir sahne kurabilirsin. ODA alıştırmasında gereken işleri, kullanabileceğin kaynakları ve bugün karşılaştığın bir engeli ekle. Sayfadan tek bir iş seç. İstersen klavyeyle yaz veya sesle anlat. Bunlar erişilebilir seçeneklerdir; her anlatım biçiminin araştırmada aynı etkiyi gösterdiğini iddia etmiyoruz. Deftere yazmak zorunda değilsin. Bu uygulamayı yapıp yapmamak da senin seçimin. [manifest-P02]"]},{heading:"Gelecek hayaliyle gerçek yaşantıyı yazmak farklı",paragraphs:["Bu yazma çalışmalarında, emek vererek ulaşabileceğin iyi bir geleceği hayal edip yazarsın. Carrillo ve arkadaşları iyi oluş, iyimserlik ve olumlu duygulanımda ortalama yararlar buldu. Çalışmaların kalitesiyle ilgili sınırlar vardı. Bu bulgu, düşünerek yazmanın bazı yararları olabileceğini destekler; yazılan olayların gerçekleşeceğini göstermez. Duyguları yazarak anlatmanın konusu ise gerçek yaşantılar veya hislerdir. O araştırmadaki küçük ortalama yarar da gelecekteki olayları düşünceyle çekme iddiasını doğrulamaz. İki yazma biçiminin neyi incelediğini ayrı tut. [manifest-T08, manifest-T12]","ODA sahneyi korur ve sayfayı kapattığında yapabileceğin bir iş ekler. Kursta zaten denediğin somut hedefi seç. Bugünkü adımı neyin engelleyebileceğini yaz. Sonra masrafını karşılayabileceğin, gerçekten yapabileceğin bir çözüm belirle. Ne zaman başlayacağını ve en küçük adımı kaydet; dene, yarın değerlendir. Mülakat provasını hazırlık olarak yaz. Gönderdiğin başvuruyu başvuru, gelen yanıtı ancak geldiğinde yanıt olarak kaydet. Böylece hayalinle yaptığın iş birbirine karışmaz. Bu düzen bir tasarım uyarlamasıdır; araştırmadaki iki yazma yönteminden hiçbirinin özgün deney düzeni değildir."]}],sources:["manifest-P02","manifest-T08","manifest-T12"]},{number:8,technique:"Hayal panosu",title:"Hayal panosu: o güzel masada bugün ne yapacaksın?",goal:"Panondaki bir görseli, yapabileceğin somut bir işe başlama işareti olarak kullan.",hook:"Panondaki çalışma masası çok güzel. Peki bugün kendi masanda hangi işi yapacaksın?",reason:"Hangi görsel başkasının başarı ölçüsünü değil, senin önceliğini anlatıyor?",paragraphs:["Hayal panosunda, istediğin hayatı anlatan görselleri ve sözleri bir araya getirirsin. Seç, yerleştir, görebileceğin bir yere koy ve ara ara bak. Bulgular karışık: güncel hedefler dikkati etkileyebilir; göze çarpan şeyler ve daha önce dikkat ettiklerin de etkiler. Bu, panonun işe yaradığını veya resimlerin fırsat çektiğini göstermez. Retiküler aktive edici sistem uyanıklıkla ilgilidir. Onu programlanabilir bir dilek filtresi diye anlatmak, kanıtın söylediğini aşar.","ODA uyarlaması: senin için anlamlı bir görsel kalsın. Altına somut hedefini ve bugün yapacağın tek işi yaz. Bir engel seç, çıkarsa ne yapacağını belirle. Görseli görmek başlama işaretin olsun. Yarın onu görünce en küçük adımı atıp atmadığına bak. Var olan bir fırsatı fark etmekle o fırsatı yaratmak farklı iddialar; kaydında da ayrı kalsın."],example:{title:"Ece masa görseline bir iş ekliyor",text:"Ece’nin panosunda bir tasarım stüdyosundaki masa var. Altına “Bir portfolyo örneği hazırla” yazıyor. Kahvaltıdan sonra resmi görünce yarım kalan projesini açıp bir açıklama yazıyor. Ortaya çıkan çalışma, stüdyo hayali kadar heyecan verici görünmüyor. Yine de dosyasına kaydediyor. Proje için hâlâ birinden yorum alması gerektiğini de not ediyor."},instructions:["Bir görsel seç; altına somut hedefini ve bugünkü yararlı işi yaz.","Görseli görmek başlama işaretin olsun. Olası bir engelde ne yapacağını planla.","İşi dene; yarın görseli gördüğünde başlama işaretini fark edip etmediğine bak."],action:["Bir portfolyo açıklaması yaz","Proje için bir yorum talebi gönder"],minimum:["Kullanılabilir bir proje açıklamasını kaydet","Yorum için belirli bir soru gönder"],cue:["Kahvaltıdan sonra panoyu görünce","Proje klasörümü açınca"],place:["Çalışma masamda","Portfolyo dosyamda"],obstacle:"Görseli görünce çalışmak yerine gezinmeye başlıyorum",fallback:["Gezinmeden önce proje dosyasını aç","Dosyanın yanına yazılı hatırlatıcı koy"],observation:["Görseli görünce işe başlayıp başlamadığım","Tamamladığım açıklama veya gönderdiğim talep"],stopRule:"Elindeki resimleri veya sözleri kullan. Seni harcamaya zorlayan görselleri atla.",scenario:"Ece her sabah panosunu görüyor, ardından stüdyo fotoğraflarına bakarak oyalanıyor. Portfolyosunda bitirdiği bir projeyi anlatmak için gereken açıklama henüz yok.",question:"Hangi değişiklik bugün daha çok işine yarar?",options:[{key:"fresh",text:"Pano yeniden anlamlı gelsin diye stüdyo görselini, ona daha çok ilham veren başka bir görselle değiştirsin.",feedback:"Yeni bir görsel seçmek hoşuna gidebilir. Ama kaydı, panoyu görünce internette gezindiğini gösteriyor; hedefinin eksik olduğunu değil. Resmi gördüğünde sırada ne yapacağını değiştirsin. Böylece mevcut görsel, bilinen işe başlamasını hatırlatabilir."},{key:"study",text:"Ulaşmak istediği düzeyi anlamak için ertesi sabahını farklı tasarım stüdyolarının portfolyolarını karşılaştırmaya ayırsın.",feedback:"Karşılaştırma daha sonra çalışmasına bilgi sağlayabilir. Ece’nin şu an açıklama bekleyen tamamlanmış bir projesi var. Gezinmek bu açıklama için gereken belirli bir soruyu yanıtlamıyorsa, bir sabah daha aynı oyalanma düzeni sürmüş olur."},{key:"label",text:"Görselin altına “Projeyi aç, açıklamasını yaz” eklesin. Stüdyo fotoğraflarına bakmadan önce bir açıklamayı kaydetsin.",feedback:"Böylece zaten gördüğü işaret, eksik olan işi hatırlatır. Ece yarın etiketi fark edip etmediğini ve açıklamayı kaydedip kaydetmediğini kontrol edebilir. Bu, inceleyebileceği somut bir denemedir. Panonun kendisi stüdyoda iş bulmayı garanti etmez."}],best:"label",takeaway:"Resmi gördüğünde bugün bir işe başla. Resmin gücünü sorgulamak yerine yaptığın işi değerlendir.",review:"Görselini görünce planladığın işi mi yaptın, yoksa başka bir şeye mi yöneldin?",deeper:[{heading:"Yeni bir şey almadan hayal panosu hazırla",paragraphs:["1. İstediğin bir yönü veya durumu seç. 2. Onu anlatan birkaç resim ve söz topla. 3. Kâğıda, elindeki bir panoya veya dijital bir sayfaya yerleştir. 4. Ara ara bakmak istediğin yere koy. 5. Panoya bakıp istediğin durumu hayal et. Bu adımlar yaygın uygulamanın nasıl yapıldığını anlatıyor. Panonun, o durumu gerçekten meydana getirdiğine dair kanıt değiller. [manifest-P03]","Bu kursta hayatının her yanını değiştirme hedeflerini yığmak yerine bir yön seç. Elindeki bir fotoğraf, çizim veya yazılı bir söz yeterli. Bir görselin altına yapacağın işi yaz: eğitim hakkında soru sormak, bir örneği bitirmek veya uygun bir ilana başvurmak. Görseli gördüğünde harekete geçebileceğin bir yer seç. Kullanacağın malzemeler ve yerleşim senin tercihin. Özel malzeme satın alman gerektiğine dair bilimsel bir koşul yok. Resimleri yerleştirmekle hedefin için seçtiğin işi tamamlamak ayrı işler; birini yapınca diğerini yapılmış sayma."]},{heading:"Fark etmek neyi açıklayabilir?",paragraphs:["Dikkat araştırması, neye yöneldiğimizi güncel hedeflerin, fiziksel olarak göze çarpan özelliklerin ve daha önce dikkat ettiğimiz şeylerin etkilediğini anlatır. İlgili fırsatlara bilinçli olarak bakmanın makul bir yanı var. Ama fark etmeyi geliştirdiği söylenen her yöntemi doğrulamaz. Retiküler aktive edici sistem, uyanıklık ve uyarılmayla ilgili sinir devrelerinde rol alır. Bu bulgular, panonun kontrol ettiği bir filtrenin iş, eş veya ev getirdiğini göstermez. Yeni fark ettiğin bir fırsat, dikkatini vermeden önce de var olmuş olabilir. Fark etmeyi, fırsatın kaynağı diye anlatma. [manifest-T15, manifest-T19]","ODA görsele gizli bir güç yüklemek yerine onu açık bir hatırlatıcı olarak kullanır. Hedefini, bugünkü işi ve seni en çok durdurabilecek engel çıkarsa ne yapacağını yaz. Panoyu görünce yine fotoğraflara dalıyorsan önce çalışma dosyanı açmayı planla. Yarın şu sorulara bak: işaret ortaya çıktı mı, onu fark ettin mi, hangi işi yaptın? Başkalarından gelen yanıtları da kendi yaptığından ayrı tut. Böylece hatırlatıcının o fırsatta neye yol açtığını görürsün. Bu görsel ve plan birleşimi, hayal panosu uygulaması olarak deneyle sınanmış değildir."]}],sources:["manifest-P03","manifest-T15","manifest-T19"]},{number:9,technique:"Olumlamalar",title:"Olumlamalar: inanamadığın cümleyi yapabileceğin işe çevir",goal:"Cesaret veren bir cümleyi, hedefin için yaptığını görebileceğin tek bir işle eşleştir.",hook:"“Çok başarılıyım” bugün sana boş mu geliyor? Sana yapacak bir iş veren cümleyi dene.",reason:"Bu cümle işi denemene yardım mı ediyor, yoksa ona mutlaka inanmak zorunda mı hissediyorsun?",paragraphs:["Olumlama, cesaret veren bir sözü tekrar tekrar söylemek veya yazmaktır. Çoğu kez istenen sonuç olmuş gibi kurulur. Cümle seçilir, tekrarlanır, ona inandığın hayal edilir. Bulgular karışık: Wood ve arkadaşlarının çalışmasında çok olumlu bir cümle, öz saygısı düşük bazı katılımcıların ruh hâlini kötüleştirdi. Araştırmadaki kendini olumlama, çoğunlukla önemli değerleri düşünmektir; başarı sloganı tekrarlamak değil. Sağlık davranışı bulguları, sözlerin iş teklifi çektiğini göstermez.","ODA uyarlaması: işine yarayan, cesaret veren bir cümle kalsın. Bir değerini ve onu yansıtan işi seç: “Yaşadığım bir olayı dürüstçe anlatmaya hazırlanıyorum.” Somut hedefini, engeli ve engel çıkarsa ne yapacağını belirle. Bugün işi dene, yarın ne yaptığına bak. Sana daha kötü hissettiren cümleyi değiştir veya atla. Onu söylemek bir zorunluluk olmasın."],example:{title:"Selin cümlesini değiştiriyor",text:"Selin toplantıdan önce “Harika bir konuşmacıyım” diyor, ama daha çok utanıyor. “Tek bir düşüncemi açıkça anlatmaya hazırlanıyorum” cümlesine geçiyor. Masasında bir öneri yazıp söylemeyi prova ediyor. Toplantıda ilk cümleyi söylüyor, sonra ne diyeceğini unutuyor. Kaydına sunduğu öneriyi ve açıklamasının yarım kalan kısmını yazıyor. Söylediğiyle söyleyemediğini ayrı tutuyor."},instructions:["Bir değerini ve somut bir işi hatırlatan, cesaret verici bir cümle seç.","Bir engel belirle. İnanmayı şart koşmadan, engel çıkarsa yapabileceğin şeyi yaz.","Bugün işini dene; yarın yaptığını ve cümlenin sana nasıl hissettirdiğini değerlendir."],action:["Toplantıda hazırladığın bir cümleyi söyle","Proje hakkında açık bir soru sor"],minimum:["Önerinin ilk cümlesini söyle","Proje hakkında belirli bir soru gönder"],cue:["Toplantıda öneriler sorulduğunda","Proje mesajlarını açtığımda"],place:["Toplantı odamızda","Proje mesaj grubunda"],obstacle:"Cesaret veren cümlem bana inandırıcı gelmiyor",fallback:["Olumlama yapmadan hazırladığım cümleyi söyle","Yapacağım işi hatırlatan kısa bir not kullan"],observation:["Ne söylediğim ve gelen yanıt","Cümle yardım etti mi, kötü hissettirdi mi?"],stopRule:"Seni sıkıntıya sokan cümleleri değiştir veya atla. Kendini kesinlikle inanmaya zorlaman gerekmiyor.",scenario:"Selin tekrar ettiği başarı cümlesiyle kendini daha kötü hissediyor. Yine de toplantıda yararlı bir öneri sunmak istiyor. Hazır bir taslak cümlesi var.",question:"Bu iki durumu da gözeten değişiklik hangisi?",options:[{key:"persist",text:"Önerisini prova etmeyi sürdürsün. Başarı cümlesini değiştirmeden önce birkaç seans daha tekrarlamaya devam etsin.",feedback:"Prova hazırlığına yardım edebilir. Ama ruh hâlini kötüleştiren bir cümlede ısrar etmesi gerekmiyor. Hazırladığı öneri zaten elinde. Bu, kendini bir söze inanmaya zorlamadan başlamasını sağlayacak başka bir yol; önerisini küçük tutarak deneyebilir."},{key:"action",text:"Sade bir iş hatırlatıcısı kullansın veya olumlamayı atlasın. Öneriler sorulduğunda hazırladığı cümleyi söylesin.",feedback:"Bu seçim, yaşadığı rahatsızlığı gözetirken yapılabilir bir katkıya yer bırakır. Selin ne söylediğini ve hatırlatıcının nasıl hissettirdiğini sonra değerlendirebilir. Öneri sunmak için harika bir konuşmacı olduğundan kesinlikle emin olması gerekmiyor. Hazır cümlesiyle başlayabilir."},{key:"wait",text:"Güçlü yanlarını anlatan daha iddialı bir cümle hazırlasın. İyice inanana kadar toplantıdaki önerisini ertelesin.",feedback:"Değerlerini düşünmekle kendini büyük bir iddiaya ikna etmeye çalışmak farklı işler. İnanmayı beklemek, zaten hazır olan öneriyi söylemek için önce öz güven şartı koyar. Katkısını küçük tutabilir; olumlama söyleyip söylememek onun seçimi olarak kalsın."}],best:"action",takeaway:"Cümleyi istersen hatırlatıcı olarak kullan. Ne yapabildiğini, yaptığın somut iş göstersin.",review:"Neyi denedin? Cümle yardım mı etti, zorlaştırdı mı, yoksa hiçbir fark yaratmadı mı?",deeper:[{heading:"Yaygın olumlama uygulamasının adımları",paragraphs:["1. İstediğin bir sonuç veya kişisel özellik seç. 2. Olumlu bir cümle kur; çoğu biçiminde şu anda doğruymuş gibi söylenir. 3. Tekrar tekrar söyle veya yaz. 4. Cümleyi kullanırken istediğin durumu hayal et. 5. Seçtiğin zamanda yeniden dön. Uygulayıcıların tariflerinde sıklık ve sözcükler değişir. Bu yaygın tarif, bilimsel olarak gerekli bir tekrar sayısı veya his belirlemez. [manifest-P04]","Uygulamanın en büyük vaadini doğru saymadan da onu sevebilirsin. ODA için, gerçekten deneyeceğin işe işaret eden bir cümle kullan. “Tek bir düşüncemi açıkça anlatmaya hazırlanıyorum” toplantı notlarının yanında durabilir. Hiç cümle kullanmamayı da seçebilirsin. Rahatsız eden veya inandırıcı gelmeyen bir söz, geçmen gereken sınav değil. Wood ve arkadaşları belirli bir olumlu sözü ve kısa süreli ruh hâli etkilerini inceledi. Bu sonuç, kendine anlayışla söylediğin her cümlenin zarar verdiğini göstermiyor. Bulguyu bütün sözlere genelleme. [manifest-T06]"]},{heading:"Bir değeri düşünmekle başarı sloganı farklı",paragraphs:["Kendini olumlama araştırmasında insanlar, kendileri için tehdit oluşturabilecek bilgiyle karşılaşmadan önce önemli değerleri, özellikleri veya ilişkileri düşünür. Epton ve arkadaşları sağlık mesajlarıyla yapılan deneyleri birleştirdi. Mesajı kabul etmede ve niyetlerde küçük ortalama etkiler, o bağlamda davranışta da yarar buldu. Bu işlemler, istenen sonucu olmuş gibi tekrar etmekten farklıdır. “İşe girdim” demenin ardından iş teklifi geleceğini göstermez. Bir araştırmanın olumlama sözcüğünü kullanması, yaygın olumlama cümlelerinin bütün vaatlerini sınadığı anlamına gelmez. [manifest-T07]","ODA bu ayrımdan yararlanır, bütün uygulamanın sınandığını söylemez. Dürüstlük gibi bir değer seç. Mevcut hedefinde bunu gösterecek tek bir iş belirle: yaptığın işi doğru anlatan bir örnek hazırla. Başlama fırsatını ve en küçük adımı kaydet. Ne diyeceğini unutmak gibi olası bir engelde ne yapacağını yaz. Bugün cümleni söylemeyi dene. Yarın sunduğun katkıyı ve hatırlatıcının kullanışlı gelip gelmediğini kaydet. Olumlama baskı yaratıyorsa atla; yapabileceğin iş kalsın. Söze inanmak, o işi denemenin ön koşulu olmasın. [manifest-T06, manifest-T07]"]}],sources:["manifest-P04","manifest-T06","manifest-T07"]},{number:10,technique:"Zihinde canlandırma",title:"Teklifi hayal ettin. Önce soruya vereceğin yanıtı prova et",goal:"Bir iş seç, zorlanacağın kısmı prova et ve gerçekten bir deneme yap.",hook:"İş teklifini hayal etmek güzel. Şimdi o tekliften önce sorulacak soruya yanıt vermeyi prova et.",reason:"Bir sahne daha kurmak gereken eksiği mi gösterecek, hazır olan işi mi geciktirecek?",paragraphs:["Zihinde canlandırma, istediğin olayı çoğu kez duyusal ayrıntılar ve başarı hissiyle hayal etmektir. Rahatla, sahneyi kur, içinde olduğunu düşün; istersen tekrarla. Manifestasyon açısından bulgular karışık: zihinsel canlandırma, sonraki davranışa ortalama destek verdi. Olayları çektiği gösterilmedi. Eski bir sınav çalışmasında bazı karşılaştırmalar, çalışma sürecini hayal etmeyi destekledi. Sonraki meta-analizde ise hangi canlandırma türünün daha iyi olduğu güvenilir biçimde belirlenemedi.","ODA uyarlaması: sonucu anlatan kısa bir sahne kalsın. Ardından yapacağın işi ve bir engelde ne yapacağını prova et. Somut hedefini ve engel çıkarsa ne yapacağını seç. Bugün tek bir işi dene, yarın değerlendir. Prova yine hazırlık olarak kalsın. Zihninde görüntü oluşmuyorsa adımları yaz. Canlı bir resim veya özel bir his gerekmiyor."],example:{title:"Emre zor soruyu prova ediyor",text:"Emre mülakatın bittiğini hayal ediyor. Ardından çalışma hayatındaki boşluğu açıklamayı prova ediyor. Donakalırsa notundaki tarihlerden başlamayı planlıyor. Öğle yemeğinden sonra bir yanıtı kaydedip dinliyor. O dönemde ne öğrendiğini söylemediğini fark ediyor, bir cümle ekliyor. Yanıtı hâlâ prova gerektiriyor. Henüz mülakat sonucu yok; elindeki kayıt yalnızca hazırlığını gösteriyor."},instructions:["Sonuç sahnesini kısa tut. Sıradaki işi ve olası bir zorlukta ne yapacağını prova et.","Somut hedefini ve bu zorluk çıkarsa ne yapacağını açıkça yaz.","Bugün işi gerçekten dene. Yarın yaptığını, provadan ayrı olarak değerlendir."],action:["Bir mülakat yanıtını prova için kaydet","Hazırladığın bir toplantı önerisini gönder"],minimum:["Tek bir taslak yanıt kaydını sakla","Önerinin bir cümlesini gönder"],cue:["Öğle yemeği bittikten sonra","Toplantıda görüşler sorulduğunda"],place:["Mülakata hazırlandığım masada","Ekibin mesaj grubunda"],obstacle:"İlk cümlede donakalıyorum",fallback:["Notumdaki tarihlerden başla","Hazırladığım kısa giriş cümlesini oku"],observation:["Gerçekten kaydettiğim yanıt","Ayrı ayrı kaydettiğim hazırlık ve katkı"],stopRule:"Canlandırma sıkıntını artırıyorsa dur. Sıradan iş notlarını ve gündüz bir fırsatı kullan.",scenario:"Emre başarılı bir mülakatı iki kez hayal etti. Kaydettiği prova yanıtında hâlâ çalışma hayatındaki boşluğu açıklamıyor. Evden çıkmadan önce beş dakikası var.",question:"Canlandırmayı bu eksik için nasıl kullanabilir?",options:[{key:"rehearse",text:"Boşluğu açıklayan ilk cümleyi prova etsin. Bir taslak yanıt kaydedip gereken tarihleri söyleyip söylemediğine baksın.",feedback:"Bu hazırlık, görülen eksiğe yönelir ve dinleyebileceği bir kayıt oluşturur. Canlandırma mülakat sonucunu güvenceye almaz. Buradaki yararlı işlevi, Emre’nin yanıtı söylemeyi denemesine yardım etmektir. Kaydı dinleyince gerekli bilgiyi ekleyip eklemediğini kontrol edebilir."},{key:"outcome",text:"Başarılı mülakat sahnesini daha zengin ayrıntılarla yeniden kursun. Sonra ne kadar öz güven hissettiğini yazsın.",feedback:"Öz güven hissini kaydetmek mümkün. Ama bu his, yanıtlanmamış soruyu yanıtlamaz. Emre’nin kaydında prova gerektiren belirli bir açıklama var. Kalan zamanını bu açıklamayı söyleyip kaydetmeye ayırsın; böylece neyi eksik bıraktığını gerçekten dinleyerek görebilir."},{key:"research",text:"Bu akşam hangi yöntemi deneyeceğine karar vermeden önce, kalan zamanda birkaç canlandırma yöntemini karşılaştırsın.",feedback:"Yöntemleri karşılaştırmak ilgi çekici olabilir. Ama buradaki kanıt, başlamak için önce belirli bir tür seçmesini gerektirmiyor. Emre hangi işi yapmadığını zaten biliyor. Kısa bir deneme, yeni bir yöntem arayışından daha yararlı bilgi sağlayabilir."}],best:"rehearse",takeaway:"Sahne, yapacağın işi göstersin. Prova hazırlanmanı sağlar; işi denediğinde ne olduğunu görürsün.",review:"Provadan sonra hangi işi gerçekten denedin? Deneyince hangi eksik daha görünür oldu?",deeper:[{heading:"Yaygın sonuç sahnesi nasıl kuruluyor?",paragraphs:["1. Gerçekleşmesini istediğin bir olay seç. 2. Rahat bir yere yerleş. 3. İstediğin sonucu gösteren kısa bir sahne hayal et. 4. Sana anlamlı gelen ayrıntılarla o sahnenin içinde olduğunu düşün. 5. İstersen sonra tekrar dön. Bazı uygulayıcılar güçlü duygu veya sonucu zaten elde etmiş olma hissi ister. Bu adımlar bir uygulamanın tarifidir. Kurulan sahnenin, dışarıdaki bir olayı düşünceyle çektiğini göstermez. Hissetmenin yoğunluğu da bu iddiayı doğrulamaz. [manifest-P05]","ODA için sonuç sahnesini kısa tut; yapacağın işe zaman kalsın. Bugünle o sahne arasında hangi işin gelmesi gerektiğini belirle. İşin zorlanacağın kısmında ne yapacağını zihninde prova et, ardından deneyeceğin çözümü yaz. Canlı görüntüler oluşturamıyorsan adımları sözle anlatabilirsin. Bu erişilebilir bir seçenektir; her hazırlık biçiminin aynı etkiyi verdiğinin kanıtı değildir. Hayal ettiğin işveren yanıtını gerçek yanıt diye kaydetme. Hazırlık ve yanıt ayrı kalsın."]},{heading:"Araştırma tek bir canlandırma türünü üstün göstermiyor",paragraphs:["Pham ve Taylor’un eski sınav çalışmasında, çalışma sürecini hayal etme, istenen notu hayal etme, bunları birleştirme ve kontrol koşulu karşılaştırıldı. Bazı karşılaştırmalar süreç canlandırmasını destekledi. Notla ilgili bulgu, sürecin kontrol grubuna göre güvenilir yararını göstermez. Cole ve arkadaşları daha sonra farklı zihinsel canlandırmaları birleştirip davranışta ortalama yarar buldu; türler arasında fark belirlemedi. Bazı alt gruplar küçüktü. Bir sahnenin her zaman en iyi sonucu vereceğine söz vermek bu kanıtı aşar. Bulgular evrensel bir sıralama sunmuyor. [manifest-T17, manifest-T04]","ODA, senin yapacağın iş için hangi hazırlığın gerektiğini sorar. Hedefini biliyor ama ilk cümleden kaçınıyorsan, başlamayı ve bu engelle karşılaşınca ne yapacağını prova et. Yapılabilir en küçük adımı, başlama işaretini, yeri ve çözümünü kaydet. Bugün işi dene, yarın değerlendir. Yararlı bir prova ile gerçekten yaptığın işi ayrı ayrı yaz. Hazırlık sürüyor ama deneme gelmiyorsa provayı kısalt veya kullanabileceğin başka bir fırsat seç. Bu sahneden denemeye geçiş düzeni ODA uyarlamasıdır. Meta-analizin doğruladığı belirli bir uygulama protokolü değildir."]}],sources:["manifest-P05","manifest-T04","manifest-T17"]},{number:11,technique:"55x5 yöntemi",title:"55x5: satırlar doldu, başvuru hâlâ boş mu?",goal:"İstersen yaz; ardından yapabileceğin tek bir işi dene ve ne olduğunu değerlendir.",hook:"Elli beş satır yazdın, başvuruya tek cümle eklemedin mi? Sıradaki cümleyi bugün işine yarayacağı yere yaz.",reason:"Asıl işe ayıracağın zamanı azaltmadan yazıya ne kadar zaman verebilirsin?",paragraphs:["55x5 yönteminde, istediğin sonucun olmuş gibi anlatıldığı bir olumlama cümlesini beş gün boyunca günde 55 kez yazarsın. Sonuç seçer, aynı cümleyi tekrar eder ve günlük sayıyı tamamlarsın. Bu tekrar sayısının ya da beş günlük düzenin istediğin sonucu hayatına çektiği iddiası kanıtla desteklenmiyor. İdeal geleceği hayal ettiren bazı deneylerde o anki enerji azaldı. Bu, her hayalin veya bu yazma ritüelinin çabayı azalttığını göstermez.","ODA uyarlaması: hoşuna gidiyorsa yazmaya devam et; tekrarlar isteğe bağlı kalsın. Belirli bir hedef ve her gün yapabileceğin tek bir iş seç. Engeli söyle, sonra fark edebileceğin bir an için “Şu olursa şunu yapacağım” planı kur. Daha çok yazmadan bugün işi dene; yarın ne yaptığını değerlendir. Araştırma bu tür somut planları destekliyor, özel tekrar takvimini değil."],example:{title:"Emre başvuruya zaman ayırıyor",text:"Emre “İşe yarayan başvurular hazırlıyorum” yazmayı seviyor, ama 55 satır molasının tamamını alıyor. Birkaç satırla yetinip öğle yemeğinden sonra başvuru için beş dakika ayırıyor. Bir bilgi eksikse işe alım ekibine soracağı soruyu yazacak. Bugün soruyu gönderiyor. Kaydına bu soruyu geçiriyor; başvuru yaptığını veya teklif aldığını yazmıyor."},instructions:["Bir hedef seç; kaç tekrar yapacağına karar vermeden önce asıl iş için zaman ayır.","Fark edebileceğin bir başlama anı seç; bir engel için “Şu olursa şunu yapacağım” de.","Bugünkü işi dene ve yarın ne yaptığını değerlendir; tekrar yapmak isteğe bağlı kalsın."],action:["Eksik bilgiyi soran bir mesaj gönder","Başvurunun bir bölümünü tamamla"],minimum:["İşe alım ekibine bir soru gönder","Tamamlanmış bir bölümü kaydet"],cue:["Öğle yemeği bittikten sonra","İsteğe bağlı yazma çalışmam bitince"],place:["İşe alım ekibine yazdığım e-posta taslağında","Başvuruyu hazırladığım masada"],obstacle:"Tekrarlar elimdeki bütün zamanı alıyor",fallback:["Tekrarı atla, en küçük adımı at","Defteri açmadan asıl işe zaman ayır"],observation:["Yaptığım iş ve yazmaya ayırdığım süre","Gönderdiğim veya kaydettiğim şey"],stopRule:"Yazmak seni zorluyorsa veya asıl işe ayırabileceğin zamanı tüketiyorsa azalt ya da atla.",scenario:"Emre iki gün boyunca 55 tekrarı tamamladı. İki gün de başvurusuna zaman kalmadı. Bugün yine aynı kısa molası var.",question:"Hangi değişiklik daha işe yarar bir düzeni denemesini sağlar?",options:[{key:"faster",text:"Ritüeli eksiksiz sürdürebilmek için tekrarları daha hızlı yazsın; sonra zaman kalırsa başvuruya başlasın.",feedback:"Daha hızlı yazmak da başvuruya zaman bırakmayabilir. Önceki iki gün, aynı molaya iki işin sığmadığını gösteriyor. Önce yapabileceği işe zaman ayırsın. Sonra kalan süreye ne kadar isteğe bağlı yazı sığacağını seçsin."},{key:"weekend",text:"Beş günlük yazıyı tamamlasın, sonra hafta sonu başvuruya daha uzun bir zaman ayırsın.",feedback:"Hafta sonu uzun bir çalışma mümkün olabilir. Ama bu seçim, kanıtla desteklenmeyen bir tekrar sayısını korumak için asıl işi erteliyor. Bugün zaten küçük bir fırsatı var. Daha çok tekrar eklemeden önce o fırsatı denesin."},{key:"reserve",text:"Başvurunun bir bölümüne beş dakika ayırsın, tekrarları azaltsın veya atlasın; kaydettiği bölüme yarın baksın.",feedback:"Bu seçim, işi engelleyen zaman sorununu değiştiriyor. Yazı kişisel bir tercih olarak kalırken başvuruyu denemek mümkün oluyor. Kaydedilmiş bir bölüm, başvuruyu göndermeye yönelik hazırlıktır. İşverenin teklif verdiği anlamına gelmez."}],best:"reserve",takeaway:"Asıl işe zaman bırak. Tekrar sayısını tamamlamak, hedefin için gereken işi tamamlamak değildir.",review:"Hangi işi denedin? Yazı yazdıktan sonra o iş için ne kadar zaman kaldı?",deeper:[{heading:"Yaygın beş günlük tekrar tarifi",paragraphs:["1. İstediğin bir sonuç seç. 2. Sanki gerçekleşmiş gibi olumlu bir cümle yaz. 3. Günlük bir oturumda bu cümleyi 55 kez kopyala. 4. Aynı oturumu beş gün boyunca tekrarla. 5. Yazarken istediğin sonuca yeniden odaklan. Buradaki kesin tekrar sayısı, yöntemi öneren kişinin kuralıdır; kontrollü araştırmayla belirlenmiş bir uygulama miktarı değildir. Bazı tarifler belirli bir duygu hissetmeni veya dikkatin hiç dağılmamasını da ister. [manifest-P06]","Bu yazma biçimi hoşuna gidiyorsa koruyabilirsin, ama aldığı zamanı hesaba kat. Başlamadan önce bugün hedefin için yapacağın asıl işe ne kadar süre gerektiğini seç. ODA uyarlamasında daha kısa yazabilir veya tekrarları tamamen atlayabilirsin. Bir günü kaçırmak, gelecekteki sonucun iptal olduğu anlamına gelmez. Doldurduğun sayfayı yazı olarak kaydet; kaydettiğin başvuru bölümünü ise başvuru üzerinde yaptığın iş olarak. Bu iki kayıt da işverenin teklif verdiğini söylemez."]},{heading:"Plana yarayan şey tekrar sayısı değil",paragraphs:["Gollwitzer ve Sheeran’ın meta-analizi, farklı işlerde belirli bir durumu hedefe yönelik bir davranışla eşleştiren planları destekliyor. 55 tekrarı veya beş günlük manifestasyon kuralını test etmiyor. Kappes ve Oettingen, ideal geleceğe dair bazı olumlu hayallerden sonra o anki enerjinin azaldığını buldu. Bu kısa deneyler, hoş bir tamamlanma hayalinin hazırlığın yerine geçmesine karşı bir uyarıdır. Her iyimser düşüncenin veya tekrarlanan cümlenin zararlı olduğunu kanıtlamaz. [manifest-T02, manifest-T05]","ODA sayfayı, yapabileceğin bir planı yazmak için kullanır. Hedefini, işin en küçük yararlı parçasını ve onu yapabileceğin fırsatı belirt. Yazı bütün molayı dolduruyorsa önce asıl işi yapmayı planla. Eksik bir bilgi yüzünden bölüm ilerlemiyorsa o bilgiyi sor. Bugün dene, yarın değerlendir: seçtiğin an geldi mi, hangi işi yaptın, geriye ne kaldı? Yazı ve eylemi birleştiren bu düzen bir uyarlamadır. Beş gün sonunda belirli bir sonuç vaat etmez."]}],sources:["manifest-P06","manifest-T02","manifest-T05"]},{number:12,technique:"İki bardak yöntemi",title:"İki bardak: istediğin duruma hangi adımla geçeceksin?",goal:"Bardaklardaki yazılardan yola çıkıp yapabileceğin bir iş ve engel için plan seç.",hook:"Bardağa “Başvuruya hazırım” yazdın, portfolyo hâlâ yarım mı? Bugün hangi iş seni başvurmaya biraz daha yaklaştırır?",reason:"Elindeki zaman ve imkânlarla istediğin duruma yaklaşmak için ne gerekir?",paragraphs:["İki bardak yönteminde bir bardağa bugünkü durumunu, diğerine istediğin durumu yazarsın. İlkini doldurur, değişimi hayal eder, suyu ikinciye döker ve içersin. Suyun niyet taşıdığı veya boyut değiştirdiği iddiası kanıtla desteklenmiyor. Hedef koyma araştırmaları belirli hedefleri, izlenecek yolları ve geri bildirimi inceler. Suyu bir bardaktan diğerine dökmeye kuantum açıklaması getirmez.","ODA uyarlaması: bardaklar sembol olarak kalsın; istersen iki daire çiz. İki yazının arasına belirli bir hedef, gerçek bir engel ve “Şu olursa şunu yapacağım” planı ekle. WOOP, istek, sonuç, engel ve plandan oluşur. Araştırmalar bu planlama birleşimini ortalama olarak destekliyor. Bugün aradaki farkı azaltacak bir işi dene. Yarın yaptığın işi, başkalarına da bağlı sonuçlardan ayrı değerlendir."],example:{title:"Ömer aradaki adımı yazıyor",text:"Ömer bardaklara “Portfolyo eksik” ve “Başvuruya hazırım” yazıyor. Aralarına bir not koyuyor: “Öğle yemeğinden sonra bir projenin açıklamasını kaydet.” Projeyi anlatamazsa projedeki temel kararını açıklayacak. Suyu döküyor, sonra açıklamayı yazıyor. Portfolyoya hâlâ bir proje daha eklemesi gerekiyor. Notuna bugün yaptığı işi ve neyin değiştiğini açıkça yazıyor."},instructions:["Bugünkü durumunu ve istediğin hedefi yaz; değişimin yapabileceğin ölçüde olmasına bak.","Aralarına bugünkü işi yaz; engel için “Şu olursa şunu yapacağım” planı ekle.","Aradaki farkı azaltacak işi dene; yarın hangi işi yaptığını değerlendir."],action:["Bir projenin açıklamasını yaz","Bir eğitimin koşulunu sor"],minimum:["Bir kararı anlatan açıklamayı kaydet","Eğitim hakkında bir soru gönder"],cue:["Öğle yemeği bittikten sonra","Bardakları kaldırdığım zaman"],place:["Portfolyo belgemde","Mutfak masasında"],obstacle:"İstediğim durum için daha fazla imkân gerekiyor",fallback:["Erişim imkânını veya daha küçük bir seçeneği sor","Projede verdiğim bir kararı sade anlat"],observation:["Aradaki farkı azaltmak için yaptığım iş","İki durum arasında hâlâ eksik kalanlar"],stopRule:"İstersen çizim kullan. Suyu içme adımını seçersen yalnızca içmeye uygun, güvenli su kullan.",scenario:"Ömer’in istediği durumu anlatan bardağında “Başvuruya hazırım” yazıyor. Portfolyosunda bir proje bitmiş ama açıklaması yok. İkinci proje ise hâlâ tamamlanmamış.",question:"Beş dakikada hangi iş aradaki farkı azaltabilir?",options:[{key:"caption",text:"Bitmiş projenin açıklamasını yazıp kaydetsin; sonra portfolyonun hazır olmasını hâlâ engelleyen eksikleri yazsın.",feedback:"Bu seçim, yapabileceği bir parçayı tamamlıyor ve kalan eksikleri görünür tutuyor. Tek açıklama bütün portfolyoyu hazır hâle getirmez. Ama yarın değerlendirebileceği, hedefe doğru atılmış somut bir adım verir."},{key:"rename",text:"Ritüel sırasında büyük hedefini aklında tutmak için ikinci bardağa “İşe alınmış tasarımcı” yazsın.",feedback:"Büyük hedefi onun için değerli olabilir. Ama bardağın yazısını değiştirmek eksik portfolyoyu ilerletmez. İsteğini korusun ve elindeki beş dakikada yapabileceği küçük işi seçsin. Bugünkü fırsat bu işe yeter."},{key:"schedule",text:"Açıklamaya başlamadan kalan bütün portfolyo işlerini sıralasın; böylece izleyeceği yolun tamamını planlamış olsun.",feedback:"İşleri sıralamak daha sonraki değerlendirmede yararlı olabilir. Bu kısa molada eksik açıklamanın ne olduğu zaten belli. Molanın tamamını yeni hazırlıklara harcamak yerine açıklamayı bitirmek, yapılabilir bir adımı denemesini sağlar."}],best:"caption",takeaway:"İki yazı aradaki farkı göstersin. Elindeki imkânlara uyan bir iş o farkın bir kısmını kapatsın.",review:"Yaptığın iş neyi değiştirdi? Yazdığın iki durum arasında hâlâ hangi eksikler var?",deeper:[{heading:"Yaygın iki bardak ritüeli",paragraphs:["1. İki bardak al; ilkine şu anki durumunu yaz. 2. İkinciye istediğin durumu yaz. 3. İlk bardağı suyla doldur. 4. Suyu ikinci bardağa dökerken istediğin değişimi hayal et. 5. Suyu iç ve istediğin duruma yeniden odaklan. Yöntemi uygulayan bazı kişiler bunu boyutlar arasında geçiş olarak anlatır. Bu metafizik açıklama, incelenen kanıtlarla doğrulanmış değildir. Buradaki adımlar, yaygın bir ritüelin nasıl yapıldığını anlatır. [manifest-P07]","Sembolik su aktarımını koruyabilir, açıklamasını bilimsel gerçek olarak kabul etmeyebilirsin. ODA çalışması için evindeki bardaklar veya çizdiğin iki daire yeterli. Suyu dökmeden iki yazının arasına yapacağın işi ekle. Başkasının henüz vermediği bir kararı kesinleşmiş gibi yazma. Portfolyo açıklamasını hazırlamak senin işin; işe alınmak ise işverenin kararına da bağlı bir sonuç. Suyu içeceksen yalnızca içmeye uygun, güvenli su kullan. Özel bir kap alman veya para harcaman gerekmez."]},{heading:"WOOP ile farkı ve imkânları düşün",paragraphs:["WOOP, bir isteği, istenen sonucu, bugünkü engeli ve planı sıraya koyar. İstenen geleceği mevcut engelle birlikte düşünmeyi “Şu olursa şunu yapacağım” planlarıyla birleştiren meta-analiz, hedefe ulaşmada ortalama olarak mütevazı bir yarar buldu. Sonuçlar değişkendi ve yayın yanlılığına dair işaretler vardı. Bardakları veya suyu test etmedi. Hedef koyma kuramında kararlılık, geri bildirim, beceri ve işin karmaşıklığı da önem taşır. Anlamlı bir hedefin uygulanabilir bir yolu olmalı; araçlara erişmeden veya yol belirlemeden zor bir hedef koymak yetmez. [manifest-T01, manifest-T11]","ODA aradaki adımı açıkça yazmanı ister. Mevcut hedefin için tek bir somut iş seç. Karşılaştığında bir şey yapabileceğin engeli söyle; eksik araç veya para gibi dış koşulları da kontrol et. “Araca erişemezsem kullanabileceğim başka bir seçenek soracağım” diyebilirsin. Böylece bugünkü işin destek istemek olur. En küçük adımı ve başlama anını kaydet, bugün dene, yarın değerlendir. Yardım isteğini, aldığın yardımdan ayrı kaydet. Sembolik bardaklarla bu pratik düzeni birleştirmek bir uyarlamadır; birlikte test edilmiş bir tedavi değildir."]}],sources:["manifest-P07","manifest-T01","manifest-T11"]},{number:15,technique:"Şükran günlüğü",title:"Şükran günlüğü: desteği gör, hayal kırıklığını saklama",goal:"Gerçekten değer verdiğin bir şeyi yaz; zorluğu inkâr etmeden yararlı bir adım dene.",hook:"Arkadaşının yardımına teşekkür edip başvurunun reddedilmesine yine de üzülebilirsin. İkisi de günlüğünde yer bulsun.",reason:"Değişmesi gerekeni gizlemeden neye teşekkür edebilir veya değer verebilirsin?",paragraphs:["Şükran günlüğünde değer verdiğin şeyleri yazarsın; çoğu zaman nedenlerini ekler ve yeniden okursun. Bazı manifestasyon tarifleri, gelecekteki bir olay olmuş gibi hayata teşekkür eder. Bulgular karışık: şükran uygulamaları bazı kontrol gruplarına göre iyi oluşta küçük ortalama yararlar gösteriyor. Psikolojik açıdan etkin başka uygulamalara göre üstünlük gösterilmedi. Belirtilerle ilgili bulgular mütevazı; şükran yeterli bir tedavi veya gelecek olayların hayatına çekildiğinin kanıtı değil.","ODA uyarlaması: günlüğün kalsın, ama gerçek bir şeyi anlat. Takdir ettiğin desteğin yanında belirli hedefini ve bir zorluğu yaz. Engel için “Şu olursa şunu yapacağım” de. Bugün bir iş seç. Yardım edene teşekkür etmek veya belirli bir konuda görüş istemek olabilir. Yarın yaptığın işi ve varsa yanıtı değerlendir. Minnettarlık hayal kırıklığını gizlemeyi gerektirmez."],example:{title:"Ayşe iki gerçeği de yazıyor",text:"Ayşe, arkadaşının başvurusuna bakmasına değer verdiğini yazıyor. Ret e-postasını da kaydediyor. Kahvaltıdan sonra hangi giriş cümlesinin düzeltilmesi gerektiğini soruyor. Arkadaşı telefonda konuşamazsa kısa mesaj gönderecek. Arkadaşı bugün cevap veremiyor. Ayşe gönderdiği soruyu ve yaşadığı hayal kırıklığını ayrı ayrı kaydediyor; henüz gelmeyen bir görüşü gelmiş gibi yazmıyor."},instructions:["Gerçekten değer verdiğin bir şeyi ve nedenini yaz; yaşadığın zorluk da görünür kalsın.","Bugünkü yararlı işi seç; olası bir engel için “Şu olursa şunu yapacağım” de.","O işi dene; yarın ne yaptığını ve varsa gelen yanıtı değerlendir."],action:["Belirli bir konuda görüş isteyen mesaj gönder","Birine verdiği somut destek için teşekkür et"],minimum:["Başvurun hakkında tek bir yorum iste","Belirli bir yardım için teşekkür mesajı gönder"],cue:["Kahvaltı bittikten sonra","Şükran günlüğündeki yazıyı bitirince"],place:["Mesajlaştığımız yerde","Mutfak masasında"],obstacle:"Yardım eden kişi telefonda konuşamıyor",fallback:["Tek bir konuda kısa bir soru sor","Bakabilecek başka bir kişiyi seç"],observation:["Gönderdiğim istek ve varsa gelen yanıt","Dürüstçe yazdığım takdir ve zorluk"],stopRule:"Kendini minnettar olmaya zorlama. Sıkıntı sürüyorsa bir günlüğün ötesinde desteği hak ediyorsun.",scenario:"Ayşe arkadaşının desteğine değer veriyor, ama başvurusu reddedildiği için üzgün. Arkadaşı mesajla tek bir somut soruya cevap verebileceğini söyledi.",question:"Bu durumda hangi günlük yazısı ve adım uygun?",options:[{key:"positive",text:"Bugün yalnızca destek gördüğü anları yazsın; ret yanıtını incelemeyi kendini daha minnettar hissettiği zamana bıraksın.",feedback:"Değer verdiği destek yazıda kalabilir. Ama takdir etmek, somut bir sorunu ertelemesini gerektirmez. Arkadaşı bir soruya cevap vermeye hazır. Ayşe reddedilmenin canını acıttığını kabul ederken işe yarayan bir soru da sorabilir."},{key:"both",text:"Desteği ve hayal kırıklığını yazsın; sonra hangi giriş cümlesinin sonraki başvuruyu daha açık kılacağını sorsun.",feedback:"Bu seçim, şükranı yaşanmış bir olaya dayandırıyor ve arkadaşının sunduğu desteği kullanıyor. Gönderdiği mesaj bir istek; henüz görüş almış değil. Yarın varsa gelen yanıtı kaydedip neyi düzelteceğine karar verebilir."},{key:"future",text:"Gelecek iş teklifi gelmiş gibi teşekkür yazsın; görüş istemeden önce bu yazıyı yeniden okusun.",feedback:"Geleceğe dönük bu tarif, yöntemi uygulayanların ritüelidir. Kaynak gösterilen derlemelerde test edilen şükran uygulaması değildir. Bir teklifin geldiğini gösteremez. Gerçek bir desteği takdir etmek ve somut bir soru sormak, günlüğü olan bitene bağlı tutar."}],best:"both",takeaway:"Gerçek olana değer ver. Zorluğu ve atacağın sıradaki yararlı adımı da görünür tut.",review:"Neye değer verdin, hangi işi denedin ve birinden yanıt geldi mi?",deeper:[{heading:"Yaygın şükran günlüğü tarifi",paragraphs:["1. Bir defter veya her zamanki yazma aracını aç. 2. Değer verdiğin bir şeyi söyle. 3. Senin için neden anlamlı olduğunu anlat. 4. İstersen başka bir madde ekle. 5. Seçtiğin bir zamanda yazdığını yeniden oku. Uygulayan bir kişinin kendi anlatısı, nedenleri yazma ve yeniden okuma biçimini tarif ediyor. Manifestasyon uyarlamaları, gelecekte olmasını istediğin bir şey için şimdiden teşekkür etmeyi ekleyebilir. Bu, alınmış bir yardıma değer vermekten farklı bir iddiadır. [manifest-P10]","ODA için sıradan bir ayrıntı yeter: işe yarayan bir cevap, paylaşılan bir araç veya dinlendiğin bir an. Her sorunun karşısına olumlu bir madde bulman gerekmez. Ret yanıtı, erişemediğin bir imkân veya hayal kırıklığı bugün senin için önemliyse, onu takdir ettiğin şeyin yanına yaz. Mevcut hedefine uyan yararlı bir iş seç. Günlük yazısı düşünmeye yarar; birine teşekkür etmek veya istek göndermek ayrı bir iştir. Ne yazmak ne de bir istekte bulunmak yanıtı garanti eder."]},{heading:"Küçük ortalama yararlar, sınırlı karşılaştırmalar",paragraphs:["Davis ve arkadaşları, şükran uygulamalarının bazı kontrol gruplarına göre iyi oluşta küçük ortalama yararlar sağladığını buldu. Şükran, iyi oluş açısından psikolojik olarak etkin diğer uygulamalardan daha iyi sonuç vermedi; kaygıyla ilgili bulgular da kesin değildi. Cregg ve Cheavens, depresyon ve kaygı belirtilerini birlikte değerlendirdiğinde mütevazı ortalama değişimler buldu. Bekleme listesine karşı etkiler, etkin kontrol uygulamalarına karşı etkilerden daha büyüktü. Ayrı kaygı analizinin sonucu kesin değildi. Bu bulgular ideal bir günlük sıklığı, kesin rahatlama veya şükranın yeterli tedavi olduğunu göstermez. Evrene teşekkür ederek gelecekteki olayları gerçekleştirmeyi de test etmez. [manifest-T09, manifest-T10]","ODA buna pratik bir plan ekler, ama onu araştırmada test edilen uygulama diye sunmaz. Hedefini belirli tut, bugünkü engeli söyle ve “Şu olursa şunu yapacağım” planı seç. Yardım eden kişi arayamıyorsa bunun yerine tek bir somut soruyu mesajla gönder. Bugün dene, yarın değerlendir. İsteğini gelen yanıttan ayrı yaz; hayal kırıklığın da kayıtta kalabilsin. Şükran yazısı zorlama geliyorsa atlayabilirsin. Yine de yararlı işi yapabilir veya destek isteyebilirsin."]}],sources:["manifest-P10","manifest-T09","manifest-T10"]},{number:16,technique:"Olmuş gibi davranma",title:"Olmuş gibi davran: önce örnek iş, sonra yeni kıyafet",goal:"Olmak istediğin kişi gibi, bütçene uyan tek bir davranış dene.",hook:"Kendini profesyonel hissetmek istiyorsun. Yeni kıyafet almadan önce örnek bir çalışma hazırlamaya ne dersin?",reason:"Başka ihtiyaçlara ayırdığın parayı harcamadan hangi davranış hedefini yansıtabilir?",paragraphs:["Olmuş gibi davranma yönteminde, istediğin sonuca ulaşmış kişi gibi davranırsın. Buna istediğin kimliği davranışında yaşatmak da denir. O kişiyi seçer, günlük düzenini hayal eder, sonra bazı davranışlarını veya sembollerini benimsersin. Bulgular karışık: belirli hedefler ve geri bildirim performansı destekleyebilir. Sonuç kesinleşmiş gibi davranmanın onu hayatına çektiği gösterilmedi. Manifestasyon inancıyla ilgili anketler bazı maddi risklerle ilişki buldu; inancın bunlara neden olduğunu kanıtlamadı.","ODA uyarlaması: kimliğini prova et, ama yapabileceğin ve bütçene uyan bir davranış seç. Belirli hedefini, engeli ve “Şu olursa şunu yapacağım” planını yaz. Profesyonel biri yararlı bir örnek çalışma hazırlayabilir veya açık bir soru sorabilir. Bugün tek bir iş yap; yarın değerlendir. Sembol satın almak isteğe bağlıdır. Başka bir kişinin kabul edip etmemesi kendi kararıdır."],example:{title:"Mert istediği işi deniyor",text:"Mert serbest çalışan bir analist olmak istiyor. Pahalı bir ofis sandalyesi almayı düşünüyor, sonra bunun yerine örnek hesap tablosunu düzeltmeyi seçiyor. Öğle yemeğinden sonra bir hesabı kontrol edip açıklama ekliyor. Yazılıma erişemezse kullanabildiği ücretsiz bir araçla çalışacak. Örnek çalışması daha anlaşılır oldu; henüz bir müşterisi yok."},instructions:["Olmak istediğin kişiyi düşün; onu yansıtan somut ve bütçene uyan bir davranış seç.","Engel için “Şu olursa şunu yapacağım” de; başkasının vereceği karar konusunda söz verme.","Bugün o davranışı dene; yarın ne yaptığını ve ne harcadığını değerlendir."],action:["Örnek bir çalışmayı geliştir","Müşteriye tek bir somut soru sor"],minimum:["Açıklamalı bir örnek hesabı kaydet","Proje hakkında bir açıklama sorusu gönder"],cue:["Öğle yemeği bittikten sonra","Örnek çalışma dosyasını açtığımda"],place:["İş masamda","Örnek hesap tablomda"],obstacle:"Planladığım araca erişemiyorum",fallback:["Erişebildiğin ücretsiz bir araç kullan","Açıklamayı bir metin dosyasına yaz"],observation:["Ürettiğim iş ve gerçekten harcadığım para","Örnek çalışmada kaydettiğim değişiklik"],stopRule:"Bütçenin sınırlarını koru. Belirsiz bir geliri veya başkasının rızasını kesinleşmiş kabul etme.",scenario:"Mert serbest çalışmak istiyor, ama henüz kesinleşmiş bir müşterisi yok. Ücretli bir araç almak temel ihtiyaçları için ayırdığı parayı harcatacak. Erişebildiği ücretsiz araç ise örnek çalışmayı yapmaya yeterli.",question:"Bugün hangi iş, istediği mesleğe en uygun adım olur?",options:[{key:"sample",text:"Elindeki araçla örnek bir çalışmayı geliştirsin, değişikliği kaydetsin ve temel ihtiyaçlarına ayırdığı parayı korusun.",feedback:"Bu seçim, istediği kimliği bütçesine uyan bir davranışa ve inceleyebileceği bir sonuca dönüştürüyor. Müşteri kazandığını göstermez, ama Mert’in paylaşabileceği işi geliştirir. Temel ihtiyaçların parası, sonucu belirsiz bir sembole gitmek zorunda değil."},{key:"purchase",text:"Çalışma ortamı olmak istediği profesyonele benzesin diye ücretli aracı şimdi satın alsın.",feedback:"Bir araç, iş onu gerektiriyorsa ve maliyeti bütçeye uyuyorsa yararlı olabilir. Burada ücretsiz araç işi yapabiliyor. Satın almak ise temel ihtiyaçların parasını azaltacak. Kimliğini prova etmek, gelecekte gelir alacağını kanıtlamaz."},{key:"wait",text:"Belirsiz bir sonuca çaba harcamamak için, örnek çalışma hazırlamadan önce kesinleşmiş bir müşterisi olmasını beklesin.",feedback:"Parayı korumak akıllıca. Ama elindeki imkânlarla küçük bir örnek çalışma hazırlayabilir. Kesinlik beklemek bu uygun maliyetli denemeyi de engelliyor. Yapabileceği kadar çabaya bir sınır koysun ve örnek çalışmanın hangi düzeltmeye ihtiyacı olduğunu incelesin."}],best:"sample",takeaway:"Bütçene uyan davranışı dene. Olmak istediğin kişiyi, harcamayı ve başkalarına bağlı sonuçları ayrı tut.",review:"Hangi davranışı denedin, neye mal oldu ve hangi sonuç gerçekten belli?",deeper:[{heading:"Yaygın kimlik provası tarifi",paragraphs:["1. İstediğin durumu veya olmak istediğin kişiyi seç. 2. O kişinin sıradan bir günü nasıl geçirdiğini hayal et. 3. O hayatla ilişkili davranışlar, eşyalar veya rutinler seç. 4. İstediğin değişim gerçekleşmiş gibi davran. 5. Provanın sana nasıl hissettirdiğine bak; istersen yeniden dene. Yöntemi uygulayan bir kişi, işi kesinleşmiş gibi kıyafet ve valiz hazırladığını anlatıyor. Sonradan aldığı teklif bir kişinin hikâyesidir; kontrollü bir karşılaştırma değildir. [manifest-P11]","ODA rol provasını korur; bütçene uyan, yapabileceğin bir iş seç. Örnek çalışma hazırlamak, toplantıya gündemle gelmek veya açık bir soru sormak mevcut hedefine uyabilir. Pahalı eşyalara sahip olmak o rolü denemenin koşulu değildir. Başka biri rıza vermiş veya henüz karar vermeyen bir işveren seni işe almış gibi davranma. Olası gelecek, ilerlemek istediğin yönü gösterir. Şimdiden elinde olan bir kaynak değildir; bugünkü imkânların yerine kullanılamaz."]},{heading:"Hedefin geri bildirime ve gerçek imkânlara ihtiyacı var",paragraphs:["Hedef koyma kuramı, belirli ve zorlayıcı hedeflerin kararlılık, geri bildirim, beceri ve işin karmaşıklığı hesaba katıldığında performansı nasıl destekleyebildiğini anlatır. Bir kimliği benimsemenin tek başına istenen sonucu verdiğini göstermez. Dixon ve arkadaşları, manifestasyon inancıyla kişinin kendi bildirdiği bazı maddi riskler ve iflas arasında ilişki buldu. Neden sonuç ilişkisini göstermedi. Özgüven veya kendini başarılı görmek, gelirin gerçekten eline geçmiş olmasıyla aynı şey değildir. [manifest-T11, manifest-T13]","ODA sembolden önce bir davranış seçer. Bugünkü işin somut çıktısını, elindeki zamanı ve araçları söyle. Yazılıma erişememek gibi olası bir engel için ne yapacağını planla; en küçük adım bütçene uysun. Bugün dene, yarın değerlendir. Ürettiğin işi, varsa masrafı ve başkasından gelen yanıtı ayrı yaz. Bir satın alma veya söz verme, başarı zaten gelmiş varsayımına dayanıyorsa yolu yeniden düşün. Kimliği eyleme bağlayan bu düzen bir uyarlamadır. Kaynak gösterilen araştırmalar bunu bir “olmuş gibi davranma” uygulaması olarak test etmedi."]}],sources:["manifest-P11","manifest-T11","manifest-T13"]},{number:17,technique:"Gelecekteki kendinden gelen bir mektup",title:"Gelecekteki senden mektup: zor geçen salıyı da yaz",goal:"Gelecekteki senden gelen mektuptan bu hafta yapabileceğin bir iş çıkar.",hook:"Gelecekteki senin hayatı daha sakin. Peki iki işin aynı güne sıkıştığı zor bir salıyı nasıl atlattı?",reason:"Hangi gelecek için bu hafta bütçene uyan bir adım atmak istiyorsun?",paragraphs:["Bu mektupta, gelecekteki senin bugünkü sana yazdığını hayal edersin. Bir gelecek tarihi seçer, hayatı ve değişimleri anlatır, cesaret veren sözler yazar ve yeniden okursun. Bulgular karışık: gelecekteki en iyi hâlini hayal edip yazmaya dayalı benzer araştırmalar, iyi oluşta ve iyimserlikte ortalama yararları destekliyor. Gelecekten mesaj geldiğini veya hedefe kesin ulaşılacağını göstermiyor. Araştırmadaki gelecek hayali, o hayata ulaşmak için çalışmayı da içeriyor.","ODA uyarlaması: mektubun sesi kalsın; çabayı, yardımı ve zor geçen sıradan bir günü de yaz. Belirli hedefini, bugünkü engeli ve “Şu olursa şunu yapacağım” planını söyle. Bugün tek bir iş seç, yapabileceğin bir fırsatı kaydet. Somut planlama araştırmayla destekleniyor; bu mektup ve plan birleşimi bir uyarlama. Yarın gelecek tahmininin çıkıp çıkmadığını değil, kendi denemeni değerlendir."],example:{title:"Ece sıradan günü yazıyor",text:"Ece’nin gelecek mektubu daha düzenli bir iş haftasını anlatıyor. İşler çakıştığında öncelikleri nasıl sorduğunu da yazıyor. Bugün iş e-postalarını açınca hangi işin önce yapılacağını soran bir mesaj gönderiyor. Yöneticisine ulaşamazsa ekip yazışmasını kullanacak. Yanıt hemen gelmiyor. Kaydında bir istek ve henüz çözüme kavuşmamış bir iş yükü var."},instructions:["Gelecekteki senin ağzından yaz; çaba, yardım ve sıradan bir engel de olsun.","Bugünkü işi ve belirli başlama anını seç; yapabileceğin bir “Şu olursa şunu yapacağım” planı ekle.","En küçük adımı dene; yarın gerçekte ne olduğuna dair kaydına bak."],action:["İş önceliği hakkında bir soru gönder","Yapabileceğin bir çalışma zamanı ayır"],minimum:["Durumu netleştirmek için bir soru gönder","Uygun bir çalışma zamanını kesinleştir"],cue:["İş e-postalarımı açtığımda","Akşam yemeği masası toplandıktan sonra"],place:["Ekip yazışmasında","Mutfak masasında"],obstacle:"İhtiyacım olan kişiye ulaşamıyorum",fallback:["Kararlaştırılmış ekip yazışmasını kullan","Çalışma için başka uygun bir zaman seç"],observation:["Gönderdiğim soru ve varsa gelen yanıt","Gerçekten kesinleştirdiğim çalışma zamanı"],stopRule:"Mektup baskı yaratıyorsa daha yakın veya daha az zorlayıcı bir geleceği seç. Ara verebilirsin.",scenario:"Ece’nin gelecek mektubu dengeli bir iş haftası vaat ediyor. Bugün iki acil iş çakışıyor. Yöneticisi, açıklama gereken soruları ekip yazışmasında sorabileceğini söyledi.",question:"Mektuba hangi ayrıntıyı eklemek işe yarar?",options:[{key:"calendar",text:"Bugünkü acil işlerden hangisinin önce yapılacağını sormadan, ideal haftasının eksiksiz takvimini anlatsın.",feedback:"Takvim, daha sonraki seçimlere yol gösterebilir. Ama bu öncelik çatışmasını tek başına çözemez. Ece’nin açıklama isteyebileceği bir yol var. O fırsatı kullansın; henüz cevaplanmayan soruyu da görünür tutsun. Hayal edilen takvim bir yanıtın yerine geçmez."},{key:"certainty",text:"Geleceğe güvenmekle ilgili daha güçlü sözler eklesin; iş yükü gözünde daha hafif görünene kadar beklesin.",feedback:"Cesaret veren sözler iyi gelebilir. Ama başka türlü hissetmeyi beklemek, iki acil işi de aynı anda bekletiyor. Kısa bir açıklama sorusu sorması zaten mümkün. Mektup yanıtı tahmin etmeden bu adımı atmasına yardım etmeli."},{key:"request",text:"Zor günlerde öncelikleri nasıl sorduğunu yazsın; sonra kararlaştırılmış ekip yazışmasından tek bir açıklama sorusu göndersin.",feedback:"Bu seçim, gelecek sahnesine bugünkü engele uyan bir davranış ekliyor. Mesajı göndermek Ece’nin yaptığı iş. Yanıt gelene kadar cevap belli değil. Yarın isteğini değerlendirip sıradaki adımını seçebilir; mektubun gerçekleştiğini varsayması gerekmez."}],best:"request",takeaway:"Gelecekteki senin sesi, bugün yapacağın somut işi ve ihtiyaç duyabileceğin desteği açıkça anlatsın.",review:"Mektuptaki hangi adımı denedin? Hangi yardım veya sonuç hâlâ belli değil?",deeper:[{heading:"Yaygın mektup biçimi",paragraphs:["1. Hayatından gelecekteki bir zaman seç. 2. Kendini o zamanki hâlinle hayal et. 3. Bugünkü kendine bir mektup yaz. 4. Nelerin değiştiğini ve sıradan hayatının nasıl hissettirdiğini anlat. 5. Cesaret veren sözler veya öğütler ekle, sonra mektubu yeniden oku. Uygulayıcı kaynağı, gelecekten bugüne konuşan bu sesi ve kendine şefkatli yaklaşımı belgeliyor. Tarihler ve hitaplar mektup biçimiyle ilgili seçimlerdir; bilimsel olarak gerekli olduğu gösterilmiş öğeler değildir. [manifest-P12]","ODA’da istediğin geleceği yaz; ama bunu bir mesaj veya tahmin olarak sunma. Sıradan bir zorluğu, gereken çabayı ve isteyebileceğin yardımı ekle. Daha sakin bir iş haftası için daha çok emin hissetmek yerine öncelikleri konuşmak gerekebilir. Gelecekteki yönünü, kursta denediğin işe bağla. Yarın yine aynı gerçek imkânlarla uyanacak kişi için yapılabilir bir adımın altını çiz. Uzak geleceği düşünmek yük geliyorsa daha yakın bir gelecekten yazabilirsin. Mektup baskı yaratmak zorunda değil."]},{heading:"Umut veren yazı bugüne bir yol açsın",paragraphs:["Gelecekteki en iyi hâlini hayal edip yazmaya dayalı çalışmaların meta-analizi, kontrol gruplarıyla karşılaştırıldığında iyi oluş, iyimserlik ve olumlu duygularda ortalama yararlar buldu. Örneklemler çoğunlukla genç öğrencilerdi. Hiçbir araştırma bütün kalite ölçütlerini karşılamadı. Hayal edilen gelecek, ona ulaşmak için çalıştıktan sonraki hayatı anlatır. Bulgular mektupların dış dünyadaki olayları tahmin ettiğini veya gerçekleştirdiğini göstermiyor. Ayrı olarak, “Şu olursa şunu yapacağım” araştırmaları belirli bir anı yapabileceğin davranışla eşleştirmeyi destekliyor. İki kaynak da bu mektup düzenini aynen test etmedi. [manifest-T08, manifest-T02]","ODA mektubu tek bir adım seçmek için kullanır. Belirli hedefini söyle, bugünkü işe en yakın engeli bul ve “Bu olursa…” diye başlayıp yapabileceğin şeyi yaz. Başlama anını, yeri ve en küçük adımı kaydet. Sonra bugün veya seçtiğin sonraki fırsatta dene. Yarın gerçekte ne olduğuna bak: bir istek, bir iş, bir gecikme veya ara verme olabilir. Diğer kişi yanıt vermediyse cevabı belirsiz bırak. Hayal ettiğin geleceği bugünün kanıtı saymadan sıradaki adımı değiştir."]}],sources:["manifest-P12","manifest-T08","manifest-T02"]},{number:13,technique:"Yastık yöntemi",title:"Yastık yöntemi: notuna sabah yapacağın bir iş ekle",goal:"Yatmadan önce yazdığın dilek notunu koru, uyanıkken yapacağın bir işe bağla.",hook:"Yatarken yine aynı dileği mi düşünüyorsun? Yastığının altındaki notuna yarın yapacağın küçük bir iş ekle.",reason:"Planı gündüz yapmak uykuya daha çok yer bırakır mı?",paragraphs:["Yastık yönteminde yazdığın dileği yastığının altına koyarsın. Yaygın tarif şöyle: Dileğini olmuş gibi yaz, kâğıdı katla, yastığın altına yerleştir. Sonra uyumadan önce cümleyi tekrarla ya da istediğin sonucu hayal et. İncelenen kanıtlar, bu kâğıdın dış dünyada istediğin sonucu sağladığını desteklemiyor. Notta yazan bir dilek, gerçekleştiği doğrulanmış bir olay değildir. [manifest-P08, manifest-T19]","ODA'da notu koruyabilirsin. Yanına açık bir hedef ve karşına çıkabilecek bir engel ekle. Belirli bir durum olunca hangi işi yapacağını da yaz. Bu tür somut planlar araştırmalarla destekleniyor; yatma saatine özgü bir çekim etkisi desteklenmiyor. Bugün yararlı bir iş yap, yarın ne olduğunu değerlendir. Plan yapmak seni uyanık tutuyorsa kalan kısmı gündüze bırak. [manifest-T02, manifest-T19]"],example:{title:"Sabah gönderilecek mesaj",text:"Merve mutfak masasında iş dileğini yazıp bir ilana uygun başvuru gönderiyor. Yastık altına koyduğu nota şunu ekliyor: Kahvaltı bulaşıklarını kaldırınca uygun bir yeni ilanı kontrol edeceğim. Ertesi sabah ilana bakıp başka bir başvuruya başlıyor. Başvuruya daha fazla ayrıntı eklemesi gerekiyor. Merve gönderdiği başvuru ile bitmemiş taslağı ayrı yazıyor; henüz hiçbir işverenden yanıt gelmedi."},instructions:["Notun kalsın; yatağa yerleşmeden önce hedefini ve olası engeli de yaz.","Belirli bir durum olunca ne yapacağını yaz, bugün yararlı bir iş yap.","Yarın denediğin işi değerlendir; yastık ritüeli ile yaptığın işi ayrı tut."],action:["Bir ilana uygun başvuru gönder","Tanıdığına iş imkânı sor"],minimum:["Uygun bir başvuruyu gönder","Belirli bir soru gönder"],cue:["Kahvaltı bulaşıklarını kaldırınca","Bugünkü öğle molasından sonra"],place:["Mutfak masasında","Her zamanki çalışma yerimde"],obstacle:"Yatmadan plan yapınca uykum kaçıyor",fallback:["Yarın öğle molasında plan yap","Gündüz kullanacağın bir not yaz"],observation:["Başvuru gönderildi; yanıt henüz bilinmiyor","Soru gönderildi; varsa yanıt ayrı yazıldı"],stopRule:"Ritüel uykunu geciktiriyorsa dur. Plan yapmayı gündüze bırak; yatarken cümleyi tekrarlaman gerekmiyor.",scenario:"Merve'nin notunda sabah uygun bir ilan hakkında soracağı soru var. Yarın ne zaman soracağı zaten belli. Ama yatarken notu yeniden yazdığı için uykusu kaçıyor.",question:"Bu gece ne yapmalı?",options:[{key:"a",text:"Notu bir kez daha yazıp ilanla ilgili sorunun hâlâ içine sinip sinmediğine yarın karar vermeli.",feedback:"Bir kez daha yazmak, gereken yeni bir ayrıntı eklemeden uykusundan çalıyor. Soruyu ne zaman soracağı zaten belli. Planladığı soruyu koruyabilir, başka bir düzeltme gerekiyorsa onu gündüz yapabilir."},{key:"b",text:"Notu olduğu gibi bırakıp uyumalı, sabah planladığı an gelince açık pozisyon hakkında sorusunu sormalı.",feedback:"Böylece hem uykusunu koruyor hem yapacağı işi unutmuyor. Yarın soruyu gönderip göndermediğini yazabilir. İşverenden gelecek yanıtı ise kendi yaptığı işten ayrı değerlendirmeli; soru göndermek, yanıt almakla aynı şey değil."},{key:"c",text:"Sabah soruyu sormak yerine gündüz daha uzun süre işverenden gelecek yanıtı gözünde canlandırmalı.",feedback:"Uzun uzun plan yapmak için gündüz daha uygun. Ama bu seçim, yapabileceği yararlı bir işin yerine geçiyor. Yanıtı hayal etmek mesajı göndermiyor ve işverenin nasıl karar vereceğini de göstermiyor."}],best:"b",takeaway:"Yastık notun kısa olsun; yapacağın iş için uyanık olduğun bir an seç.",review:"Notu yazdıktan sonra hangi işi denedin? Yatarken plan yapmak uykunu etkiledi mi?",deeper:[{heading:"Yastık yönteminin yaygın tarifi",paragraphs:["1. İstediğin sonucu seç ve sanki şu anda gerçekmiş gibi bir cümle yaz. Örneğin, beklediğin teklifin geldiğini hayal ederek yazabilirsin. Bu, yöntemi anlatan kişinin tarifindeki bir adım. Cümle, doğrulanmış bir haberi değil senin dileğini anlatıyor. Yazdığını kimseyle paylaşmak zorunda değilsin; not sana özel kalabilir. [manifest-P08]","2. Kâğıdı katla ve yastığının altına koy. Rehberde nasıl yazılacağı ve katlanacağı hakkında başka ayrıntılar da var. Bunlar yazarın kendi tarifine ait; dış dünyada sonuç almak için gerekli oldukları gösterilmiş değil. Elinde bulunan sıradan bir not kâğıdı yeterli. [manifest-P08]","3. Yatağa yerleşirken cümleyi oku ya da içinden tekrarla. Bu kısmı seviyorsan dileğin gerçekleşmiş gibi hayal edebilirsin. Ardından uyumana izin ver. Bırakmak için görüntünün çok canlı olması, cümleyi tekrar tekrar söylemen ya da belirli bir duyguyu yakalaman gerekmiyor. [manifest-P08]","4. İstersen başka bir akşam nota tekrar bak. Rehber, insanların kullandığı bir ritüeli anlatıyor; işe yaradığını gösteren kontrollü bir araştırma değil. Uyanıklıkla ilgili beyin devrelerini ele alan derleme de yatarken tutulan dileklerin sorgulayıcı düşünmeyi devre dışı bıraktığını ya da dış dünyada olayları gerçekleştirdiğini göstermiyor. [manifest-P08, manifest-T19]"]},{heading:"Notuna uyanıkken yapacağın bir iş ekle",paragraphs:["Yatağa girmeden önce nota küçük, uygulanabilir bir talimat ekle. Hedefini açıkça yaz; karşına çıkmasını beklediğin engeli ve yapabileceğin işi belirt. İş arıyorsan şöyle olabilir: 'Kahvaltı masası kalkınca uygun bir başvuruyu göndereceğim. Formu anlayamazsam işe alım sorumlusuna belirli bir soru soracağım.' İş teklifi gibi sonucu henüz bilinmeyen şeyleri, senin yapacağın başvurudan ayrı tut. [manifest-T02]","Gollwitzer ve Sheeran'ın birçok araştırmayı bir araya getiren incelemesinde, belirli bir durum olunca ne yapılacağını söyleyen planlar farklı ortamlarda hedefe ulaşmaya ortalama olarak katkı sağladı. İnceleme, yastık altındaki kâğıdı test etmedi; plan yapmanın çaba gereksinimini kaldırdığını da göstermedi. Uyanıklık derlemesi ise birlikte çalışan beyin devrelerini anlatıyor, dilekleri gerçekleştiren bir bilinçaltı yolunu değil. Bunlar birbirinden ayrı iddialar. [manifest-T02, manifest-T19]","Bugün işi denemek ve yarın değerlendirmek, ODA'nın uygulamaya eklediği pratik tercihler. Birlikte test edilmiş bir yatma rutini değiller. Neyi gönderdiğini, sorduğunu ya da tamamladığını yaz; gelen yanıtı ayrıca belirt. Notu düzeltirken uykun kaçıyorsa bırak ve gündüz uygun bir fırsat seç. Yapacağın yararlı iş, ritüeli bitirmiş olmana bağlı değil. [manifest-T02, manifest-P08]"]}],sources:["manifest-P08","manifest-T02","manifest-T19"]},{number:14,technique:"Fısıltı yöntemi",title:"Fısıltı yöntemi: söyleyebileceğin bir isteğin provasını yap",goal:"Hayalindeki konuşmayı, bugün senin yapabileceğin açık ve saygılı bir isteğe dönüştür.",hook:"Mesajına yanıt mı bekliyorsun? Fısıltı ritüelini kullanarak sıradaki adımını sen seçebilirsin.",reason:"Saygılı biçimde dile getirebileceğim bir isteğim var mı?",paragraphs:["Fısıltı yönteminde başka birine bir isteğini söylediğini hayal edersin. Yaygın tarif şöyle: Rahatla, o kişiye yaklaştığını düşün, istediğini üç kez kulağına fısılda ve hayalindeki sahneden ayrıl. İncelenen kanıtlar, bu yolla uzaktaki birinin sana yanıt vermesini sağlayabildiğini desteklemiyor. Karşı tarafın rızası ve koyduğu sınırlar hâlâ geçerli; hayalinde konuşman bunları değiştirmiyor. [manifest-P09]","ODA'da fısıltı sana özel kalabilir. Belirli bir hedef seç ve önündeki engeli yaz. Karşı tarafın hayır diyebilmesine de yer bırakarak saygılı bir isteğin provasını yap. Belirli bir durum olunca ne yapacağını planla, bugün uygun bir istekte bulun ve yarın kendi yaptığını değerlendir. Bu tür planları araştırmalar destekliyor. Başkasının yanıtından emin olman, onun kabul edeceğine dair kanıt değil. [manifest-T02, manifest-T13]"],example:{title:"Üstelemeden sormak",text:"Can öğle molasında bir proje görüşmesi isteğini fısıldadığını hayal ediyor. Sonra bunu gönderebileceği bir cümleye çeviriyor: 'Perşembe günü on dakika konuşabilir miyiz?' İş arkadaşı perşembe günü boş zamanı olmadığını söylüyor. Can mesajı ve hayır yanıtını yazıp gelecek haftanın uygun olup olmadığını soruyor. Can'ın yaptığı ritüel, arkadaşını kabul etmek zorunda bırakmadı."},instructions:["İsteğini kendi başına, saygılı bir cümleyle fısılda; karşı tarafın hayır diyebilmesine yer bırak.","Hedefini, engeli ve ne zaman ne yapacağını yaz; bugün uygun bir istekte bulun.","Yarın ne sorduğuna ve gelen yanıtı nasıl karşıladığına bak."],action:["Kısa bir proje görüşmesi iste","Uygun zamanı öğrenmek için soru gönder"],minimum:["Açık bir görüşme isteği gönder","Konuyla ilgili bir soru sor"],cue:["Bugünkü öğle molasından sonra","Birlikte kararlaştırdığımız görüşme başlayınca"],place:["İş yerindeki masamda","Her zamanki görüşme yerimizde"],obstacle:"Basit bir isteği sürekli yeniden yazıyorum",fallback:["Sade bir istek cümlesi kullan","Kararlaştırdığımız görüşmede sor"],observation:["İstek iletildi; varsa yanıt ayrı yazıldı","Sınır gözetildi; sonraki adım seçildi"],stopRule:"İletişim kurmanı istemediğini söyleyen birine ulaşma. Kendi hayalinde canlandırdığın şey, başka birinin sınırlarını geçersiz kılamaz.",scenario:"Can görüşmek istiyor. İş arkadaşı bu hafta zamanı olmadığını söylemiş, ama gelecek hafta için sorabileceğini belirtmiş. Fısıltı çalışması Can'a güven veriyor.",question:"Elindeki bilgiye göre hangi adım uygun?",options:[{key:"a",text:"Gelecek hafta ne zaman uygun olduğunu bir kez sormalı, sonra tekrar tekrar mesaj atmadan yanıtı kabul etmeli.",feedback:"Arkadaşı gelecek hafta için sorabileceğini söyledi; açık bir soru sormak bu sınırı gözetiyor. Can isteği ve yanıtı ayrı yazabilir. İçinin rahatlaması, arkadaşının zamanı üzerinde söz hakkı olduğu anlamına gelmiyor."},{key:"b",text:"Hayalindeki konuşma tamamlanmış gibi hissettirdiği için arkadaşının bir saat önermesini beklemeli.",feedback:"Beklemeyi seçebilir, ama hayalindeki konuşmada gelecek haftayı gerçekten sormuş olmadı. Arkadaşının önerisi, uygun bir istekte bulunabileceği bir fırsat. Görüşme hâlâ işine yarayacaksa bu fırsatı kullanarak bir kez sorabilir."},{key:"c",text:"Bu haftaki görüşmenin kendisi için ne kadar değerli olduğunu daha içten bir mesajla anlatmalı.",feedback:"Daha içten bir mesaj da arkadaşından, uygun olmadığını söylediği haftayı yeniden düşünmesini istiyor. Daha güçlü duygularını üstelemek için gerekçe yapmamalı. Bunun yerine arkadaşının sunduğu gelecek hafta seçeneği hakkında sorabilir."}],best:"a",takeaway:"İsteğini prova et; karşı taraf kendi yanıtını seçer.",review:"Gerçekte hangi istekte bulundun? Karşı tarafın yanıtını veya koyduğu sınırı nasıl karşıladın?",deeper:[{heading:"Hayalde yapılan konuşmanın yaygın tarifi",paragraphs:["1. Kişiyi ve ondan almak istediğin yanıtı seç. Yöntemi anlatan kişinin tarifinde bu çalışma hayalinde yapılıyor. Bir yanıt seçmek, senin ne istediğini gösterir. Karşı tarafın ne istediğini göstermez ve onunla iletişim kurmana izin verildiği anlamına gelmez. [manifest-P09]","2. Rahatla ve o kişiyi bir yerde hayal et. Yanına yaklaşıp isteğini üç kez kulağına fısıldadığını düşün. Üç tekrar, bu tarifin bir parçası; birini etkilemek için bilimsel olarak belirlenmiş bir miktar değil. Dilersen gözlerini açık tutabilir ya da sahneyi görüntü yerine sözlerle anlatabilirsin; bu senin uyarlaman olur. [manifest-P09]","3. Hayalindeki sahneden ayrıl. Bazı tariflerde kişinin alnını öptüğünü hayal etmek de var. Bu, sahnenin başka bir ayrıntısı; uzaktan etki olduğuna dair kanıt değil. ODA'da çalışmayı kendine sakla ve gerçekten saygılı biçimde söyleyebileceğin bir istek seç. Hayalindeki yakınlığı gerçek kişinin rızası yerine koyma. [manifest-P09]","4. Gerçekte bir istekte bulunmanın uygun olup olmadığına karar ver. Bu anlatı, ritüelin nasıl yapıldığını belgeliyor; telepatiyi ya da birini kontrol edebildiğini göstermiyor. Karşı taraf hayır diyebilir, sessiz kalabilir veya fikrini değiştirebilir. İsteği tekrar tekrar fısıldamak, ona yanıt verme zorunluluğu getirmez. [manifest-P09]"]},{heading:"Konuşmada senin yapacağın kısmı planla",paragraphs:["Hedefin açık olsun: Uygun bir görüşme zamanı sormak, birinin sana hayran olmasını sağlamaktan farklı. Basit bir mesajı tekrar tekrar düzeltip geciktirmek gibi, karşılaştığında bir şey yapabileceğin bir engel seç. Sonra başlama anını belirle: 'Öğle molam bitince uygun zamanını öğrenmek için açık bir soru göndereceğim.' Karşı taraf iletişim istemiyorsa yapacağın iş, bu sınırı gözetmek olabilir. [manifest-T02, manifest-P09]","Belirli bir durum olunca ne yapılacağını planlama araştırmaları, fark edebileceğin bir durumu seçtiğin işe bağlamayı destekliyor. Mesajı alan kişiyi kontrol ettiğini göstermiyor. Dixon ve çalışma arkadaşları üç çevrimiçi anket örnekleminde, manifestasyona inanmak ile özgüven ve bildirilen bazı maddi riskler arasında ilişki buldu. Bu ilişkiler neden sonuç bağı kurmuyor; çalışma fısıltı yöntemini de test etmedi. Kendinden emin olmak, başka birinin kabul ettiğini göstermez. [manifest-T02, manifest-T13]","Kendi başına prova yapmak ve ertesi gün değerlendirmek, ODA'nın eklediği uyarlamalar. Bugün uygun bir istekte bulun veya birlikte kararlaştırdığınız fırsatı planına yaz. Yarın gerçekten ne sorduğunu, gelen bir yanıt varsa ne olduğunu ve o yanıtı gözetip gözetmediğini belirt. Sessizlik varsa sonuç hâlâ bilinmiyor. Uygun başka bir adım seçebilir ya da durabilirsin; hayalindeki konuşmayı yapılmış bir konuşma olarak sayma. [manifest-T02, manifest-P09]"]}],sources:["manifest-P09","manifest-T02","manifest-T13"]},{number:18,technique:"17 saniye odaklanma",title:"17 saniye odaklanma: süre bitince işe başla",goal:"Sevdiğin kısa arayı başlamak için kullan; süreye bilimsel bir özellik yükleme.",hook:"On yedi saniye dolmadan aklın mı dağıldı? Yine de şimdi sıradaki adımı atabilirsin.",reason:"Sayaç başlamama mı yardım ediyor, işi mi geciktiriyor?",paragraphs:["17 saniye yönteminde istediğin şeyi, ona ters düşen bir düşünce olmadan on yedi saniye boyunca aklında tutarsın. Bazı tariflerde on yedi saniyelik dört aralık kullanılır ve toplam altmış sekiz saniye olur. İncelenen kanıtlar bu sürelere özel bir çekim eşiği olduğunu desteklemiyor. Ön uyaranların davranışı nasıl etkilediğini inceleyen hazırlama araştırmaları da bu sayıları ya da bilinçli dilek ritüellerini doğrulamıyor. [manifest-P13, manifest-T16]","ODA'da on yedi saniyeyi sevdiğin bir kısa ara olarak tutabilirsin. Hedefini ve engeli açıkça yaz. Belirli bir durum olunca bugün hangi işi yapacağını planla, yarın da denemeyi değerlendir. Somut planları araştırmalar destekliyor. Düşüncen dağıldı diye süreyi yeniden başlatman gerekmiyor. Sayaç sana ne zaman başlayacağını hatırlatsın; sonuç almanın koşulu olmasın. [manifest-T02, manifest-P13]"],example:{title:"Yarım kalan odaklanma arası",text:"Ayşe öğle yemeğinden önce portfolyosu için on yedi saniyelik sayaç kuruyor. Gelen kargo düşüncesini bölüyor. Sayacı yeniden kurmadan planını uyguluyor: Yemekten sonra uygun bir müşteriye işlerinden bir örnek gönderecek. Müşteri başka bir tarz istediğini söylüyor. Ayşe yeniden odaklanma çalışmasına dönmek yerine gönderdiği mesajı ve aldığı geri bildirimi yazıyor; bunları birbirinden ayrı değerlendiriyor."},instructions:["Hedefini seç; istersen on yedi saniyelik kısa bir ara ver.","Engeli ve ne zaman ne yapacağını yaz; bugün yararlı bir iş yap.","Yarın denediğin işi ve varsa aldığın geri bildirimi birlikte değerlendir."],action:["Uygun bir iş örneği gönder","Bir taslak hakkında geri bildirim iste"],minimum:["Uygun bir örnek gönder","Geri bildirim için belirli bir soru sor"],cue:["Bugünkü öğle yemeğinden sonra","Sayaç kullanırsam, süre bitince"],place:["Her zamanki çalışma yerimde","Kütüphanedeki masada"],obstacle:"Dikkatim dağılınca süreyi baştan başlatıyorum",fallback:["Sayacı atla ve örneği gönder","Başlama anını bir nota yaz"],observation:["Örnek gönderildi; varsa yanıt ayrı yazıldı","Soru soruldu; geri bildirim henüz bilinmiyor"],stopRule:"Baştan başlamak işi geciktiriyorsa veya sıkıntı veriyorsa sayacı bırak. İstemediğin düşünceler geldi diye ritüelle düzeltmen gereken bir şey yok.",scenario:"Ayşe'nin hazır örneği müşterinin isteğine uygun. Bir bildirim odaklanma süresini böldü. Toplantıdan önce örneği göndermek için beş dakikası var.",question:"Bu fırsatı en iyi nasıl kullanır?",options:[{key:"a",text:"Bildirimleri kapatıp bir kez daha odaklanmalı, toplantıdan önce yeterli zaman kalırsa örneği göndermeli.",feedback:"Bildirimleri kapatmak sevdiği kısa arayı kolaylaştırabilir. Ama yapabileceği iş zaten belli. Kesintisiz bir süre daha odaklanmayı şart koşarsa şu anda örneği gönderebileceği fırsatı kaçırabilir; işe başlamak için bunu beklemesi gerekmiyor."},{key:"b",text:"Hem odaklanma çalışmasını hem örneği göndermeyi yarın daha uzun, kesintisiz bir zamana bırakmalı.",feedback:"Daha çok zaman isteyen bir iş için ileri bir saat seçilebilir. Burada örnek hazır ve beş dakikası var. Ritüelin yarıda kalması, gönderilecek mesajı da ertelemesini gerektirmiyor; bu süreyi örneği göndermek için kullanabilir."},{key:"c",text:"Hazır örneği şimdi göndermeli, mesajı ve yarıda kalan odaklanma arasını birbirinden ayrı yazmalı.",feedback:"Bu seçim elindeki fırsatı kullanıyor ve olanı açıkça gösteriyor. Örnek gönderildi; odaklanma arası bölündü. Bunlar ayrı olaylar. İkisi de müşterinin nasıl karar vereceğini söylemiyor; o yanıtı ayrıca beklemesi gerekiyor."}],best:"c",takeaway:"Sayaç, işe ne zaman başlayacağını hatırlatsın; başlamadan önce tamamlaman gereken bir koşul olmasın.",review:"Hangi yararlı işi denedin? Sayaç başlamana yardım mı etti, seni mi geciktirdi?",deeper:[{heading:"On yedi saniyelik tarif ne istiyor?",paragraphs:["1. Yaşamak istediğin bir deneyim veya olumlu bir düşünce seç. Esther ve Jerry Hicks aracılığıyla Abraham'a atfedilen öğreti, karşıt bir düşünce olmadan buna odaklanmanı istiyor. Bu açıklama ritüelin nasıl yapıldığını anlatıyor. Araştırmayla sınanmış bir yöntem tarif etmiyor. [manifest-P13]","2. Düşünceyi on yedi saniye aklında tut. Bazı tariflerde dört aralık art arda uygulanır; toplam süre altmış sekiz saniye olur. Tanıdık biçimi korumak istiyorsan sayaç kullanabilirsin. Ama incelenen kanıtlar, bu iki süreden herhangi birinde dileklerin gerçekleşmesini sağlayan özel bir çekim eşiği bulunduğunu göstermiyor. [manifest-P13, manifest-T16]","3. Dikkatinin dağılıp dağılmadığını fark et; bunu geleceğin hakkında bir hükme dönüştürme. ODA'da işe başlamak için süreyi yeniden başlatmak gerekmiyor. Öğretide düşüncelerin gerçekliği değiştirdiği ya da saatlerce çalışmaya denk geldiği söyleniyor. Bunlar burada incelenen araştırmaların bulguları değil. [manifest-P13]","4. Arayı bitir ve sıradaki işini seç. Deneysel hazırlama araştırmaları, belirli koşullarda sunulan uyaranların etkisini inceliyor. Bilinçli olarak süre tutup dilek düşünmekle aynı çalışma değil. Sevdiğin bir süre ritüelinin parçası olarak kalabilir; onu koruman, bu sürenin bilimsel olarak doğrulandığı anlamına gelmez. [manifest-T16, manifest-P13]"]},{heading:"Sürenin sonunu başlama anı yap",paragraphs:["Sayacı kurmadan önce bir iş seç. Portfolyo hedefi için bugün uygun bir iş örneğini göndermek olabilir. Engeli de belirt: Kusursuz odaklandığını hissedene kadar süreyi baştan başlatmak. Sonra şöyle yaz: 'Sayaç bitince, düşüncem dağılmış olsa da hazır örneği göndereceğim.' Sayaç baskı yaratıyorsa ne zaman başlayacağını hatırlatan başka bir işaret seç. [manifest-T02]","Gollwitzer ve Sheeran'ın meta-analizi, belirli bir durum olunca ne yapılacağını söyleyen planları farklı işlerde ortalama olarak destekliyor. Dai ve çalışma arkadaşlarının hazırlama derlemesi genel toplamda ortalama bir etki buldu. Ancak yöntemleri önceden kaydedilmiş çalışmaların sınırlı alt grubunda etkiler daha küçüktü ve istatistiksel olarak kesin sonuca varılamadı. Bu belirsizlik bütün hazırlama etkilerini çürütmüyor. İki derleme de on yedi saniyeyi, altmış sekiz saniyeyi veya istenmeyen düşüncelerin sonuçları engellediği kuralını doğrulamıyor. [manifest-T02, manifest-T16]","ODA'nın kısa ara verip işe başlama sırası bir uyarlama; bu iki araştırmanın uyguladığı yöntem değil. Yarın denediğin işi ve dışarıdan gelen geri bildirimi, ne kadar iyi odaklandığından ayrı yaz. Ara, sana uygun bir başlama anı sağladı mı? Yoksa tekrarlarken işi yapabileceğin zamanı mı tüketti? Gerçekte olanlara bakarak sayacı koruyabilir, süreyi kısaltabilir veya tamamen bırakabilirsin. [manifest-T02, manifest-P13]"]}],sources:["manifest-P13","manifest-T02","manifest-T16"]},{number:19,technique:"Dilek kutusu",title:"Dilek kutusu: bir dilek için bugün adım at",goal:"Dilek kutun kalsın; belirli bir hedef için yapabileceğin bir adım at.",hook:"Kutuna dilek ekleyip duruyor musun? Bugün hangi kart için bir iş yapacaksın?",reason:"Bugün zamanım ve imkânlarım hangi dileğe uygun?",paragraphs:["Dilek kutusunda yazılı dilekleri, resimleri veya senin için anlamlı nesneleri bir kapta saklarsın. Yaygın tarif şöyle: Bir kutu seç, niyetlerini ve yaşamak istediğin duyguları içine ekle. Sonra ara sıra bakıp dileklerin gerçekleştiğini hayal et. İncelenen kanıtlar, bir kabın bu dilekleri gerçekleştirdiğini desteklemiyor. Elindeki bir kutu yeterli; özel bir kutu edinmen gerekmiyor. [manifest-P14]","ODA'da kartları koruyabilirsin. Birini seçip açık bir hedef, bir engel ve o engelle karşılaşınca ne yapacağını yaz. Bugün bir iş yap, yarın gerçekten nasıl denediğini değerlendir. Hedefi engellerle karşılaştırıp ne yapılacağını planlamak araştırmalarla destekleniyor. İlerlemeyi takip etmek de ortalama olarak destek buluyor. Ama bu kutu uyarlaması, bütünüyle test edilmiş bir program değil. [manifest-T01, manifest-T03]"],example:{title:"Kutudan çıkan bir kart",text:"Emre mutfak masasında hafta sonu kursu için yazdığı kartı eski bir ayakkabı kutusuna koyuyor. Engeli yazıyor: Zamanı sınırlı. Sonra kursu düzenleyen kişiyi arayıp farklı katılım seçenekleri olup olmadığını soruyor. Kursta esnek bir seçenek yok. Ertesi gün aramayı yazıp başka bir kurs seçiyor; kutuya daha fazla dilek eklemekle yetinmiyor."},instructions:["Elindeki bir kabı kullan ve açık bir hedef içeren bir kart seç.","Engeli ve o durumda ne yapacağını yaz; bugün yapabileceğin bir iş yap.","Yarın o kartı aç, gerçekte hangi işi denediğini ve ne olduğunu yaz."],action:["Kursa katılım seçeneklerini sor","Program hakkında gereken bir ayrıntıyı sor"],minimum:["Kurs hakkında belirli bir soru gönder","İşine yarayacak bir bilgi sor"],cue:["Bugünkü kahvaltıdan sonra","Ofisin telefon hattı açılınca"],place:["Mutfak masasında","Sessiz çalışma köşemde"],obstacle:"Kursun saatleri bana uymayabilir",fallback:["Başka bir katılım seçeneği sor","Uygun başka bir yerle iletişim kur"],observation:["Soru gönderildi; varsa saatlerle ilgili yanıt yazıldı","Başka yere ulaşıldı; yanıt henüz bilinmiyor"],stopRule:"Elindeki malzemeleri kullan. Bir seçenek imkânlarını aşıyorsa yapacağın işi değiştir veya ara ver.",scenario:"Emre'nin kurs kartında saatlerin çakışması yazıyor. Kursu düzenleyen kişi bugün sorulara yanıt verebiliyor. Emre'nin kutuya eklemek istediği birkaç yeni resim de var.",question:"Kursun ona uyup uymadığını en iyi hangi adım gösterir?",options:[{key:"a",text:"Kursu düzenleyen kişiye katılım seçeneklerini sormalı, sonra gelen yanıtı kurs kartına yazmalı.",feedback:"Bu adım, yazdığı engeli kontrol etmesini ve gerçekten olanı görmesini sağlıyor. Yanıt, bu kursun uygun olmadığını gösterebilir. Bu da Emre'nin yapabileceği başka bir adımı seçmesine yarayan bir bilgi."},{key:"b",text:"Kutu, istediği deneyimin tamamını anlatsın diye önce yeni resimleri içine eklemeli.",feedback:"Resimler sevdiği ritüelin parçası olarak kalabilir. Ama kursun saatleriyle ilgili soruya yanıt vermiyorlar. Bugün elindeki fırsat, kursa katılmanın mümkün olup olmadığını sormak. Resimleri eklemek bu soruyu sormanın yerine geçmez."},{key:"c",text:"Saatler çakıştığı için bu kurs belirsiz; hemen başka bir kurs seçmeli.",feedback:"Başka bir kurs daha uygun olabilir. Ama kursu düzenleyen kişi bu belirsizliği şimdi açıklığa kavuşturabilir. Emre, hedefini değiştirip değiştirmeyeceğine karar vermeden önce belirli bir soru sorarak işe yarayan bilgi alabilir."}],best:"a",takeaway:"Dilek kartın kalsın; yapabileceğin bir iş ekle ve gerçekte ne olduğunu yaz.",review:"Kartındaki hedef için bugün hangi işi denedin? Yazdığın engel hakkında ne öğrendin?",deeper:[{heading:"Yaygın dilek kutusunu hazırla",paragraphs:["1. Bir kutu veya kap seç. Yöntemi anlatan rehber, kutuyu niyetleri saklayacağın bir yer olarak kullanıyor. ODA'da eski bir ayakkabı kutusu ya da zarf gibi, zaten elinde olan bir şeyi kullanmanı istiyoruz. Özel bir nesne satın almak bu çalışmanın parçası değil. [manifest-P14]","2. Dileklerini kartlara yaz veya onları temsil eden resimler seç. Rehberde her sonucu neden istediğin ve elde edince nasıl hissedeceğin de yazılıyor. İstersen bu kişisel ayrıntıları kendine saklayabilirsin. Sade bir başlık da kartın neyi temsil ettiğini gösterir ve yöntemin biçimini korumaya yeter. [manifest-P14]","3. Kartları veya resimleri kutuya koy. Bu ritüeli seviyorsan arada içindekilere bakıp dileklerini elde ettiğini hayal et. Bunlar yöntemi kendi deneyimiyle anlatan bir kişinin adımları. Kabın dış dünyada bir olay yarattığına dair kanıt değiller. [manifest-P14]","4. Gerçek bir fırsatta üzerinde çalışacağın bir kart seç. Rehberdeki enerji alanı açıklaması, araştırmayla ortaya konmuş bir bulgu değil, bir inanç. Simgesel kutunu koruyabilir, bugün kart için ne yaptığını değiştirebilirsin. [manifest-P14]"]},{heading:"Engeli kartın arkasına yaz",paragraphs:["Dilek veya resim ön yüzde kalsın. Arka yüze hedefini açıkça yaz; beklediğin engeli ve o durumda ne yapacağını ekle. Kurs için şöyle olabilir: 'Kurs ofisinin telefon hattı açılınca katılım seçeneklerini soracağım. Saatler bana uymuyorsa uygun başka bir kurs hakkında bilgi isteyeceğim.' Bugün yapabileceğin bir iş seç. Kart hazırlamak ile gerçekten bilgi sormak farklı işler; kartı yazmış olmayı soru sorulmuş gibi sayma. [manifest-T01]","Zihinsel karşılaştırmayı uygulama planıyla birleştirmek, istediğin sonucu gerçek bir engel ve o engelle karşılaşınca yapacağın işe bağlar. Meta-analizde hedefe ulaşmaya ortalama olarak küçük bir katkı bulundu; sonuçlar değişkendi ve yayın yanlılığı olasılığı vardı. Harkin ve çalışma arkadaşları ilerlemeyi takip etmeye teşvik etmenin ortalama yararını buldu. Bu iki derleme de dilek kutusunu test etmedi. Ertesi gün değerlendirmenin en iyi takvim olduğunu da kanıtlamadı. [manifest-T01, manifest-T03]","ODA'da ertesi gün karta dönmek, yaptığını değerlendireceğin pratik bir zaman sağlar. Gerçekte ne sorduğunu ve ne öğrendiğini yaz. Bir soruyu göndermek, yararlı yanıt almak veya kursa kaydolmakla aynı şey değil. Para, erişim veya zaman yüzünden hedef mümkün değilse onu değiştir. Kutunda yeniden yazılmış bir kart, ara verdiğin bir hedef ya da denediğin hâlde sonuç alamadığın bir iş de bulunabilir. [manifest-T01, manifest-T03]"]}],sources:["manifest-P14","manifest-T01","manifest-T03"]},{number:20,technique:"SATS: uykuya benzer hâl",title:"SATS: sahneyi bırakıp uyuyabilirsin",goal:"Sakin bir sahne hayal et, uykuyu geciktirmeden yapacağın işin provasını yap.",hook:"Yatarken kusursuz sahneyi tekrar tekrar mı kuruyorsun? Şimdi bırakıp yarın yine yararlı bir adım atabilirsin.",reason:"Bu sahneyi canlandırınca uykuya yeterince zaman kalıyor mu?",paragraphs:["SATS, yani uykuya benzer hâl, rahatlayıp uykun gelmişken dileğinin gerçekleştiği kısa bir sahne hayal etmektir. Uygulayanlar başarıya ulaşıldığını düşündüren bir sahne seçer, kendilerini içindeymiş gibi hayal eder ve gerçekmiş gibi tekrarlar. Bazıları bu sırada uyur. Araştırmanın sonucu: Benzer canlandırma çalışmalarında bulgular karışık; uykuluyken hayal kurmanın dilekleri gerçekleştirmesi desteklenmiyor. Zihinsel canlandırma davranışa ortalama olarak katkı sağlayabilir, ama yatma saatine özel bir üstünlük gösterilmiş değil. [manifest-P15, manifest-T04, manifest-T19]","ODA'da sakin bir sahne hayal edebilirsin. Hedefini ve engeli açıkça yaz; belirli bir durum olunca ne yapacağını planla. Sonra ilk uygulanabilir adımın provasını yap. Bugün bir iş yap, yarın ne olduğunu değerlendir. Sahnenin kusursuz gelmesi gerekmiyor. Tekrarlamak seni uyanık tutuyorsa dur; uyuyabilmen, ne kadar inandığını gösteren bir sınav değil. [manifest-P15, manifest-T19]"],example:{title:"Süresi sınırlı bir sahne",text:"Ece masasında bir eğitim programı hakkında soru gönderiyor. Yatmadan önce programa katıldığını kısaca hayal ediyor, sonra yarın öğle molasında ücreti sormanın provasını yapıyor. Sahneyi tekrarlayınca uykusu açıldığı için bırakıyor. Ertesi gün soruyor; program onun için fazla pahalı. Gelen ücret yanıtını ayrı yazıp ücretsiz bir seçenek arıyor."},instructions:["Uykuya hazırlanmadan önce hedefini, engeli ve ne zaman ne yapacağını bir nota yaz.","İlk adımın kısa bir provasını yap; bugün yararlı bir iş yap.","Uykuya öncelik ver; yarın gerçekte denediğin işi ve ne olduğunu değerlendir."],action:["Bir programın ücretini sor","Programa katılmak için gereken bir ayrıntıyı sor"],minimum:["Ücret hakkında belirli bir soru gönder","Katılım imkânı hakkında bir soru sor"],cue:["Bugünkü öğle molasından sonra","Programın ofisi açılınca"],place:["Her zamanki çalışma yerimde","Mutfak masasında"],obstacle:"Hayal kurarken uykum kaçıyor",fallback:["Gündüz sözlerle prova yap","Hayal kurmadan doğrudan sor"],observation:["Soru soruldu; varsa yanıt ayrı yazıldı","Uykum açıldı; canlandırmayı bıraktım"],stopRule:"Canlandırma uykunu açıyorsa veya sıkıntını artırıyorsa dur. Gündüz prova yapabilir ya da canlandırmayı atlayabilirsin; uykunu koru.",scenario:"Ece'nin gündüz ücreti sormak için açık bir planı var. Tekrarladığı SATS sahnesi onu uyanık tutuyor. Üstelik sahne hâlâ tam olarak gerçekmiş gibi hissettirmiyor.",question:"Şimdi hangi seçimi yapmalı?",options:[{key:"a",text:"Sahneyi basitleştirip yeterince inandırıcı gelene ve bırakabileceğini hissedene kadar tekrar etmeli.",feedback:"Sahneyi basitleştirmek gündüz yapılan bir provaya uygun olabilir. Ama sahnenin inandırıcı gelmesi, durmanın şartı değil. Tekrarlar onu uyanık tutuyor; devam etmek, ritüeli uykunun önüne koyuyor. Sahneyi bırakmak için bu hissi beklememeli."},{key:"b",text:"Sahneyi bırakıp uyumalı, gündüz planladığı an gelince programın ücretini sormalı.",feedback:"Ne zaman ne yapacağı zaten belli. Sahneyi bırakmak, hedeften vazgeçmeden uykusunu korumasını sağlıyor. Yarın sorduğu soruyu ve ücret hakkında aldığı bilgiyi yazabilir; bu işi yapabilmek için sahneyi tamamlaması gerekmiyor."},{key:"c",text:"Ücreti sormak yerine gündüz daha kolay yöneteceği, daha uzun bir SATS çalışması yapmalı.",feedback:"İsteğe bağlı canlandırma için gündüz daha uygun olabilir. Ama daha uzun bir sahne de ücret sorusuna yanıt vermiyor. Gerçek soruyu sorma planı kalsın; yapacağı bir prova varsa onu bu işe hazırlık olarak görsün."}],best:"b",takeaway:"Kısa sahnenin kusursuz gelmesini beklemeden bırakabilirsin; gerçekte hangi işi denediğini hayal ettiğinden ayrı yaz ve değerlendir.",review:"Gerçekte hangi işi yapmayı denedin? Sahneyi canlandırmak sana uyumak için yeterince zaman bıraktı mı?",deeper:[{heading:"SATS öğretisindeki sahne",paragraphs:["1. Bir sonuç ve bu sonucun gerçekleştiğini düşündüren kısa bir sahne seç. Neville Goddard'ın derslerinde, kendine dışarıdan bakmak yerine dileğinin gerçekleştiği sahnenin içinde yer almak anlatılıyor. Bu, öğretmenin yönteminin bir parçası. Dış dünyadaki olayları değiştirmenin kanıtlanmış bir yolu değil. [manifest-P15]","2. Rahatça otur veya uzan. İstersen gözlerini kapat, gevşe ve uykunun gelmesine izin ver. Kaynak, bu hâli uygulamanın bir parçası olarak görüyor. ODA'da gözlerin açık kalabilir veya sahneyi sözlerle anlatabilirsin. Uykunu zorla getirmeye çalışman istenmiyor. [manifest-P15]","3. Kısa sahneyi gerçekmiş gibi hayal ederek tekrarla. Bazı tariflerde bu duygu içindeyken uykuya dalınır; bazılarında hafifçe dikkatini vermeye devam edersin. Sahne inandırıcı gelmeden önce de bırakabilirsin. Hayalinde belirlediğin bir ölçüyü tutturmak için kendini uyanık tutma. [manifest-P15]","4. Metafizik iddiaları tariften ayrı tut. Uyanıklık üzerine derleme, birbiriyle etkileşen uyku ve uyanıklık devrelerini anlatıyor. Uykulu hâlin dilekleri gerçeğe dönüştürdüğüne dair kanıt sunmuyor. Goddard'ın hiçbir iş yapmaya gerek olmadığı yönündeki öğretisi de zihinsel canlandırma araştırmalarının sonucu değil. [manifest-P15, manifest-T19, manifest-T04]"]},{heading:"Uykunu koruyarak bir adımın provasını yap",paragraphs:["Uykuya hazırlanmadan önce belirli bir hedef seç ve engeli yaz. Eğitim programında hedefin, ücretin imkânlarına uyup uymadığını öğrenmek olabilir. Gerçekte soracağın sorunun kısa bir provasını yap. Yanıt, programın sana uygun olmadığını gösterirse ne yapacağını da düşün. Bu, ODA'nın pratik uyarlaması; Goddard'ın tarif ettiği duyguyu veya sahneyi aynen kurman gerekmiyor. [manifest-P15, manifest-T04]","Cole ve çalışma arkadaşlarının araştırmaları birleştiren incelemesinde, zihinsel canlandırma farklı çalışmalarda davranışa ortalama olarak katkı sağladı. Katılımcıların çoğu öğrenciydi. Canlandırma türleri arasında güvenilir bir sıralama veya yatma saatine özel bir üstünlük gösterilmedi. Uyanıklık derlemesi de uykulu olmanın düşünceyi devre dışı bıraktığını ya da dış dünyada sonuç yarattığını göstermiyor. Genel canlandırma bulguları, SATS hakkındaki her iddiayı doğrulayamaz. [manifest-T04, manifest-T19]","Gerçek soruyu sormak için gündüz bir başlama anı seç. Uygunsa bugün yararlı bir bilgi sor. Yarın soruyu ve gelen yanıtı, hayal ettiğin sahneden ayrı yaz. Sahne uykunu açıyorsa dur; gündüz prova yapmayı veya canlandırmayı bırakmayı seç. Sahneyi yarım bıraksan da sıradaki iş planında kalabilir. Bu adımların tamamı, bir SATS uygulaması olarak birlikte test edilmiş değil. [manifest-P15, manifest-T04, manifest-T19]"]}],sources:["manifest-P15","manifest-T04","manifest-T19"]}],m=T.sort((a,e)=>a.number-e.number).map(K),Y=[...u,{id:"M01",title:"Wang, Wang ve Gai · 2021 · Zihinsel karşılaştırma ve “şu olursa bunu yaparım” planları",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 makaleden 24 bağımsız etki, 15.907 katılımcı: hedefe ulaşmada mütevazı ortalama yarar, g = 0,336 [0,229, 0,443]. Yayın yanlılığı düzeltmesiyle tahmin 0,242 [0,143, 0,342] oldu.",limitation:"Sonuçlar oldukça farklıydı, yayın yanlılığı işaretleri vardı. Bu kurs ve kısa alıştırmaları sınanmadı. Sonuçlar garanti değil."},{id:"M02",title:"Gollwitzer ve Sheeran · 2006 · Belirli planlar ve hedefe ulaşma",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 bağımsız test, 8.461 katılımcı: belirli “şu olursa bunu yaparım” planları hedefe ulaşmaya ortalama destek verdi, d = 0,65 [0,60, 0,70].",limitation:"Farklı yöntemlerle yapılmış, eski tarihli çalışmalar. Hepsi önceden kayıt altına alınmış değildi. Planlar çabayı, hatırlamayı, somut kısıtları veya belirsizliği ortadan kaldırmaz."},{id:"M03",title:"Harkin ve arkadaşları · 2016 · Hedefte ilerlemeyi izlemek",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 deneyde toplam 19.951 katılımcı vardı. Hedefe ulaşma analizinde 18.398 kişi: d = 0,40 [0,32, 0,48]. Küçük çalışmalar için duyarlılık düzeltmesi 0,19 [0,10, 0,28] tahmini verdi.",limitation:"Hedefler ve uygulamalar farklıydı. Çalışmaların özellikleriyle etki büyüklükleri arasındaki ilişkiler, herkese açık paylaşımın gerekli olduğunu göstermez. Bu kayıt biçimi, değerlendirme zamanı veya ODA kursu doğrulanmadı."},{id:"M04",title:"Cole ve arkadaşları · 2021 · Zihinde canlandırma ve davranış değişikliği",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 çalışma, 123 etki, 5.685 katılımcı: zihinde canlandırmanın genel etkisi g = 0,49 [0,37, 0,62]. Türlerin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı.",limitation:"Çoğunlukla öğrencilerle, farklı canlandırmalar incelendi. Yalnızca süreç canlandırması beş etki içeriyordu; tahmin kesin değildi. Güvenilir bir tür sıralaması veya bu kısa alıştırmanın doğrulaması yok."},{id:"M07",title:"Dixon, Hornsey ve Hartley · 2025, çevrim içi 2023 · Manifestasyon inancı",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Üç ABD çevrim içi anketi, 1.023 katılımcı: manifestasyon inancı bazı mali risk bildirimleri ve bildirilen iflasla ilişkiliydi. Bildirilen gelir veya eğitimle ilişki bulunmadı.",limitation:"İlişki neden-sonucu göstermez, her manifestasyon tekniğini nesnel olarak sınamaz. Kişinin bildirdiği mali sonuçlar, tek bir kişinin geleceği için tahmin değildir."},{id:"M10",title:"Gollwitzer ve Brandstätter · 1997 · Belirli bir başlama fırsatı seçmek",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/gollwitzer_brandstatter_1997_-_implementation_intentions_effective_goal_pursuit.pdf",type:"research",finding:"İkinci çalışmada 86 öğrenciden rapor yazmaları istendi. Raporunu geri veren, kimliği belirlenebilen 36 kişi içinde, plan yapan 17 kişiden 12’si, kontrollerde 19 kişiden altısı iki gün içinde yazdı.",limitation:"%71 ile %32 karşılaştırması araştırmaya alınan herkesi değil, raporu geri verenleri kapsar. Planlama toplam katılımı artırmadı. Dar bir öğrenci işi; ODA kursu doğrulanmadı."},{id:"M11",title:"Oettingen ve arkadaşları · 2015 · Planlama ve takvime saat yazmak",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Birinci çalışmada 84 lisans öğrencisi analiz edildi. Önceden planlanan karşılaştırma, planlanan saatlerde zihinsel karşılaştırma ve “şu olursa bunu yaparım” planları lehineydi: p = 0,03. Genel karşılaştırma p = 0,057.",limitation:"Tamamlanan iş veya üretkenlik değil, takvime saat yazma ölçüldü. Eksik yanıtlar dışlandı. Kursun kısa uyarlaması ve koşulların uygunluğunu ayırma biçimi sınanmadı."},{id:"M14",title:"NIMH · Ruh sağlığı sorunlarında yardım almak",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Resmî rehber, sıkıntı, günlük hayatta aksama veya acil tehlike için uzman ve kriz desteği yollarını anlatır.",limitation:"Bir rehber, etkililik deneyi değil. ODA ruhsal hastalığa tanı koymaz, tedavi etmez. ABD dışında yerel sağlık ve acil yardım hizmetlerini kullan."},{id:"manifest-positive-fantasies",title:"Kappes ve Oettingen · 2011 · İdealleştirilmiş olumlu hayaller",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Çoğunlukla öğrencilerle yapılan dört deneyde bazı idealleştirilmiş olumlu hayallerden sonra anlık enerji daha düşüktü. Üçüncü çalışma olumlu hayalleri sorgulayanlarla değil, nötr veya yönlendirilmemiş hayallerle karşılaştırdı.",limitation:"Küçük, kısa deneylerdir. Bütün iyimserlik veya hayal kurma zararlı değildir. Tekrarlanan hayal döngüsü veya beynin hedefi tamamlanmış saydığı bir sinyal ölçülmedi."},{id:"manifest-belief-study",title:"Dixon, Hornsey ve Hartley · 2025, çevrim içi 2023 · Manifestasyon inancı",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Toplam 1.023 kişilik üç ABD çevrim içi anketinde manifestasyon inancı, kendine güvenle ve iflas dahil bazı mali risk bildirimleriyle ilişkiliydi. Bildirilen gelir veya eğitimle ilişki yoktu.",limitation:"İlişkiler neden-sonucu göstermez, her tekniği nesnel olarak sınamaz. Kişilerin bildirdiği sonuçlar, tek bir kişinin geleceği için tahmin değildir."},{id:"manifest-murphy",title:"Joseph Murphy · Bilinçaltının Gücü · Yayıncının kitap tanıtımı",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Yayıncı, Murphy’nin popüler kişisel gelişim kitabını ve hayal gücüyle inanç hakkındaki öğretilerini tanımlar.",limitation:"Yayıncı özeti, kontrollü çalışma değil. Yatma ritüelinin tam metni doğrulanmadı. Burada para çekmeye, iyileşmeye veya yatma vaktinin öğrenmede özel üstünlüğüne kanıt yok."}],G={id:"manifest",title:"Hayalin yerinde sayıyor mu? Bugün bir adım at",subtitle:"Beş temel dersin ardından 15 yaygın teknik: araştırmanın söylediği ve bugün yapabileceğin bir iş.",description:"Seçtiğin bir isteği somut işe dönüştür. Teknik kütüphanesinde de aynı denemeyi sürdür: uygulamaları öğren, araştırmanın sınırına bak ve yapabileceğin bir adım dene.",lessonLibrary:{id:"manifest-technique-library",title:"Teknik kütüphanesi",description:"15 tanıdık uygulama. Nasıl yapıldıklarını, araştırmanın neyi desteklediğini ve iş yapıp sonucu değerlendirdiğin ODA uyarlamasını öğren.",lessonIds:m.map(a=>a.id),sourceIds:u.map(a=>a.id)},scope:"Burada manifestasyon, niyetini hazırlık ve davranışla hayata geçirme çalışmasıdır. Düşüncelerin kuantum etkileriyle olayları yönettiği, evrenin odaklandığın şeyi getirdiği veya her isteğin kesin gerçekleşeceği iddia edilmez. Bu kurs mali, tıbbi veya psikolojik danışmanlık değildir.",outcome:"Anlamlı tek hedef, kullanabileceğin en küçük adım, dürüst deneme kayıtları ve gelecek haftaya uyan bir plan.",photo:{id:"1676782778930-11b311ec5134",alt:"Çimenli tepeden uzak dağlara doğru yükselen toprak yol"},lessons:[{id:"manifest-1",v2:{schemaVersion:2,revision:2,id:"manifest-1",courseId:"manifest",locale:"tr",title:"Hayalin bekliyor mu? Bugün işe yarayan bir şey yap",goal:"Seçtiğin hedef için kullanabileceğin küçük bir iş çıkar.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Yine bir hafta geçti, istediğin hayat hâlâ uzakta mı? Bir isteğin için bugün somut bir iş yap.",reason:{id:"manifest-1-reason",label:"Bu kimin hedefi? Zaman ayırmana gerçekten değer mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Benim hedefim; akşam telefona bakmak bekleyebilir","Ailemin önceliği; metni cilalamak bekleyebilir","Başkasının hedefi; ayıracağım zamanı yeniden düşünmeliyim","Bu hedefi kimin için istediğimden emin değilim"]},why:{id:"manifest-1-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Daha iyi bir iş bulmak sonuçtur. Öz geçmişindeki bir cümleyi düzeltmek ise yapabileceğin bir iştir. Seni arayıp aramamaya yine başkaları karar verir. Yapmaya değer bir iş seç. Emeğini, onların yanıtına göre ölçmek zorunda değilsin.","Öğrencilerle yapılan bir deneyde başlama zamanını ve yerini seçmek, raporunu geri verenler arasında zamanında yazmayı artırdı. Toplam katılımı artırmadı. Plan başlamak için destek olabilir, sonucu garanti etmez. Bugün kullanabileceğin bir cümle yaz, soruyu yanıtla veya bir şey iste. Kurs boyunca aynı hedefi koru. Sonra gerçekte ne olduğunu anlatmak için dön."],example:{title:"Emre işe başlıyor",text:"Akşam yemeğinden sonra Emre mutfak masasında lojistik işi hedefi için on dakika ayırıyor. Öz geçmişindeki bir cümleyi, depodaki sekiz vardiyanın planını nasıl yaptığını anlatacak biçimde düzeltiyor. Cümle hâlâ içine sinmiyor. Yine de taslağı saklayıp neyi değiştirdiğini kaydediyor. Hiçbir işveren henüz metni görmedi. Yarın üzerinde çalışabileceği gerçek bir taslak var."}},move:{invitation:"Kendi işine yarayan adımı belirt. Öneriler, Emre’nin öz geçmişinden uyarlayabileceğin örnekler.",instructions:["Kaydetmeden önce hangi belgeyi, soruyu veya nesneyi değiştireceğini belirt.","En küçük adımı at. Dışarıdan gelen yanıtı, yaptığın işten ayrı kaydet."],prompts:[],suggestions:{action:["Öz geçmişte vardiya planını anlatan cümleyi düzelt","Öz geçmişi okuyana hangi ayrıntının eksik olduğunu sor","Vardiya dağılımını gösteren bir iş örneği hazırla"],minimum:["Vardiya planıyla ilgili bir öz geçmiş cümlesi kaydet","Eksik öz geçmiş ayrıntısını soran mesajı gönder","Vardiya dağılımını gösteren iş örneğini kaydet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Akşam yemeğinin sofrası toplandıktan sonra","Öğle yemeği bitince","Sabah içeceğimi içtikten sonra"],place:["Mutfak masamda","Kütüphanedeki çalışma masasında","Öz geçmiş belgemde"],minutes:[10,2,5],fallback:["Bir vardiya değişikliğini sade bir cümleyle yaz","Uygun başka bir fırsat seç ve belirt","Kütüphane görevlisine bilgisayar kullanıp kullanamayacağını sor"],observation:["Kaydettiğim öz geçmiş cümlesi","Öz geçmiş sorusunu gönderip göndermediğim","En küçük adımı neyin engellediği"]},suggested:{action:"Öz geçmişte vardiya planını anlatan cümleyi düzelt",minimum:"Vardiya planıyla ilgili bir öz geçmiş cümlesi kaydet",minutes:10,cueHint:"Akşam yemeğinin sofrası toplandıktan sonra",placeHint:"Mutfak masamda",obstacleHint:"Ayırabildiğim süre planladığımdan daha kısa",fallbackHint:"Bir vardiya değişikliğini sade bir cümleyle yaz",observationHint:"Kaydettiğim öz geçmiş cümlesi"},accessibleAlternative:"Yazabilir, sesle yazdırabilir veya her zamanki araçlarını kullanabilirsin. Gerekiyorsa işin için somut yardım iste.",stopRule:"Güvenli olmayan veya maddi gücünü aşan adımlara ara ver. Bunun yerine somut destek seç."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-1-decision",scenario:"Emre kendisine uygun bir iş ilanı bulmuş. Akşam yemeğine on dakika var. Öz geçmişi, ilanda istenen vardiya planlama deneyimini anlatmıyor.",question:"İlk denemede hangi adım daha işe yarar?",options:[{id:"manifest-1-research-more",text:"İşin istediği hayata gerçekten uyup uymadığını anlamak için başka ilanlara da bakmak.",feedback:"İlan karşılaştırmak hedefini netleştirebilir. Ama bu iş zaten uygun. Eksik olan, Emre’nin deneyimini işe yarar biçimde anlatan bir cümle. Elindeki zamanı o cümleyi düzeltmek için kullan."},{id:"manifest-1-improve-line",text:"Bu ilana uygun bir öz geçmiş cümlesi yazmak, taslağı saklamak ve eksikleri not etmek.",feedback:"Bu seçim, on dakikaya sığan ve Emre’nin kullanabileceği bir iş çıkarır. Taslağa yorum gerekebilir, işveren yanıt vermeyebilir. Bunların hiçbiri yaptığı işi ortadan kaldırmaz."},{id:"manifest-1-clarify-future",text:"Öz geçmişine ne yazacağını seçmeden önce ideal çalışma gününü ayrıntılarıyla anlatmak.",feedback:"İstediği çalışma gününü anlatmak sonraki seçimlere yön verebilir. Emre uygun işi zaten seçmiş. Daha çok anlatmak bu somut eksiği erteler. Önce cümleyi yaz, sonra ne gerektiğine bak."}],bestOptionId:"manifest-1-improve-line"}},carry:{takeaway:"İsteğin için bugün işe yarayan bir adım at. Gerçekte yaptığını, beklediğin yanıttan ayrı kaydet.",followUp:{questionId:"manifest-1-return",question:"Kaydettiğin denemeden sonra elinde kullanabileceğin hangi iş var?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Başlama planı neye yardım edebilir?",paragraphs:["Gollwitzer ve Brandstätter’in 1997 tarihli ikinci deneyinde Münih’teki 86 öğrenciye Noel hakkında rapor yazma işi verildi. Plan yapanlar kesin bir zaman ve yer seçti. O fırsatı gözlerinde canlandırdı, başlamaya karar verdi ve seçimlerini yazdı. Raporunu geri veren, kimliği belirlenebilen 36 kişinin içinde plan yapan 17 kişiden 12’si, kontrol grubundaki 19 kişiden altısı istenen iki günde yazdı. Bu oranlar araştırmaya alınan herkesi değil, raporunu geri verenleri anlatır. Plan yapmak toplam katılımı artırmadı. [M10]","Ders, belirli bir başlama fırsatı seçme fikrini alıyor. Ardından o anda kullanabileceğin bir iş yapmanı istiyor. Bu genel uyarlama, Noel raporu deneyinde sınanmadı. Yalnızca bir tarih seçmek, o gün zamanı nereden bulacağını söylemez. Fark edebileceğin bir olayı ve ulaşabileceğin bir yeri seç. Gerekli araç veya kaynak yoksa onu istemek bugünkü adımın olabilir. Yardım henüz gelmese de yaptığın isteği kaydet. İsteğin gönderilmesi, yardımın alınması veya işin bitmesiyle aynı sonuç değil."]},{heading:"İsteklerin başkalarının kararını yönetmez",paragraphs:["Wang ve arkadaşlarının 2021 derlemesi, 15.907 katılımcı içeren 21 makaleden 24 bağımsız etkiyi birleştirdi. İstenen sonucu bir engel ve “şu olursa bunu yapacağım” planıyla ele almak, hedefe ulaşmada mütevazı bir ortalama yarar gösterdi. Etki g = 0,336, %95 güven aralığı 0,229 ile 0,443 arasındaydı. Bulgular oldukça farklıydı. Yayın yanlılığı için yapılan düzeltme tahmini küçülttü. Bu bulgu, sınırları olan planlamayı destekler. Kursun sana sonuç vereceğine söz vermez. [M01]","Dixon ve arkadaşları, toplam 1.023 kişinin katıldığı üç ABD çevrim içi anketinde manifestasyon inancını inceledi. Bu inanç, bildirilen bazı mali risklerle ve iflas bildirimleriyle ilişkiliydi. Bildirilen gelir veya eğitimle ilişki bulunmadı. Bu ilişkiler, inancın iflasa neden olduğunu göstermez. Her manifestasyon alıştırmasını nesnel olarak sınamaz. [M07] İsteğini yapacağın işi seçmek ve koşullara bakmak için kullan. Düşüncelerinin fırsatları çektiği, sıkıntıya neden olduğu veya bir sonucu hak ettirdiği sonucunu çıkarma. Para, bakım ihtiyaçları, erişim ve başkalarının kararları yine önem taşır."]}],sourceIds:["M10","M01","M07"]}},photo:{id:"1768055104910-8c8d213835fb",alt:"Deftere yapılacaklar listesi yazan el"},schemaVersion:2,title:"Hayalin bekliyor mu? Bugün işe yarayan bir şey yap",minutes:6,goal:"Seçtiğin hedef için kullanabileceğin küçük bir iş çıkar.",reading:["Daha iyi bir iş bulmak sonuçtur. Öz geçmişindeki bir cümleyi düzeltmek ise yapabileceğin bir iştir. Seni arayıp aramamaya yine başkaları karar verir. Yapmaya değer bir iş seç. Emeğini, onların yanıtına göre ölçmek zorunda değilsin.","Öğrencilerle yapılan bir deneyde başlama zamanını ve yerini seçmek, raporunu geri verenler arasında zamanında yazmayı artırdı. Toplam katılımı artırmadı. Plan başlamak için destek olabilir, sonucu garanti etmez. Bugün kullanabileceğin bir cümle yaz, soruyu yanıtla veya bir şey iste. Kurs boyunca aynı hedefi koru. Sonra gerçekte ne olduğunu anlatmak için dön."],practice:["Senin için önemli bir isteği tek cümleyle yaz veya düşün.","Seni o isteğe yaklaştıran ve senin seçebileceğin bir davranış belirle.","İşin küçük bir kısmını ve ne zaman bitmiş sayılacağını belirt. Örneğin “taslağın üç cümlesini yazmak”."],reflection:"Bugün isteğin için yapabileceğin davranış ne?",question:"Hangisini doğrudan yapmayı seçebilirsin?",options:["İşverenin kesin beni seçmesi.","Yarın öz geçmişimin üç cümlesini düzenlemek.","Hiçbir şeyin ters gitmemesi."],correct:1,feedback:"Başkalarının kararını garanti edemezsin. Kendi hazırlığını somut bir işe dönüştürebilirsin.",takeaway:"İsteğin için bugün işe yarayan bir adım at. Gerçekte yaptığını, beklediğin yanıttan ayrı kaydet.",sources:["M10","M01","M07"],deeper:[{heading:"Başlama planı neye yardım edebilir?",paragraphs:["Gollwitzer ve Brandstätter’in 1997 tarihli ikinci deneyinde Münih’teki 86 öğrenciye Noel hakkında rapor yazma işi verildi. Plan yapanlar kesin bir zaman ve yer seçti. O fırsatı gözlerinde canlandırdı, başlamaya karar verdi ve seçimlerini yazdı. Raporunu geri veren, kimliği belirlenebilen 36 kişinin içinde plan yapan 17 kişiden 12’si, kontrol grubundaki 19 kişiden altısı istenen iki günde yazdı. Bu oranlar araştırmaya alınan herkesi değil, raporunu geri verenleri anlatır. Plan yapmak toplam katılımı artırmadı. [M10]","Ders, belirli bir başlama fırsatı seçme fikrini alıyor. Ardından o anda kullanabileceğin bir iş yapmanı istiyor. Bu genel uyarlama, Noel raporu deneyinde sınanmadı. Yalnızca bir tarih seçmek, o gün zamanı nereden bulacağını söylemez. Fark edebileceğin bir olayı ve ulaşabileceğin bir yeri seç. Gerekli araç veya kaynak yoksa onu istemek bugünkü adımın olabilir. Yardım henüz gelmese de yaptığın isteği kaydet. İsteğin gönderilmesi, yardımın alınması veya işin bitmesiyle aynı sonuç değil."]},{heading:"İsteklerin başkalarının kararını yönetmez",paragraphs:["Wang ve arkadaşlarının 2021 derlemesi, 15.907 katılımcı içeren 21 makaleden 24 bağımsız etkiyi birleştirdi. İstenen sonucu bir engel ve “şu olursa bunu yapacağım” planıyla ele almak, hedefe ulaşmada mütevazı bir ortalama yarar gösterdi. Etki g = 0,336, %95 güven aralığı 0,229 ile 0,443 arasındaydı. Bulgular oldukça farklıydı. Yayın yanlılığı için yapılan düzeltme tahmini küçülttü. Bu bulgu, sınırları olan planlamayı destekler. Kursun sana sonuç vereceğine söz vermez. [M01]","Dixon ve arkadaşları, toplam 1.023 kişinin katıldığı üç ABD çevrim içi anketinde manifestasyon inancını inceledi. Bu inanç, bildirilen bazı mali risklerle ve iflas bildirimleriyle ilişkiliydi. Bildirilen gelir veya eğitimle ilişki bulunmadı. Bu ilişkiler, inancın iflasa neden olduğunu göstermez. Her manifestasyon alıştırmasını nesnel olarak sınamaz. [M07] İsteğini yapacağın işi seçmek ve koşullara bakmak için kullan. Düşüncelerinin fırsatları çektiği, sıkıntıya neden olduğu veya bir sonucu hak ettirdiği sonucunu çıkarma. Para, bakım ihtiyaçları, erişim ve başkalarının kararları yine önem taşır."]}],example:{title:"Emre işe başlıyor",text:"Akşam yemeğinden sonra Emre mutfak masasında lojistik işi hedefi için on dakika ayırıyor. Öz geçmişindeki bir cümleyi, depodaki sekiz vardiyanın planını nasıl yaptığını anlatacak biçimde düzeltiyor. Cümle hâlâ içine sinmiyor. Yine de taslağı saklayıp neyi değiştirdiğini kaydediyor. Hiçbir işveren henüz metni görmedi. Yarın üzerinde çalışabileceği gerçek bir taslak var."}},{id:"manifest-2",v2:{schemaVersion:2,revision:2,id:"manifest-2",courseId:"manifest",locale:"tr",title:"Yine prova mı? Şimdi gerçekten bir cümle yaz",goal:"Takıldığın bir anı prova et. Ardından aynı hedef için yaptığın işin bir sonraki küçük parçasını tamamla.",minutes:{learning:6,suggestedAction:5,review:2,rehearsal:1},direction:{hook:"İstediğin hayatı gözünde canlandırmak kolay. Peki boş sayfayı açtığında ne yapıyorsun?",reason:{id:"manifest-2-reason",label:"Bir prova daha işe yarar mı, yoksa asıl denemeyi mi erteler?",kind:"text",maxLength:160,optional:!0,suggestions:["Eksik bir yönergeyi fark ettirir","Yazmaya hazır cümleyi erteler","Henüz bir prova kaydım yok"]},why:{id:"manifest-2-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin işi ve varsa o iş için tuttuğun kaydı aç. Prova, belirli bir hareketi zihninde yapmaktır. İlk cümleni söylemek gibi. Adımları sıraya koymak başka bir hazırlıktır. İkisi de işi gerçekten yaptığın denemenin yerine geçmez.","Bir derlemede zihinde canlandırmanın davranışa ortalama yararları bulundu. Ama hangi türünün en iyi olduğu gösterilmedi. Bu kısa provanın işe yaradığını da kanıtlamaz. Yalnızca nerede takıldığını ve o anda ne yapabileceğini bulmak için kullan. Görüntü oluşmuyorsa hareketi sözcüklerle anlat. Ardından aynı işte kullanabileceğin bir sonraki cümleyi yaz."],example:{title:"Emre boş satırda takılıyor",text:"Emre akşam yemeğinden sonra öz geçmişine dönüyor. Otuz saniye boyunca zor bir vardiya değişikliğini anlatmayı prova ediyor. Donup kalacağını düşünüyor. Bu yüzden “Sekiz vardiyayı şu durumda değiştirdim…” diye başlamayı deniyor. Sonra kullanabileceği bir cümle yazıyor. İki sözcüğü siliyor ve yorum almak için bir soru bırakıyor. Prova, ne kadar ayrıntı gerekeceğini göstermemişti."},rehearsal:{label:"İsteğe bağlı hazırlık",steps:["Sonraki hareketi ve nerede takılabileceğini anlat.","İlk yapacağını bir kez prova et. Bu, hazırlıktır."]}},move:{invitation:"Seçtiğin işi koru. Öz geçmiş önerileri, kendi işine göre düzenleyebileceğin örnekler.",instructions:["Seçtiğin işi, en küçük adımı, başlama anını ve yeri koru. Takıldığın ana odaklan.","Planın yoksa kaydetmeden önce yapacağın işi ve uygun bir fırsatı belirt.","Bir kez prova et, ardından yap. Yalnızca prova etmek hazırlıktır."],prompts:[],suggestions:{action:["Prova et, sonra vardiya planını anlatan cümleyi yaz","Prova et, sonra öz geçmiş ayrıntısını sor","Yazılı adımlarla bir öz geçmiş tarihini düzelt"],minimum:["Provanın ardından bir öz geçmiş cümlesi kaydet","Eksik öz geçmiş ayrıntısını soran mesajı gönder","Öz geçmişte düzelttiğin bir tarihi kaydet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Akşam yemeğinin sofrası toplandıktan sonra","Öğle yemeği bitince","Öz geçmiş belgesi açılınca"],place:["Mutfak masamda","Kütüphanedeki çalışma masasında","Öz geçmiş belgemde"],minutes:[5,2,10],fallback:["Provayı bırak, yaşadığın bir vardiya değişikliğini yaz","Gözünde canlandırmak yerine yazdığın ilk adımı kullan","Metni okuyana hangi ayrıntının eksik olduğunu sor"],observation:["Provada fark etmeyip işi yaparken gördüğüm ayrıntı","Yazdığım öz geçmiş cümlesi","Yalnızca prova edip etmediğim"]},suggested:{action:"Prova et, sonra vardiya planını anlatan cümleyi yaz",minimum:"Provanın ardından bir öz geçmiş cümlesi kaydet",minutes:5,cueHint:"Akşam yemeğinin sofrası toplandıktan sonra",placeHint:"Mutfak masamda",obstacleHint:"Başlamak yerine provayı düzeltip duruyorum",fallbackHint:"Provayı bırak, yaşadığın bir vardiya değişikliğini yaz",observationHint:"Provada fark etmeyip işi yaparken gördüğüm ayrıntı"},accessibleAlternative:"Yazabilir, sesle yazdırabilir veya her zamanki araçlarını kullanabilirsin. Gerekiyorsa işin için somut yardım iste.",stopRule:"Yatakta plan yapmak seni uyanık tutuyorsa bırak. Gündüz uygun bir fırsat seç."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-2-decision",scenario:"Emre ilk öz geçmiş cümlesini anlatabiliyor ve belgesi hazır. Ama başvurunun tamamını bir kez daha prova etmek istiyor.",question:"Sıradaki hangi adım bu denemeye yardımcı olur?",options:[{id:"manifest-2-full-rehearsal",text:"Hiç yazmadan önce en iyi başlangıcı seçebilmek için başvurunun tamamını bir kez daha prova etmek.",feedback:"Tam prova ilerideki işi hazırlayabilir. Ama Emre’nin kullanabileceği bir başlangıcı ve hazır bir belgesi var. Baştan bir tur daha dönmek, önündeki denemeyi erteler. Cümleyi yazıp ortaya çıkana bak."},{id:"manifest-2-new-goal-scene",text:"Motivasyonunu tazelemek için yeni işteki ilk gününü canlandırıp başvuruya daha sonra dönmek.",feedback:"İşi hayal etmek neden önemli olduğunu netleştirebilir. Ama Emre’nin hazır başlangıcını sınamaz. Cümleyi şimdi belgeye yaz. Ardından hangi kısmın beklediğinden daha zor geldiğine bak."},{id:"manifest-2-perform-opening",text:"İlk cümleyi bir kez prova etmek, taslağa yazmak ve zorluğu beklediğiyle karşılaştırmak.",feedback:"Bu seçim, hazırlığı gerçek bir adım için kullanır. Yazılan cümle Emre’ye değerlendirebileceği bir şey verir. Cümlenin niteliği ve yazarken hissettiği rahatsızlık henüz belli değildir. Denemenin sayılması için bunların çözülmesi gerekmez."}],bestOptionId:"manifest-2-perform-opening"}},carry:{takeaway:"İşe yarayan hazırlığın ardından gerçek bir adım at. İkisini ayrı kaydet.",followUp:{questionId:"manifest-2-return",question:"Hareketi prova etmekle gerçekten yapmak arasında hangi farkı gördün?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Canlandırma araştırması bir sıralama vermiyor",paragraphs:["Cole ve arkadaşlarının 2021 derlemesi, 5.685 katılımcıyla yapılan 94 çalışmadaki 123 etkiyi birleştirdi. Zihinde canlandırmanın davranış üzerindeki genel etkisi g = 0,49, %95 güven aralığı 0,37 ile 0,62 arasındaydı. Örneklemlerin çoğu öğrencilerden oluşuyordu. Canlandırmaların içeriği, süresi ve ölçülen sonuçları farklıydı. Bu yüzden ortalama sonuç, senin kısa alıştırmanda ne olacağını önceden söylemez. Bunu kişisel bir başarı oranı olarak da okuyamayız. [M04]","Derleme, süreç adımlarını düşünmekle bir işi zihninde yapmayı ayrı ele aldı. Yalnızca süreç adımlarına ilişkin tahmin beş etkiye dayanıyordu. Güven aralığı etkisizlik değerini de içeriyordu. Türlerin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı. Bu nedenle daha yüksek alt grup ortalamaları, güvenilir bir kazanan olduğunu göstermez. Bir grafiği daha yoğun canlandırma talimatına dönüştürme. Ders, provayı tek bir somut ayrıntıyı görmek için kullanıyor. Ardından işi denemeni istiyor. Yazıyla anlatmak erişilebilir bir seçenektir. Araştırmada görüntüyle eşdeğer bulunmuş bir yöntem olduğu iddiası değildir."]},{heading:"Fırsata hazırlan, sonra o fırsatı kullan",paragraphs:["İlk rapor planlama deneyinde katılımcılar, işe başlayacakları belirli zaman ve yeri gözlerinde canlandırdı. Zamanında yazma karşılaştırması, raporu geri veren ve kimliği belirlenebilen öğrencilerle sınırlıydı. İş, dar kapsamlı bir öğrenci ödeviydi. Bu bulgu herkes için geçerli bir hayal etme metni sunmaz. Yatakta prova yapmanın yararını da göstermez. [M10] Burada hazırlık, mevcut hedefin için bir sonraki kısmı gerçekten yapmana yardım ettiği sürece işe yarar.","Bir şifrenin eksik olduğunu, yönergenin açık olmadığını veya bir cümleyi henüz anlatamadığını fark edebilirsin. Şifreyi yenilemek hazırlıktır. Gereken bilgiyi göndermek ise işin bir parçasıdır. Kaydında bu fark görülsün. Yatarken plan yapmak seni uyanık tutuyorsa bırak. Bunun yerine gündüz uygun bir fırsat seç. Bu, kursun pratik bir uyarlaması. Kısa prova, isteğe bağlı bir uygulama alıştırmasıdır. Doğrulanmış bir ritüel veya başlamanın şartı değildir. Canlı bir görüntü kurman ya da belli bir duyguyu hissetmen gerekmiyor."]}],sourceIds:["M04","M10"]}},photo:{id:"1517363898874-737b62a7db91",alt:"Sıcak ışıkta pencere yanında sessizce oturan biri"},schemaVersion:2,title:"Yine prova mı? Şimdi gerçekten bir cümle yaz",minutes:6,goal:"Takıldığın bir anı prova et. Ardından aynı hedef için yaptığın işin bir sonraki küçük parçasını tamamla.",reading:["Seçtiğin işi ve varsa o iş için tuttuğun kaydı aç. Prova, belirli bir hareketi zihninde yapmaktır. İlk cümleni söylemek gibi. Adımları sıraya koymak başka bir hazırlıktır. İkisi de işi gerçekten yaptığın denemenin yerine geçmez.","Bir derlemede zihinde canlandırmanın davranışa ortalama yararları bulundu. Ama hangi türünün en iyi olduğu gösterilmedi. Bu kısa provanın işe yaradığını da kanıtlamaz. Yalnızca nerede takıldığını ve o anda ne yapabileceğini bulmak için kullan. Görüntü oluşmuyorsa hareketi sözcüklerle anlat. Ardından aynı işte kullanabileceğin bir sonraki cümleyi yaz."],practice:["Hedefinin hayatında yaratmasını istediğin bir farkı belirt.","İlk iki hareketini görüntüyle veya sözcüklerle sıraya koy.","Provadan sonra bir hazırlık işini gerçekten yap."],reflection:"Provada hangi eksik hazırlığı fark ettin?",question:"Bu kursta zihinsel prova ne demek?",options:["Gerçek bir işi yapmaya hazırlanmak için alıştırma.","Düşüncelerinle dışarıdaki olayları kesin olarak yönetmek.","Bir daha denemeye gerek duymamak."],correct:0,feedback:"Prova hazırlıktır. Kaynaklar bu kısa alıştırmayı doğrulamaz veya dışarıdaki sonucu yönettiğini göstermez. Hazırlığı gerçek bir adım için kullan.",takeaway:"İşe yarayan hazırlığın ardından gerçek bir adım at. İkisini ayrı kaydet.",sources:["M04","M10"],deeper:[{heading:"Canlandırma araştırması bir sıralama vermiyor",paragraphs:["Cole ve arkadaşlarının 2021 derlemesi, 5.685 katılımcıyla yapılan 94 çalışmadaki 123 etkiyi birleştirdi. Zihinde canlandırmanın davranış üzerindeki genel etkisi g = 0,49, %95 güven aralığı 0,37 ile 0,62 arasındaydı. Örneklemlerin çoğu öğrencilerden oluşuyordu. Canlandırmaların içeriği, süresi ve ölçülen sonuçları farklıydı. Bu yüzden ortalama sonuç, senin kısa alıştırmanda ne olacağını önceden söylemez. Bunu kişisel bir başarı oranı olarak da okuyamayız. [M04]","Derleme, süreç adımlarını düşünmekle bir işi zihninde yapmayı ayrı ele aldı. Yalnızca süreç adımlarına ilişkin tahmin beş etkiye dayanıyordu. Güven aralığı etkisizlik değerini de içeriyordu. Türlerin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı. Bu nedenle daha yüksek alt grup ortalamaları, güvenilir bir kazanan olduğunu göstermez. Bir grafiği daha yoğun canlandırma talimatına dönüştürme. Ders, provayı tek bir somut ayrıntıyı görmek için kullanıyor. Ardından işi denemeni istiyor. Yazıyla anlatmak erişilebilir bir seçenektir. Araştırmada görüntüyle eşdeğer bulunmuş bir yöntem olduğu iddiası değildir."]},{heading:"Fırsata hazırlan, sonra o fırsatı kullan",paragraphs:["İlk rapor planlama deneyinde katılımcılar, işe başlayacakları belirli zaman ve yeri gözlerinde canlandırdı. Zamanında yazma karşılaştırması, raporu geri veren ve kimliği belirlenebilen öğrencilerle sınırlıydı. İş, dar kapsamlı bir öğrenci ödeviydi. Bu bulgu herkes için geçerli bir hayal etme metni sunmaz. Yatakta prova yapmanın yararını da göstermez. [M10] Burada hazırlık, mevcut hedefin için bir sonraki kısmı gerçekten yapmana yardım ettiği sürece işe yarar.","Bir şifrenin eksik olduğunu, yönergenin açık olmadığını veya bir cümleyi henüz anlatamadığını fark edebilirsin. Şifreyi yenilemek hazırlıktır. Gereken bilgiyi göndermek ise işin bir parçasıdır. Kaydında bu fark görülsün. Yatarken plan yapmak seni uyanık tutuyorsa bırak. Bunun yerine gündüz uygun bir fırsat seç. Bu, kursun pratik bir uyarlaması. Kısa prova, isteğe bağlı bir uygulama alıştırmasıdır. Doğrulanmış bir ritüel veya başlamanın şartı değildir. Canlı bir görüntü kurman ya da belli bir duyguyu hissetmen gerekmiyor."]}],example:{title:"Emre boş satırda takılıyor",text:"Emre akşam yemeğinden sonra öz geçmişine dönüyor. Otuz saniye boyunca zor bir vardiya değişikliğini anlatmayı prova ediyor. Donup kalacağını düşünüyor. Bu yüzden “Sekiz vardiyayı şu durumda değiştirdim…” diye başlamayı deniyor. Sonra kullanabileceği bir cümle yazıyor. İki sözcüğü siliyor ve yorum almak için bir soru bırakıyor. Prova, ne kadar ayrıntı gerekeceğini göstermemişti."}},{id:"manifest-3",v2:{schemaVersion:2,revision:2,id:"manifest-3",courseId:"manifest",locale:"tr",title:"Engel gerçek. Önce koşulları değiştir",goal:"Son denemene bak. Engel için yapabileceğin bir değişiklik seç ve dene.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Çocuk bakımı, bilgisayara erişim ya da bitkinlik mi önünü kesiyor? Daha çok inanmak gününü yeniden düzenlemez.",reason:{id:"manifest-3-reason",label:"Nerede destek gerekiyor? Şimdi hangi koşulu değiştirebilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Ortak bilgisayarı kullanacağım saatte anlaşmalıyız","Öz geçmişte yapacağım düzeltmeyi küçültebilirim","Bakım sorumluluklarım bugün zaman bırakmıyor","Henüz somut bir engelle karşılaşmadım"]},why:{id:"manifest-3-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı hedefini ve varsa deneme kaydını kullan. Henüz denemedin mi? Karşılaşabileceğin somut bir engeli belirt. “Akşam yemeğinden sonra ortak bilgisayarı kullanamıyorum” neyi değiştirebileceğini gösterir. “Disiplinsizim” ise hangi koşulun seni durdurduğunu söylemez.","İstenen sonucu, gerçek engeli ve “şu olursa bunu yapacağım” yanıtını birleştiren çalışmalarda mütevazı ortalama yararlar bulundu. Rahatsızlık hissetmenin yöntemin işe yaramasını sağladığı gösterilmedi. Para, bakım sorumlulukları, zaman ve erişim gerçek koşullardır. İnancındaki kusurlar değildir. Tek bir değişiklik dene: işi küçült, uygun bir fırsat bul veya belirli bir yardım iste. İstemek, yardımın geldiği anlamına gelmez."],example:{title:"Emre bilgisayarı başka saatte kullanıyor",text:"Emre akşam yemeğinden sonra öz geçmişini düzenleyecekti. Ama kızının ödevi için ortak bilgisayar gerekti. Kaydına bu çakışmayı yazıyor. Ertesi gün akşam yemeğinden önce bilgisayarı on dakika kullanıp kullanamayacağını soruyor. Anlaşıyorlar. O fırsat geldiğinde bir cümleyi düzeltiyor ve duruyor. Başvuruda hâlâ yapılacak iş var. Bilgisayar zamanı istemekle cümleyi düzeltmeyi ayrı ayrı kaydedebiliyor."}},move:{invitation:"Bilgisayar gibi bir kaynağa mı ihtiyacın var? “Bunu uyarla”, sonra “Destek” seç. Kime soracağını belirt.",instructions:["Gereken kaynağı kullanabileceğin kesinleştiyse seçtiğin işi, en küçük adımı, başlama anını ve yeri koru.","Gereken kaynağı kullanamıyorsan kimden yardım isteyeceğini, neye ihtiyacın olduğunu ve ne zaman kullanacağını belirt.","İstemeyi, yardım almaktan veya işi tamamlamaktan ayrı kaydet."],prompts:[],suggestions:{action:["Kızıma akşam yemeğinden önce bilgisayarı kullanıp kullanamayacağımı sor","Kütüphane görevlisine uygun bilgisayar saatini sor"],minimum:["Kızımdan bilgisayarı on dakika kullanmayı iste","Kütüphaneye mesaj atıp bilgisayar kullanma imkânını sor"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Evde ödevlerin zamanı konuşulunca","Bugün öğle yemeğinden sonra","Akşam yemeğinin sofrası toplandıktan sonra"],place:["Mutfak masamda","Kütüphanenin iletişim formunda","Kütüphanedeki çalışma masasında"],minutes:[5,2,10],fallback:["Kütüphane görevlisine bilgisayar kullanıp kullanamayacağını sor","Evdeki kişiye bilgisayarı kullanmak istediğini mesajla bildir","Uygun bir zaman kararlaştırılana kadar ara ver"],observation:["Erişim isteğim ve varsa gelen yanıt","Bilgisayar zamanının kararlaştırılıp kararlaştırılmadığı","Belirttiğim öz geçmiş düzeltmesini yapıp yapmadığım"]},suggested:{action:"Kızıma akşam yemeğinden önce bilgisayarı kullanıp kullanamayacağımı sor",minimum:"Kızımdan bilgisayarı on dakika kullanmayı iste",minutes:5,cueHint:"Evde ödevlerin zamanı konuşulunca",placeHint:"Mutfak masamda",obstacleHint:"Kızım bilgisayar için zaman ayıramıyor",fallbackHint:"Kütüphane görevlisine bilgisayar kullanıp kullanamayacağını sor",observationHint:"Erişim isteğim ve varsa gelen yanıt",kind:"support"},accessibleAlternative:"Yazabilir, konuşabilir veya yardım alabilirsin. Erişim kararlaştırıldıktan sonra işi yapmak için “Bunu uyarla” seç.",stopRule:"Alıştırma seni çok bunaltıyorsa veya ortam güvenli değilse ara ver. Uygun destek al."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-3-decision",scenario:"Emre’nin akşam öz geçmiş düzenleme saatleri, ortak bilgisayarda yapılan ödevlerle çakışıyor. Evdekiler anlaşırsa akşam yemeğinden önce on dakikalık bir fırsat var.",question:"Bu engeli aşmak için hangi adım daha uygun?",options:[{id:"manifest-3-arrange-opening",text:"Uygun on dakika için anlaşmak ve aynı taslakta işe yarayan bir cümleyi o anda düzeltmek.",feedback:"Bu seçim, işi durduran koşulu değiştirir ve işe yarayan en küçük adımı korur. Yine de anlaşmaları gerekir. Fırsat henüz kesinleşmediyse yaptığın isteği ayrı kaydet. Bilgisayarı kullanmış gibi yazma."},{id:"manifest-3-keep-evening",text:"Akşam planını korumak, bilgisayar boşalınca hazır olmak için daha uzun bir prova eklemek.",feedback:"Prova cümleleri hazırlayabilir. Ama bilgisayarın kullanımındaki çakışmayı çözmez. Emre’nin başka bir zaman seçme olasılığı var. Yeni bir hazırlık düzeni eklemeden önce o zaman için anlaş."},{id:"manifest-3-wait-week",text:"Ödevler hafifleyene kadar gelecek haftayı beklemek, sonra istediği daha uzun öz geçmiş çalışmasına dönmek.",feedback:"Yapılabilir hiçbir fırsat yoksa beklemek uygun olabilir. Burada küçük bir fırsat şimdi kararlaştırılabilir. İşin tamamını kendiliğinden ertelemek yerine önce bu seçeneği dene. Sonucu sonra değerlendir."}],bestOptionId:"manifest-3-arrange-opening"}},carry:{takeaway:"Seni durduran gerçek koşulu belirt. Yapacağın işi değiştir veya gereken somut desteği iste.",followUp:{questionId:"manifest-3-return",question:"Erişim isteğini ilettin mi ya da işi yaptın mı? Hangi konuda hâlâ anlaşmak gerekiyor?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Engel bir ipucu. Rahatsızlık şart değil",paragraphs:["2021’de zihinsel karşılaştırmayı planlamayla birleştiren derleme, 24 bağımsız etkide hedefe ulaşmada mütevazı ortalama artış buldu. Sonuçların oldukça farklı olması ve yayın yanlılığı işaretleri kesinliği sınırlar. Derleme, rahatsızlık hissetmeyi yöntemin işe yarayan parçası olarak ayrı ayrı sınamadı. Bir güçlüğü adlandırmak hoş gelmeyebilir. Ama burada amaç sıkıntıyı bilerek artırmak değil. Ne gerektiğini görmek ve atabileceğin bir adım seçmek. [M01]","Oettingen ve arkadaşlarının incelenen 2015 uygulamasında öğrenciler istedikleri sonucu ve temel engeli ayrıntılı yazdı. Engel çıkarsa ne yapacaklarını seçip planladı. Olağan zamanını ve yerini ekledi. Birinci çalışmada önceden planlanan karşılaştırma, takvime yazılan saatler için yöntem lehineydi. Ölçülen sonuç tamamlanmış iş değil, planlamaydı. Koşulların genel karşılaştırması kesin sonuç vermedi. [M11] ODA, koşulların uygunluğunu kontrol etmeyi ve gerçek denemeyi ekliyor. Bu kısa alıştırma, dış koşullarla kişisel tepkileri ayırma biçimiyle birlikte o deneyde ayrıca doğrulanmadı. Sonucu bir üretkenlik sözü olarak kullanamayız."]},{heading:"Doğru adım bazen destek istemektir",paragraphs:["İstediğin sonucu, o sonuca ilerlemek için gereken koşullardan ayır. Araç eksikse erişim gerekir. Ortam güvenli değilse korunmak gerekir. Bakım sorumluluğuyla çakışma varsa başka bir zaman gerekebilir. Bu ayrım, planlama araştırmasından yararlanan bir kurs tercihidir. Her engeli tek bir kutuya yerleştiren doğrulanmış bir sınıflandırma değil. Destek isteğinde hangi yardıma, hangi fırsatta ihtiyaç duyduğunu söylersen somut bir istek yapmış olursun. Yardımı istemek, karşı tarafın vereceği yanıttan ayrı kalır. [M01, M11]","Biri yanıt vermediyse isteği ve henüz yanıt gelmediğini kaydet. Yardım almış veya işi tamamlamış gibi yazma. Başka yapılabilir bir adım seçebilir, hedefini değiştirebilir ya da ara verebilirsin. Sıkıntı sürüyorsa veya günlük hayatını önemli ölçüde aksatıyorsa alıştırmayı yoğunlaştırmak yerine uzman desteği al. NIMH rehberi, sağlık ve kriz desteğine ulaşma yollarını anlatır. ODA’nın bir durumu tedavi ettiğine kanıt değildir. [M14] Sonraki kaydın, korunmak veya destek istemek dahil, seçtiğin işi anlatsın. Başta gördüğün gerçek engeli sonradan yeterince inanmadığın için yaşanmış gibi anlatma."]}],sourceIds:["M01","M11","M14"]}},photo:{id:"1767134063671-322e6faf9206",alt:"Yapraklı orman yoluna devrilmiş ağaç"},schemaVersion:2,title:"Engel gerçek. Önce koşulları değiştir",minutes:6,goal:"Son denemene bak. Engel için yapabileceğin bir değişiklik seç ve dene.",reading:["Aynı hedefini ve varsa deneme kaydını kullan. Henüz denemedin mi? Karşılaşabileceğin somut bir engeli belirt. “Akşam yemeğinden sonra ortak bilgisayarı kullanamıyorum” neyi değiştirebileceğini gösterir. “Disiplinsizim” ise hangi koşulun seni durdurduğunu söylemez.","İstenen sonucu, gerçek engeli ve “şu olursa bunu yapacağım” yanıtını birleştiren çalışmalarda mütevazı ortalama yararlar bulundu. Rahatsızlık hissetmenin yöntemin işe yaramasını sağladığı gösterilmedi. Para, bakım sorumlulukları, zaman ve erişim gerçek koşullardır. İnancındaki kusurlar değildir. Tek bir değişiklik dene: işi küçült, uygun bir fırsat bul veya belirli bir yardım iste. İstemek, yardımın geldiği anlamına gelmez."],practice:["Hedefinin önündeki en yakın engeli belirt.","Değiştirebileceğin kısmıyla destek veya zaman gerektiren kısmını ayır.","Şimdi yapılmıyorsa işi küçült veya uygun bir zamana taşı."],reflection:"Engeline daha gerçekçi bakınca planında ne değişti?",question:"Dış koşullar önümü kestiğinde…",options:["Yeterince inanmadığım için olduğunu varsaymalıyım.","Koşulları görmezden gelmeliyim.","Desteği, zamanı veya hedefin büyüklüğünü yeniden düşünebilirim."],correct:2,feedback:"Gerçekçi plan dış koşullara bakar. Sonuçları yalnızca düşüncelerin belirlemez.",takeaway:"Seni durduran gerçek koşulu belirt. Yapacağın işi değiştir veya gereken somut desteği iste.",sources:["M01","M11","M14"],deeper:[{heading:"Engel bir ipucu. Rahatsızlık şart değil",paragraphs:["2021’de zihinsel karşılaştırmayı planlamayla birleştiren derleme, 24 bağımsız etkide hedefe ulaşmada mütevazı ortalama artış buldu. Sonuçların oldukça farklı olması ve yayın yanlılığı işaretleri kesinliği sınırlar. Derleme, rahatsızlık hissetmeyi yöntemin işe yarayan parçası olarak ayrı ayrı sınamadı. Bir güçlüğü adlandırmak hoş gelmeyebilir. Ama burada amaç sıkıntıyı bilerek artırmak değil. Ne gerektiğini görmek ve atabileceğin bir adım seçmek. [M01]","Oettingen ve arkadaşlarının incelenen 2015 uygulamasında öğrenciler istedikleri sonucu ve temel engeli ayrıntılı yazdı. Engel çıkarsa ne yapacaklarını seçip planladı. Olağan zamanını ve yerini ekledi. Birinci çalışmada önceden planlanan karşılaştırma, takvime yazılan saatler için yöntem lehineydi. Ölçülen sonuç tamamlanmış iş değil, planlamaydı. Koşulların genel karşılaştırması kesin sonuç vermedi. [M11] ODA, koşulların uygunluğunu kontrol etmeyi ve gerçek denemeyi ekliyor. Bu kısa alıştırma, dış koşullarla kişisel tepkileri ayırma biçimiyle birlikte o deneyde ayrıca doğrulanmadı. Sonucu bir üretkenlik sözü olarak kullanamayız."]},{heading:"Doğru adım bazen destek istemektir",paragraphs:["İstediğin sonucu, o sonuca ilerlemek için gereken koşullardan ayır. Araç eksikse erişim gerekir. Ortam güvenli değilse korunmak gerekir. Bakım sorumluluğuyla çakışma varsa başka bir zaman gerekebilir. Bu ayrım, planlama araştırmasından yararlanan bir kurs tercihidir. Her engeli tek bir kutuya yerleştiren doğrulanmış bir sınıflandırma değil. Destek isteğinde hangi yardıma, hangi fırsatta ihtiyaç duyduğunu söylersen somut bir istek yapmış olursun. Yardımı istemek, karşı tarafın vereceği yanıttan ayrı kalır. [M01, M11]","Biri yanıt vermediyse isteği ve henüz yanıt gelmediğini kaydet. Yardım almış veya işi tamamlamış gibi yazma. Başka yapılabilir bir adım seçebilir, hedefini değiştirebilir ya da ara verebilirsin. Sıkıntı sürüyorsa veya günlük hayatını önemli ölçüde aksatıyorsa alıştırmayı yoğunlaştırmak yerine uzman desteği al. NIMH rehberi, sağlık ve kriz desteğine ulaşma yollarını anlatır. ODA’nın bir durumu tedavi ettiğine kanıt değildir. [M14] Sonraki kaydın, korunmak veya destek istemek dahil, seçtiğin işi anlatsın. Başta gördüğün gerçek engeli sonradan yeterince inanmadığın için yaşanmış gibi anlatma."]}],example:{title:"Emre bilgisayarı başka saatte kullanıyor",text:"Emre akşam yemeğinden sonra öz geçmişini düzenleyecekti. Ama kızının ödevi için ortak bilgisayar gerekti. Kaydına bu çakışmayı yazıyor. Ertesi gün akşam yemeğinden önce bilgisayarı on dakika kullanıp kullanamayacağını soruyor. Anlaşıyorlar. O fırsat geldiğinde bir cümleyi düzeltiyor ve duruyor. Başvuruda hâlâ yapılacak iş var. Bilgisayar zamanı istemekle cümleyi düzeltmeyi ayrı ayrı kaydedebiliyor."}},{id:"manifest-4",v2:{schemaVersion:2,revision:2,id:"manifest-4",courseId:"manifest",locale:"tr",title:"Hazır hissetmeyi bekleyip durma",goal:"Fark edebileceğin bir başlama işareti seç. Takıldığın yerde küçük bir adım dene.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"“Hazır olunca” dediğin an hep erteleniyor. Gerçekten fark edebileceğin bir olay seç.",reason:{id:"manifest-4-reason",label:"İşaret en son geldiğinde işi ertelemek sana neye mal oldu?",kind:"text",maxLength:160,optional:!0,suggestions:["Örnekleri karşılaştırdım; cümle yazamadım","Hazır hissetmeyi bekledim; taslak değişmedi","Bakım sorumluluğu vardı; güvenli fırsat yoktu","Başlama anı henüz gelmedi; cümle kurarken oyalanabilirim"],help:"Önceki denemen yoksa seni durdurabilecek bir tereddüdü belirt."},why:{id:"manifest-4-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Başlama işareti ve engel çıkınca yapacağın şey farklı işlere yarar. “Tabaklar kalkınca bir öz geçmiş cümlesi yaz” sana fırsat verir. “Takılırsam bir vardiya değişikliğini anlat” ise o fırsatın içinde ne yapacağını söyler.","Farklı hedeflerde yapılan araştırmalar, belirli “şu olursa bunu yaparım” planlarının işi sürdürmeye ortalama destek verdiğini buldu. Bütün unutkanlığı, çabayı veya somut engelleri kaldırmazlar. Seçtiğin işi koru. Varsa kaydettiğin engeli ele al. Fark edebileceğin tek işaret ve o anda atabileceğin küçük bir adım seç. İşaret hiç oluşmazsa fırsat olmadığını kaydet ve başka bir zaman bul."],example:{title:"Emre işareti kullanıyor",text:"Emre ortak bilgisayarın yanına not bırakıyor: “Tabaklar kalkınca bir cümleyi düzelt. Takılırsan bir vardiya değişikliğini anlat.” Perşembe günü o an geliyor ve notu görüyor. Kullanabileceği bir cümle yazıyor. Ama aile sorumlulukları yeniden başlamadan bölümü bitiremiyor. Kaydında iki bilgi de var: Cümle yazıldı, bölüm henüz tamamlanmadı. Birini ötekinin yerine koymuyor."}},move:{invitation:"Seçtiğin işi ve başlama zamanını koru. Öneriler, Emre’nin öz geçmişinden uyarlayabileceğin örnekler.",instructions:["Değişiklik gerekmiyorsa seçtiğin işi, en küçük adımı, başlama anını ve yeri koru.","Kaydetmeden önce gerçekten takıldığın an için daha küçük ne yapabileceğini belirt."],prompts:[],suggestions:{action:["Akşam yemeğinden sonra vardiya planını anlatan cümleyi yaz","Öğle yemeğinden sonra öz geçmiş ayrıntısını sor","Çaydan sonra öz geçmişte bir tarihi düzelt"],minimum:["Vardiya planıyla ilgili bir öz geçmiş cümlesi kaydet","Eksik öz geçmiş ayrıntısını soran mesajı gönder","Öz geçmişte düzelttiğin bir tarihi kaydet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Tabaklar kaldırılınca","Öğle yemeği bitince","Çayımı masaya bıraktığımda"],place:["Mutfak masamda","Öz geçmiş belgemde","Kütüphanedeki çalışma masasında"],minutes:[5,2,10],fallback:["Yaşadığın bir vardiya değişikliğini tek cümleyle anlat","Uygun başka bir fırsat seç ve belirt","Kütüphane görevlisine bilgisayar kullanıp kullanamayacağını sor"],observation:["İşaretin oluşması ve onu fark etmem","Vardiya değişikliğini anlatıp anlatmadığım","Öz geçmişte kaydettiğim düzeltme"]},suggested:{action:"Akşam yemeğinden sonra vardiya planını anlatan cümleyi yaz",minimum:"Vardiya planıyla ilgili bir öz geçmiş cümlesi kaydet",minutes:5,cueHint:"Tabaklar kaldırılınca",placeHint:"Mutfak masamda",obstacleHint:"Başlama anı geliyor ama cümleyi kurarken takılıyorum",fallbackHint:"Yaşadığın bir vardiya değişikliğini tek cümleyle anlat",observationHint:"İşaretin oluşması ve onu fark etmem"},accessibleAlternative:"Yazabilir, sesle yazdırabilir veya her zamanki araçlarını kullanabilirsin. Gerekiyorsa işin için somut yardım iste.",stopRule:"Bakım ve güvenlik sorumluluklarını koru. Bu işaret uygun olmaktan çıkarsa başka fırsat kullan."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-4-decision",scenario:"Emre’nin akşam yemeğinin sofrasını topladıktan sonra beş dakikası var. Taslağı ve doğru bir vardiya değişikliği örneği hazır. Ama cümleyi kurarken oyalanıyor.",question:"Hangi plan hem başlamaya hem takılınca ilerlemeye uyar?",options:[{id:"manifest-4-mood-cue",text:"Akşam yemeğinden sonra zihni daha açık olduğunda, en iyi örnekleriyle öz geçmiş bölümünü beş dakika düzenlemek.",feedback:"Zihninin açılması güzel olurdu. Ama bu, sürekli değişebilen bir başlama işareti. Akşam yemeğinin bittiği, fark edebileceğin anı kullan. Elindeki beş dakikaya sığacak kadar küçük bir adım seç. Hazır hissetmeyi beklemen gerekmiyor."},{id:"manifest-4-full-section",text:"Tabakları kaldırınca üç vardiya örneğini karşılaştırmak ve öz geçmiş cümlesi için en iyisini seçmek.",feedback:"Karşılaştırma seçim yapmayı kolaylaştırabilir. Ama Emre’nin doğru bir örneği zaten var. Yeni örnek aramak beş dakikayı tüketir. Önce o vardiya değişikliğini anlat. Cümle ortaya çıktıktan sonra sözcüklere bak."},{id:"manifest-4-cue-and-response",text:"Tabakları kaldırınca bir cümleyi düzeltmek; sözcüklerde takılırsa yaşadığı bir vardiya değişikliğini sade anlatmak.",feedback:"Bu plan, ne zaman başlayacağını ve takılırsa ne yapacağını ayrı ayrı belirler. Emre hazır taslağıyla deneyebilir. Plan bir adımı destekler. Çabasız hatırlama veya bütün bölümü bitirme sözü vermez. Gerçekte olanı kaydet."}],bestOptionId:"manifest-4-cue-and-response"}},carry:{takeaway:"Başlama anını seç. Takılırsan ne yapacağını belirle. Sonra ikisinin de gerçekleşip gerçekleşmediğine bak.",followUp:{questionId:"manifest-4-return",question:"Başlama işaretini fark ettin mi? Takılınca yapmayı planladığın adımı o anda atabildin mi?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Belirli bir plan neye yardım eder?",paragraphs:["Gollwitzer ve Sheeran’ın 2006 bölümü, 8.461 katılımcıyla yapılan 94 bağımsız testi birleştirdi. “Şu olursa bunu yapacağım” planlarının hedefe ulaşmadaki ortalama etkisi d = 0,65, %95 güven aralığı 0,60 ile 0,70 arasındaydı. İşler ve yöntemler farklıydı. Bu eski araştırmaların hepsi önceden kayıt altına alınmış değildi. Sonuç, kendi yazdığın herhangi bir cümlenin kesin işe yarayacağını göstermez. Ortalamayı kişisel sonucun gibi kullanma. [M02]","Fırsat planlama deneyinde öğrenciler rapora başlayacakları belirli zaman ve yeri seçti. Zamanında yazma karşılaştırması herkesi değil, raporunu geri veren ve kimliği bilinen kişileri kapsıyordu. [M10] Buradaki pratik fikir, “plan iradenin yerini alır” iddiasından daha dar. Önceden ne yapacağını seç. Sonra o an geldi mi, fark ettin mi, seçtiğin adımı atabildin mi, bunlara bak. Gerekiyorsa dışarıdan hatırlatıcı kullanmayı sürdür. Bir aracın yanına not bırakmak ODA’da bir seçenek. Notu mutlaka fark edeceğini gösteren, deneyle sınanmış bir garanti değil."]},{heading:"Aynı denemede iki ayrı ihtiyaç",paragraphs:["Başlama planın işi ne zaman deneyeceğini söyler. Engel çıkınca yapacağın şey ise gördüğün güçlüğe karşılık verir. İncelenen zihinsel karşılaştırma uygulaması engelle davranışı eşleştirdi, olağan zamanını ve yerini ekledi. Herkesin iki ayrı kurala ihtiyacı olduğunu göstermedi. [M11] Kurs bu iki işi, mevcut denemende neyin aksadığını daha kolay görebilmen için ayırıyor. Bu, araştırmada ayrıca sınanmış bir teşhis yöntemi değil. Kendi kaydına bakarak yapabileceğin sonraki seçimi netleştiriyor.","Planladığın fırsat hiç oluşmadı diyelim. O zaman engel çıkınca atmayı seçtiğin adımın başarısız olduğunu söyleyemezsin. Fırsat oluştu ama kaçırdıysan işareti veya hatırlatıcıyı değiştir. Fark ettin ama iş büyük geldiyse sonraki işe yarayan parçayı küçült. Bunlar denenecek seçeneklerdir. Tek bir özel kaydın kanıtladığı araştırma sonuçları değil. Eski kayıtları, ilk seçtiğin en küçük adımla birlikte koru. Sonraki planı değiştirmek, geçmişte yarım kalmış işi tamamlanmış yapmaz. Gerçekte ne yaptığını değerlendir. Destek alma, dinlenme, ara verme veya hedefi değiştirme seçeneklerin de kalsın."]}],sourceIds:["M02","M10","M11"]}},photo:{id:"1591462391971-9ffc57b382b9",alt:"Renkli yapışkan notlar ve kalemler"},schemaVersion:2,title:"Hazır hissetmeyi bekleyip durma",minutes:6,goal:"Fark edebileceğin bir başlama işareti seç. Takıldığın yerde küçük bir adım dene.",reading:["Başlama işareti ve engel çıkınca yapacağın şey farklı işlere yarar. “Tabaklar kalkınca bir öz geçmiş cümlesi yaz” sana fırsat verir. “Takılırsam bir vardiya değişikliğini anlat” ise o fırsatın içinde ne yapacağını söyler.","Farklı hedeflerde yapılan araştırmalar, belirli “şu olursa bunu yaparım” planlarının işi sürdürmeye ortalama destek verdiğini buldu. Bütün unutkanlığı, çabayı veya somut engelleri kaldırmazlar. Seçtiğin işi koru. Varsa kaydettiğin engeli ele al. Fark edebileceğin tek işaret ve o anda atabileceğin küçük bir adım seç. İşaret hiç oluşmazsa fırsat olmadığını kaydet ve başka bir zaman bul."],practice:["Bir engeli fark edeceğin anı “Şu olursa…” diye anlat.","“Bunu yaparım…” kısmına tek küçük davranış yaz.","Planın elindeki zamana ve araçlara uyduğunu kontrol et. Sonra bir kez prova et."],reflection:"Senin “şu olursa bunu yaparım” cümlen ne?",question:"Hangi plan gerçekten denenebilir?",options:["Her şey kendiliğinden düzelir.","Dosyayı açınca takılırsam önce başlığı yazarım.","İyi enerji gönderirsem bütün engeller kaybolur."],correct:1,feedback:"İkinci seçenek, belirli bir durumu gözlenebilen davranışla birleştiriyor. Araştırmada sınanan yaklaşım, bu tür davranış planlamasına benzer.",takeaway:"Başlama anını seç. Takılırsan ne yapacağını belirle. Sonra ikisinin de gerçekleşip gerçekleşmediğine bak.",sources:["M02","M10","M11"],deeper:[{heading:"Belirli bir plan neye yardım eder?",paragraphs:["Gollwitzer ve Sheeran’ın 2006 bölümü, 8.461 katılımcıyla yapılan 94 bağımsız testi birleştirdi. “Şu olursa bunu yapacağım” planlarının hedefe ulaşmadaki ortalama etkisi d = 0,65, %95 güven aralığı 0,60 ile 0,70 arasındaydı. İşler ve yöntemler farklıydı. Bu eski araştırmaların hepsi önceden kayıt altına alınmış değildi. Sonuç, kendi yazdığın herhangi bir cümlenin kesin işe yarayacağını göstermez. Ortalamayı kişisel sonucun gibi kullanma. [M02]","Fırsat planlama deneyinde öğrenciler rapora başlayacakları belirli zaman ve yeri seçti. Zamanında yazma karşılaştırması herkesi değil, raporunu geri veren ve kimliği bilinen kişileri kapsıyordu. [M10] Buradaki pratik fikir, “plan iradenin yerini alır” iddiasından daha dar. Önceden ne yapacağını seç. Sonra o an geldi mi, fark ettin mi, seçtiğin adımı atabildin mi, bunlara bak. Gerekiyorsa dışarıdan hatırlatıcı kullanmayı sürdür. Bir aracın yanına not bırakmak ODA’da bir seçenek. Notu mutlaka fark edeceğini gösteren, deneyle sınanmış bir garanti değil."]},{heading:"Aynı denemede iki ayrı ihtiyaç",paragraphs:["Başlama planın işi ne zaman deneyeceğini söyler. Engel çıkınca yapacağın şey ise gördüğün güçlüğe karşılık verir. İncelenen zihinsel karşılaştırma uygulaması engelle davranışı eşleştirdi, olağan zamanını ve yerini ekledi. Herkesin iki ayrı kurala ihtiyacı olduğunu göstermedi. [M11] Kurs bu iki işi, mevcut denemende neyin aksadığını daha kolay görebilmen için ayırıyor. Bu, araştırmada ayrıca sınanmış bir teşhis yöntemi değil. Kendi kaydına bakarak yapabileceğin sonraki seçimi netleştiriyor.","Planladığın fırsat hiç oluşmadı diyelim. O zaman engel çıkınca atmayı seçtiğin adımın başarısız olduğunu söyleyemezsin. Fırsat oluştu ama kaçırdıysan işareti veya hatırlatıcıyı değiştir. Fark ettin ama iş büyük geldiyse sonraki işe yarayan parçayı küçült. Bunlar denenecek seçeneklerdir. Tek bir özel kaydın kanıtladığı araştırma sonuçları değil. Eski kayıtları, ilk seçtiğin en küçük adımla birlikte koru. Sonraki planı değiştirmek, geçmişte yarım kalmış işi tamamlanmış yapmaz. Gerçekte ne yaptığını değerlendir. Destek alma, dinlenme, ara verme veya hedefi değiştirme seçeneklerin de kalsın."]}],example:{title:"Emre işareti kullanıyor",text:"Emre ortak bilgisayarın yanına not bırakıyor: “Tabaklar kalkınca bir cümleyi düzelt. Takılırsan bir vardiya değişikliğini anlat.” Perşembe günü o an geliyor ve notu görüyor. Kullanabileceği bir cümle yazıyor. Ama aile sorumlulukları yeniden başlamadan bölümü bitiremiyor. Kaydında iki bilgi de var: Cümle yazıldı, bölüm henüz tamamlanmadı. Birini ötekinin yerine koymuyor."}},{id:"manifest-5",v2:{schemaVersion:2,revision:2,id:"manifest-5",courseId:"manifest",locale:"tr",title:"Sonuç yok mu? Önce yaptıklarına bak",goal:"Deneme kayıtlarına göre yapılabilir bir sonraki adım seç. Gelecek hafta ne zaman değerlendireceğini belirle.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Hayalinden vazgeçmeden önce bak: Bu yolu gerçekten denedin mi, yoksa hep plan mı yaptın?",reason:{id:"manifest-5-reason",label:"Bu yolu sürdürmek, değiştirmek veya bırakmak için neye bakarsın?",kind:"text",maxLength:160,optional:!0,suggestions:["Kullanılabilir taslak var; başvuruyu gönder","Zamanlar hep çakışıyor; fırsatı değiştir","Somut yorum var; belirsiz cümleyi düzelt","Henüz deneme yok; ilk adımı seç"]},why:{id:"manifest-5-purpose",label:"Bu adım bu hafta ne yapmanı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı hedef için tuttuğun kayıtları oku. Planladığını, provasını yaptığını, gerçekten yaptığını ve başkalarından geleni ayır. Sakladığın taslak, taslak üzerinde çalıştığını gösterir. Başvuruyu gönderdiğini veya işverenin ilgilendiğini göstermez. Kaydında olmayan bir sonucu kendiliğinden ekleme.","138 deneyi birleştiren derlemede, ilerlemeyi daha çok izlemenin ortalama yararları bulundu. Bu kayıt biçimi veya en iyi değerlendirme aralığı doğrulanmadı. Gerçeklerden yola çık: işe yarayan adımı tekrarla, tek sorunu değiştir, yorum iste veya uygun olmayan hedefi bırak. Deneme yoksa bu boşluğu belirt. Sonra kullanabileceğin ilk küçük işi yap."],example:{title:"Emre gelecek haftayı seçiyor",text:"Emre tarihli üç düzeltmeyi ve kaçırdığı bir bilgisayar fırsatını okuyor. Öz geçmişi daha açık. Ama başvuru göndermemiş. Uygun bir ilan seçiyor, koşullarını kontrol ediyor ve hazırladığı sürümü cuma günü gönderiyor. Gönderdiğini kaydedip gelecek hafta değerlendirmek için zaman ayırıyor. Henüz yanıt yok. Kaydı başvuruyu anlatıyor, işverenin ilgisini varsaymıyor."}},move:{invitation:"İşe yarayanı koru. Sonra ne yapacağını belirt. Öneriler, hazır bir başvurudan uyarlayabileceğin örnekler.",instructions:["Tekrarlarken seçtiğin en küçük adımı ve zamanı koru. Yalnızca gördüğün sorunu değiştir.","Kaydın yoksa kaydetmeden önce ilk işini ve ona uyan en küçük adımı belirt.","Bilgi istemek, soru sormaktır. Durmuş olan işi tamamlamak değildir."],prompts:[],suggestions:{action:["Hazır başvuruyu seçtiğim iş ilanına gönder","Başvurudaki belirsiz koşulu ilgili kişiye sor","Metni okuyanın yorumuyla bir öz geçmiş cümlesini düzelt"],minimum:["Hazır başvuruyu bir kez gönder","Başvuru koşuluyla ilgili soruyu gönder","Düzelttiğin öz geçmiş cümlesini kaydet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1},{label:"İki gün sonra",daysFromToday:2}],cue:["Öğle yemeği bitince","Akşam yemeğinin sofrası toplandıktan sonra","İlanın başvuru sayfası açılınca"],place:["Mutfak masamda","Kütüphanedeki çalışma masasında","İlanın başvuru formunda"],minutes:[10,2,5],fallback:["Başvurudaki belirsiz koşulu ilgili kişiye sor","Belirsiz cümle hakkında metni okuyandan yorum iste","Gereken bilgi gelene kadar ara ver"],observation:["Gönderdiğim başvuru ve varsa gönderim onayı","Bilgi isteğim ve beklenen yanıt","Kontrolüm dışında kalan koşullar"]},suggested:{action:"Hazır başvuruyu seçtiğim iş ilanına gönder",minimum:"Hazır başvuruyu bir kez gönder",minutes:10,cueHint:"Öğle yemeği bitince",placeHint:"Mutfak masamda",obstacleHint:"Başvuruda gereken bir ayrıntı belirsiz",fallbackHint:"Başvurudaki belirsiz koşulu ilgili kişiye sor",observationHint:"Gönderdiğim başvuru ve varsa gönderim onayı"},accessibleAlternative:"Yazabilir, sesle yazdırabilir veya her zamanki araçlarını kullanabilirsin. Gerekiyorsa işin için somut yardım iste.",stopRule:"Belirsiz bir sonucu kurtarmak için harcamanı artırma veya gereken bakım ve sağlık desteğinden vazgeçme."},result:{question:"Seçtiğin en küçük adımı attın mı?",observationPrompt:"Gerçekte ne yaptın veya ortaya ne çıkardın?"},judgment:{primary:{id:"manifest-5-decision",scenario:"Emre öz geçmişini düzenlemiş ama başvurmamış. Uygun ilanın süresi bu gece doluyor. Taslağı koşulları karşılıyor. Bir kişi yarın sürümleri karşılaştırabilir.",question:"Bu değerlendirme hangi adıma götürmeli?",options:[{id:"manifest-5-next-application",text:"Hazır başvuruyu göndermek, gönderimi kaydetmek ve yanıt belirsizken daha sonraki değerlendirme zamanını seçmek.",feedback:"Kayıt, Emre’nin yapabileceği ve hazır olan somut bir sonraki adımı gösteriyor. Yapılacak iş başvuruyu göndermek. Gerçek bir yanıt gelene kadar işverenin kararı belli değil. Gönderimi sonuçtan ayrı kaydet."},{id:"manifest-5-double-editing",text:"Zayıf ifadeleri azaltmak için göndermeden önce birinden iki öz geçmiş sürümünü karşılaştırmasını istemek.",feedback:"Karşılaştırmak metindeki sorunları gösterebilir. Ama bu gecenin son tarihine yetişmez. Emre koşulları kontrol etmiş, bilinen bir eksik kalmamış. Uygun sürümü gönder. Sonraki yorumları gerçek bir değişiklik için kullan."},{id:"manifest-5-change-direction",text:"Hangi öz geçmiş sürümünü koruyacağını seçmeden önce daha çok yere ulaşmak için birkaç genel başvuru göndermek.",feedback:"Daha çok yerde iş aramak fırsat yaratabilir. Burada uygun bir başvuru zaten hazır. Onu göndermek bu eşleşmeyi sınar. Başvuru sayısını artırmak sonraki seçim olabilir. Hazır ve uygun başvurunun yerine geçmesi gerekmez."}],bestOptionId:"manifest-5-next-application"}},carry:{takeaway:"Sonraki adımı kaydına göre seç. Çaba, hazırlık ve dışarıdan gelen sonuç aynı şey değil.",followUp:{questionId:"manifest-5-return",question:"Seçtiğin işte veya bilgi isteğinde ne oldu? Hangi konu hâlâ yanıt bekliyor?",observationPrompt:"Planladığın başlama anı geldiğinde gerçekte ne oldu?",adjustmentPrompt:"Sonraki fırsatın sana uyması için hangi koşulu değiştirirsin?"}},goDeeper:{sections:[{heading:"Takip, bir sonraki kararına bilgi verir",paragraphs:["Harkin ve arkadaşlarının 2016 derlemesinde rastgele gruplara ayrılan toplam 19.951 kişiyle 138 deney vardı. Hedefe ulaşma analizi 18.398 katılımcı içeriyordu. Etki d = 0,40, %95 güven aralığı 0,32 ile 0,48 arasındaydı. Küçük çalışmaların olası etkisini kontrol eden duyarlılık düzeltmesi daha düşük tahmin verdi. Müdahaleler, hedefler ve kayıt yöntemleri farklıydı. Derleme ODA’nın kayıt özetini veya ertesi gün kartını sınamadı. Bu ortalama, senin işinde aynı yararın olacağına söz vermez. [M03]","Çalışmalar arasında ilerlemeyi yazmak veya başkalarına bildirmek daha büyük etkilerle ilişkiliydi. Bu karşılaştırmalar herkese açık paylaşımın gerekli olduğunu göstermez. Tek bir uygulama biçiminin yarara neden olduğunu da kanıtlamaz. Durumuna uyuyorsa kişisel ayrıntılarını kendine sakla. Kayıtlarına bak: ne yapmayı planlamıştın, gerçekte ne yaptığını yazdın? İkisini karşılaştır. Kayıt yoksa ne olduğu bilinmiyor. Tamamladığın hazırlık, yanıtsız istek veya bıraktığın deneme kendi adıyla kalsın. Böylece sonraki seçimin incelenebilir olur. Olumlu bir hikâye yazman veya olmayan ilerlemeyi varmış gibi göstermen gerekmez."]},{heading:"Geçmişi değiştirmeden gelecek haftayı seç",paragraphs:["Kısa bir kişisel kayıt, tekrar eden bir durum düşündürebilir. Ama dışarıdan gelen sonucun nedenini kanıtlayamaz. Başvurular, siparişler ve başkasının yanıtı kaliteye, zamana, kaynaklara veya kaydının ölçmediği koşullara bağlı olabilir. Takip araştırması bilgiyi kullanmayı destekler. Hedefini değiştirmeden önce herkesin belli sayıda deneme yapması gerektiğini göstermez. [M03] Değerlendirirken bu belirsizliği görünür tut. Tek kişinin kaydı, o sonuca neyin neden olduğunu açıklayan bir deney değil.","Gelecek hafta için yapılabilir tek bir fırsat ve değerlendirme zamanı seç. Kullanabildiğin en küçük adımı ve işe erişmeni kolaylaştıran koşulları koru. Kayıtlarında sorun gördüğün kısmı değiştir. Deneme kaydı yoksa bildiğin gerçekleri yaz veya sonraki küçük işi ilk denemen say. Yapmadığın işleri yapmış gibi yazma. Planlama çalışmaları farklı sonuçlarla birlikte ortalama yararlar gösteriyor, garanti değil. [M01] Ara vermek, yorum istemek, somut destek bulmak veya yön değiştirmek değerlendirmenin bilinçli sonucu olabilir. Önceki kaydı koru. Böylece bu seçimin nedenini daha sonra da görebilirsin."]}],sourceIds:["M03","M01"]}},photo:{id:"1762920738995-f393efe82205",alt:"Ormanda farklı yönleri gösteren ahşap yön tabelası"},schemaVersion:2,title:"Sonuç yok mu? Önce yaptıklarına bak",minutes:6,goal:"Deneme kayıtlarına göre yapılabilir bir sonraki adım seç. Gelecek hafta ne zaman değerlendireceğini belirle.",reading:["Aynı hedef için tuttuğun kayıtları oku. Planladığını, provasını yaptığını, gerçekten yaptığını ve başkalarından geleni ayır. Sakladığın taslak, taslak üzerinde çalıştığını gösterir. Başvuruyu gönderdiğini veya işverenin ilgilendiğini göstermez. Kaydında olmayan bir sonucu kendiliğinden ekleme.","138 deneyi birleştiren derlemede, ilerlemeyi daha çok izlemenin ortalama yararları bulundu. Bu kayıt biçimi veya en iyi değerlendirme aralığı doğrulanmadı. Gerçeklerden yola çık: işe yarayan adımı tekrarla, tek sorunu değiştir, yorum iste veya uygun olmayan hedefi bırak. Deneme yoksa bu boşluğu belirt. Sonra kullanabileceğin ilk küçük işi yap."],practice:["İlk küçük denemeni yap veya ne zaman yapacağını kesinleştir.","Sonuca bakmak için makul bir tarih seç. “Neyi denedim, ne öğrendim?” diye sor.","Sana uyan seçeneği belirle: sürdür, küçült, destek al veya hedefi değiştir."],reflection:"Hangi gün, hangi bilgilere bakarak planını değerlendireceksin?",question:"İstediğin sonuç gelmediğinde hangi değerlendirme daha işe yarar?",options:["Düşüncelerim yeterince güçlü değildi.","Denediğim davranışlara ve koşullara bakıp sonraki seçimi yapmak.","Gerçeklere bakmadan aynı beklentiyi sürdürmek."],correct:1,feedback:"Planla gerçeği karşılaştırmak yeni bilgi verir. Hiçbir kurs sonucu garanti etmez. Kendi yaptığınla dış koşulları birlikte değerlendirebilirsin.",takeaway:"Sonraki adımı kaydına göre seç. Çaba, hazırlık ve dışarıdan gelen sonuç aynı şey değil.",sources:["M03","M01"],deeper:[{heading:"Takip, bir sonraki kararına bilgi verir",paragraphs:["Harkin ve arkadaşlarının 2016 derlemesinde rastgele gruplara ayrılan toplam 19.951 kişiyle 138 deney vardı. Hedefe ulaşma analizi 18.398 katılımcı içeriyordu. Etki d = 0,40, %95 güven aralığı 0,32 ile 0,48 arasındaydı. Küçük çalışmaların olası etkisini kontrol eden duyarlılık düzeltmesi daha düşük tahmin verdi. Müdahaleler, hedefler ve kayıt yöntemleri farklıydı. Derleme ODA’nın kayıt özetini veya ertesi gün kartını sınamadı. Bu ortalama, senin işinde aynı yararın olacağına söz vermez. [M03]","Çalışmalar arasında ilerlemeyi yazmak veya başkalarına bildirmek daha büyük etkilerle ilişkiliydi. Bu karşılaştırmalar herkese açık paylaşımın gerekli olduğunu göstermez. Tek bir uygulama biçiminin yarara neden olduğunu da kanıtlamaz. Durumuna uyuyorsa kişisel ayrıntılarını kendine sakla. Kayıtlarına bak: ne yapmayı planlamıştın, gerçekte ne yaptığını yazdın? İkisini karşılaştır. Kayıt yoksa ne olduğu bilinmiyor. Tamamladığın hazırlık, yanıtsız istek veya bıraktığın deneme kendi adıyla kalsın. Böylece sonraki seçimin incelenebilir olur. Olumlu bir hikâye yazman veya olmayan ilerlemeyi varmış gibi göstermen gerekmez."]},{heading:"Geçmişi değiştirmeden gelecek haftayı seç",paragraphs:["Kısa bir kişisel kayıt, tekrar eden bir durum düşündürebilir. Ama dışarıdan gelen sonucun nedenini kanıtlayamaz. Başvurular, siparişler ve başkasının yanıtı kaliteye, zamana, kaynaklara veya kaydının ölçmediği koşullara bağlı olabilir. Takip araştırması bilgiyi kullanmayı destekler. Hedefini değiştirmeden önce herkesin belli sayıda deneme yapması gerektiğini göstermez. [M03] Değerlendirirken bu belirsizliği görünür tut. Tek kişinin kaydı, o sonuca neyin neden olduğunu açıklayan bir deney değil.","Gelecek hafta için yapılabilir tek bir fırsat ve değerlendirme zamanı seç. Kullanabildiğin en küçük adımı ve işe erişmeni kolaylaştıran koşulları koru. Kayıtlarında sorun gördüğün kısmı değiştir. Deneme kaydı yoksa bildiğin gerçekleri yaz veya sonraki küçük işi ilk denemen say. Yapmadığın işleri yapmış gibi yazma. Planlama çalışmaları farklı sonuçlarla birlikte ortalama yararlar gösteriyor, garanti değil. [M01] Ara vermek, yorum istemek, somut destek bulmak veya yön değiştirmek değerlendirmenin bilinçli sonucu olabilir. Önceki kaydı koru. Böylece bu seçimin nedenini daha sonra da görebilirsin."]}],example:{title:"Emre gelecek haftayı seçiyor",text:"Emre tarihli üç düzeltmeyi ve kaçırdığı bir bilgisayar fırsatını okuyor. Öz geçmişi daha açık. Ama başvuru göndermemiş. Uygun bir ilan seçiyor, koşullarını kontrol ediyor ve hazırladığı sürümü cuma günü gönderiyor. Gönderdiğini kaydedip gelecek hafta değerlendirmek için zaman ayırıyor. Henüz yanıt yok. Kaydı başvuruyu anlatıyor, işverenin ilgisini varsaymıyor."}},...m.map(b)],lang:"tr"},C=Object.freeze(Object.defineProperty({__proto__:null,COURSE:G,SOURCES:Y},Symbol.toStringTag,{value:"Module"})),x=[{id:"meditation-M01",title:"Goyal ve diğerleri · 2014 · Psikolojik stres ve iyi oluş için meditasyon programları",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"Sağlık sorunu veya stresi olan 3.515 yetişkini kapsayan 47 rastgele kontrollü çalışma, kaygı, depresyon ve ağrıda mütevazı ortalama faydalar buldu. Programlarda eğitmenin hazır bulunduğu en az dört saatlik eğitim vardı.",limitation:"Bunlar eğitmenle yürütülen programlardı; ODA’nın kısa alıştırmaları değildi. Etkin tedavilere üstünlük gösterilmedi. Bu, onlarla eşit etkiyi kanıtlamaz. Bazı sonuçlar için kanıt yetersizdi."},{id:"meditation-M03",title:"NCCIH · Meditasyon ve bilinçli farkındalık: etkililik ve güvenlik",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"Halka yönelik rehber, meditasyonu sağlık hizmetinin yerine koymamayı ve değerlendirmeyi geciktirmemeyi önerir. Zararlara ilişkin araştırma sınırlı. Beyin görüntüleri tek başına günlük hayatta sağlık faydasını göstermez.",limitation:"Bu rehber ODA’yı sınayan bir çalışma değil. Süreyi kısaltmak, gözleri açmak veya dikkati çevreye vermek güvenliği garanti etmez."},{id:"meditation-M04",title:"Farias ve diğerleri · 2020 · Meditasyon uygulamaları ve terapilerinde olumsuz deneyimler",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"Derleme, 6.703 kişiyi kapsayan, birbirinden farklı 83 çalışmayı içeriyordu; bunların 55’inde en az bir olumsuz deneyim bildirildi. Birleştirilmiş görülme oranı %8,3 idi. Deneysel ve gözlemsel çalışmalardaki tahminler belirgin biçimde farklıydı.",limitation:"Tanımlar ve deneyimleri saptama yolları farklıydı. Bu oran, kısa bir uygulama seansındaki kişisel riskini göstermez. Bildirilen her olayın meditasyondan kaynaklandığı da gösterilmedi."},{id:"meditation-M05",title:"Gollwitzer ve Sheeran · 2006 · Duruma bağlı planlar ve hedefe ulaşma",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 katılımcıyı kapsayan 94 bağımsız sınamada, tanınabilir bir durumla belirli bir davranışı eşleştiren planlar hedefe ulaşmayı ortalama olarak destekledi.",limitation:"Hedefler ve yöntemler farklıydı. Katılımcıların çoğu üniversite öğrencisiydi. Bu bulgu ODA’nın düzeninin faydasını, en iyi meditasyon süresini veya sakinleşmeyi kanıtlamaz."},{id:"meditation-M06",title:"Gan, Zhang ve Chen · 2022 · Beden taraması meditasyonunun etkileri",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"14 bağımsız rastgele kontrollü çalışma makalesinde, pasif kontrollere göre bilinçli farkındalıkta küçük fark bulundu: g = 0,268, %95 güven aralığı 0,032 ile 0,504. Tek başına beden taramasının sağlık faydası hâlâ belirsiz.",limitation:"Çalışmaların kalitesi düşük, farklılıkları büyüktü. Özet, toplam katılımcı sayısını veya sağlık etkisi tahminlerini doğrulamıyor. Beden taramasının herkeste etkisiz olduğunu ya da kısa taramanın sağlık faydasını göstermez."},{id:"meditation-M07",title:"Fischer, Messner ve Pollatos · 2017 · Beden taraması sonrası bedensel sinyalleri fark etme",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2017.00452/full",type:"research",finding:"Sekiz hafta boyunca günde yirmi dakika beden taraması, 1. çalışmada kalp atımlarını saymada sesli kitaba göre istatistiksel olarak anlamlı üstünlük göstermedi. 2. çalışmada tarama, etkin olmayan kontrolden daha iyi sonuç verdi.",limitation:"Küçük öğrenci örneklemleri; sonuçlar karşılaştırılan gruba göre değişiyor. Kalp atımlarını saymak hastalığı teşhis etmez, uyuşmayı açıklamaz veya ODA’nın kısa temas alıştırmasını doğrulamaz."},{id:"meditation-M08",title:"Hasenkamp ve diğerleri · 2012 · Odaklanmış meditasyonda zihnin dalması",url:"https://wendyhasenkamp.net/wp-content/uploads/2016/02/hasenkamp-neuroimage-2012.pdf",type:"research",finding:"Meditasyon deneyimi olan on dört kişi, MR cihazında nefese odaklanırken zihinlerinin daldığı anları işaretledi. Araştırmacılar dalmayı, bunu fark etmeyi, dikkati geri getirmeyi ve odağı sürdürmeyi modelledi.",limitation:"Küçük, keşif amaçlı bir beyin görüntüleme çalışması. Yeni başlayanlara yönelik bir müdahale değil. Beynin geliştiğini, sağlık faydasını veya ses, temas ve günlük işe geçiş uyarlamalarının etkisini göstermez."},{id:"meditation-M09",title:"Zeng ve diğerleri · 2015 · İyi dilek meditasyonu ve olumlu duygular",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"24 araştırma raporunda 1.759 kişi vardı. Bekleme listesiyle yapılan sekiz rastgele karşılaştırmada günlük olumlu duygularda mütevazı ortalama fayda bulundu. Birleştirilmiş g = 0,395 veya 0,392, aynı deneydeki alternatif ölçümleri kullandı.",limitation:"Bunlar aynı sonucu farklı ölçümlerle hesaplayan tahminler; enerjik ve sakin duyguların ayrı etkileri değil. Etkin karşılaştırmalar az. İyilik, ilişki gelişimi veya kişilik değişimi garanti edilmez. Yanlılık yüzdesinin paydası doğrulanmadı."},{id:"meditation-M11",title:"Fredrickson ve diğerleri · 2008 · İyi dilek atölyesi ve kişisel kaynaklar",url:"https://d1ftyfwtsv9bor.cloudfront.net/cbrt-readings/mod-6/fredrickson-open-hearts-build-lives-2008.pdf",type:"research",finding:"Programda yedi haftaya yayılan, eğitmenle yapılan altı seans ve evde dinlenen kayıtlar vardı. Olumlu duygulardaki haftalık değişim, çalışmayı bitiren 139 kişide gruplar arasında istatistiksel olarak anlamlı biçimde farklıydı.",limitation:"Aynı etki, başlangıçta atanan gruba göre ve protokole uyanlarla yapılan analizlerde anlamlı değildi. Dışlamalar ve bekleme listesiyle karşılaştırma, yorumu sınırlar. Kısa dilekler bu atölye değildir; davranışa aktarımın kanıtı da değildir."},{id:"meditation-M12",title:"Álvarez-Pérez ve diğerleri · 2022 · Mantraya dayalı meditasyon derlemesi",url:"https://doi.org/10.3390/ijerph19063380",type:"research",finding:"51 çalışma farklı mantra yöntemlerini kapsadı. Kaygı analizinde 25 çalışma ve 1.825 kişi vardı. Ortalama tahmin müdahaleyi destekliyordu; gelecekteki bir çalışma için tahmin aralığı fayda olmamasını da içeriyordu.",limitation:"Hiçbir çalışmanın genel yanlılık riski düşük değildi. Derleme Benson’ın tam yöntemini veya ODA’nın kısa kelime alıştırmasını doğrulamaz, üstünlük göstermez ya da ücretli eğitimi gerekli kılmaz."},{id:"meditation-M13",title:"Toth ve diğerleri · 2020 · Zihinde prova ve performans",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"Üniversitenin yayımladığı özet, iş ve beceri provasına ilişkin 37 çalışma bildiriyor. Yayın yanlılığına göre düzeltilen performans ilişkisi küçüktü: r = 0,131.",limitation:"Tam yöntemler, toplam katılımcı sayısı, güven aralığı, 115 etki sayısı ve eski karşılaştırma doğrulanmadı. Kişilik değişimini, iyileşmeyi veya ODA’nın prova ile davranışı birleştiren alıştırmasının etkisini göstermez."},{id:"meditation-M14",title:"Lally ve diğerleri · 2010 · Günlük hayatta alışkanlık oluşumu",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"96 gönüllü, yeme, içme veya hareket davranışlarını 84 gün izledi. Uygun bulunan 39 modelde, davranışın modellenen otomatiklik düzeyinin %95’ine ulaşma süresi oldukça değişkendi.",limitation:"Gözlemsel modelleme; tahminler kısmen takip süresinin ötesine uzanıyor. Ne 21 ne 66 gün bir bitiş tarihi. Araştırma meditasyon değildi. Kaçırılan fırsatlar rastgele belirlenmediğinden analiz, ilerideki aksamaların sonuçlarını garanti edemez."},{id:"meditation-M15",title:"Simonsson ve diğerleri · 2026 · Kısa meditasyonda olumsuz deneyimler",url:"https://mental.jmir.org/2026/1/e95628/",type:"research",finding:"ABD ve Birleşik Krallık’tan 5.049 yetişkin, kısa uygulamalara veya olağan internet kullanımına rastgele atandı. Meditasyonda internete göre saptanabilir ek sıkıntı görülmedi: OR 1,05, %95 güven aralığı 0,76 ile 1,47.",limitation:"Yine de sıkıntı yaşayanlar vardı. Genel %4,1 bütün grupları kapsar; yalnız meditasyonu değil. Bu ikincil analiz eşit riski, tekrarların güvenliğini veya meditasyona özgü bir süre etkisini kanıtlamaz."},{id:"meditation-M16",title:"Harvard Health · 2011 · Benson’ın gevşeme yanıtı",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Uygulayıcı rehberi, sessiz bir yerde rahat oturmayı, kişiye uygun kelime, ses, cümle veya duayı tekrarlamayı ve düşünce araya girince geri dönmeyi anlatır. Önerisi günde on ile yirmi dakikaydı.",limitation:"Blog yazısı ve kişisel anlatı; etkililik deneyi değil. Ayaklardan yüze doğru tam yönergeler, nefes verme sırası, aynı kelimeyi bir hafta kullanma şartı, dinî ve din dışı eşit etki ya da sınanmış kısa sürüm doğrulanmadı."},{id:"meditation-M17",title:"Plum Village · Yürüyüş meditasyonu",url:"https://plumvillage.org/live-events/walking-meditation",type:"technique",finding:"Geleneksel rehber ayakların yere temasına ve olağan nefese dikkat verir. Adımları nefesle eşleştirmek isteğe bağlıdır, rahat ritmi izler. Dikkat çevreyi de kapsayabilir.",limitation:"Uygulama rehberi; tek başına etkililik deneyi veya en iyi süreyi gösteren kanıt değil. Gözler açık, tehlikeler öncelikli olsun. ODA’nın oturarak ve kısa seçenekleri birer uyarlama."},{id:"meditation-M18",title:"Sharon Salzberg · Lovingkindness kitabının sayfası",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"Yazarın sayfası, iyi dilek meditasyonunun Budist geleneğindeki kökenini gösterir ve kısa iyi dileklere yer verir.",limitation:"Kitabın içeriği ve tam metinler incelenmedi. Sayfa her cümleyi veya dilek yöneltilen kişilerin sırasını doğrulamaz; klinik etkiyi de göstermez. ODA’nın sözleri ve isteğe bağlı kişi seçimi uyarlamadır."},{id:"meditation-M19",title:"David Treleaven · Travmaya duyarlı bilinçli farkındalık",url:"https://davidtreleaven.com/",type:"guidance",finding:"Eğitimci, dikkati uzun süre içe vermenin geçmişi yeniden yaşama, sıkıntı ve gerçeklikten kopma dâhil travmatik stresi harekete geçirebileceği konusunda uyarır.",limitation:"Ana sayfa ve uygulayıcı yaklaşımı; etkililik deneyi değil. Riskin sıklığını veya gözleri açık tutma, süreyi kısaltma ya da çevreye odaklanma gibi belirli değişikliklerin zararı önlediğini göstermez."},{id:"meditation-M20",title:"Joe Dispenza · Kendin Olma Alışkanlığını Kırmak · yayınevinin içindekiler sayfası",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Yayınevinin içindekiler sayfasında fark etme, dile getirme, teslim olma, yeniden yönlendirme ve yaratma veya prova aşamalarını içeren dört haftalık bir sıra var.",limitation:"Kitabın içeriği incelenmedi. Markalı programın veya ODA’nın birleşik prova alıştırmasının kontrollü doğrulaması bulunmadı. Planlama ve iş provası kanıtları kuantum, genetik, iyileşme veya kişilik iddialarını doğrulamaz."},{id:"meditation-M21",title:"Kral ve diğerleri · 2022 · MBSR sonrası yapısal beyin değişikliği saptanmaması",url:"https://doi.org/10.1126/sciadv.abk3316",type:"research",finding:"İki rastgele kontrollü çalışmada, meditasyona yeni başlayan 218 kişi yapısal beyin taramalarını tamamladı. Sekiz haftalık MBSR, kontrollere göre gri madde hacmi, yoğunluğu veya beyin kabuğu kalınlığında saptanabilir değişiklik yaratmadı.",limitation:"Bu bulgu, yapının kesin olarak yeniden düzenleneceği iddiasına karşıdır. İşlevsel değişiklik veya klinik fayda olmadığını göstermez. ODA’yı da sınamaz."},{id:"meditation-goyal",title:"Goyal ve diğerleri · 2014 · Psikolojik stres ve iyi oluş için meditasyon programları",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"Sağlık sorunu veya stresi olan 3.515 yetişkini kapsayan 47 rastgele kontrollü çalışma, kaygı, depresyon ve ağrıda mütevazı ortalama faydalar buldu. Programlarda eğitmenin hazır bulunduğu en az dört saatlik eğitim vardı.",limitation:"Bunlar eğitmenle yürütülen programlardı; ODA’nın kısa alıştırmaları değildi. Etkin tedavilere üstünlük gösterilmedi. Bu, onlarla eşit etkiyi kanıtlamaz. Bazı sonuçlar için kanıt yetersizdi."},{id:"meditation-body-scan",title:"Gan, Zhang ve Chen · 2022 · Beden taraması meditasyonunun etkileri",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"14 bağımsız rastgele kontrollü çalışma makalesinde, pasif kontrollere göre bilinçli farkındalıkta küçük fark bulundu: g = 0,268, %95 güven aralığı 0,032 ile 0,504. Tek başına beden taramasının sağlık faydası hâlâ belirsiz.",limitation:"Çalışmaların kalitesi düşük, farklılıkları büyüktü. Özet, toplam katılımcı sayısını veya sağlık etkisi tahminlerini doğrulamıyor. Beden taramasının herkeste etkisiz olduğunu ya da kısa taramanın sağlık faydasını göstermez."},{id:"meditation-lovingkindness",title:"Zeng ve diğerleri · 2015 · İyi dilek meditasyonu ve olumlu duygular",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"24 araştırma raporunda 1.759 kişi vardı. Bekleme listesiyle yapılan sekiz rastgele karşılaştırmada günlük olumlu duygularda mütevazı ortalama fayda bulundu. Birleştirilmiş g = 0,395 veya 0,392, aynı deneydeki alternatif ölçümleri kullandı.",limitation:"Bunlar aynı sonucu farklı ölçümlerle hesaplayan tahminler; enerjik ve sakin duyguların ayrı etkileri değil. Etkin karşılaştırmalar az. İyilik, ilişki gelişimi veya kişilik değişimi garanti edilmez. Yanlılık yüzdesinin paydası doğrulanmadı."},{id:"mental-practice",title:"Toth ve diğerleri · 2020 · Zihinde prova ve performans",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"Üniversitenin yayımladığı özet, iş ve beceri provasına ilişkin 37 çalışma bildiriyor. Yayın yanlılığına göre düzeltilen performans ilişkisi küçüktü: r = 0,131.",limitation:"Tam yöntemler, toplam katılımcı sayısı, güven aralığı, 115 etki sayısı ve eski karşılaştırma doğrulanmadı. Kişilik değişimini, iyileşmeyi veya ODA’nın prova ile davranışı birleştiren alıştırmasının etkisini göstermez."},{id:"meditation-adverse",title:"Farias ve diğerleri · 2020 · Meditasyon uygulamaları ve terapilerinde olumsuz deneyimler",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"Derleme, 6.703 kişiyi kapsayan, birbirinden farklı 83 çalışmayı içeriyordu; bunların 55’inde en az bir olumsuz deneyim bildirildi. Birleştirilmiş görülme oranı %8,3 idi. Deneysel ve gözlemsel çalışmalardaki tahminler belirgin biçimde farklıydı.",limitation:"Tanımlar ve deneyimleri saptama yolları farklıydı. Bu oran, kısa bir uygulama seansındaki kişisel riskini göstermez. Bildirilen her olayın meditasyondan kaynaklandığı da gösterilmedi."},{id:"meditation-nccih",title:"NCCIH · Meditasyon ve bilinçli farkındalık: etkililik ve güvenlik",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"Halka yönelik rehber, meditasyonu sağlık hizmetinin yerine koymamayı ve değerlendirmeyi geciktirmemeyi önerir. Zararlara ilişkin araştırma sınırlı. Beyin görüntüleri tek başına günlük hayatta sağlık faydasını göstermez.",limitation:"Bu rehber ODA’yı sınayan bir çalışma değil. Süreyi kısaltmak, gözleri açmak veya dikkati çevreye vermek güvenliği garanti etmez."},{id:"meditation-mind-wandering-cycle",title:"Hasenkamp ve diğerleri · 2012 · Odaklanmış meditasyonda zihnin dalması",url:"https://wendyhasenkamp.net/wp-content/uploads/2016/02/hasenkamp-neuroimage-2012.pdf",type:"research",finding:"Meditasyon deneyimi olan on dört kişi, MR cihazında nefese odaklanırken zihinlerinin daldığı anları işaretledi. Araştırmacılar dalmayı, bunu fark etmeyi, dikkati geri getirmeyi ve odağı sürdürmeyi modelledi.",limitation:"Küçük, keşif amaçlı bir beyin görüntüleme çalışması. Yeni başlayanlara yönelik bir müdahale değil. Beynin geliştiğini, sağlık faydasını veya ses, temas ve günlük işe geçiş uyarlamalarının etkisini göstermez."},{id:"meditation-trauma-sensitive",title:"David Treleaven · Travmaya duyarlı bilinçli farkındalık",url:"https://davidtreleaven.com/",type:"guidance",finding:"Eğitimci, dikkati uzun süre içe vermenin geçmişi yeniden yaşama, sıkıntı ve gerçeklikten kopma dâhil travmatik stresi harekete geçirebileceği konusunda uyarır.",limitation:"Ana sayfa ve uygulayıcı yaklaşımı; etkililik deneyi değil. Riskin sıklığını veya gözleri açık tutma, süreyi kısaltma ya da çevreye odaklanma gibi belirli değişikliklerin zararı önlediğini göstermez."},{id:"meditation-kabat-zinn",title:"Goyal ve diğerleri · 2014 · Psikolojik stres ve iyi oluş için meditasyon programları",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"Sağlık sorunu veya stresi olan 3.515 yetişkini kapsayan 47 rastgele kontrollü çalışma, kaygı, depresyon ve ağrıda mütevazı ortalama faydalar buldu. Programlarda eğitmenin hazır bulunduğu en az dört saatlik eğitim vardı.",limitation:"Bunlar eğitmenle yürütülen programlardı; ODA’nın kısa alıştırmaları değildi. Etkin tedavilere üstünlük gösterilmedi. Bu, onlarla eşit etkiyi kanıtlamaz. Bazı sonuçlar için kanıt yetersizdi."},{id:"meditation-benson",title:"Harvard Health · 2011 · Benson’ın gevşeme yanıtı",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Uygulayıcı rehberi, sessiz bir yerde rahat oturmayı, kişiye uygun kelime, ses, cümle veya duayı tekrarlamayı ve düşünce araya girince geri dönmeyi anlatır. Önerisi günde on ile yirmi dakikaydı.",limitation:"Blog yazısı ve kişisel anlatı; etkililik deneyi değil. Ayaklardan yüze doğru tam yönergeler, nefes verme sırası, aynı kelimeyi bir hafta kullanma şartı, dinî ve din dışı eşit etki ya da sınanmış kısa sürüm doğrulanmadı."},{id:"meditation-thich-nhat-hanh",title:"Plum Village · Yürüyüş meditasyonu",url:"https://plumvillage.org/live-events/walking-meditation",type:"technique",finding:"Geleneksel rehber ayakların yere temasına ve olağan nefese dikkat verir. Adımları nefesle eşleştirmek isteğe bağlıdır, rahat ritmi izler. Dikkat çevreyi de kapsayabilir.",limitation:"Uygulama rehberi; tek başına etkililik deneyi veya en iyi süreyi gösteren kanıt değil. Gözler açık, tehlikeler öncelikli olsun. ODA’nın oturarak ve kısa seçenekleri birer uyarlama."},{id:"meditation-salzberg",title:"Sharon Salzberg · Lovingkindness kitabının sayfası",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"Yazarın sayfası, iyi dilek meditasyonunun Budist geleneğindeki kökenini gösterir ve kısa iyi dileklere yer verir.",limitation:"Kitabın içeriği ve tam metinler incelenmedi. Sayfa her cümleyi veya dilek yöneltilen kişilerin sırasını doğrulamaz; klinik etkiyi de göstermez. ODA’nın sözleri ve isteğe bağlı kişi seçimi uyarlamadır."},{id:"dispenza-breaking-habit",title:"Joe Dispenza · Kendin Olma Alışkanlığını Kırmak · yayınevinin içindekiler sayfası",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Yayınevinin içindekiler sayfasında fark etme, dile getirme, teslim olma, yeniden yönlendirme ve yaratma veya prova aşamalarını içeren dört haftalık bir sıra var.",limitation:"Kitabın içeriği incelenmedi. Markalı programın veya ODA’nın birleşik prova alıştırmasının kontrollü doğrulaması bulunmadı. Planlama ve iş provası kanıtları kuantum, genetik, iyileşme veya kişilik iddialarını doğrulamaz."}],o=[{schemaVersion:2,revision:2,id:"meditation-1",courseId:"meditation",locale:"tr",title:"Yine daldın mı? Dikkatini bir kez geri getir.",goal:"Dikkatini rahat bir şeye bir kez geri getir. Ardından işe yarayan tek bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bir dakika daha kaygıyla mı geçti? Dikkatini geri getireceğin bir şey seç, sonra yapacağın işe dön.",reason:{id:"meditation-1-reason",label:"Neye dikkat vermek istiyorsun? Dağılması sana ne kaybettiriyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Yemek planlarken yazmaya ayırdığım zaman gitti","Birinin söylediğini kaçırdım","Yararlı bir işi yarım bıraktım","Henüz böyle bir fırsat olmadı"]},why:{id:"meditation-1-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Meditasyon deneyimi olanlar da zihinlerinin daldığını fark eder. Nefese odaklanılan küçük bir çalışmada araştırmacılar dalmayı, fark etmeyi, geri dönmeyi ve odakta kalmayı izledi. Çalışma, uygulama sırasındaki dikkati anlattı. Sağlığın iyileştiğini kanıtlamadı. Bu ayrımı, zihninin tamamen susmasını beklemeden kendi denemende kullanabilirsin.","Dikkatini rahatça verebildiğin bir şey seç: olağan nefesin, bir ses veya gördüğün bir nesne. Aklının nereye gittiğini fark et, sonra bir kez geri dön. İstersen gözlerin açık kalsın. Bu kısa aradan sonra seçtiğin işte veya konuşmada işe yarayan bir adım at. Dikkatini geri getirmeyi ve yaptığın işi ayrı kaydet. İkisi için de sakin olman gerekmiyor."],example:{title:"Leyla dikkatini bir kez geri getiriyor",text:"Leyla saat 13.10’da, gönüllü ekip için bir bilgilendirme notu yazmadan önce mutfak masasına oturuyor. Odadaki bir sesi dinliyor. Akşam yemeğini planlamaya daldığını fark edip sese dönüyor. Sonra notun işe yarayan ilk cümlesini yazıyor. Dikkati yine dağılıyor. Hem sese döndüğünü hem cümleyi yazdığını kaydediyor. “Zihnim sustu” diye yazmıyor."}},move:{invitation:"Seçtiğin işi koru. Gönüllü ekibin bilgi notu örneğini kendine göre düzenle.",instructions:["Rahat bir şeye odaklan. Daldığını fark edince dikkatini geri getir.","Seçtiğin yararlı adımı at. Sonra ne olduğunu kaydet."],prompts:[],suggestions:{action:["Dikkatini geri getir; bilgi notuna ilk cümleyi yaz","Dikkatini geri getir; gönüllü çalışmasının başlama saatini sor"],minimum:["Bir kez yeniden odaklan; bilgi notuna cümle yaz","Yeniden odaklan; gönüllü çalışması hakkında bir soru sor"],cue:["Öğle yemeğinden sonra, bilgi notunu yazmadan önce","Gönüllü sorumlusu soru sormamızı istediğinde"],place:["Mutfak masasında, gözlerim açık otururken","Gönüllü sorumlusuyla mesajlaştığımız ekranda"],minutes:[2,1,3],fallback:["Gördüğün bir nesneye odaklan; bilgi notunun cümlesini yaz","Ara ver ve destek seç"],observation:["Dikkatimi geri getirdim mi; cümleyi yazdım mı","Hangi odağı rahatça kullanabildiğim"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Dikkatini geri getir; bilgi notuna ilk cümleyi yaz",minimum:"Bir kez yeniden odaklan; bilgi notuna cümle yaz",minutes:2,cueHint:"Öğle yemeğinden sonra, bilgi notunu yazmadan önce",placeHint:"Mutfak masasında, gözlerim açık otururken",obstacleHint:"Nefesimi izlemek bana rahatsızlık veriyor",fallbackHint:"Gördüğün bir nesneye odaklan; bilgi notunun cümlesini yaz",observationHint:"Dikkatimi geri getirdim mi; cümleyi yazdım mı"},stopRule:"Sıkıntı artarsa, başın dönerse veya gerçeklikten kopmuş hissedersen dur. Çevrene yönel. Belirtiler sürerse ya da seni kaygılandırırsa destek al.",accessibleAlternative:"Gözlerin açık kalsın. Bir ses, gördüğün bir nesne veya otururken hissettiğin teması kullan."},result:{question:"Dikkatini geri getirip seçtiğin yararlı adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-1-decision",scenario:"Leyla’nın bir dakikalık ses alıştırması huzursuz geçiyor ama katlanılabilir. Akşam yemeği planına daldığını fark ediyor. Bilgi notunun ilk cümlesi hâlâ yazılmayı bekliyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-1-restart",text:"Bilgi notuna başlamadan önce daha iyi odaklanmak için bir dakikalık alıştırmaya yeniden başlasın.",feedback:"Baştan başlamak çekici gelebilir. Ama planladığı ara, bir odaklanma sınavı değildi. Dikkatini bir kez geri getir, planladığın gibi bitir ve işe yarayan cümleyi yaz."},{id:"meditation-1-return",text:"Sese geri dönsün, arayı bitirsin, ardından bilgi notunun ilk cümlesini yazsın.",feedback:"Bu seçim, denenen beceriyi ve amacını birlikte sınar. Huzursuz geçen bir molada da dikkatini geri getirebilirsin. Cümle, ardından ne yaptığını gösterir. Sakinleştiğini kanıtlaması gerekmez."},{id:"meditation-1-solve",text:"Bilgi notuna başlamadan önce kalan arada akşam yemeği planını netleştirsin.",feedback:"Yemeği planlamak iş bitirmek gibi gelebilir. Ama bu denemenin amacını değiştiriyor. Gerekirse düşünceyi not et, dikkatini seçtiğin şeye geri getir ve kararlaştırdığın işi yap."}],bestOptionId:"meditation-1-return"}},carry:{takeaway:"Dikkatini geri getirmeyi dene. Sonra onu kendi seçtiğin iş için kullan.",followUp:{questionId:"meditation-1-return",question:"Dikkatini geri getirdikten sonra seçtiğin işi yaptın mı, yoksa yalnızca ara mı verdin?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Deneyimli zihinler de dalar",paragraphs:["Hasenkamp ve arkadaşları, meditasyon deneyimi olan on dört kişiyi MR cihazında yirmi dakika boyunca nefese odaklanırken inceledi. Katılımcılar burun delikleri veya üst dudak çevresindeki hislere dikkat verdi. Dikkatlerinin tamamen dağıldığını fark ettiklerinde düğmeye basıp geri döndüler. Araştırmacılar dört aşama modelledi: dalma, bunu fark etme, dikkati geri çevirme ve odağı sürdürme. Bu, tek bir görevin işleyişini anlatır. Herkesin ne kadar oturması gerektiğini belirleyen bir talimat değildir. (meditation-M08)","Beyin görüntülerindeki ilişkiler, her geri dönüşün beynini yeniden düzenlediğini, zekânı artırdığını veya sağlığını değiştirdiğini göstermez. ODA’nın sesi dinleme, gözleri açık tutma ve kısa başlangıç arası, laboratuvardaki yöntemden farklıdır. Bunları isteğe bağlı uyarlamalar olarak kullan. Kaydında bir şeye dikkat vermeyi, daldığını fark etmeyi ve geri dönmeyi ayırt et. Her düşünceyi sayman gerekmiyor. Hedef tutturmak için dikkatini bilerek dağıtmana da gerek yok."]},{heading:"Kısa aranın amacı daha sınırlı",paragraphs:["Goyal’ın derlemesinde, sağlık sorunu veya stresi olan 3.515 yetişkinle yapılmış kırk yedi rastgele kontrollü çalışma vardı. Programlarda eğitmenin hazır bulunduğu en az dört saatlik eğitim yer alıyordu. Kaygı, depresyon ve ağrı sonuçları, bazı bilinçli farkındalık programlarında ortalama olarak mütevazı düzeyde daha iyiydi. Bunlar ODA’nın bir dakikalık arası için aynı sonuçları göstermez. Derlemede etkin tedavilere üstünlük bulunmadı. Bu da o tedavilerle eşit etkiyi kanıtlamaz. (meditation-M01)","Senin denemende daha dar bir soru var: rahat bir odak seçip geri dönebilir, ardından günlük bir iş için dikkatini kullanabilir misin? ODA bu birleşimi sınamadı. İşe yarayan bir cümleyi, soruyu veya ara verme kararını sağlık iddiasına çevirmeden kaydedebilirsin. NCCIH, meditasyonu sağlık hizmetinin yerine koymama ve değerlendirmeyi geciktirmeme uyarısı yapıyor. Sana önerilen tedaviyi sürdür. Uygulama veya belirtiler seni kaygılandırıyorsa uygun destek al. (meditation-M03)"]}],sourceIds:["meditation-M08","meditation-M01","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-2",courseId:"meditation",locale:"tr",title:"Rahatsızlığı görmezden gelip devam etme",goal:"Rahat bir teması dene. İşe yarayan bir düzenleme yap, sonra seçtiğin işe dön.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Rahatsız sandalyeyi yine mi görmezden geldin? İşe yarayan bir seçim yapacak kadar dikkat et.",reason:{id:"meditation-2-reason",label:"Devam etmek için hangi ihtiyacını görmezden geliyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Rahat olmayan oturma yeri","İhtiyacım olan bir mola","Değerlendirme gerektiren ağrı","Fark ettiğim bir ihtiyaç yok"]},why:{id:"meditation-2-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Beden taramasında hisleri fark edersin. Bu, tanı koymak değildir. Sekiz haftalık bir çalışmada beden taraması, kalp atımlarını sayma görevinde sesli kitap dinlemekten üstün çıkmadı. Başka bir karşılaştırmada, hiçbir şey yapmayan gruptan daha iyi sonuç verdi. Bu fark önemli. Bedenini fark etmek, daha iyi sağlığa götürdüğü kanıtlanmış bir kestirme yol değil.","Bunu yalnızca önceki odak sana zor geldiyse veya günlük bir ihtiyacını gözden kaçırdıysan kullan. Ellerin ve oturduğun yer gibi, rahat iki temas noktasını kısaca fark et. Belirgin bir his fark etmemek de gözlemdir. Gerekliyse işine yarayan bir düzenleme yap. Sonra daha önce seçtiğin aynı işi yap. İstersen dikkatini çevrende bir şeye vermeyi sürdürebilirsin."],example:{title:"Leyla sandalyeyi daha rahat hâle getiriyor",text:"Leyla bir sonraki bilgi notunu yazmadan önce ellerinin masaya, bedeninin sert sandalyeye temasını fark ediyor. Bir minder koyuyor, sonra işe yarayan bir cümle yazıyor. Omuzları hâlâ gergin. Yaptığı düzenlemeyi ve cümleyi kaydediyor. Tam beden taraması yapmaya söz vermiyor. Odadaki sesleri de kullanabileceği bir seçenek olarak tutuyor."}},move:{invitation:"Seçtiğin işi koru. Sandalye ve bilgi notu örneğini kendine uyarla.",instructions:["Rahat iki temas noktasını fark et veya dikkatini çevrendeki bir şeye ver.","İşe yarayan bir düzenleme yap. Sonra önceden seçtiğin yararlı adımı at."],prompts:[],suggestions:{action:["Sandalyeyi düzenle; bilgi notuna ilk cümleyi yaz","Teması fark et; gönüllü çalışmasının başlama saatini sor"],minimum:["Rahat teması fark et; bilgi notuna cümle yaz","Teması fark et; gönüllü çalışması için soru sor"],cue:["Gönüllü ekibin bilgi notunu yazmak için oturduğumda","Gönüllü sorumlusu soru sormamızı istediğinde"],place:["Mutfak masasında, rahat bir sandalyede","Gönüllü sorumlusuyla mesajlaştığımız ekranda"],minutes:[3,2,1],fallback:["Odadaki sesleri dinle; bilgi notunun cümlesini yaz","Ara ver ve ihtiyacına uygun destek iste"],observation:["Rahatlık için düzenleme yaptım mı; cümleyi yazdım mı","Temasa odaklanmanın rahat gelip gelmediği"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Sandalyeyi düzenle; bilgi notuna ilk cümleyi yaz",minimum:"Rahat teması fark et; bilgi notuna cümle yaz",minutes:3,cueHint:"Gönüllü ekibin bilgi notunu yazmak için oturduğumda",placeHint:"Mutfak masasında, rahat bir sandalyede",obstacleHint:"Temasa odaklanmak rahatsızlık vermeye başlıyor",fallbackHint:"Odadaki sesleri dinle; bilgi notunun cümlesini yaz",observationHint:"Rahatlık için düzenleme yaptım mı; cümleyi yazdım mı"},stopRule:"Sıkıntı artarsa dur. Yeni başlayan veya süren ağrı, uyuşma ya da kaygılandıran belirtiler için tıbbi değerlendirme gerekir.",accessibleAlternative:"Gözlerin açıkken odadaki sesleri kullan. Oturarak, hareket etmeden denemen yeterli."},result:{question:"Gereken değişikliği yapıp ardından önceden seçtiğin yararlı adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-2-decision",scenario:"Leyla masada omuzlarındaki tanıdık gerginliği fark ediyor. Ona odaklandıkça rahatsız oluyor. Bilgi notunda bir cümle hâlâ yazılmayı bekliyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-2-extend",text:"Bir düzenleme seçmeden önce gerginliği anlamak için bedeninin başka bölgelerini de tarasın.",feedback:"Daha fazla gözlem bilgi toplamak gibi gelebilir. Ama rahatsızlık artıyor ve bu alıştırma nedenini açıklayamaz. Dur veya çevrene odaklan. Ardından günlük bir çözüm seç."},{id:"meditation-2-hold",text:"Omzu gevşeyene kadar dikkatini orada tutsun, sonra bilgi notunun cümlesini yazsın.",feedback:"Gevşemeyi beklemek, başlamayı bir duyguya bağlıyor. Rahatsız eden odağı bırakabilir, ortamı düzenleyebilir ve uygunsa cümleyi yazabilirsin. Hislerinin önce değişmesi gerekmiyor."},{id:"meditation-2-adapt",text:"Odadaki seslere dönsün, sandalyeyi düzenleyip koşullar uygunsa bilgi notunun cümlesini yazsın.",feedback:"Bu seçim, rahatsızlığı dikkate alırken seçme hakkını ve işe yarayan adımı koruyor. Temas alıştırması isteğe bağlı. Hoş olmayan odağa katlanmanı veya bir hissi tanı etmeni istemiyor."}],bestOptionId:"meditation-2-adapt"}},carry:{takeaway:"Fark ettiğin ihtiyacı dikkate al. Sonraki adımını buna göre seç.",followUp:{questionId:"meditation-2-return",question:"İşe yarayan bir düzenleme yapıp ardından seçtiğin adımı attın mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Bir his, tanı değildir",paragraphs:["Fischer ve arkadaşları, küçük öğrenci örneklemlerinde sekiz hafta boyunca günde yirmi dakika rehberli beden taramasını inceledi. Kayıt, dikkati beden bölgeleri arasında gezdiriyordu. Bütün bedene dikkat verme ve kapanış aşaması da vardı. Tam metin ve bölgelere ayrılan süreler yayımlanmadı. ODA’nın kısa temas alıştırması bir uyarlamadır. Sınanan ses kaydını baştan oluşturduğumuz anlamına gelmez. Araştırmadaki yöntemin sonuçlarını bu kısa denemeye otomatik olarak aktaramayız. (meditation-M07)","1. çalışmada kalp atımlarını saymadaki değişim, sesli kitap grubundan istatistiksel olarak anlamlı düzeyde daha büyük değildi. 2. çalışmada beden taraması, etkin olmayan karşılaştırmadan daha iyi sonuç verdi. İkisi de hastalık saptamayı, her bedensel ihtiyacı doğru yorumlamayı veya bugünkü kısa alıştırmanın sağlık etkisini göstermez. “Belirgin bir his fark etmedim”, bu denemedeki dikkati anlatır. Yeni uyuşmayı başka adla anlatmak, ağrıyı önemsememek veya tıbbi değerlendirmeyi ertelemek için kullanılmamalı. Rahatlık için düzenleme yapmakla sağlık yardımı istemek farklı ihtiyaçları karşılar."]},{heading:"Sana uyana bak. Tedavi iddiasına çevirme.",paragraphs:["Gan ve arkadaşları, tek başına beden taramasına ilişkin on dört bağımsız rastgele kontrollü çalışma makalesini derledi. Pasif kontrollere göre bilinçli farkındalıkta küçük fark bildirdiler. Çalışmaların kalitesi düşüktü, sonuçlar oldukça değişkendi. Tek başına beden taramasının sağlık faydası hâlâ belirsiz. Bu, taramanın hiç kimseye yardım etmediğinin kanıtı değil. Kısa taramanın uzun olandan daha iyi olduğunu da göstermez. Bu sınırları, kendi denemende ne olduğunu yorumlarken koru. (meditation-M06)","Senin karşılaştırman, sana uyup uymadığıyla ilgili. Temasa dikkat vermek kullanabileceğin kadar rahat mıydı? Ardından işe yarayan bir seçim yaptın mı? Aynı işi koru ki odağı değiştirmek kurs içinde ayrı bir projeye dönüşmesin. Gözleri açmak, çevreye yönelmek, bazı bölgeleri atlamak ve süreyi kısaltmak önlem seçenekleridir. Doğrulanmış travma tedavisi veya kesin koruma değildir. NCCIH, sağlık hizmetini sürdürmeyi ve değerlendirmeyi geciktirmemeyi önerir. Dürüst bir ara verme kaydı; yardım, dinlenme veya uygun başka bir ortam seçmene yol gösterebilir. (meditation-M03)"]}],sourceIds:["meditation-M07","meditation-M06","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-3",courseId:"meditation",locale:"tr",title:"Nefesi izlemek zor mu? Bir kelime dene.",goal:"Önceki odak sana zor geldiyse, seçtiğin yararlı adımdan önce nötr bir kelimeyi dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"İşi yapmak yerine nefesini kontrol edip duruyor musun? Sana nötr gelen tek bir kelime dene.",reason:{id:"meditation-3-reason",label:"Bu ara seçtiğin işi destekleyecek mi, erteleyecek mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Önceki odak zor gelince işi destekler","Sakinleşip sakinleşmediğime bakarken işi erteler","Denemeden bilemiyorum"]},why:{id:"meditation-3-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Tekrarladığın kelime, dikkatin için başka bir odaktır. Daha güçlü bir komut değil. Benson’ın uygulayıcı rehberi, düşünceler araya girince seçilen kelimeye dönmeyi anlatır. Nötr bir kelime ile duanın aynı etkiyi yarattığını göstermez. Tek bir kelimeyi bir hafta boyunca kullanman gerektiğini de söylemez.","Kaydında nefes veya temasa odaklanmak zor geldiyse “burada” gibi sana uygun bir kelime dene. Nefesin doğal kalsın, bakışını zorlama. Dikkatinin dağıldığını fark edince kelimeye dön. Planladığın süre dolunca bitir ve önceden seçtiğin yararlı adımı at. Kullandığın odak zaten sana uyuyorsa onu tekrar et. Başarmış sayılmak için sakin hissetmen gerekmiyor."],example:{title:"Leyla “burada” kelimesini deniyor",text:"Leyla’nın kaydında, nefesini izlerken her nefes alışını kontrol ettiği yazıyor. Ertesi gün saat 13.10’da gözleri açık, bir dakika boyunca içinden “burada” diyor. Alışveriş düşüncesine dalınca kelimeye dönüyor. Sonra bilgi notuna bir cümle yazıyor. Kelime ona sakinleştirici olmaktan çok sıradan geliyor. Bunu kaydediyor. İşe yarayan en küçük adımı yine o cümle."}},move:{invitation:"Seçtiğin işi koru. Kelime ve bilgi notu örneğini kendine göre düzenle.",instructions:["Nefesini değiştirmeden, sana uygun tek bir kelimeye geri dön.","Arayı bitir. Ardından önceden seçtiğin yararlı adımı at."],prompts:[],suggestions:{action:["“Burada” de; bilgi notuna ilk cümleyi yaz","Odadaki sesleri dinle; gönüllü çalışmasının başlama saatini sor"],minimum:["“Burada” kelimesine dön; bilgi notunun cümlesini yaz","Dikkatini bir kez geri getir; gönüllü çalışmasını sor"],cue:["Öğle yemeğinden sonra, bilgi notunu yazmadan önce","Gönüllü sorumlusu soru sormamızı istediğinde"],place:["Mutfak masasında, gözlerim açık otururken","Gönüllü sorumlusuyla mesajlaştığımız ekranda"],minutes:[2,1,3],fallback:["Arayı bitir, ardından bilgi notunun cümlesini yaz","Arayı bitir ve destek al"],observation:["Kelimeyi kullanmak nasıldı, bilgi notunun cümlesini yazdım mı","Aradan sonra attığım işe yarayan adım"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"“Burada” de; bilgi notuna ilk cümleyi yaz",minimum:"“Burada” kelimesine dön; bilgi notunun cümlesini yaz",minutes:2,cueHint:"Öğle yemeğinden sonra, bilgi notunu yazmadan önce",placeHint:"Mutfak masasında, gözlerim açık otururken",obstacleHint:"Sakinleşip sakinleşmediğimi kontrol etmeye başlıyorum",fallbackHint:"Arayı bitir, ardından bilgi notunun cümlesini yaz",observationHint:"Kelimeyi kullanmak nasıldı, bilgi notunun cümlesini yazdım mı"},stopRule:"Sıkıntı artarsa, başın dönerse veya gerçeklikten kopmuş hissedersen dur. Çevrene yönel ve gerekirse destek al.",accessibleAlternative:"Kelime rahatsız ediyorsa bir ses veya gördüğün nesneyi seç. Gözlerin açık kalsın."},result:{question:"Planladığın arayı bitirip ardından önceden seçtiğin yararlı adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-3-decision",scenario:"Leyla’ya kelime nötr geliyor; kullanmak da rahatsız etmiyor. Yine de sakinleşip sakinleşmediğini kontrol ediyor. Planladığı bir dakika bitmek üzere.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-3-end",text:"Kelimeye geri dönsün, planladığı bir dakikayı bitirsin, sonra bilgi notunun cümlesini yazsın.",feedback:"Kelime, dikkatini vereceğin bir şey sağlıyor. Ruh hâlini ölçen bir sınav değil. Zamanında bitirmek, işe başlamaya zaman bırakır. Sakinleşmeyi şart koşma; kelimenin nasıl geldiğini ve yazdığın cümleyi kaydet."},{id:"meditation-3-switch",text:"Kalan dakikada başka bir kelime deneyip daha sakinleştirici olanı bulmaya çalışsın.",feedback:"Rahatsız eden odağı değiştirmek mantıklı olabilir. Burada kelime rahatsız etmiyor. Durmadan başka kelime aramak, farklı bir soruya cevap arıyor. İşe yarayan adımın yerini ruh hâlini kontrol etmek alabilir."},{id:"meditation-3-lengthen",text:"Kelimenin sakinleştirmeye daha çok zamanı olsun diye bir dakika daha eklesin.",feedback:"Daha uzun uygulama bir seçenek. Ama burada sakinleşmek için gerekli bir süreyi gösteren kanıt yok. Yapabileceğin arayı bitir, işi yap. Başka bir denemenin faydasını sonra değerlendirebilirsin."}],bestOptionId:"meditation-3-end"}},carry:{takeaway:"Kullanabildiğin bir odak seç. Ardından attığın yararlı adımı da ayrı değerlendir.",followUp:{questionId:"meditation-3-return",question:"Kelime sana uydu mu? Ardından seçtiğin adımı attın mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Kelime alıştırmasının kaynağı",paragraphs:["Harvard Health’in Benson’ın gevşeme yanıtını anlatan yazısında rahat oturma, sessiz ortam, seçilen kelime, ses, cümle veya dua ve düşünceler araya girince geri dönme yer alır. Uygulayıcının önerisi günde on ile yirmi dakikadır. Bu, listedeki her adımı sınayan bir deney değil, blog yazısı ve kişisel anlatıdır. Açılan sayfa, ayaklardan yüze doğru ilerleyen tam gevşeme metnini veya zorunlu bir nefes verme sırasını doğrulamıyor. (meditation-M16)","ODA’nın daha kısa kelime denemesi, gözleri açık tutma ve nötr söz seçimi birer uyarlamadır. Bu sayfa, onların tıbbi etkisini kanıtlamaz. İnancına uyuyorsa kendi içinde dua seçebilirsin. Burada dinî ve din dışı odakların aynı etkiyi verdiğini gösteren bir karşılaştırmalı deney yok. Sayfa, aynı kelimeye bir hafta bağlı kalmanın gerekli olduğunu da ortaya koymuyor. Geçmişteki yöntemi aynen yapmak yerine sana uygunluğa ve gerçekte ne yaşadığına göre seç."]},{heading:"Mantra derlemesi bu denemeden daha geniş",paragraphs:["Álvarez-Pérez ve arkadaşları, farklı mantra uygulamalarına ilişkin elli bir çalışmayı birleştirdi. Kaygı analizinde yirmi beş çalışma ve 1.825 kişi vardı. Ortalama tahmin müdahaleyi destekliyordu. Ama gelecekteki bir çalışma için tahmin aralığı, fayda görülmemesini de içeriyordu. Hiçbir çalışmanın genel yanlılık riski düşük değildi ve takip sınırlıydı. Adı olan bir yöntem herkese çözüm diye sunulduğunda bu sınırlara dikkat etmek gerekir. (meditation-M12)","Derleme, Benson’ın tam yöntemini, bugünkü bir dakikalık kelime odağını veya başka uygulamalara üstünlüğü doğrulamaz. Bu isteğe bağlı deneme için alışveriş veya ücretli eğitim gerekmez. Günlük hayattaki aynı işi koruyup tek bir odağı değiştir. Böylece neyi karşılaştırdığın belli kalır. Neyi kullandığını ve ardından ne yaptığını anlat. Tek bir iyi gün, gelişmeye kelimenin neden olduğunu kanıtlamaz. Uygulama hoşuna gitse de NCCIH’nin sağlık hizmetini sürdürme uyarısı geçerlidir. (meditation-M03)"]}],sourceIds:["meditation-M16","meditation-M12","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-4",courseId:"meditation",locale:"tr",title:"Masaya geldin. Aklın hâlâ telefonda mı?",goal:"Güvenli bir geçiş sırasında dikkatini geri getir. Vardığında seçtiğin yararlı adımı at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Masaya vardın ama aklın hâlâ telefonda mı? Yoldan masaya geçerken yapacağın işe dikkatini getir.",reason:{id:"meditation-4-reason",label:"Seçtiğin işe başlamak için vardığında hangi alışkanlığı bırakacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Mesajlara ilk cümleden sonra bakmak","Konuşmadan önce telefonu kaldırmak","İşimi engelleyen alışkanlık fark etmedim"]},why:{id:"meditation-4-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Yürürken dikkatini ayaklarının yere temasına ve doğal nefesine verebilirsin. Plum Village rehberinde adımları nefesle eşleştirmek bir seçenek. Zorunlu bir nefes oranı değil. Bu, özel bir sağlık etkisinin kanıtı değil, geleneksel bir uygulama tarifi. Dikkatini verdiğin şeyden önce çevrende olup bitenler gelir.","Önceki araya bir türlü yer açamıyorsan zaten yaptığın bir geçişi kullan. Gözlerin açık olsun, güvenli hızla ilerle. Teması yalnızca tehlikelere dikkat vermeni engellemediği yerde fark et. Oturarak, yerinde durarak yapılan sürüm de bir uyarlama olarak kullanılabilir. Vardığında önceden seçtiğin yararlı adımı at. Burada, ne kadar yavaş yürüdüğünü değil, işe nasıl vardığını ve başladığını deniyorsun."],example:{title:"Leyla kütüphanede işe başlıyor",text:"Leyla mutfaktaki başlama anını sık sık kaçırıyor. Bu kez her zamanki kütüphaneye geliş anını kullanmayı deniyor. Karşıya geçerken çevresine dikkat ediyor. Sessiz girişte birkaç adımda ayaklarının yere değdiğini fark ediyor. Masada telefonunu kaldırıp bilgi notuna işe yarayan bir cümle yazıyor. Daha sonra bir bildirim yine bölüyor. Gelişini ve cümleyi kaydediyor. Gün boyu dikkati hiç dağılmadı demiyor."}},move:{invitation:"Seçtiğin işi koru. Kütüphaneye geliş örneğini kendine göre düzenle.",instructions:["Gözlerin açık, çevren öncelikli olsun. Nefesin doğal kalsın.","Vardığın yerde önceden seçtiğin yararlı adımı at."],prompts:[],suggestions:{action:["Vardığında gönüllü ekibin bilgi notuna ilk cümleyi yaz","Vardığında gönüllü çalışmasının başlama saatini sor"],minimum:["Otururken teması fark et; bilgi notuna cümle yaz","Teması fark et; gönüllü çalışması için soru sor"],cue:["Kütüphanede masama vardığımda","Gönüllü ekibin kısa toplantısına geldiğimde"],place:["Kütüphanedeki yazı masasında","Rahatça erişebildiğim gönüllü ekip toplantı masasında"],minutes:[2,1,3],fallback:["Vardığında otururken hissettiğin teması fark et","Odağı bırak, dikkatini tehlikelere ver"],observation:["Kütüphaneye vardım mı, bilgi notunun cümlesini yazdım mı","Yola bağlı başlama fırsatı oluştu mu"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Vardığında gönüllü ekibin bilgi notuna ilk cümleyi yaz",minimum:"Otururken teması fark et; bilgi notuna cümle yaz",minutes:2,cueHint:"Kütüphanede masama vardığımda",placeHint:"Kütüphanedeki yazı masasında",obstacleHint:"Yolda bütün dikkatimi çevreye vermem gerekiyor",fallbackHint:"Vardığında otururken hissettiğin teması fark et",observationHint:"Kütüphaneye vardım mı, bilgi notunun cümlesini yazdım mı"},stopRule:"Gözlerin açık kalsın. Tehlikeler dikkatini gerektirdiğinde odak alıştırmasını bırak. Sıkıntı veya baş dönmesi artarsa dur ve destek al.",accessibleAlternative:"Oturarak, yerinde dururken ses veya temasa odaklan. Hareket etmen gerekmiyor."},result:{question:"Gideceğin yere güvenle varıp ardından seçtiğin yararlı adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-4-decision",scenario:"Leyla’nın yolunda kalabalık yaya geçitleri var. Vardığında seçtiği yazı masası boş. Ayaklarının yere temasına dikkat vermeyi planlamıştı.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-4-count",text:"Yol boyunca adım ritmini korusun, sonra masaya geçip bilgi notunun cümlesini yazsın.",feedback:"Alıştığı ritmi sürdürmek çekici gelebilir. Ama geçitlerde dikkat gerekiyor. Saymak tehlikeleri izlemeni engellediğinde bırak. Vardığın yerde işe yarayan adımı hâlâ atabilirsin."},{id:"meditation-4-arrive",text:"Geçitlerde çevresine dikkat etsin. Varınca otururken hissettiği teması fark edip bilgi notunu yazsın.",feedback:"Bu seçim güvenliği öne alıyor, seçilen başlama anını da deniyor. Oturarak teması fark etmek bir ODA uyarlaması. Denemenin değeri daha düşük değil. Bir tedaviyle aynı etkiyi verdiği de kanıtlanmış değil."},{id:"meditation-4-relocate",text:"Yazı denemesine dönmeden önce sessiz bir park yolunu kullanabileceği zamanı beklesin.",feedback:"Park başka bir uygulamaya uygun olabilir. Ama Leyla’nın işi yapacağı yer şimdi hazır. Kusursuz yolu şart koşmak yerine vardığında güvenli biçimde durup oturarak odaklanabilir."}],bestOptionId:"meditation-4-arrive"}},carry:{takeaway:"Güvenle varmak seçtiğin işe başlamana yardım etsin. Yol, bir odaklanma sınavı değil.",followUp:{questionId:"meditation-4-return",question:"Bir yerden diğerine geçmek, seçtiğin işe başlamanı kolaylaştırdı mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Ritmi yola göre seç",paragraphs:["Plum Village’in yürüyüş rehberi, ayakların yere temasına, doğal nefese ve çevredeki dünyaya dikkat verir. Adımları rahat nefes ritmiyle eşleştirme örnekleri sunar. Bu örnekler, zorlayarak tutturman gereken nefes hedefleri değildir. Sayfa bir uygulayıcı rehberidir. Tek başına yürüyüş meditasyonunun etkisini sınayan bir deney değildir. Geleneğin manevi sözleri de tıbbi iyileşmenin kanıtı sayılmaz. Adımlara dikkat vermeyi seçerken bu sınırı koru. (meditation-M17)","ODA, kısa ve tanıdık bir geçişi ancak önceki denemende bir soruna yanıt veriyorsa kullanır. Örneğin oturarak başlamak için seçtiğin an pek oluşmuyorsa. Sessiz yollar dâhil her yerde gözlerin açık kalsın. Saymak çevreni izlemeni engelliyorsa bırak. Oturarak veya yerinde durarak odaklanmak erişim için bir uyarlamadır. Bilimsel olarak eşit etkisi gösterilmiş değildir. İşe yarayan adımı vardığın yerde at. Onu yürüyüşten veya varıştaki kısa aradan ayrı kaydet."]},{heading:"Zaten yaptığın bir geçiş, başlama anın olabilir",paragraphs:["Gollwitzer ve Sheeran’ın derlemesinde, bir durumla belirli bir davranışı eşleştiren planlara ilişkin doksan dört bağımsız sınama vardı. Bu planlar farklı alanlarda hedefe ulaşmayı ortalama olarak destekledi. Katılımcıların çoğu üniversite öğrencisiydi. Derleme, kütüphaneye geliş düzeninin etkisini göstermez. Daha sınırlı bir planlama fikrini destekler: tanıyabileceğin bir fırsat ve yapabileceğin bir davranış seç. Böylece ne zaman ne yapacağını önceden belirleyebilirsin. (meditation-M05)","“Masama vardığımda dikkatimi bir kez geri getirip işe yarayan ilk cümleyi yazacağım”, hem fırsatı hem davranışı söyler. Gideceğin yer uygun değilse ilk deneme olmuş gibi yapma. Kullanabildiğin başka bir yer seç. Kalabalık yol gerçek bir kısıt; disiplin eksikliği değil. Bu uyarlama, egzersiz araştırmalarında görülen faydaları vaat etmez veya düşüncelere daha az takılmayı vaat etmez. NCCIH sağlık hizmetini sürdürmeyi önerir; zarar araştırmasının sınırlı olduğunu belirtir. Dışarıda olmak her uygulamayı sana uygun kılmaz. (meditation-M03)"]}],sourceIds:["meditation-M17","meditation-M05","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-5",courseId:"meditation",locale:"tr",title:"Sınırın kalsın. İğneleyen sözü çıkar.",goal:"Sertlik seçtiğin işe engelse, açık bir yanıttan önce isteğe bağlı tek bir iyi dilek dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yanıtına bir laf sokmak üzeresin. Söylemek istediğini koru, fazladan iğneleyen sözü çıkar.",reason:{id:"meditation-5-reason",label:"Bu yanıtta hangi sınır veya işe yarayan bilgi korunmalı?",kind:"text",maxLength:160,optional:!0,suggestions:["Pazar günü görev alamam","Gerçekte ayırabildiğim saatler","Bilgi notu için gereken ayrıntı"]},why:{id:"meditation-5-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İyi dilek meditasyonu araştırmaları, kişinin bildirdiği duyguları ölçer. Günlük davranışlarında iyiliği garanti etmez. Bir derleme, çoğunlukla bekleme listeleriyle karşılaştırıldığında olumlu duygularda mütevazı ortalama faydalar buldu. Bu, kısa bir dileğin yanıtını iyileştireceğini veya bir ilişkiyi onaracağını kanıtlamaz.","Kaydında sertliğin seçtiğin işe engel olduğunu görüyorsan bu seçeneği kullan. Kendine veya güvenli, sevdiğin birine kendi isteğinle tek bir dilek sun: “Destek bulmanı dilerim.” İçinin ısınması şart değil. Ardından önceden seçtiğin yararlı adımı at. Örneğin iğnelemeden açık bir cümle gönder. Sınırın kalsın. Dilekler canını yakıyorsa atla veya dur. Güvenli olmayan biriyle iletişim kurman hiç gerekmez."],example:{title:"Leyla sınırını açık söylüyor",text:"Leyla’nın bilgi notu, ek gönüllü çalışması için yanıt gerektiriyor. Taslağında “Bunu zaten bilmen gerekirdi” var. Mutfak masasında kız kardeşi için içinden iyi bir dilekte bulunuyor. Sonra iğneleyen kısmı çıkarıp cümlesini gönderiyor: “Cumartesi görev alabilirim ama pazar gelemem.” Hâlâ kızgın. Gönderdiği sınır cümlesini kaydediyor. İlişkiyi dileğin iyileştirdiğini söylemiyor."}},move:{invitation:"Seçtiğin işi koru. Gönüllü ekibe yanıt örneğini kendine göre düzenle.",instructions:["Kendini veya güvenli bir kişiyi seç. İçinin ısınması şart değil.","Asıl bilgiyi veya sınırını koruyarak açık cümleni kullan."],prompts:[],suggestions:{action:["Sorumluya yalnızca cumartesi görev alabileceğini söyle","Kendini suçlamadan bilgi notunun cümlesini yaz"],minimum:["Laf sokmadan cumartesi uygun olduğunu yazıp gönder","Gönüllü ekibin bilgi notuna kullanılabilir bir cümle yaz"],cue:["Gönüllü sorumlusuna yanıt vermeden önce","Öğle yemeğinden sonra, bilgi notunu yazmadan önce"],place:["Gönüllü sorumlusuyla mesajlaştığımız ekranda","Mutfaktaki yazı masasında"],minutes:[2,1,3],fallback:["Dilekleri atla; uygun olduğun günü açıkça yazıp gönder","Ara ver; korunmayı veya destek almayı seç"],observation:["Uygun olduğum günü bildirdim mi; yanıt geldi mi","Dileklerin bana uygun gelip gelmediği"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Sorumluya yalnızca cumartesi görev alabileceğini söyle",minimum:"Laf sokmadan cumartesi uygun olduğunu yazıp gönder",minutes:2,cueHint:"Gönüllü sorumlusuna yanıt vermeden önce",placeHint:"Gönüllü sorumlusuyla mesajlaştığımız ekranda",obstacleHint:"Dilek canımı yakıyor veya zoraki geliyor",fallbackHint:"Dilekleri atla; uygun olduğun günü açıkça yazıp gönder",observationHint:"Uygun olduğum günü bildirdim mi; yanıt geldi mi"},stopRule:"Sıkıntı veren dilekleri bırak. Çevrene odaklan veya destek al. Sınırlarını koru, güvenli olmayan iletişimden kaçın.",accessibleAlternative:"Gözlerin açık kalsın. Güvenli bir kişiyi, nötr sözleri veya hiç dilek söylememeyi seç."},result:{question:"Açık cümleni kullandın mı veya seçtiğin adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-5-decision",scenario:"Leyla’nın güvenle konuşabildiği gönüllü sorumlusu pazar günü çalışma istiyor. Leyla pazar görev alamaz. Taslağında iğneleyen bir söz var, hâlâ kızgın hissediyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-5-delay",text:"İyi dilek kızgınlığını değiştirene kadar hazırladığı yanıtı bir süre bekletsin.",feedback:"Bilgi eksikse beklemek yardımcı olabilir. Burada Leyla’nın uygun olduğu gün belli. İçinin ısınmasını beklemeden iğneleyen sözü çıkarıp sınırını açıkça yazıp gönderebilir. Kızgınlık önce geçmek zorunda değil."},{id:"meditation-5-accept",text:"Pazar sınırını iyice belli edeceğini düşünerek iğneleyen sözü olan yanıtı göndersin.",feedback:"Sınırının ciddiye alınmasını istemesi, laf sokmayı çekici kılıyor. Oysa uygun olduğu günü açıkça söylemek sınırı zaten bildiriyor. Ek eleştiri, korumak istediği sınırın önüne geçebilir."},{id:"meditation-5-send",text:"İğneleyen sözü çıkarsın, hangi gün uygun olduğunu açıkça yazıp şimdi göndersin.",feedback:"Bu seçim, duyguyu ön şart yapmadan kararlaştırdığı işi günlük hayata taşıyor. İsterse iyi bir dilek de sunabilir. Ne yaptığına dair kanıt, gerçekten gönderdiği cümledir."}],bestOptionId:"meditation-5-send"}},carry:{takeaway:"İsteğe bağlı bir dilek, açık bir adıma eşlik edebilir. Sınırından vazgeçmeni istemez.",followUp:{questionId:"meditation-5-return",question:"Kullandığın cümle asıl bilgiyi korudu mu? Gereksiz iğneleyici sözü çıkardın mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Olumlu duygu başka bir sonuçtur",paragraphs:["Zeng ve arkadaşları, 1.759 kişiyi kapsayan yirmi dört raporu derledi. Günlük olumlu duygu tahminine, bekleme listesiyle yapılan sekiz rastgele karşılaştırma katkı verdi. Birleştirilmiş 0,395 ve 0,392 değerleri, aynı deneydeki uyarılma düzeyine ilişkin alternatif ölçümlerden birini seçerek hesaplandı. Aynı sonucun iki tahminidirler. Enerjik ve sakin duygular üzerindeki ayrı etkiler değildirler. Etkin karşılaştırma kullanan çalışma azdı. Bu yüzden sonucu, bugün söyleyeceğin tek dileğe eşit tutma. (meditation-M09)","Başka bir erken atölyede, yedi haftaya yayılan eğitmenle altı seans ve evde dinlenen kayıtlar vardı. Olumlu duygulardaki haftalık değişim, çalışmayı bitiren 139 kişide gruplar arasında istatistiksel olarak anlamlı biçimde farklıydı. Başlangıçta atanan gruba göre ve protokole uyanlarla yapılan analizlerde ise anlamlı değildi. Dışlanan kişiler ve bekleme listesiyle karşılaştırma, çıkarımı sınırlar. Yazmadan önceki kısa dilek o atölye değildir. İki makale de dileklerin daha iyiliksever davranmanı sağladığını, bu ilişkiyi iyileştirdiğini veya örnekteki açık yanıta neden olduğunu göstermez. (meditation-M11)"]},{heading:"Niyet, seçim ve sınırlar",paragraphs:["Salzberg’in yazar sayfası, iyi dilek geleneğinin kaynağını gösterir ve kısa dilek örnekleri verir. Tam bir metin sunmaz; her cümleyi ve dilek yöneltilen kişilerin sırasını doğrulamaz. Bugünkü özgün sözler, güvenli kişi seçimi ve kısaltılmış uygulama ODA uyarlamalarıdır. Eğitmenin tam yöntemi değildir. Zor bir kişiyi seçmek isteğe bağlıdır. Dersi bitirmek için hiçbir zaman zorunlu tutulmaz. Buna göre bir kişiyi atlayabilir veya başka güvenli kişiyi seçebilirsin. (meditation-M18)","Niyet ile duygu arasındaki ayrımı koru. İçin ısınmadan dilek sunabilir, kendin yerine güvenli birini seçebilir, uygulamayı atlayabilir veya sıkıntı veriyorsa durabilirsin. Bu seçimler sınırının geçerli olup olmadığını belirlemez. Kullandığın cümleye bak: hangi bilgi gerekliydi, hangi söz laf sokuyordu, ardından nasıl bir yanıt geldi? Ruh hâlin değişmediyse veya mesajın yanıtsız kaldıysa bunu da olduğu gibi kaydet. Önceki odağın daha uygunsa onu kullan. Kurs boyunca denediğin şey, kendi seçtiğin işe yarayan adım olarak kalsın."]}],sourceIds:["meditation-M09","meditation-M11","meditation-M18"]}},{schemaVersion:2,revision:2,id:"meditation-6",courseId:"meditation",locale:"tr",title:"Yine sert tepki mi? Bir sonraki yanıtını prova et.",goal:"Tanıdık bir durum işi aksatıyorsa tek bir davranış hazırla. O an geldiğinde kullan.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yine mi sert mesajı gönderdin? O an kullanacağın cümleyi önceden prova et.",reason:{id:"meditation-6-reason",label:"Son tepkin neye mal oldu? Hangi davranışını değiştirebilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Sonra düzeltmem gereken sözler gönderdim","İşe yarayan bir fırsatı kaçırdım","Çözülmemiş ayrıntıyı belirsiz bıraktım","Önceki bir denemem yok"]},why:{id:"meditation-6-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Zihinde prova araştırması, iş ve becerilerle ilgili. Yeni bir kişilik yaratmakla değil. Otuz yedi çalışmada, yayın yanlılığına göre düzeltilen ortalama performans ilişkisi küçüktü. Duygusal teslimiyeti, düşünceyle iyileşmeyi veya üç kez tekrar etme şartını doğrulamadı.","Notlarında belirli bir durumun seçtiğin yararlı adımı engellediğini görüyorsan prova yap. O anı ve kontrolündeki tek davranışı belirle. İstersen bir kez gözünde canlandır veya hiç görüntü kurmadan cümleyi yaz. Sonra gerçek, güvenli bir fırsatta kullan. Hazırlık tek başına hazırlık kalır. O an hiç gelmezse fırsat oluşmadığını kaydet. Olmamış başarıyı yazmak veya daha sakin hissetmek zorunda değilsin."],example:{title:"Leyla geciken bilgi için soru hazırlıyor",text:"Leyla saat 09.00’da “Hâlâ ne eksik?” diye yazıyor. Çünkü geciken bilgi notları onu sık sık sert yanıta sürüklüyor. Soruyu sorduğunu kısaca hayal ediyor, ardından öğlenki konuşmada bu soruyu sormayı eylem olarak planına kaydediyor. Not gecikiyor. Soruyu sorunca bir ayrıntının çözülmediğini öğreniyor. Sorduğu soruyu kaydediyor. Kişiliğinin değiştiğini veya toplantının pürüzsüz geçtiğini söylemiyor."}},move:{invitation:"Seçtiğin işi koru. Geciken bilgi notu örneğini kendine göre düzenle.",instructions:["Kaydetmeden önce gerçek fırsatı belirle. İsteğe bağlı prova hazırlık olarak kalır.","Seçtiğin davranışı o anda kullan. Yazı yazmayı konuşmaya çevirmen gerekmez."],prompts:[],suggestions:{action:["Gönüllü sorumlusuna hâlâ neyin eksik olduğunu sor","Bilgi notuna sıradaki doğru bilgiyi anlatan cümleyi yaz"],minimum:["Hâlâ neyin eksik olduğunu sor","Bilgi notuna doğru bilgiyi anlatan bir cümle yaz"],cue:["Gönüllü ekibin bilgi notu geç geldiğinde","Gönüllü ekibin yarım kalan bilgi notunu açtığımda"],place:["Gönüllü sorumlusuyla mesajlaştığımız ekranda","Mutfaktaki yazı masasında"],minutes:[2,1,3],fallback:["“Hâlâ ne eksik?” sorusunu yazıyla ilet","Sonraki gerçek ve uygun fırsatı seç"],observation:["Gecikme, sorduğum soru ve gelen yanıt veya sessizlik","Seçtiğim davranıştan sonra ne olduğu"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Gönüllü sorumlusuna hâlâ neyin eksik olduğunu sor",minimum:"Hâlâ neyin eksik olduğunu sor",minutes:2,cueHint:"Gönüllü ekibin bilgi notu geç geldiğinde",placeHint:"Gönüllü sorumlusuyla mesajlaştığımız ekranda",obstacleHint:"Cümleyi hatırlamadan o durumla karşılaşıyorum",fallbackHint:"“Hâlâ ne eksik?” sorusunu yazıyla ilet",observationHint:"Gecikme, sorduğum soru ve gelen yanıt veya sessizlik"},stopRule:"Ortam güvenli değilse veya sıkıntı artarsa ara ver. Korunmayı, desteği veya çevrende bir şeye odaklanmayı seç.",accessibleAlternative:"Kaydetmeden önce ne yapacağını ve hangi anda kullanacağını belirle. Yazı, işaret dili ve hayal etmeden denemek geçerli."},result:{question:"Hazırladığın davranışı, fırsat gerçekten geldiğinde günlük hayatta kullandın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-6-decision",scenario:"Leyla sorusunu biliyor. Gönüllü sorumlusuyla güvenli bir konuşma fırsatı var. Bilgi notu geç geliyor; Leyla kızgın hissediyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-6-ideal",text:"Soruyu sorup sormamaya karar vermeden önce konuşmanın bütünüyle pürüzsüz geçtiğini hayal etsin.",feedback:"Pürüzsüz bir sahne güven verebilir. Ama şimdi oluşan fırsattan uzaklaştırıyor. Kullanabileceği bir soru ve güvenli bir fırsat var. Soruyu sorup gelen yanıtı kaydedebilir."},{id:"meditation-6-ask",text:"Geciken notu fark etsin. Başka yorum yapmadan önce hazırladığı soruyu sorsun.",feedback:"Bu seçim, o ana bağlı gerçek davranışı deniyor. Kızgınlık sürebilir. Prova hazırlıktı. Soruyu sormak ve yanıtı kaydetmek, günlük hayatta ne yaptığına dair kanıt sağlar."},{id:"meditation-6-rehearse",text:"Soruyu tamamen rahat söyleyebilmek için kullanmadan önce birkaç kez daha prova etsin.",feedback:"Gerçek bir beceri eksiği varsa daha çok prova yardımcı olabilir. Burada soru hazır. Ek hazırlık fırsatı kaçırmasına yol açabilir. Hislerin tamamen yatışmasını şart koşmadan bir kez sor."}],bestOptionId:"meditation-6-ask"}},carry:{takeaway:"Kullanabileceğin tek bir davranışı prova et. Sonra gerçekten kullanıp kullanmadığını kaydet.",followUp:{questionId:"meditation-6-return",question:"O an geldi mi? Yalnızca prova mı ettin, yoksa seçtiğin davranışı kullandın mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"İş provası için kanıt daha sınırlı",paragraphs:["Toth ve arkadaşlarının üniversitede yayımlanan özeti, 1995 ile 2018 arasında çıkan, zihinde provaya ilişkin otuz yedi çalışma bildiriyor. Yayın yanlılığına göre düzeltilen performans ilişkisi küçüktü: r = 0,131. Özet, tam yöntemleri, toplam katılımcı sayısını veya güven aralığını vermiyor. Daha eski karşılaştırmayı veya toplam etki sayısını da doğrulamıyor. Araştırmanın sınırını değerlendirirken erişilen bu bilgiyle yetinmek gerekir. (meditation-M13)","Bu kanıt iş ve becerilerle ilgili. Kişilik değişimini, duygusal boşalmayı veya iyileşmeyi göstermez. Bugünkü belirli fırsatı, soruyu veya isteğe bağlı tek provayı da sınamaz. Bir davranışı yazmak veya hayal etmek hazırlık olarak kaydedilebilir. Sonraki gerçek davranışın kendi denemesi ve sonucu vardır. Bunları ayrı tut ki başarılı prova, gerçekleşmemiş bir konuşmanın yerine geçmesin. Belirli bir duygu veya tekrar sayısı şart değil. Soruyu rahatça prova etmiş olmak, onu karşındaki kişiye sorduğun anlamına gelmez."]},{heading:"Değişmiş hissetmeyi beklemeden davranışını planla",paragraphs:["Gollwitzer ve Sheeran’ın hedef planlama derlemesi, farklı alanlarda tanınabilir bir durumu yapılabilir bir davranışla eşleştirmeyi destekler. Birleşik her prova düzenini doğrulamaz. “Not gecikirse neyin eksik olduğunu soracağım”, kontrolünde olan bir işi söyler. “Sakin bir lider olacağım” belirli bir işi söylemez. Buradaki zaman ve söz seçimi ODA’ya aittir. Kendi denemende de fırsatı ve kullanacağın cümleyi açıkça belirt. (meditation-M05)","Dispenza’nın yayınevinin içindekiler sayfası, dört haftalık programın aşamalarını gösteriyor. Kitabın içeriği incelenmedi ve bu birleşik programın kontrollü doğrulaması bulunmadı. Planlama ve iş provası bulguları onun teslimiyet, kuantum, genetik veya iyileşme iddialarını kanıtlayamaz. Değişmiş hissetmeyi beklemek yerine güvenli fırsatı, cümleyi denemek için kullan. Gözlenebilir bir davranış seç. Duyguların sürebilir. Gerçekte yaptığının sonucuna bak; gerekirse yol açtığın sorunu düzelt. Sana önerilen tedaviyi sürdür. (meditation-M20)"]}],sourceIds:["meditation-M13","meditation-M05","meditation-M20"]}},{schemaVersion:2,revision:2,id:"meditation-7",courseId:"meditation",locale:"tr",title:"Gününe gerçekten uyan denemeyi koru",goal:"Dikkatini geri getirdiğin ve iş yaptığın kayıtları gözden geçir. Yapılabilir sürümü koru, sonraki denemenin gününü belirle.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dersler hoşuna gitti ama düzen dağıldı mı? Gelecek hafta için gerçekten denediğin yöntemi seç.",reason:{id:"meditation-7-reason",label:"Gelecek hafta neyi koruyacak, küçültecek veya bırakacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Kütüphaneye varınca başlamayı sürdürmek","Arayı kısaltıp işi korumak","Sıkıntı veren uygulamayı bırakmak","Kayıt yok; ilk işi seçmek"]},why:{id:"meditation-7-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı koşullarda tekrar edilen davranış zamanla daha otomatik olabilir. Ama alışkanlık süresi değişir. Gözlemsel bir çalışma, meditasyonu değil günlük davranışları izledi. Modellerdeki süreler, uygulaman için yirmi bir veya altmış altı günlük bitiş tarihi belirlemiyor.","Sürdürdüğün denemeyi gözden geçir. Hangi başlama anları oluştu? Hangi odakları rahatsız olmadan kullanabildin? Ardından hangi yararlı adımları attın? Kaydın desteklediği bir sürümü koru. Kayıt yoksa ilk denemeyi planla. Gelecek hafta üç uygun fırsat seç. Bu, kursun önerisi; zorunlu uygulama süresi değil. İlkinden başla, her birini ayrı kaydet. Destek almak, dinlenmek veya bırakmak da uygun karar olabilir."],example:{title:"Leyla kendine uyan anı koruyor",text:"Leyla pazar günü üç kayda bakıyor. Mutfakta bir kez denemiş. Kütüphaneye iki gelişinde de ardından bilgi notuna bir cümle yazmış. Kütüphaneye geliş anını koruyup pazartesi kısa bir deneme planlıyor. Pazartesi odadaki sese dönüyor ve bir cümle yazıyor. Huzurlu değil, telaşlı hissediyor. Bunu kaydediyor. Sonraki günleri şimdiden yapılmış saymıyor."}},move:{invitation:"Seçtiğin işi koru. Havlu katlama örneğini kendine göre düzenle.",instructions:["Kayıtlı işini, en küçük adımı, başlama anını, yeri koru. Yoksa örnek veya ilk işini seç.","Planı değiştirdiysen kaydetmeden önce yeni başlama anını belirle.","Destek, dinlenme veya başka işi kendi en küçük adımına göre kaydet."],prompts:[],suggestions:{action:["Odadaki seslere dön; bir havlu katla","Yeniden odaklan; gönüllü ekibin bilgilendirmesini sonuna kadar dinle"],minimum:["Dikkatini bir kez geri getirip bir havlu katla","Konuşan kişi bilgi vermeyi bitirene kadar dinle"],cue:["Öğle yemeğinin bulaşıkları kaldırıldıktan sonra","Gönüllü ekibin kısa toplantısı başladığında"],place:["Mutfak masasında","Rahatça erişebildiğim gönüllü ekip toplantı masasında"],minutes:[2,1,3],fallback:["Uygun başlama anını seç; rahat kullandığın odağı koru","Yeni deneme planlamadan ara ver"],observation:["Başlama anı, dikkatimi geri getirmem ve katladığım havlu","Bilgilendirmeyi dinledim mi; konuşanın sözünü kestim mi"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Odadaki seslere dön; bir havlu katla",minimum:"Dikkatini bir kez geri getirip bir havlu katla",minutes:2,cueHint:"Öğle yemeğinin bulaşıkları kaldırıldıktan sonra",placeHint:"Mutfak masasında",obstacleHint:"Öğle yemeği sonrası başlama anı artık haftama uymuyor",fallbackHint:"Uygun başlama anını seç; rahat kullandığın odağı koru",observationHint:"Başlama anı, dikkatimi geri getirmem ve katladığım havlu"},stopRule:"Sıkıntı, baş dönmesi veya gerçeklikten kopma hissinde dur. Tekrarlayan kaygılandırıcı durumlar için yetkin bir uzmandan yardım al. Sağlık hizmetini geciktirme.",accessibleAlternative:"Çevrene odaklan, oturarak veya hareket etmeden dene. Başlama anını değiştirdiysen kaydetmeden önce belirle. Yardım için “Bunu uyarla”, ardından “Destek” seç. İsteğini ve en küçük adımını belirt."},result:{question:"Sonraki kısa sürümü veya seçtiğin destek adımını gerçekten denedin mi?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-7-decision",scenario:"Leyla’nın kayıtlarında sabahların sıkışık olduğu, kütüphaneye iki gelişinde denemenin yürüdüğü görünüyor. Gelecek hafta aynı bilgi notuna dikkatini vermek istiyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-7-restore",text:"İlk düzeni hakkıyla denemek için gelecek hafta daha uzun sabah seanslarına zaman ayırsın.",feedback:"Koşullar değiştiyse daha uzun deneme uyabilir. Ama kayıtlar şimdi sabahların sıkışık olduğunu gösteriyor. Pek oluşmayan planı büyütmeden önce gördüğün kütüphane fırsatını kullan. İlk düzeni korumak şart değil."},{id:"meditation-7-rotate",text:"İlgisini yeniden canlandıracak yöntemi bulmak için gelecek hafta her gün başka teknik seçsin.",feedback:"Araştırmak yararlı olabilir. Ama kayıtlar kullanılabilir bir odağı ve oluşan fırsatı zaten gösteriyor. Her şeyi değiştirmek, nerede takıldığını anlamayı zorlaştırır. Önce elindeki denemeye bak."},{id:"meditation-7-keep",text:"Kütüphaneye geliş anını ve rahat kullanabildiği odağı korusun. Bir sonraki cümleyi ne zaman yazacağını planlasın.",feedback:"Bu seçim, gerçek denemelerden yararlanıp yapılabilir sonraki sürümü seçiyor. Daha sonraki fırsatlar denenene kadar plan kalır. Her kayda ayrı bak. Sakinlik veya kusursuz bir hafta şart değil."}],bestOptionId:"meditation-7-keep"}},carry:{takeaway:"Rahatça kullanabildiğin odağa geri dön, işe yarayan adımı at. Gelecek haftaya kayıtların yön versin.",followUp:{questionId:"meditation-7-return",question:"Seçtiğin işte veya destek isteğinde gerçekte ne oldu? Bir sonraki uygun fırsatta neyi değiştirmek gerekiyor?",observationPrompt:"Ne yapıldı? Hangi yanıt veya sonraki adım hâlâ bekliyor?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Bir hafta, gözden geçirme aralığıdır",paragraphs:["Lally ve arkadaşları, doksan altı gönüllüyü seksen dört gün izledi. Katılımcılar tekrarlanan koşullarda yeme, içme veya hareket davranışlarını sürdürüyordu. Seksen iki kişi yeterli veri sağladı. Otuz dokuz kişinin otomatiklik modeli uygun bulundu. Tahmini süreler çok değişkendi ve kısmen gözlem süresinin ötesine uzanıyordu. Ortanca altmış altı günlük tahmin bir model sonucu. Alışkanlığın tamamlanma tarihi veya meditasyona ilişkin bulgu değil. Bu yüzden kendi uygulaman için bir son tarih olarak kullanma. (meditation-M14)","Kaçırılan fırsatlara ilişkin gözlemsel analiz, tek bir fırsattan sonra otomatiklikte istatistiksel olarak anlamlı düşüş bulmadı. Ama bu aksamalar rastgele belirlenmedi. Gelecekteki her kaçırmanın ne anlama geldiğini garanti edemez. ODA’nın üç uygun fırsatı ve haftalık değerlendirmesi birer tasarım seçimi. Başlama anı, adımın boyutu ve ortamın hayatına uyup uymadığını görmek için kullan. İlerideki tarih, yapılmış deneme değildir. Sonraki planı değiştirirken eski kayıtları koru. Bir sonraki denemenin en küçük adımını değiştirmen, önceki sözünü değiştirmez."]},{heading:"Devam planında durmaya da yer var",paragraphs:["NCCIH, sağlık hizmetinin yerine meditasyon koymamayı ve değerlendirmeyi geciktirmemeyi önerir. Zararlara ilişkin araştırmanın sınırlı olduğunu belirtir. Farias ve arkadaşlarının derlemesinde, gözlemsel raporlar ve deneyler dâhil birbirinden farklı seksen üç çalışma vardı. Birleştirilmiş %8,3 olumsuz deneyim tahmini, sonraki kısa uygulama seansının olasılığı değildir. Tanımlar, süreler ve deneyimleri saptama yolları oldukça farklıydı. Zor deneyimler, uygulamanın işe yaradığının kanıtı değil. Böyle bir deneyimi ilerleme işareti sayıp sürdürmen gerekmez. (meditation-M03; meditation-M04)","Hangi odağı korursan koru, durmak için de yolun olsun. Gözleri açık tutmak, kısa süre, çevreye odaklanmak veya oturmak önlemdir; garanti değil. Tekrarlayan sıkıntı veya gerçeklikten kopma kaygısı, yetkin bir ruh sağlığı uzmanının desteğini gerektirir. Meditasyon eğitmeni değerlendirme yerine geçmez. Dinlenme planı veya yardım isteği hayatına yeni bir seanstan daha iyi hizmet edebilir. Devam eden deneme, sana uygunluğu ve işe yarayan adımı sınar. Belirtileri iyileştirmeyi, sürekli sakinliği, kusursuz katılımı veya bütün teknikleri deneme borcunu değil."]}],sourceIds:["meditation-M14","meditation-M03","meditation-M04"]}}],M=[{id:"meditation-1",practice:["Bir dakika gibi, seçtiğin kısa bir süre güvenle otur. Zamanlayıcı isteğe bağlı.","Olağan nefes hislerini, gözlerin açıkken bir sesi veya gördüğün bir nesneyi seç.","Daldığını fark edince bir kez geri dön. Sıkıntı, baş dönmesi veya gerçeklikten kopma hissi artarsa dur."],reflection:"Dikkatin en çok nereye gitti? Geri dönmek nasıl geldi?",question:"Otururken dikkatin sürekli dağılıyorsa bu ne anlama gelir?",options:["Meditasyon bana göre değil; bırakmalıyım.","Daldığımı fark edip geri dönmek, alıştırmanın kendisi.","Zihnim tamamen boşalana kadar kendimi daha çok zorlamalıyım."],correct:1,feedback:"Zihnin dalabilir. Bilinçli farkındalık meditasyonunda amaç düşüncesiz bir zihin değil. Daldığını fark edip zorlamadan geri gelme becerisini deniyorsun.",photo:{id:"1758273240112-c7724c9bb4a5",alt:"Evde, yerde oturup gözleri kapalı meditasyon yapan genç bir kadın"}},{id:"meditation-2",practice:["Rahatça otur veya uzan. Yapabileceğin kısa bir süre seç. İstersen gözlerin açık kalsın.","İstersen rahat temas noktalarını fark et. Rahatsız bölgeleri atla veya dikkatini çevrene ver.","Gerçekte ne fark ettiğini söyle. Gerekliyse işine yarayan bir düzenleme yap. Sıkıntı artarsa dur."],reflection:"Bedeninin hangi bölümünü fark etmek sana yeni veya şaşırtıcı geldi?",question:"Beden taramasında bir bölgede hiçbir şey hissetmezsen ne yaparsın?",options:["Bir his gelene kadar o bölgeyi kasar veya hareket ettiririm.","“Burada belirgin bir his fark etmedim” deyip ilerlerim.","Yanlış yaptığımı düşünüp baştan başlarım."],correct:1,feedback:"Belirgin bir his fark etmemek, dikkatine ilişkin gözlemdir. Uyuşma tanıi değildir. Hisleri zorlama. Yeni başlayan veya süren kaygılandırıcı belirtiler için tıbbi değerlendirme gerekir.",photo:{id:"1535987271305-c26a8935f74a",alt:"Güneş altında çimlere uzanmış dinlenen bir kadın"}},{id:"meditation-3",practice:["Dikkatini bir söze vermek istiyorsan sana uygun kısa kelime, ses, cümle veya özel dua seç.","Seçtiğin kısa süre rahat otur. İstersen gözlerin açık kalsın; nefesin doğal olsun.","Düşünceler araya girince kelimene dön. Rahatsızlık artarsa dur veya çevrene yönel."],reflection:"Seçtiğin kelime sana nasıl geldi? Yarın aynısını kullanacak mısın?",question:"Benson’ın yönteminde düşünceler araya girince ne yaparsın?",options:["Düşünceyi itip zihnimi boşaltırım.","Ortada bırakırım. Bu, odaklanamadığım anlamına gelir.","Zorlamadan düşünceyi fark edip kelimeme geri dönerim."],correct:2,feedback:"Uygulayıcı rehberi, zorlamadan geri dönmeyi anlatır. Belirli bir cümle, nefes düzeni veya aynı kelimeyi bir hafta kullanma şartı koymaz. Sıkıntı artarsa dur veya uyarla.",photo:{id:"1513097847644-f00cfe868607",alt:"Güneşli bir günde ahşap iskelede sessizce oturan bir kadın"}},{id:"meditation-4",practice:["Güvenli ve tanıdık bir yol seç. İstersen oturarak, yerinde dururken teması kullan.","Gözlerin açık, tehlikeler öncelikli olsun. Doğal nefes al. Rahat adım eşleştirmesi isteğe bağlı.","Seçtiğin kısa sürede güvenli temasları veya çevreni fark et. Güvenlik dikkat gerektirince saymayı bırak."],reflection:"Yavaş yürürken daha önce fark etmediğin ne gördün veya duydun?",question:"Yürüyüş meditasyonunda adım sayısı nasıl seçilir?",options:["Herkes için sabittir: her nefeste dört adım.","Kendi nefes ritmime ve yürüme hızıma göre ayarlarım.","Amaç olabildiğince çok adım atmak."],correct:1,feedback:"İsteğe bağlı adım eşleştirmesi, rahat ve doğal ritmi izler. Gözlerin açık, çevren öncelikli olsun. Bu rehber sabit oranı veya tek başına sağlık etkisini kanıtlamaz.",photo:{id:"1477332552946-cfb384aeaf1c",alt:"Güneşli bir yolda yavaşça yürüyen bir kadın"}},{id:"meditation-5",practice:["Kendin veya güvenli, sevdiğin biri için uygun kısa dilekler seç. Sözler ODA uyarlaması.","İçinin ısınması şart değil. Kendi isteğinle dilek sun. Rahatsız ediyorsa kişileri atla veya çevrene yönel.","Zor bir kişi isteğe bağlı, hiçbir zaman gerekli değil. Sıkıntıda dur. Sınırlarını koru, güvensiz iletişimden kaçın."],reflection:"İyi dileklerini kime yöneltmek en kolaydı? Kime en zordu?",question:"Metta sırasında sıcak bir duygu hissetmiyorsan ne yaparsın?",options:["Yöntemin bana uymadığına karar verip bırakmayı seçerim.","Duyguyu zorla ortaya çıkarmaya çalışırım.","Rahatsız etmiyorsa sıcak duygu şart koşmadan kendi isteğimle sürdürebilirim."],correct:2,feedback:"İsteğe bağlı dilek için sıcak duygu şart değil. Sıkıntıya rağmen devam etmek de şart değil. Kişiyi değiştirebilir, çevrene yönelebilir veya durabilirsin. Dilekler affetmeyi veya iletişim kurmayı gerektirmez.",photo:{id:"1604881991720-f91add269bed",alt:"Masanın iki yanından birbirinin elini şefkatle tutan iki kişi"}},{id:"meditation-6",practice:["Tekrarlayan belirli bir durumu, gelen düşünceyi ve değiştirmek istediğin davranışı belirle.","İstersen güvenli bir sahnede yapılabilir tek davranışı yaz veya hayal et. Bu hazırlık; kişilik değişimi değil.","Gerçek davranışı ve anını seç: “Bu olursa şunu yapacağım.” Gerçek denemeyi ayrı kaydet."],reflection:"Eski tepkin devreye girdiği anda olmak istediğin kişi neyi farklı yapardı?",question:"Bu tekniğin hangi bölümü araştırmayla en iyi destekleniyor?",options:["Kuantum alanıyla olayları ve gerçekliği değiştirmek.","İstediğim davranışı zihnimde prova edip sonra günlük hayatta denemek.","İlaç gerekmeyecek biçimde düşünceyle hastalığı iyileştirmek."],correct:1,feedback:"Araştırma, iş ve beceri performansında küçük ortalama faydalarla ilgili. Kendini yeniden yaratma alıştırmasını veya gerçek deneme eklemenin üstünlüğünü doğrulamaz. Sağlık hizmetini sürdür. Kuantum ve iyileşme iddiaları desteklenmiyor.",photo:{id:"1631832293782-2eda7804489b",alt:"Penceresinden sabah güneşi giren, pencere önünde saksı bitkisi bulunan sessiz bir oda"}},{id:"meditation-7",practice:["Hayatına uyan bir uygulama için tanıyabileceğin başlama anı ve güvenli yer seç.","Rahatsızlık duymadan kullanabildiğin kısa sürümü seç, sonraki denemenin gününü belirle. Denemelerini yaptıktan sonra kaydet.","Çevreye odaklanma, oturma veya hareketsiz seçeneğe uygun yedek plan yaz. Gerekirse durma ve destek de olsun."],reflection:"Bu kursta sana en çok hangi teknik yardım etti? Neden?",question:"Meditasyonda sıkıntın belirgin artıyor, eski anılar seni sarsıyorsa ne yapmalısın?",options:["Durur, gözlerimi açar, ayaklarımı hisseder ve bir uzmandan destek alırım.","Daha uzun oturur, hislerin kendiliğinden geçmesini beklerim.","Bunu meditasyonun iyi gittiğinin işareti sayıp zorlamayı sürdürürüm."],correct:0,feedback:"Zor deneyimler olabilir. Ama derlemedeki toplu yüzde, kısa seansındaki kişisel riskin değil. Sıkıntı artarsa dur. Tekrarlayan kaygılandırıcı durumlarda yetkin destek al. Sağlık hizmetini veya acil yardımı geciktirme.",photo:{id:"1781255575628-d645cc39160f",alt:"Ahşap zeminde renkli yer minderleri ve örgü pufları olan sade bir köşe"}}],w={id:"meditation",title:"Aklın yine mi dağıldı? Önem verdiğin şeye dön.",subtitle:"Yedi kısa ders. Rahat bir odak dene, ardından dikkatini bir işte veya konuşmada kullan.",description:"Kendi hayatındaki işe yarayan tek bir adım için, kendi isteğinle dikkatini geri getirmeyi dene. Başka bir odağı ancak gerçek bir güçlüğüne karşılık geliyorsa kullan. Ne olduğuna bak, sana uyan sürümü koru.",scope:"Yetişkinler için meditasyon eğitimi. Tanı veya tedavi değildir; terapinin veya ilacın yerini tutmaz. Hekimine danışmadan sana önerilen tedaviyi değiştirme. Travma, psikoz veya yoğun sıkıntıda planını yetkin bir ruh sağlığı uzmanıyla yap. Eğitmen, değerlendirme yerine geçmez. Gerektiğinde gözlerini açık tut, çevrende bir şeye odaklan veya ara ver. Sıkıntı, baş dönmesi veya gerçeklikten kopma hissi artarsa dur. Süren, tekrarlayan veya kaygılandıran belirtilerde destek al. Araç kullanırken uygulama yapma. Yeni başlayan veya süren ağrı, uyuşma ya da kaygılandıran diğer belirtiler için tıbbi değerlendirme al. Kendine zarar verme düşüncelerinde gecikmeden uzman veya kriz desteği al. Acil tehlikede yerel acil yardıma ulaş.",outcome:"Seçtiğin dikkat ve eylem planı, dürüst deneme kayıtları. Gelecek hafta için sana uyan bir sürüm; ne zaman duracağın ve nasıl destek alacağın açık.",photo:{id:"1522075782449-e45a34f1ddfb",alt:"Bir bankta sessizce oturup dağ manzarasına bakan bir kadın"},lang:"tr",lessons:o.map((a,e)=>({...M[e],schemaVersion:2,v2:a,title:a.title,goal:a.goal,minutes:a.minutes.learning,reading:a.idea.paragraphs,example:a.idea.example,deeper:a.goDeeper.sections,sources:[...new Set([...a.goDeeper.sourceIds,"meditation-M03"])],takeaway:a.carry.takeaway,visual:{kind:"steps",title:"Aynı denemeyi sürdür",steps:[{label:"Başlama anı",text:"Sana uyan bir fırsat seç."},{label:"Adım",text:"İşe yarayan en küçük adımı dene."},{label:"Geri bak",text:"Ne olduğunu kaydet, sonraki denemeyi seç."}]}}))},F=Object.freeze(Object.defineProperty({__proto__:null,COURSE:w,MEDITATION_LESSONS_V2:o,SOURCES:x},Symbol.toStringTag,{value:"Module"})),P=[{id:"M01",title:"Ryan ve Deci · 2000 · Öz belirleme kuramı",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Motivasyon, yaptığın işten keyif almasan da benimsediğin değerleri yansıtabilir. Kuram, özerklik, yeterlik ve ilişki kurmayı temel ihtiyaçlar olarak önerir.",limitation:"Bu, bir kuramı ve araştırmaları anlatan derleme. ODA sorularını sınayan bir deney değil. Özerklik bağımsızlık demek değildir. Ödüller ve yükümlülükler hedefi kendiliğinden sana ait olmaktan çıkarmaz."},{id:"M02",title:"Ntoumanis ve diğerleri · 2021 · İhtiyaçları destekleyen sağlık programları",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 çalışmada, kişinin benimsediği motivasyonda ve sonraki sağlık davranışlarında mütevazı ortalama faydalar görüldü. Hemen sonraki fiziksel sağlık gelişimi istatistiksel olarak anlamlı değildi.",limitation:"İncelenen sağlık programları birden çok desteği birleştiriyor. Çalışmalar arasında ciddi farklar var; araştırma tasarımları da sınırlı. Değerlerini düşünmeye yönelten tek bir soru bu programların yerini tutmaz. Bulgular her hedef için aynı etkiyi göstermiyor."},{id:"M03",title:"Duckworth ve diğerleri · 2013 · Akademik MCII programı",url:"https://www.researchgate.net/publication/256294319_From_Fantasy_to_Action_Mental_Contrasting_With_Implementation_Intentions_MCII_Improves_Academic_Performance_in_Children",type:"research",finding:"77 beşinci sınıf öğrencisiyle yapılan deneyde, küçük gruplarda birer saatlik üç oturum ve tekrarlanan sonuç, engel, yanıt planları kullanıldı. Bazı akademik sonuçlar iyileşti.",limitation:"Araştırma tek bir okulda yapıldı. Sonraki ölçümlerde gruplar arasında istatistiksel olarak anlamlı fark bulunmadı. Destek ve süre çocuklara özgüydü. Yetişkinlerin telefondaki kısa alıştırması için gösterilmiş bir etki yok."},{id:"M04",title:"Cerasoli, Nicklin ve Ford · 2014 · Motivasyon ve teşvikler",url:"https://selfdeterminationtheory.org/wp-content/uploads/2017/06/2014_Cerasoli_Intrinsic.pdf",type:"research",finding:"183 örneklemde içten gelen motivasyon da teşvikler de performansla ilişkiliydi. İşin niteliği ve miktarı için farklı ilişki biçimleri vardı.",limitation:"Bulgular ilişkileri gösteriyor ve çalışmalara göre değişiyor. Herkes için aynı ödülü öneremez veya takdir gören bir hedefi kişinin benimsemediğini söyleyemeyiz."},{id:"M05",title:"Lally ve diğerleri · 2010 · Alışkanlık oluşumunun modellenmesi",url:"https://www.flexyourbrain.com/wp-content/uploads/2015/10/UL-STUDY-66-Days-IJSP_998-1009.pdf",type:"research",finding:"Verilere iyi uyan 39 otomatikleşme eğrisinde, modelin tahmin ettiği sabit düzeyin yüzde 95’ine ulaşmak için tahmini ortanca süre 66 gündü. Tek bir fırsatı kaçırmak modellenen süreci belirgin biçimde bozmadı.",limitation:"Gözlem 84 gün sürdü; 254 gün, gözlem süresinin dışına uzatılan bir tahmindi. Bu tahminler gözlenmiş tamamlanma tarihleri değil. Herkese uygun bir takvim sunmuyor veya uzun araların etkisini göstermiyor."},{id:"M07",title:"Wood ve Rünger · 2016 · Alışkanlık psikolojisi",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"Tekrarlanan ortamlar ve davranışlar alışkanlık öğrenmeyi destekleyebilir. Bilinçli hedefler ve alışkanlık halindeki davranışlar bir arada olabilir.",limitation:"Bu, araştırmaları anlatan bir derleme. ODA’nın küçük adım yöntemini veya bir işe günlük rutinden sonra başlama planını sınayan bir deney değil. Başlama işareti, işi yapacağını garanti etmez. Küçük işler mutlaka büyümek zorunda değil."},{id:"M08",title:"Gollwitzer ve Sheeran · 2006 · Şu olursa bunu yaparım planları",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Belirli “şu olursa bunu yapacağım” planları, 94 bağımsız sınamada hedefe ulaşmayı ortalama olarak artırdı. Geçmiş çalışmalardaki standartlaştırılmış etki d = 0,65 idi.",limitation:"Bulgular farklı hedeflerden ve eski çalışmalardan geliyor. Etki büyüklüğü yüzde 65 gelişme demek değildir. Planın kesinlikle uygulanacağını göstermez; uygulamadaki hatırlatıcının etkisi için de ölçüt olmaz."},{id:"M10",title:"Wang, Wang ve Gai · 2021 · Zihinsel karşılaştırma ve planlama",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 makaledeki 24 bağımsız etkiyi birleştiren analizde, sonuç, engel ve yanıt planları hedefe ulaşmada küçük ile orta arasında ortalama faydalar gösterdi.",limitation:"Çalışmaların farklılığı ve yayın yanlılığına işaret eden bulgular, etki büyüklüğünü yorumlamayı sınırlar. Dileklerin gerçekleşeceğini garanti etmez. Düşüncelerin dış olayları değiştirdiğini veya her WOOP biçiminin doğrulandığını göstermez."},{id:"M13",title:"Harkin ve diğerleri · 2016 · İlerlemeyi izleme",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"İzleme müdahaleleri, 138 rastgele atamalı araştırmada hedefe ulaşmayı ortalama olarak artırdı.",limitation:"Hedefler ve yöntemler farklı. Daha büyük etkilerle ilişkili özellikler, kayıt tutmanın veya paylaşmanın tek başına bu etkilere neden olduğunu göstermez. Haftalık değerlendirmenin en iyi sıklık olduğunu ya da herkesle paylaşman gerektiğini söyleyemeyiz."},{id:"M15",title:"Fogg · Tiny Habits tasarım adımları",url:"https://tinyhabits.com/design/",type:"technique",finding:"Fogg’un önerdiği yöntem, mevcut bir günlük rutini çok küçük bir davranışla eşleştirir. İşlemeyen eşleşmeleri yeniden düzenlemeyi önerir.",limitation:"Bu sayfada yöntemin bütünü için kontrollü bir etki tahmini yok. Kutlamanın şart olduğunu, bir dakikadan kısa sürenin en iyi seçenek olduğunu veya küçük işin mutlaka büyüyeceğini göstermiyor."},{id:"M20",title:"NIMH · Ruh sağlığına özen göstermek",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Uzun süren ağır veya sıkıntı veren belirtiler, ilgi kaybı veya günlük işleri tamamlayamama uzman desteğini gerektirir. Acil tehlikede hemen yardım gerekir.",limitation:"Bu, halka yönelik bir rehber. ODA’nın etkisini sınayan bir deney değil; yalnızca isteksizliğe bakarak tanı koymaz. Kaygın varsa yardım istemek için iki haftanın geçmesini, art arda uygulama yapmayı veya dersleri bitirmeyi beklemen gerekmez."},{id:"motivation-sdt",title:"Ryan ve Deci · 2000 · Öz belirleme kuramı",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Motivasyon, yaptığın işten keyif almasan da benimsediğin değerleri yansıtabilir. Kuram, özerklik, yeterlik ve ilişki kurmayı temel ihtiyaçlar olarak önerir.",limitation:"Bu, bir kuramı ve araştırmaları anlatan derleme. ODA sorularını sınayan bir deney değil. Özerklik bağımsızlık demek değildir. Ödüller ve yükümlülükler hedefi kendiliğinden sana ait olmaktan çıkarmaz."},{id:"motivation-sdt-meta",title:"Ntoumanis ve diğerleri · 2021 · İhtiyaçları destekleyen sağlık programları",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 çalışmada, kişinin benimsediği motivasyonda ve sonraki sağlık davranışlarında mütevazı ortalama faydalar görüldü. Hemen sonraki fiziksel sağlık gelişimi istatistiksel olarak anlamlı değildi.",limitation:"İncelenen sağlık programları birden çok desteği birleştiriyor. Çalışmalar arasında ciddi farklar var; araştırma tasarımları da sınırlı. Değerlerini düşünmeye yönelten tek bir soru bu programların yerini tutmaz. Bulgular her hedef için aynı etkiyi göstermiyor."},{id:"M16",title:"Fogg · Tiny Habits olumlu hareket önerisi",url:"https://tinyhabits.com/rewire/",type:"technique",finding:"Fogg, küçük davranışın hemen ardından kişinin kendi seçtiği olumlu bir hareketi önerir.",limitation:"Bu, yöntemi öneren kişinin sayfası; kontrollü bir etki tahmini sunmuyor. Kutlamanın şart olduğu, sinirsel bağlantıları daha hızlı kurduğu veya kutu işaretlemenin aynı etkiyi verdiği bağımsız araştırmayla gösterilmedi."}],d=[{schemaVersion:2,revision:2,id:"motivation-1",courseId:"motivation",locale:"tr",title:"İşi sevmiyor musun? Hedefine bir bak.",goal:"Bu hedefin ayıracağın emeğe değip değmediğine karar ver. Sonra hedefin için işe yarayan küçük bir adım dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Listedeki hedef sana pahalıya mı geliyor? Bu hafta vereceğin emeğin hayatında neyi değiştireceğine bak.",reason:{id:"motivation-1-reason",label:"Bu hedef hayatında neyi değiştirecek? Haftada ayıracağın zamana değer mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Ailem için yeni seçenekler yaratmak","Merakıma zaman ayırmak","Benimsediğim bir sorumluluğu yerine getirmek"]},why:{id:"motivation-1-why",label:"Bu hedef hayatında neyi değiştirecek? Haftada ayıracağın zamana değer mi?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir işi sevmemen, onun senin için önemsiz olduğu anlamına gelmez. Düzenli gelir için çalışmak, ailene bakmak veya bir meslek belgesi almak senin seçimin olabilir. İşi severek yapmak başka, neden yaptığını benimsemek başka. Başkalarının seni takdir etmesi de bu hedefi tek başına senin seçimin olmaktan çıkarmaz. İkisi aynı anda hayatında yer alabilir.","Hedef günlük hayatında neyi değiştirecek? Bu hafta ne kadar zamanını ya da enerjini alacak? Sürdürmeye, biçimini değiştirmeye, ertelemeye veya bırakmaya karar ver. Sürdüreceksen uygun bir anda işe yarayan küçük bir parçasını dene. Burada seçimini sınıyorsun. Gerçek niyetini ortaya çıkaran bir kişilik testi çözmüyorsun."],example:{title:"Leyla’nın ilk sorusu",text:"Saat 19.00’da Leyla iki seçeneği tartıyor: meslek belgesi için çalışmak veya ailesiyle zaman geçirmek. Dersleri sevmiyor ama belgenin açabileceği iş seçenekleri ona değerli geliyor. Hedefinden vazgeçmiyor ve mutfak masasında bir deneme sorusunu cevaplıyor. Cevabı eksik kalıyor. Denemesini kaydedip başka bir uygun an seçiyor. Çalışmaktan zevk aldığını söylemesine gerek duymuyor."}},move:{invitation:"Hedefini seç. Örneği kullanmadan önce, o hedef için ne yapacağını açıkça yaz.",instructions:["Örnekleri kendine göre düzenle. Bakım vermeyi, işi, ilişkileri veya kendi seçtiğin bir adımı düşünebilirsin.","Bu küçük işi ne zaman, neyin ardından ve nerede yapacağını planına yaz."],prompts:[{id:"motivation-1-0",label:"Bu hedefe zaman ayırınca başka neye daha az zaman kalacak?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Örnek: meslek sınavımdaki ilk deneme sorusunu cevapla","Yarın çocuğu okuldan alma saatini Merve’yle netleştir","Müşteriye yazacağım bilgi notuna bir cümle ekle","Akşam konuşmamızda Serkan’a kararlaştırdığımız soruyu sor"],minimum:["Seçtiğim deneme sorusunu cevapla","Merve’ye okuldan alma saatini mesajla bildir","Bilgi notuna işe yarayan ilk cümleyi yaz","Serkan’a bugünkü randevusunun nasıl geçtiğini sor"],cue:["Akşam yemeğinde kendi tabağımı kaldırdıktan sonra","Merve’nin okuldan alma saatiyle ilgili mesajı gelince","İşte saat 14.00 molam bittikten hemen sonra","Kararlaştırdığımız akşam konuşması başlayınca"],place:["Evde mutfak masasının başında","Her zamanki mesajlaşmamızda","İşteki bilgisayarımın başında","Her zamanki telefon görüşmemizde"],minutes:[2,1,5],fallback:["Aynı notlardan daha kısa bir soruyu cevapla","Kararlaştırdığımız iletişim yoluyla aramayı dene","Cümleyi notlarıma sesle yazdır","Kararlaştırdığımız mesajlaşma seçeneğini öner"],observation:["Yazdığım cevap ve harcadığım süre","Saati bildirdim mi? Yanıtı ayrı kaydet.","Bilgi notuna hangi işe yarar cümle eklendi","Sorduğum soru; yanıt gelmediyse bunu da yaz"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: meslek sınavımdaki ilk deneme sorusunu cevapla",minimum:"Seçtiğim deneme sorusunu cevapla",cue:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",place:"Evde mutfak masasının başında",fallback:"Aynı notlardan daha kısa bir soruyu cevapla",observation:"Yazdığım cevap ve harcadığım süre",minutes:2},{action:"Yarın çocuğu okuldan alma saatini Merve’yle netleştir",minimum:"Merve’ye okuldan alma saatini mesajla bildir",cue:"Merve’nin okuldan alma saatiyle ilgili mesajı gelince",place:"Her zamanki mesajlaşmamızda",fallback:"Kararlaştırdığımız iletişim yoluyla aramayı dene",observation:"Saati bildirdim mi? Yanıtı ayrı kaydet.",minutes:1},{action:"Müşteriye yazacağım bilgi notuna bir cümle ekle",minimum:"Bilgi notuna işe yarayan ilk cümleyi yaz",cue:"İşte saat 14.00 molam bittikten hemen sonra",place:"İşteki bilgisayarımın başında",fallback:"Cümleyi notlarıma sesle yazdır",observation:"Bilgi notuna hangi işe yarar cümle eklendi",minutes:5},{action:"Akşam konuşmamızda Serkan’a kararlaştırdığımız soruyu sor",minimum:"Serkan’a bugünkü randevusunun nasıl geçtiğini sor",cue:"Kararlaştırdığımız akşam konuşması başlayınca",place:"Her zamanki telefon görüşmemizde",fallback:"Kararlaştırdığımız mesajlaşma seçeneğini öner",observation:"Sorduğum soru; yanıt gelmediyse bunu da yaz",minutes:2}]},suggested:{action:"Örnek: meslek sınavımdaki ilk deneme sorusunu cevapla",minimum:"Seçtiğim deneme sorusunu cevapla",minutes:2,cueHint:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",placeHint:"Evde mutfak masasının başında",obstacleHint:"Örnek: bugünkü soru aileme ayırdığım zamana denk geliyor",fallbackHint:"Aynı notlardan daha kısa bir soruyu cevapla",observationHint:"Yazdığım cevap ve harcadığım süre"},stopRule:"Hastayken, tehlike içindeyken veya günlük işlerini uzun süredir yapmakta zorlanırken kendini zorlama. Şimdi destek alabilirsin.",accessibleAlternative:"Ses kaydı, sesle yazma, yardımcı araçlar veya kararlaştırılmış yardım kullan. Açıkça ara vermeyi de seçebilirsin."},result:{question:"Seçtiğin davranışı gerçekten denedin mi?",observationPrompt:"Gerçekte ne yaptın, buna ne kadar zaman veya enerji harcadın?"},judgment:{primary:{id:"motivation-1-decision",scenario:"Leyla meslek belgesi için çalışmayı sevmiyor. Ailesi için daha düzenli iş seçenekleri istiyor. İş arkadaşları da bu belgeyi değerli buluyor.",question:"Bu hedefi sürdürüp sürdürmeyeceğini nasıl sınayabilir?",options:[{id:"motivation-1-endorse",text:"Getireceği faydayı ve istediği zamanı kabul edip etmediğine baksın, sonra bir deneme sorusunu cevaplasın.",feedback:"Bu seçim, işi sevmemekle hedefi benimsememeyi ayırıyor ve yapılabilir bir davranışı sınıyor. Takdir görmekle kendi nedenin bir arada olabilir. Zamanı uymuyorsa hedefi değiştirmek veya ertelemek hâlâ Leyla’nın seçimi."},{id:"motivation-1-interest",text:"Bu belgenin hâlâ kendi hedefi olup olmadığına karar vermeden önce bir hafta daha keyifli bir hedef denesin.",feedback:"Başka bir ilgi alanını denemek yararlı olabilir. Ama keyif almak, bu hedefin Leyla’ya ait olup olmadığını tek başına söylemez. Önce benimsediği faydaya ve vereceği zamana baksın. Değerli bir iş sıkıcı kalabilir."},{id:"motivation-1-advice",text:"Belgeli iş arkadaşlarına hangi eğitimi seçeceklerini sorsun, sonra onların önerdiği meslek belgesi için çalışsın.",feedback:"İş arkadaşları seçenekleri ve gerekenleri açıklayabilir. Ama Leyla’nın neye zaman ayıracağına onun yerine karar veremezler. Öneriyi benimsemeden önce kendi nedenini ve gerçekten ayırabileceği zamanı netleştirmesi gerekir."}],bestOptionId:"motivation-1-endorse"}},carry:{takeaway:"Seçtiğin hedef zor olabilir. Değerine ve alacağı emeğe bak, sonra küçük bir parçasını dene.",followUp:{questionId:"motivation-1-return",question:"Denediğin iş seçtiğin nedene hizmet etti mi? Aldığı zaman ve enerji hâlâ buna değer mi?",observationPrompt:"Gerçekte ne yaptın, ne kadar zaman veya enerji harcadın?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Benimsemek, zevk almak zorunda olmak değildir",paragraphs:["Ryan ve Deci’nin öz belirleme kuramı, bir işi içinden gelerek sevmekle o işin nedenini benimsemeyi ayırır. Dışarıdan gelen bir hedefi zamanla değerli bulabilirsin. Meslek belgesi, gelir, bakım veya ortak bir sorumluluk, yapılan iş sıkıcı olsa da senin için önemli olabilir. Buradaki özerklik, hiçbir yükümlülüğün veya dış etki olmaması değil, seçim yapabildiğini hissetmektir. 2000 tarihli yazıları bir kuram ve anlatı derlemesidir. Bu dersin sınandığı bir deney değildir. [M01]","Bu dersteki sürdür, değiştir, ertele veya bırak seçimi ODA’nın düşünme alıştırmasıdır. Saf niyetleri ortaya çıkarmaz, bir hedefin gerçekten sana ait olduğunu onaylamaz. Cerasoli ve çalışma arkadaşlarının büyük meta-analizinde, içten gelen motivasyon da teşvikler de performansla ilişkiliydi. İşin niteliği ve miktarı için ilişki farklıydı. Sonuçlar ödüllerin her koşulda iyi ya da kötü olduğunu söylemiyor. [M04] Birden çok nedenin olduğunu kabul edebilirsin. Yine de bu davranışın istediğin hayata hizmet edip etmediğine kendin karar verebilirsin."]},{heading:"Tek bir soru, bütün programın yerini tutmaz",paragraphs:["Ntoumanis ve çalışma arkadaşları, öz belirleme kuramından yararlanan 73 sağlık müdahalesi çalışmasını birleştirdi. Kişinin benimsediği motivasyonda ve sonraki sağlık davranışlarında ortalama olarak mütevazı faydalar buldular. Programlarda birden çok destek vardı; sonuçlar ciddi ölçüde farklılaşıyordu. Hemen sonraki fiziksel sağlık gelişimi istatistiksel olarak anlamlı değildi. Bu sonuçlar her meslek, eğitim veya kişisel hedef için aynı faydayı göstermiyor. [M02]","Nedenini soran tek bir cümle o programların yerini tutamaz. Burada nedenin sana küçük bir denemede yol gösteriyor: bir hedef, gerçekten yapılan bir iş, dürüst bir kayıt ve sonraki uygun an. İlk denemede heves şartı koymadan uygunluğa, erişime ve harcadığın emeğe bak. İstersen ayrıntıları kendine sakla. Sonraki derslerde aynı yönü koruyup işe yarayan küçük bir adımı, kullanılabilir bir başlama işaretini ve gerçek bir engele vereceğin yanıtı sınayacaksın. Hedefini veya koşullarını yeniden değerlendirmen gerekiyorsa ara vermek ya da destek istemek de geçerli bir seçimdir."]}],sourceIds:["M01","M04","M02"]}},{schemaVersion:2,revision:2,id:"motivation-2",courseId:"motivation",locale:"tr",title:"Kitabı yine açıp okumadan kapattın mı?",goal:"Seçtiğin işin küçük bir kısmını dene. Küçük olsun ama yine de işine yarasın.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kitabı açtın ama okumadın mı? İşe yarayan kısmı bugün yapabileceğin kadar küçült.",reason:{id:"motivation-2-useful-unit-cost",label:"İşe yarayan kısma yer açmak için hangi hazırlığı bırakabilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Tekrar açmayı bırak, bir cümle oku","Düzenlemeyi bırak, bir cümle yaz","İş kalsın, boyutu küçülsün"]},why:{id:"motivation-2-why",label:"Seçtiğin nedene hizmet eden en küçük yararlı iş ne?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin hedefi koru. Yapacağın işi bugüne sığacak kadar küçült. İşe yarayan kısmını koru. Kitabı elinin altına koy, sonra bir cümle oku. Başvuru dosyasını aç, sonra işe yarayan bir cümle yaz. Malzemeleri hazırlamak hazırlıktır. Okuduğun ya da yazdığın cümle ise denemek istediğin davranışın kendisidir. Birbirinin yerine geçmezler. İkisini ayrı ayrı kaydedebilirsin.","Alışkanlık araştırmaları, tekrarlanan koşullarda yapılan davranışlara bakar. Her küçük başlangıcın büyüyeceğini ya da kutucuğu işaretlemenin kutlamayla aynı etkiyi yaratacağını göstermez. En küçük adımın küçük kalabilir. Bir kez dene, gerçekte ne olduğunu kaydet. Sonra bu miktarın seçtiğin nedene hâlâ hizmet edip etmediğine bak."],example:{title:"Leyla’nın daha küçük sorusu",text:"Salı akşamı yemekten sonra Leyla’nın aynı meslek belgesi için iki dakikası var. Notlarını elinin altına koyuyor, sonra kısa bir deneme sorusunu cevaplıyor. Ailesine ayırdığı zaman da önemli olduğu için orada duruyor. Cevabını düzeltmesi gerekiyor. Süreyi uzatmadan, yazdığı cevabı çalışma olarak kaydediyor. Notları önüne koymasını ise ayrı bir hazırlık olarak tutuyor."}},move:{invitation:"Aynı işi sürdür. Planını kaydetmeden önce işe yarayan en küçük kısmını seç.",instructions:["İşi ve yapabildiğin ortamı değiştirme. Yalnızca ne kadarını yapacağını yeniden seç.","Gereken malzemeyi elinin altına koy, sonra o küçük işi gerçekten yap."],prompts:[],suggestions:{action:["Örnek: meslek sınavımdaki sıradaki soruyu cevapla","Kaydettiğim başvuru metninin o paragrafını yaz","Üzerime aldığım mutfak temizliğini yap"],minimum:["O sorunun ilk bölümüne bir cevap yaz","O paragrafa işe yarayan bir cümle yaz","Kararlaştırdığımız iki kupayı yıka"],cue:["Akşam yemeğinde kendi tabağımı kaldırdıktan sonra","İşte saat 14.00 molam bittikten hemen sonra","Birlikte yediğimiz yemek bittikten hemen sonra"],place:["Evde mutfak masasının başında","İşteki bilgisayarımın başında","Kullanabildiğim mutfak lavabosunda"],minutes:[2,1],fallback:["Kullanabildiğim notlardan ilk bölümün cevabını sesle yazdır","Notlarıma işe yarayan bir cümleyi sesle yazdır","Kararlaştırdığımız, yapabileceğim başka bir temizlik işini seç"],observation:["Cevap yazıldı mı, yalnızca malzemeler mi hazırlandı","Cümle yazıldı mı, yalnızca dosya mı açıldı","İş yapıldı mı, yalnızca malzemeler mi dizildi"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: meslek sınavımdaki sıradaki soruyu cevapla",minimum:"O sorunun ilk bölümüne bir cevap yaz",cue:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",place:"Evde mutfak masasının başında",fallback:"Kullanabildiğim notlardan ilk bölümün cevabını sesle yazdır",observation:"Cevap yazıldı mı, yalnızca malzemeler mi hazırlandı",minutes:2},{action:"Kaydettiğim başvuru metninin o paragrafını yaz",minimum:"O paragrafa işe yarayan bir cümle yaz",cue:"İşte saat 14.00 molam bittikten hemen sonra",place:"İşteki bilgisayarımın başında",fallback:"Notlarıma işe yarayan bir cümleyi sesle yazdır",observation:"Cümle yazıldı mı, yalnızca dosya mı açıldı",minutes:1},{action:"Üzerime aldığım mutfak temizliğini yap",minimum:"Kararlaştırdığımız iki kupayı yıka",cue:"Birlikte yediğimiz yemek bittikten hemen sonra",place:"Kullanabildiğim mutfak lavabosunda",fallback:"Kararlaştırdığımız, yapabileceğim başka bir temizlik işini seç",observation:"İş yapıldı mı, yalnızca malzemeler mi dizildi",minutes:2}]},suggested:{action:"Örnek: meslek sınavımdaki sıradaki soruyu cevapla",minimum:"O sorunun ilk bölümüne bir cevap yaz",minutes:2,cueHint:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",placeHint:"Evde mutfak masasının başında",obstacleHint:"Örnek: malzemeleri hazırlıyorum ama soruyu cevaplamıyorum",fallbackHint:"Kullanabildiğim notlardan ilk bölümün cevabını sesle yazdır",observationHint:"Cevap yazıldı mı, yalnızca malzemeler mi hazırlandı"},stopRule:"Güvenli bir iş seç. Ağrı, hastalık, acil ihtiyaç veya kullanamadığın bir ortam varsa dur.",accessibleAlternative:"Dinle, sesle yazdır veya yardımcı araç kullan. Hazırlık seçersen bunu açıkça belirt; hazırladığını kullanmak için sonraki uygun zamanı seç."},result:{question:"En küçük adımının işe yarayan kısmını yaptın mı?",observationPrompt:"Gerçekten yapılan iş neydi, yalnızca hazırlık olan neydi?"},judgment:{primary:{id:"motivation-2-decision",scenario:"Bir başvuru yazmak istiyorsun. Üç oturumdur dosyayı açtın ama hiçbir şey yazmadın. İki dakikan var ve istenen bölümün içeriğini biliyorsun.",question:"Şimdi hangi küçük adımla ilerlemeyi deneyebilirsin?",options:[{id:"motivation-2-bigger",text:"Daha sonra uzun bir zaman ayır, böylece tam bir cevap yazmaya başlamak daha anlamlı gelsin.",feedback:"Daha uzun süre bitirmeye yardımcı olabilir. Ama şu anki yalnızca hazırlık yapma döngüsünü sınamıyor. Şimdi taslak bir cümle yaz; daha uzun zamana ihtiyacın olup olmadığına sonra karar ver."},{id:"motivation-2-outline",text:"Bu iki dakikada üç maddelik bir taslak çıkar, sonra istenen bölümü daha uzun bir zamanda yaz.",feedback:"Taslak içeriği netleştirebilir. Ama bu bölümü zaten biliyorsun; tekrar eden engel, metni yazmaya başlamak. Taslak bir cümle o engeli şimdi sınar. Taslak çıkarırsan onu hazırlık olarak kaydet."},{id:"motivation-2-sentence",text:"İstenen bölüme taslak bir cümle yaz, sonra elindeki iki dakikalık süre dolunca dur.",feedback:"Bu seçim davranışın kendisini içeriyor ve düzenleyebileceğin bir parça bırakıyor. Başvurunun başarısını garanti etmiyor, daha uzun süre de istemiyor. Yazdığın cümleyi dosyayı açmaktan ayrı kaydet."}],bestOptionId:"motivation-2-sentence"}},carry:{takeaway:"Başlangıcı bugün yapılabilir hâle getir. Küçültürken asıl işe yarayan kısmı içinden çıkarma.",followUp:{questionId:"motivation-2-return",question:"Küçülttüğün işi gerçekten yaptın mı, yoksa sadece hazırlık mı yaptın?",observationPrompt:"Gerçekten yapılan iş neydi, yalnızca hazırlık olan neydi?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Küçük olması bir seçimdir, garanti değil",paragraphs:["Wood ve Rünger alışkanlıkları, tekrarlanan koşullarla bağlantılı öğrenilmiş davranışlar olarak ele alıyor. Tekrar, davranışın daha kendiliğinden yapılmasını destekleyebilir; bilinçli hedefler de önemini koruyabilir. Derlemeleri tek cümlenin en iyi miktar olduğunu veya her küçük davranışın mutlaka büyüyeceğini göstermiyor. Bu derste küçük bir iş seçiyorsun. Bu haftaki koşullarında onu yapabiliyor musun ve işine yarıyor mu, buna bakıyorsun. [M07]","Seçtiğin küçük adımda hazırlığı, yapmak istediğin işten ayır. Cevaplanan bir soruyu kontrol edebilirsin. Okunan bir cümle bilgi verebilir. Yazılan bir cümleyi düzenleyebilirsin. Malzemelerin hazır olması yararlı bir hazırlıktır ama bu davranışların kendisini içermez. Birkaç küçük deneme seçtiğin nedene hiç hizmet etmiyorsa davranışına veya hedefine yeniden bak. Farklı bir parça, daha fazla destek ya da gerçekten ayırabildiğin daha uzun bir zaman gerekebilir. Kolayca bir kutuyu işaretleyebiliyor olman, yapılmamış işi ilerleme sayman için bir neden değildir. [M07]"]},{heading:"Bu yöntem önerisinin de sınırları var",paragraphs:["BJ Fogg’un Tiny Habits tarifi, mevcut bir günlük rutini çok küçük bir davranışla eşleştirir. İşlemeyen eşleşmeyi yeniden düzenlemeyi önerir. Bu bir uygulayıcı tekniğidir. İncelenen sayfa, tarifin tamamının sıradan başlama işareti planından daha iyi olduğunu bağımsız biçimde göstermiyor. Her davranışın bir dakikadan kısa sürmesi gerektiğini de kanıtlamıyor. [M15]","Fogg, küçük davranışın hemen ardından kişinin kendi seçtiği olumlu bir hareketi de önerir. Sinirsel bağlantıların daha hızlı kurulması, kutlamanın şart olması veya kutuyu işaretlemenin aynı pekiştirme işini yapması iddiaları, araştırma dosyasında kontrollü kanıtla doğrulanmadı. [M16] Memnuniyet gelirse fark edebilirsin; gelmiyorsa üretmeye çalışma. Ne yaptığını dürüstçe yaz. Sonrasında ne hissettiğin ayrı bir bilgidir. İşe yarayan en küçük adımda durabilir, yarın aynı boyutta tutabilir, araçlarını veya erişim biçimini değiştirebilirsin. Daha az iş yapmak, karakterinin daha zayıf olduğunu göstermez."]}],sourceIds:["M07","M15","M16"]}},{schemaVersion:2,revision:2,id:"motivation-3",courseId:"motivation",locale:"tr",title:"Hatırlatıcı çaldı. Yine başlayamadın.",goal:"Seçtiğin küçük işi, zamanın, malzemen ve erişimin olduğu bir başlama anında dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hatırlatıcı sen hâlâ otobüsteyken mi çalıyor? İşi gerçekten yapabileceğin uygun bir başlama anı seç.",reason:{id:"motivation-3-available-setting-cost",label:"Hangi uygun ortamı kullanacaksın? Ona yer açmak için neyi başka zamana alacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Koruyabildiğim sabit molayı kullanmak","Esnek bir ev işini başka zamana almak","Çalışırken bakımın aksamamasını sağlamak"]},why:{id:"motivation-3-why",label:"Hedefine gerçekten zaman ayırabileceğin hangi an var?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Başlama işaretinin üç şartı var: o anın gelmesi, senin fark etmen ve o işi yapabiliyor olman. Çocuğu okula bıraktıktan sonra doğrudan işe gidiyorsan, o an masa başında çalışmaya uygun değildir. İşe yarayan küçük adımını koru. Onu gerçekten yapmana izin veren bir ortam seç. Zaman var gibi görünmesi, malzemenin de yanında olduğu anlamına gelmez.","“Şu olunca bunu yapacağım” gibi belirli planlar, niyetini davranışa dönüştürmene yardımcı olabilir. Tekrarlanan koşullarda davranışı yinelemek alışkanlığı destekleyebilir. Ama herkes için aynı bitiş tarihi yok. Bugün otomatikleşmeye çalışmak yerine başlama anını sına. Bu üç koşuldan hangisi tuttu, hangisini değiştirmen gerekiyor, kaydet."],example:{title:"Leyla’nın uygun çalışma anı",text:"Leyla sorusunu çocuğu okula bıraktıktan sonra cevaplamayı planlamıştı. Ama notları yanında olmadan doğrudan işe gitti. Çarşamba günü aynı soruyu akşam yemeğinden sonraya, mutfak masasına aldı. Başlama anı geldi ve Leyla fark etti. Masayı toplamadan soruyu cevapladı. Artık üzerinde çalışabileceği bir cevabı var. Önceki uygun olmayan anı da kayıtta bıraktı; hiç yaşanmamış gibi silmedi."}},move:{invitation:"Aynı küçük işi sürdür. Başlayabileceğin bir an ve yapabileceğin bir yer seç.",instructions:["Seçtiğin an geliyor mu? Fark ediyor musun? Planındaki işi o anda yapabiliyor musun?","Tarihi seç. Malzemenin veya gerekli erişimin o anda orada olacağını kontrol et."],prompts:[],suggestions:{action:["Örnek: kaydettiğim meslek sınavı sorusunu cevapla","Kaydettiğim başvuru metnine o cümleyi yaz","Üzerime aldığım mutfak temizliğini yap"],minimum:["Aynı deneme sorusuna bir cevap yaz","Aynı işe yarayan cümleyi yaz","Üzerime aldığım aynı iki kupayı yıka"],cue:["Akşam yemeğinde kendi tabağımı kaldırdıktan sonra","Sabit 12.30 molam başlayınca","Birlikte yediğimiz yemek bittikten hemen sonra"],place:["Evde mutfak masasının başında","Molada kullanabildiğim masada","Kullanabildiğim mutfak lavabosunda"],minutes:[2,1],fallback:["Yarın yemek sonrası kullanabildiğim notlardan soruya dön","Kaydettiğim notlardan o cümleyi sesle yazdır","Yardımın kararlaştırıldığı bir sonraki temizlik saatini kullan"],observation:["An geldi mi? Fark ettim mi? Yapabildim mi?","Bu ortam aynı küçük işi yapmaya uygun muydu","Başlama anı geldi mi, üstlendiğim iş yapılabilir miydi"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: kaydettiğim meslek sınavı sorusunu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",cue:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",place:"Evde mutfak masasının başında",fallback:"Yarın yemek sonrası kullanabildiğim notlardan soruya dön",observation:"An geldi mi? Fark ettim mi? Yapabildim mi?",minutes:2},{action:"Kaydettiğim başvuru metnine o cümleyi yaz",minimum:"Aynı işe yarayan cümleyi yaz",cue:"Sabit 12.30 molam başlayınca",place:"Molada kullanabildiğim masada",fallback:"Kaydettiğim notlardan o cümleyi sesle yazdır",observation:"Bu ortam aynı küçük işi yapmaya uygun muydu",minutes:1},{action:"Üzerime aldığım mutfak temizliğini yap",minimum:"Üzerime aldığım aynı iki kupayı yıka",cue:"Birlikte yediğimiz yemek bittikten hemen sonra",place:"Kullanabildiğim mutfak lavabosunda",fallback:"Yardımın kararlaştırıldığı bir sonraki temizlik saatini kullan",observation:"Başlama anı geldi mi, üstlendiğim iş yapılabilir miydi",minutes:2}]},suggested:{action:"Örnek: kaydettiğim meslek sınavı sorusunu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",minutes:2,cueHint:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",placeHint:"Evde mutfak masasının başında",obstacleHint:"Örnek: önceki başlama anında notlarım yanımda değildi",fallbackHint:"Yarın yemek sonrası kullanabildiğim notlardan soruya dön",observationHint:"An geldi mi? Fark ettim mi? Yapabildim mi?"},stopRule:"Araç kullanırken ya da bakım işini veya güvenliği aksatacak bir yerde uygulama yapma.",accessibleAlternative:"Görebildiğin veya kullanabildiğin hatırlatıcı, sesli malzeme, kararlaştırılmış yardım veya daha uygun bir sonraki anı kullan."},result:{question:"Başlama anında o küçük işi gerçekten yapabildin mi?",observationPrompt:"Başlama anı geldi mi, fark ettin mi, işi yapabildin mi?"},judgment:{primary:{id:"motivation-3-usable-setting-decision",scenario:"Leyla bugün planındaki soruyu cevaplamak istiyor. Çocuğu okula bıraktıktan sonra doğrudan işe gittiği için önceki plan işlemedi. Akşam, notları elinin altındayken ayırabileceği beş dakika var. Sabit öğle molasında notlarının telefon kopyasını kullanabilir. Yarın trende de çalışabilir ama kalkış saati henüz belli değil.",question:"Aynı küçük işi bugün denemesi için hangi değişiklik en uygun?",options:[{id:"motivation-3-dinner",text:"Akşam yemeği sonrası ayırabildiği zamanı kullansın; elindeki notlarla planındaki aynı soruya bir cevap yazsın.",feedback:"Bu seçim işi ve malzemeyi koruyup uygun olmayan başlama anını değiştiriyor. Bugünkü zaman kesinleşmiş. O an geldi mi, Leyla fark etti mi, soruyu cevaplayabildi mi? Bunları kaydet."},{id:"motivation-3-phone-copy",text:"Öğle molasında notlarının bir kopyasını telefonuna alsın, soruyu daha sonraki uygun bir molada cevaplasın.",feedback:"Taşınabilir notlar ileride iş molalarında yardımcı olabilir. Ama bu seçim bugünkü bilinen zamanı hazırlığa ayırıyor; cevaplamanın tarihi belirsiz kalıyor. Akşam elindeki notlarla kayıtlı davranışı bugün sınayabilir."},{id:"motivation-3-train",text:"Notlarını yarınki tren için yanına alsın, kalkış kesinleşince kaydettiği aynı soruyu trende cevaplasın.",feedback:"Tren, saati kesinleşince uygun bir ortam olabilir. Ama bugün uygun zaman varken denemeyi erteliyor. Akşam artık uygun gelmezse trene göre plan kaydetmeden önce yolculuk tarihini ve saatini netleştirsin."}],bestOptionId:"motivation-3-dinner"}},carry:{takeaway:"Seçtiğin başlama anı gelmeli. O anı fark etmeli ve işi yapabilecek durumda olmalısın.",followUp:{questionId:"motivation-3-return",question:"Başlama anı gelmedi mi, fark etmedin mi, yoksa o anda işi yapamadın mı?",observationPrompt:"Başlama anı geldi mi, fark ettin mi, işi yapabildin mi?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Başlama işareti, sınayacağın bir koşuldur",paragraphs:["Gollwitzer ve Sheeran’ın 2006 tarihli derlemesi, bir durumu seçilmiş bir davranışa bağlayan planların 94 bağımsız sınamasını birleştirdi. Hedefe ulaşma ortalama olarak arttı. Geçmiş çalışmalardaki standartlaştırılmış etki büyüklüğü 0,65’ti. Bu, yüzde 65 gelişme demek değildir. Uygulamadaki hatırlatıcının etkisini de öngörmez. Bu ortalamalar farklı hedeflerden ve ortamlardan geliyor. Burada seçtiğin çalışma anının etkisi ayrıca ölçülmüş değil. [M08]","Wood ve Rünger, aynı ortamla bağlantılı tekrarı alışkanlık öğrenmenin bir parçası olarak anlatır. Tek başına bir işaret davranışı garanti etmez; her günlük rutin de otomatik olmak zorunda değildir. [M07] ODA’nın “geldi, fark edildi, yapılabildi” kontrolü bir öğretme aracıdır. Kaçırılan hatırlatıcıyı, eksik malzemeden veya başka bir sorumluluktan ayırmana yardım eder. Seçtiğin an gelmediyse uygun olduğu durumda “Fırsat olmadı” seçeneğini kullan. Geldiyse ama yapmadıysan da bunu açıkça yazabilirsin. Bu olayı, ne kadar kararlı olduğuna dair genel bir yargıya çevirmene gerek yok."]},{heading:"Altmış altı gün bir model tahminiydi",paragraphs:["Lally’nin 2010 çalışması, kişilerin seçtiği günlük davranışları 84 gün izledi. Verilere iyi uyan 39 otomatikleşme eğrisinde, son düzeyin yüzde 95’ine ulaşmak için modelin tahmin ettiği ortanca süre 66 gündü. Tahminler 18 ile 254 gün arasındaydı. En uzun tahmin, gözlem süresinin dışına uzanıyordu. Bunlar gözlenmiş en hızlı, ortalama ve en yavaş alışkanlık tamamlama tarihleri değildi. [M05]","Meslek sınavına çalışman, araştırmadaki yeme, içme veya hareket davranışlarının aynısı değil. Tahmini kendine son tarih yapmak veya çalışmanın artık zahmetsiz olması gerektiğine kanıt saymak doğru olmaz. Aynı denemeyi sürdür. Gerçekten uygun anlara, işe yarayan davranışa ve onu destekleyen koşullara bak. Bir başlama anı hafta içi uyarken vardiya veya bakım günlerinde başka düzen gerekebilir. Seçerek tek bir değişikliği dene. Önceki kaydı da koru ki geri baktığında hayali bir düzene değil, gerçekte karşılaştığın koşullara bakabilesin."]}],sourceIds:["M08","M07","M05"]}},{schemaVersion:2,revision:2,id:"motivation-4",courseId:"motivation",locale:"tr",title:"Planın bozulduğu anı da hesaba kat",goal:"Karşılaştığın bir engel için yapabileceğin tek bir adımı dene. İhtiyaçlarını ve sorumluluklarını aksatma.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Çalışma saatin çocuğu yatırmaya mı denk geliyor? Kendine gaz vermek bakım işini üstlenecek birini getirmez.",reason:{id:"motivation-4-accepted-change-cost",label:"Kaydındaki engeli gidermek için hangi somut değişikliği yapmayı seçersin?",kind:"text",maxLength:160,optional:!0,suggestions:["Saati değiştir, işe yarayan küçük iş kalsın","Yardımı kesinleşmiş saymadan önce açıkça yardım iste","Daha çok zorlamak yerine erişim biçimini değiştir"]},why:{id:"motivation-4-why",label:"Bu hedef ilerlerken hangi gerçek ihtiyacın korunması gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Hedefini ve işe yarayan küçük işini koru. Gerçek bir denemeden tek bir engel seç: başka işe kaymak, eksik malzeme, bakım sorumluluğu veya sağlık ihtiyacı. İstenen sonucu, engeli ve o engelde yapacağını birlikte planlamak araştırmalarda ortalama olarak mütevazı faydalar gösteriyor. Ama olmayan zamanı veya yardımı var edemez. Karşılaştığın koşulu açıkça adlandır; hepsini isteksizlik diye açıklama.","Seçtiğin adım o engele uysun. Dikkatini dağıtan bir sekme için ortamı değiştirebilirsin. Bakım verdiğin kişi için, o sırada başka birinin sorumluluğu üstlenmesi gerekebilir. Hastalıkta dinlenmek gerekebilir. O adımla yapabileceğin ilk yararlı işi planla, sonra uygun anda sına. Prova hazırlıktır; yedek planın gerçekten işlediğinin kanıtı değildir."],example:{title:"Leyla’nın bakım yardımı",text:"Perşembe günü Leyla’nın çalışma anı, çocuğunu yatırdığı sırada geliyor. Eşi, yatma hazırlığı bitince beş dakika çocukla ilgilenmeyi kabul ediyor. Leyla aynı soruyu o zamana alıyor. Çocuğun bakımı sürerken masada soruyu cevaplıyor. Yardımı ve cevabını ayrı kaydediyor. Soru hâlâ çalışma istiyor. Bugünkü anlaşmaya bakıp yarın da aynı yardımın hazır olacağını varsaymıyor."}},move:{invitation:"Kaydındaki engele uyan tek bir koşulu değiştir. İşe yarayan davranışın aynı kalsın.",instructions:["Bakım yardımı kesinleştiyse kayıtlı işini dene. Yalnızca kaydındaki engelle ilgili koşulu değiştir.","Anlaşma yoksa “Bunu uyarla”, ardından “Destek” seç. Hangi işte, kimden, ne zaman yardım istediğini belirt.","Kabul edilmezse gerçekten uygun bir zaman seç veya ara ver. Yardım istemek uygulamadan ayrı."],prompts:[{id:"motivation-4-support-request",label:"Destek gerekiyorsa hangi iş için, kimden ve hangi zaman için yardım isteyeceksin?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Örnek: Merve’ye mesaj atıp beş dakikalık bakım yardımı iste."}],suggestions:{action:["Örnek: kaydettiğim başvuru metninin o cümlesini yaz","Bakım yardımı kararlaştırıldığında kayıtlı sorumu cevapla","Kaydettiğim bölümü sesli kayıttan dinle"],minimum:["Başvurudaki aynı işe yarayan cümleyi yaz","Aynı deneme sorusuna bir cevap yaz","Aynı işe yarayan bölümü dinle"],cue:["İşte saat 14.00 molam bittikten hemen sonra","Kararlaştırdığımız beş dakikalık bakım yardımı başlayınca","Kesinleşen 12.30 molam başlayınca"],place:["İşteki bilgisayarımın başında","Evde mutfak masasının başında","Rahatça kullanabildiğim sessiz mola alanında"],minutes:[2,5],fallback:["Gereksiz bildirimleri sessize al; acil iletişimi açık tut","Bakım yardımı olmazsa çalışmaya ara ver","Ses kaydı çalışmazsa kullanabileceğin başka bir biçim iste"],observation:["Bildirim geldi mi; seçtiğim yanıt yazmaya yaradı mı","Bakım desteğini ve soruya verdiğim cevabı ayrı kaydet","Bölüme erişebildim mi? Dinledim mi? Ayrı kaydet."],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: kaydettiğim başvuru metninin o cümlesini yaz",minimum:"Başvurudaki aynı işe yarayan cümleyi yaz",cue:"İşte saat 14.00 molam bittikten hemen sonra",place:"İşteki bilgisayarımın başında",fallback:"Gereksiz bildirimleri sessize al; acil iletişimi açık tut",observation:"Bildirim geldi mi; seçtiğim yanıt yazmaya yaradı mı",minutes:2},{action:"Bakım yardımı kararlaştırıldığında kayıtlı sorumu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",cue:"Kararlaştırdığımız beş dakikalık bakım yardımı başlayınca",place:"Evde mutfak masasının başında",fallback:"Bakım yardımı olmazsa çalışmaya ara ver",observation:"Bakım desteğini ve soruya verdiğim cevabı ayrı kaydet",minutes:2},{action:"Kaydettiğim bölümü sesli kayıttan dinle",minimum:"Aynı işe yarayan bölümü dinle",cue:"Kesinleşen 12.30 molam başlayınca",place:"Rahatça kullanabildiğim sessiz mola alanında",fallback:"Ses kaydı çalışmazsa kullanabileceğin başka bir biçim iste",observation:"Bölüme erişebildim mi? Dinledim mi? Ayrı kaydet.",minutes:5}]},suggested:{action:"Örnek: kaydettiğim başvuru metninin o cümlesini yaz",minimum:"Başvurudaki aynı işe yarayan cümleyi yaz",minutes:2,cueHint:"İşte saat 14.00 molam bittikten hemen sonra",placeHint:"İşteki bilgisayarımın başında",obstacleHint:"Örnek: gereksiz telefon bildirimleri son cümlemi böldü",fallbackHint:"Gereksiz bildirimleri sessize al; acil iletişimi açık tut",observationHint:"Bildirim geldi mi; seçtiğim yanıt yazmaya yaradı mı"},stopRule:"Bakımı ve acil ihtiyaçları aksatma. Hastalıkta veya güvenli olmayan koşullarda destek ya da dinlenmeyi seç.",accessibleAlternative:"Kararlaştırılmış yardım iste, erişimi veya zamanı değiştir. Destek istemek ya da dinlenmek de seçebileceğin bir adım."},result:{question:"Seçtiğin çözüm sayesinde planındaki küçük işini yapabildin mi?",observationPrompt:"Engel çıktı mı, çıktığında hangi yanıtı kullandın?"},judgment:{primary:{id:"motivation-4-covered-slot-decision",scenario:"Gitar çalışması çocuğun yatma hazırlığına denk geliyor. Bu akşam için beş dakikalık bakım yardımı kesinleşmiş, gitar hazır. Komşu cumartesi daha uzun yardım edebilir ama anlaşmadılar. Ebeveyn, bakımı aksatmadan bu akşam kısa bir bölüm çalmak istiyor.",question:"Sıradaki denemeye en uygun yanıt hangisi?",options:[{id:"motivation-4-confirmed-cover",text:"Bu akşam kesinleşen beş dakikalık bakım yardımı sırasında kısa bölümü çalsın, yardım süresi bitince dursun.",feedback:"Anlaşma, işi büyütmeden eksik koşulu sağlıyor. Aynı kısa bölümü dene; çalışmayı bakım yardımından ayrı kaydet. Bu akşamki düzen, gelecekteki yardımın da şimdiden kararlaştırıldığı anlamına gelmez."},{id:"motivation-4-saturday-request",text:"Komşudan cumartesi daha uzun bakım yardımı istesin, o çalışmayı planlamadan önce yanıtın kesinleşmesini beklesin.",feedback:"Bu, ilerideki bir fırsat için güvenli bir destek isteği. Ama bu akşam zaten yapılabilir olan kısa bölümü sınamıyor. Bu akşam artık uymuyorsa seç; anlaşılana kadar cumartesiyi kesinleşmiş sayma."},{id:"motivation-4-prepare-first",text:"Bu akşam yardım aldığı beş dakikada akordu kontrol edip başka bir çalışma zamanı için bölümü işaretlesin.",feedback:"Gerektiğinde akordu kontrol etmek ve çalacağın bölümü işaretlemek yararlı bir hazırlıktır. Burada çalgı ve bölüm zaten hazır. Tekrar hazırlık yaparsan asıl çalışmayı denememiş olursun. Kesinleşen bakım desteği sayesinde ayırabildiğin zamanda o bölümü çal."}],bestOptionId:"motivation-4-confirmed-cover"}},carry:{takeaway:"Seçtiğin yanıt karşılaştığın engele uysun. İşe yararken gerçek ihtiyaçları ve sorumlulukları da korusun.",followUp:{questionId:"motivation-4-barrier-response-return",question:"Kaydettiğin iş gerçekten yapıldı mı? Değiştirdiğin koşul, kaydındaki engeli gidermeye yaradı mı?",observationPrompt:"Hangisi uygulamaydı, hangisi destekti? Hangi engel hâlâ vardı?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Planlama araştırması süreyi ve desteği de içerir",paragraphs:["Wang ve çalışma arkadaşlarının 2021 derlemesi, zihinsel karşılaştırmayı “şu olursa bunu yapacağım” planlarıyla birleştiren 21 makaledeki 24 etkiyi topladı. Hedefe ulaşmadaki ortalama etki küçük ile orta arasındaydı. Sonuçlar hedefe göre değişti; yayın yanlılığına işaret eden bulgular vardı. Sonucu, engeli ve yanıtı birleştirmek dilekleri garanti etmez. Düşüncelerin dış olayları değiştirdiğini ya da her WOOP biçiminin birbirine eşit olduğunu göstermez. [M10]","Duckworth ve çalışma arkadaşları bir okuldaki 77 beşinci sınıf öğrencisiyle akademik bir program denedi. Öğrenciler küçük gruplarda birer saatlik üç oturum yaptı. Alıştırmalar tekrarlandı, hatırlatma kartları kullanıldı. Bazı akademik sonuçlar iyileşti ama sonraki gruplar arası farklar anlamlı değildi. [M03] ODA’nın kısa yetişkin alıştırmasında katılımcı, destek ve süre farklı. Bu, sınanabilir bir yanıt seçmek için uyarlama; araştırmadaki programın bütünü değil. Faydalıysa prova yap. Sonra hazırlığı, engelin gerçekten çıktığı ve yanıta ihtiyaç duyduğun andan ayrı tut."]},{heading:"Engeli tanı, kendini suçlama",paragraphs:["Planlama yöntemi istenen sonuca, engele ve o engele karşı seçilen davranışa bakar. Her engelin senin tutumundan kaynaklandığını göstermez. Bakım, para, engellilikle ilgili erişim sorunları, vardiya, hastalık veya birinin zarar veren davranışı, neyi yapabileceğini sınırlayabilir. İşe yarayan yanıt kararlaştırılmış yardım, değişen saat, bir uyarlama, dinlenme veya sınır olabilir. Yetişkinler için uyarlamada bu koşulları dürüstçe adlandırmak gerekir. [M03, M10]","Tek bir koşulu değiştirmek için gerçekte olanı kaydettiğin yere bak. Başlama anı geldi ama malzeme yoksa daha güçlü söz vermek sorunu çözmez. Bakım verdiğin kişi sana ihtiyaç duyduysa, onun bakımını aksatmayacak bir düzen kur. Dikkatini dağıtan alışkanlık ortaya çıktıysa acil iletişimi açık bırakan bir yanıt dene. Hiç çıkmayan engelin yedek yanıtı da sınanmış sayılmaz. Küçük işi, yardım ayarlamaktan veya malzemeyi taşımaktan ayrı kaydet. Sonra işe yarayan düzeni koru. Yeni ritüeller biriktirmene veya daha istekli hissetmeyi şart koşmana gerek yok."]}],sourceIds:["M10","M03"]}},{schemaVersion:2,revision:2,id:"motivation-5",courseId:"motivation",locale:"tr",title:"Bir gün aksadı mı? Uygun bir zamanda dön.",goal:"Aynı denemeyi gözden geçir. İşe yarayan bir koşulu koru. Sıradaki denemeyi yapabileceğin bir tarih seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Denemeler aksadı mı? Hedefin mi değişti, yoksa ayırabildiğin zaman mı?",reason:{id:"motivation-5-reason",label:"Bu hedef gelecek hafta hâlâ zaman ayırmaya değer mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Hâlâ seçtiğim hedefe geri dönmek","Artık uymayan başlama anını değiştirmek","Dinlenmeyi koruyup gereken desteği istemek"]},why:{id:"motivation-5-why",label:"Bu hedef gelecek hafta hâlâ zaman ayırmaya değer mi?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin nedene, işe yarayan küçük adıma, başlama anına ve gerçek kayıtlarına bak. İlerlemeyi izlemek, araştırmalarda ortalama olarak hedefe ulaşmayı destekleyebilir. Ama denenmemiş planı yapılmış işe çeviremez. Kayıt boşsa başarısız oldun da diyemez. Neyin yardım ettiğine karar verirken hazırlığı, gerçek çalışmayı ve ara vermeyi ayrı tut. Her birinin ne olduğu açık olsun.","Bir çalışmada tek bir fırsatı kaçırmak, modellenen alışkanlık oluşumunu belirgin biçimde bozmadı. Bu, uzun araların zararsız olduğunu göstermez. Sana uyan düzeni tekrar kullan, uygun olmayan anı değiştir veya hedefine yeniden bak. Sıradaki yararlı işi ne zaman yapacağını seç. Telafi için iki kat çalışman gerekmiyor. Dinlenme hakkını da çalışarak kazanmak zorunda değilsin."],example:{title:"Leyla’nın sıradaki zamanı",text:"Pazar günü Leyla meslek belgesi için yaptığı plana bakıyor. Yemek sonrası ayırdığı zaman iki kez işe yaramış. Vardiya değişikliği yüzünden iki denemeyi yapamamış. Hedefini hâlâ sürdürmek istiyor. Bir soruyu pazartesi öğle molasında cevaplamayı planlıyor. Kullanabildiği notları da yanında olacak. Sonraki denemenin zamanını yazıyor. Aksayan çalışmaları yapılmış saymıyor. Pazartesi yapacağı iş kayıtta henüz bir plan olarak duruyor."}},move:{invitation:"Kaydına bak. Aynı işe yarayan küçük adım için gerçekten uygun bir tarih belirle.",instructions:["Denemelerinde sorun çıkaran tek bir koşulu değiştir. Seçtiğin günün ve ortamın uygun olduğunu kontrol et.","Plan yalnızca bu denemeyi ve ertesi gün değerlendirmesini kapsar. Haftalık değerlendirme sana kalır."],prompts:[],suggestions:{action:["Örnek: kaydettiğim meslek sınavı sorusunu cevapla","Kaydettiğim kısa yürüyüşe çık","Üzerime aldığım mutfak temizliğini yap"],minimum:["Aynı deneme sorusuna bir cevap yaz","Aynı güvenli beş dakikalık yolda yürü","Üzerime aldığım aynı iki kupayı yıka"],cue:["Kesinleşen 12.30 öğle molam başlayınca","Saati belli olan öğle molam başlayınca","Birlikte yediğimiz yemek bittikten hemen sonra"],place:["Molada kullanabildiğim masada","İşyerimde yürüyebildiğim aynı güzergahta","Kullanabildiğim mutfak lavabosunda"],minutes:[2,5],fallback:["Öğle molası iptal olursa uygun başka saat belirle","Yol güvenli değilse oturarak hareket etmeyi seç","Yapamıyorsam yararlı başka bir temizlik işi için anlaş"],observation:["Yeni başlama anında aynı soruyu cevaplayabildim mi","Yaptığım hareket ve ayırabildiğim süre","Yapılan iş ve ortamın uygun olup olmadığı"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: kaydettiğim meslek sınavı sorusunu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",cue:"Kesinleşen 12.30 öğle molam başlayınca",place:"Molada kullanabildiğim masada",fallback:"Öğle molası iptal olursa uygun başka saat belirle",observation:"Yeni başlama anında aynı soruyu cevaplayabildim mi",minutes:2},{action:"Kaydettiğim kısa yürüyüşe çık",minimum:"Aynı güvenli beş dakikalık yolda yürü",cue:"Saati belli olan öğle molam başlayınca",place:"İşyerimde yürüyebildiğim aynı güzergahta",fallback:"Yol güvenli değilse oturarak hareket etmeyi seç",observation:"Yaptığım hareket ve ayırabildiğim süre",minutes:5},{action:"Üzerime aldığım mutfak temizliğini yap",minimum:"Üzerime aldığım aynı iki kupayı yıka",cue:"Birlikte yediğimiz yemek bittikten hemen sonra",place:"Kullanabildiğim mutfak lavabosunda",fallback:"Yapamıyorsam yararlı başka bir temizlik işi için anlaş",observation:"Yapılan iş ve ortamın uygun olup olmadığı",minutes:2}]},suggested:{action:"Örnek: kaydettiğim meslek sınavı sorusunu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",minutes:2,cueHint:"Kesinleşen 12.30 öğle molam başlayınca",placeHint:"Molada kullanabildiğim masada",obstacleHint:"Örnek: vardiyam değişti, akşam çalışmaya ayırdığım zaman kalmadı",fallbackHint:"Öğle molası iptal olursa uygun başka saat belirle",observationHint:"Yeni başlama anında aynı soruyu cevaplayabildim mi"},stopRule:"Uzun süren ilgi kaybı veya günlük işlerde zorlanma varsa şimdi destek alabilirsin. Acil tehlikede hemen yardım iste.",accessibleAlternative:"Kullanabildiğin malzemeyi, kararlaştırılmış yardımı, destek isteğini, dinlenmeyi veya açıkça ara vermeyi seçebilirsin."},result:{question:"Seçtiğin geri dönüşü gerçekten yaptın mı?",observationPrompt:"Hangi gerçek davranışı, desteği veya ara vermeyi kaydettin?"},judgment:{primary:{id:"motivation-5-recorded-barrier-decision",scenario:"Kerem’in yeni vardiyası akşam yemeği bitmeden başlıyor; yürüyüş zamanı kalmıyor. Yürümeyi hâlâ seçiyor. Her gün öğle molasında güvenli beş dakikalık yol var. Vardiya öncesi yol erken kalkmayı gerektiriyor; pazar daha uzun yol uygun. Uykusunu azaltmadan hafta içi geri dönmeyi sınamak istiyor.",question:"Kaydındaki engele ve vereceği emeğe hangi plan uyuyor?",options:[{id:"motivation-5-early-walk",text:"Yürüyüşü vardiya öncesine alsın, yeni başlama anını korumak için alarmını her zamankinden erkene kursun.",feedback:"Vardiya öncesi yol, akşam çakışmasını çözer. Ama erken alarm uyku için koyduğu sınırla çelişir. Mevcut öğle molası, bu ek bedel olmadan hafta içi geri dönmeyi sınamasına izin verir."},{id:"motivation-5-sunday-walk",text:"Pazar günkü daha uzun yürüyüşe geçsin, haftada bir yapmanın programına daha iyi uyup uymadığına baksın.",feedback:"Haftalık yürüyüş, yapılabilir bir hedef değişikliği olabilir; başarısızlık değildir. Kerem şu an hafta içini sınamak istiyor ve öğle molası uygun. Sıklığı değiştirmeden önce bu koşulu denesin."},{id:"motivation-5-lunch-return",text:"Sıradaki öğle molasını seçsin, güvenli beş dakikalık yürüyüşü yapsın ve yeni saatin uyup uymadığını kaydetsin.",feedback:"Bu seçim yürüyüşü ve işe yarayan küçük kısmını korurken uygun olmayan akşam saatini değiştiriyor. Yalnızca yapılan yürüyüş uygulama sayılır. Yarınki değerlendirme bu düzeni tekrarlamak, değiştirmek veya bırakmak için bilgi verebilir."}],bestOptionId:"motivation-5-lunch-return"}},carry:{takeaway:"Nedenini ve işe yarayan adımını koru. Kaydına bakıp uymayan tek bir koşulu değiştir.",followUp:{questionId:"motivation-5-return",question:"Yeni başlama anı uydu mu? Hedef gelecek hafta da vereceğin zaman ve enerjiye değer mi?",observationPrompt:"Hangi gerçek davranışı, desteği veya ara vermeyi kaydettin?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Kayıtları birleştir, yapılmamış bir seri yaratma",paragraphs:["Harkin ve çalışma arkadaşlarının 138 rastgele atamalı araştırmayı kapsayan derlemesinde ilerlemeyi izlemek, hedefe ulaşmada ortalama fayda gösterdi. Hedefler ve yöntemler farklıydı. Kayıt tutma ve sonuçları bildirme gibi özellikler, daha büyük etkilerle ilişkiliydi. Ama bunlar herkesle paylaşmanın veya haftalık sıklığın şart olduğunu göstermiyor. ODA’nın ertesi gün dönüşü bir uyarlamadır; araştırmayla doğrulanmış bir süre değildir. Haftalık değerlendirme isteğe bağlıdır, bu plan onu kendiliğinden takvime koymaz. [M13]","Lally’nin gözlem çalışmasında tek bir fırsatı kaçırmak, modellenen alışkanlık oluşumunu belirgin biçimde bozmadı. Bu dar sonuç, uzun araların alışkanlığı hiç değiştirmediğini kanıtlamaz. [M05] Sonraki adımı kendi denemelerine bakarak seç. İşe yarayan kısmı koru, uymayan başlama anını veya yanıtını değiştir, geçmişte yapılmayanları kayıtta bırak. Gelecek için kaydettiğin iş, hâlâ yalnızca bir plan. Hedef artık ayıracağın zamana değmiyorsa bilinçli biçimde değiştir, ertele veya bırak. Dersi bitirmek, işi yapmak ve denemeyi değerlendirmek ayrı şeylerdir."]},{heading:"Keyif şart değil, destek şimdi de mümkün",paragraphs:["Son ders, yeni bir motivasyon ritüeli eklemek yerine aynı denemeyi toparlıyor. İzleme araştırmaları gerçek ilerlemeyi seçilmiş bir hedefle karşılaştırmanın ortalama olarak yararlı olabildiğini gösterir. Her kişi için en iyi tekniği söylemez. Kaydın, başlama anının uygun olmadığını, malzemenin eksik kaldığını veya hedefin alacağı zamanın artık uymadığını gösterebilir. Sonraki tek değişikliği bu görülen koşula göre seç. Hazırlığı veya verilen sözü, davranışın kendisi olarak sayma. [M13]","Dinlenmeyi veya bütün keyifli etkinlikleri önce iş bitirme şartına bağlama. Daha sonra uygun, ücretsiz bir ses içeriği dinlersen trafikte çevrene ve güvenliğine dikkat et. Uzun süren ilgi kaybı, sıkıntı, bitkinlik veya günlük işleri tamamlamakta zorlanma, uzman değerlendirmesi gerektirebilir. NIMH rehberi destek istemeyi, acil tehlikede hemen yardım almayı önerir. Yalnızca isteksizliğe bakıp nedenini teşhis etmez, yardım istemeden önce beklemeni de şart koşmaz. [M20] Bu konuyla ilgilenirken küçük yararlı uygulamanı sürdürebilir, destek isteyebilir veya ara verebilirsin."]}],sourceIds:["M13","M05","M20"]}}];function k(a,e,l){const i=a.judgment.primary,r=[...i.options],t=r.findIndex(n=>n.id===i.bestOptionId);return[r[e],r[t]]=[r[t],r[e]],{id:a.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,practice:[a.move.instructions[0],a.move.instructions[1],"Gerçekte ne olduğunu kaydet. Yarın aynı denemeye geri bak."],reflection:a.direction.reason.label,question:`${i.scenario} ${i.question}`,options:r.map(n=>n.text),correct:e,feedback:r[e].feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds,photo:l}}const O={id:"motivation",title:"Yine mi heves bekliyorsun? Hedefine bugün zaman ayır.",subtitle:"5 ders. Emeğine değen hedefi seç, işe yarayan küçük adımı dene, düzenini haftana uydur.",description:"Neye emek vermek istediğini seç. Küçük ama işe yarayan bir iş yap. Gerçekte olanlara göre başlama anını veya desteği değiştir.",scope:"Günlük hedefler için eğitim. Sürekli isteksizlik, bitkinlik veya günlük işlerini yapamama yalnızca motivasyon sorunu olmayabilir. Destek almak uygundur; bir sağlık uzmanı nedenini anlamana yardımcı olabilir.",outcome:"Kendi kayıtlarına göre şekillendirdiğin bir davranış ve tarihini belirlediğin sıradaki deneme.",photo:{id:"1790004245013-b347139d5591",alt:"Güneşli orman yolunda koşan bir adam"},lang:"tr",lessons:[k(d[0],1,{id:"1517971129774-8a2b38fa128e",alt:"Pencere yanında defterine yazan bir kadın"}),k(d[1],2,{id:"1581578731509-8ae9c5a3e7d3",alt:"Kapının yanında duran bir çift ayakkabı"}),k(d[2],2,{id:"1499933374294-4584851497cc",alt:"Masada siyah bir çalar saat"}),k(d[3],1,{id:"1575478004055-999ebe26dab7",alt:"Yağmurda şemsiyeyle yürüyen bir kadın"}),k(d[4],0,{id:"1577950248429-7530424d9682",alt:"Panoya asılmış bir aylık takvim"})]},U=Object.freeze(Object.defineProperty({__proto__:null,COURSE:O,LESSONS_V2:d,SOURCES:P},Symbol.toStringTag,{value:"Module"}));export{g as S,q as a,R as b,L as c,C as d,F as e,U as f,I as m,j as t};
